import React, { useMemo } from 'react';
import { getInstitutions, getEvaluations, getComplianceRecords } from '../services/db';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { MATURITY_LEVELS, calculateRiskScore } from '../constants';
import { Building, AlertTriangle, CheckCircle, TrendingUp } from 'lucide-react';

const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#f97316', '#ef4444'];

const KPICard = ({ title, value, icon: Icon, color, subtext }: any) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-start justify-between">
    <div>
      <p className="text-gray-500 text-sm font-medium mb-1">{title}</p>
      <h3 className="text-3xl font-bold text-navy-900">{value}</h3>
      {subtext && <p className="text-xs text-gray-400 mt-2">{subtext}</p>}
    </div>
    <div className={`p-3 rounded-lg ${color}`}>
      <Icon className="text-white" size={24} />
    </div>
  </div>
);

const Dashboard: React.FC = () => {
  const institutions = getInstitutions();
  const compliance = getComplianceRecords();

  // Calc Compliance Risks
  const riskStats = useMemo(() => {
    let high = 0, critical = 0;
    compliance.forEach(c => {
      const { score } = calculateRiskScore(c);
      if (score >= 9) critical++;
      else if (score >= 6) high++;
    });
    return { high, critical };
  }, [compliance]);

  // Mock Data for Charts (Normally aggregated from evaluations)
  const maturityData = [
    { name: 'ممتاز', value: 2 },
    { name: 'جيد جداً', value: 5 },
    { name: 'جيد', value: 8 },
    { name: 'يحتاج تحسين', value: 3 },
    { name: 'ضعيف', value: 1 },
  ];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
         <div>
            <h2 className="text-2xl font-bold text-navy-900">لوحة القيادة</h2>
            <p className="text-gray-500">نظرة عامة على أداء المؤسسات الوقفية</p>
         </div>
         <div className="text-sm bg-gold-100 text-gold-700 px-3 py-1 rounded-full border border-gold-200">
            السنة الحالية: {new Date().getFullYear()}
         </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPICard 
          title="إجمالي المؤسسات" 
          value={institutions.length} 
          icon={Building} 
          color="bg-navy-800"
          subtext="المؤسسات المسجلة في النظام"
        />
        <KPICard 
          title="مؤسسات مكتملة التقييم" 
          value="0" // Dynamic later
          icon={CheckCircle} 
          color="bg-teal-600"
          subtext="لهذا العام"
        />
        <KPICard 
          title="مخاطر عالية/حرجة" 
          value={riskStats.high + riskStats.critical} 
          icon={AlertTriangle} 
          color="bg-red-500"
          subtext="تتطلب تدخلاً عاجلاً"
        />
         <KPICard 
          title="متوسط معدل النضج" 
          value="3.2" 
          icon={TrendingUp} 
          color="bg-gold-500"
          subtext="جيد (مؤشر عام)"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Maturity Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-navy-900 mb-4">توزيع مستويات النضج المؤسسي</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={maturityData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {maturityData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Compliance Risks Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-navy-900 mb-4">حالة الامتثال النظامي</h3>
          <div className="h-64 flex items-center justify-center text-gray-400">
             {compliance.length === 0 ? (
               <p>لا توجد بيانات امتثال. الرجاء استيراد ملف الامتثال.</p>
             ) : (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={[
                    { name: 'منخفض', count: 10 },
                    { name: 'متوسط', count: 5 },
                    { name: 'مرتفع', count: 3 },
                    { name: 'حرج', count: 1 },
                  ]}>
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip />
                    <Bar dataKey="count" fill="#0d9488" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType } from '../types';
import { GOVERNORATES } from '../constants';
import { Plus, Search, Edit2, Trash2 } from 'lucide-react';

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<Partial<Institution>>({});

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name!,
      type: (formData.type as InstitutionType) || 'وقفية عامة',
      capital_omr: Number(formData.capital_omr) || 0,
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone || '',
      email: formData.email || '',
      governorate: formData.governorate || '',
      wilayat: formData.wilayat || '',
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
    }
  };

  const filtered = list.filter(i => i.name.includes(search));

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900">بيانات المؤسسات</h2>
        <button 
          onClick={() => { setFormData({}); setShowForm(true); }}
          className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900"
        >
          <Plus size={18} /> إضافة مؤسسة
        </button>
      </div>

      {/* Search */}
      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-right">
          <thead className="bg-gray-50 text-gray-600 font-medium">
            <tr>
              <th className="p-4">المؤسسة</th>
              <th className="p-4">النوع</th>
              <th className="p-4">رأس المال (ر.ع)</th>
              <th className="p-4">المحافظة</th>
              <th className="p-4">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map(inst => (
              <tr key={inst.id} className="hover:bg-gray-50">
                <td className="p-4 font-medium text-navy-900">{inst.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded text-xs ${inst.type === 'وقفية عامة' ? 'bg-teal-100 text-teal-800' : 'bg-gold-100 text-gold-800'}`}>
                    {inst.type}
                  </span>
                </td>
                <td className="p-4 font-mono">{inst.capital_omr.toLocaleString()}</td>
                <td className="p-4">{inst.governorate}</td>
                <td className="p-4 flex gap-2">
                  <button onClick={() => { setFormData(inst); setShowForm(true); }} className="text-blue-600 hover:text-blue-800">
                    <Edit2 size={18} />
                  </button>
                  <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800">
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
