export default Institutions;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId } from '../services/db';
import { Institution, Indicator, Evaluation, Response } from '../types';
import { CURRENT_YEAR } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp } from 'lucide-react';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});
  const [loading, setLoading] = useState(false);

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    setIndicators(getIndicators());
  }, []);

  useEffect(() => {
    if (selectedInstId && indicators.length > 0) {
      // Find or Create Evaluation
      let ev = getEvaluationByInstAndYear(selectedInstId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [selectedInstId, indicators.length]);

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      // Expected columns: "المحور", "وصف التقييم"
      const newIndicators: Indicator[] = data.map((row, idx) => ({
        id: `IND-${idx + 1}`,
        axis: row['المحور'] || 'عام',
        text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
        weight: 1,
        active: true
      })).filter(i => i.text !== 'بدون نص');

      saveIndicators(newIndicators);
      setIndicators(newIndicators);
      alert(`تم استيراد ${newIndicators.length} مؤشر بنجاح`);
    };
    reader.readAsBinaryString(file);
  };

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>

        <div className="flex gap-2">
            <label className="bg-teal-600 hover:bg-teal-700 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2">
                <Upload size={18} /> استيراد المؤشرات (Excel)
                <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
            </label>
        </div>
      </div>

      {/* Institution Selector */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة للتقييم ({CURRENT_YEAR})</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && indicators.length > 0 && (
        <div className="space-y-4">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
              <button 
                className="w-full flex items-center justify-between p-4 bg-gray-50 hover:bg-gray-100 transition-colors"
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                {openAxis === axis ? <ChevronUp /> : <ChevronDown />}
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-6 animate-fadeIn">
                  {grouped[axis].map(ind => (
                    <div key={ind.id} className="border-b border-gray-100 last:border-0 pb-4 last:pb-0">
                      <p className="text-gray-800 mb-3 font-medium">{ind.text}</p>
                      <div className="flex flex-wrap gap-2">
                        {[1, 2, 3, 4, 5].map(score => (
                          <button
                            key={score}
                            onClick={() => handleScore(ind.id, score)}
                            className={`w-10 h-10 rounded-full flex items-center justify-center font-bold border transition-all ${
                              responses[ind.id]?.score === score
                                ? 'bg-gold-500 text-white border-gold-500 scale-110 shadow-md'
                                : 'bg-white text-gray-500 border-gray-300 hover:border-gold-400'
                            }`}
                          >
                            {score}
                          </button>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          <div className="sticky bottom-4 bg-white p-4 shadow-lg rounded-xl border border-gray-200 flex justify-between items-center z-20">
             <div>
                <span className="text-sm text-gray-500">تم تقييم {Object.keys(responses).length} من {indicators.length}</span>
                <div className="w-32 h-2 bg-gray-200 rounded-full mt-1">
                    <div className="h-full bg-teal-600 rounded-full" style={{width: `${(Object.keys(responses).length / indicators.length) * 100}%`}}></div>
                </div>
             </div>
             <button className="bg-navy-800 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900">
                <Save size={18} /> حفظ المسودة
             </button>
          </div>
        </div>
      )}

      {(!selectedInstId || indicators.length === 0) && (
        <div className="text-center py-20 text-gray-400 bg-white rounded-xl border border-dashed border-gray-300">
           {indicators.length === 0 ? "الرجاء استيراد ملف المؤشرات أولاً" : "اختر مؤسسة للبدء"}
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, saveInstitution } from '../services/db';
import { Institution, ComplianceRecord } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Upload, FileText, AlertCircle, Check, X as XIcon } from 'lucide-react';

declare const XLSX: any;
declare const mammoth: any;

const CompliancePage: React.FC = () => {
  const [records, setRecords] = useState<ComplianceRecord[]>([]);
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [viewMode, setViewMode] = useState<'list' | 'import'>('list');
  const [importPreview, setImportPreview] = useState<any[]>([]);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setInstitutions(getInstitutions());
    setRecords(getComplianceRecords(CURRENT_YEAR));
  };

  // Import Handler (DOCX/CSV/Excel)
  // Since browser-side DOCX table parsing is tricky without heavy libs, 
  // we will support CSV/XLSX fully and provide a text-based parser for DOCX as fallback 
  // or use mammoth to extract raw text and try to find patterns if table parsing fails.
  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.name.endsWith('.xlsx') || file.name.endsWith('.csv')) {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const bstr = evt.target?.result;
            const wb = XLSX.read(bstr, { type: 'binary' });
            const ws = wb.Sheets[wb.SheetNames[0]];
            const data: any[] = XLSX.utils.sheet_to_json(ws);
            processImportData(data);
        };
        reader.readAsBinaryString(file);
    } else if (file.name.endsWith('.docx')) {
        // Simple Mammoth text extraction (Table parsing is hard in mammoth browser)
        // For prototype, we will alert user to use CSV/Excel for reliable table import
        alert("تنبيه: لاستيراد الجداول بدقة يفضل تحويل ملف الوورد إلى Excel. سيتم محاولة قراءة النص.");
        const reader = new FileReader();
        reader.onload = (event) => {
           const arrayBuffer = event.target?.result;
           mammoth.extractRawText({arrayBuffer: arrayBuffer})
            .then((result: any) => {
                console.log(result.value); // Text is here, but parsing tables is hard.
                alert("لم يتم العثور على جدول مهيكل. يرجى استخدام Excel.");
            })
            .done();
        };
        reader.readAsArrayBuffer(file);
    }
  };

  const processImportData = (data: any[]) => {
      // Map columns (fuzzy matching)
      const mapped = data.map(row => {
          // Try to find keys
          const name = row['المؤسسة'] || row['Institution Name'] || row['الاسم'];
          if (!name) return null;

          return {
              institution_name: name,
              institution_status: row['الحالة'] || 'فاعلة',
              board_status: row['مجلس الإدارة'] || 'غير موجود', // logic needed to parse "قائم" vs "منتهي"
              has_executive: (row['إدارة تنفيذية'] || '').includes('نعم') || (row['إدارة تنفيذية'] || '').includes('يوجد'),
              has_auditor: (row['شركة تدقيق'] || '').includes('نعم') || (row['شركة تدقيق'] || '').includes('تم'),
              has_minutes: (row['المحاضر'] || '').includes('نعم'),
              has_finance: (row['التقرير المالي'] || '').includes('نعم'),
              raw: row
          };
      }).filter(Boolean);

      setImportPreview(mapped);
      setViewMode('import');
  };

  const confirmImport = () => {
      let addedInst = 0;
      let updatedRec = 0;

      importPreview.forEach(item => {
          // Find or create institution
          let inst = institutions.find(i => i.name === item.institution_name);
          if (!inst) {
              inst = {
                  id: generateId(),
                  name: item.institution_name,
                  type: 'وقفية عامة',
                  capital_omr: 0,
                  employees_omani: 0,
                  employees_non_omani: 0,
                  contact_phone: '-',
                  created_at: new Date().toISOString()
              };
              saveInstitution(inst);
              addedInst++;
          }

          const rec: ComplianceRecord = {
              id: generateId(),
              institution_id: inst.id,
              cycle_year: CURRENT_YEAR,
              institution_status: item.institution_status.includes('تصفية') ? 'قيد التصفية' : (item.institution_status.includes('فاعلة') ? 'فاعلة' : 'أخرى'),
              board_status: item.board_status.includes('منته') ? 'منتهي' : (item.board_status.includes('قائم') ? 'قائم' : 'غير موجود'),
              has_executive_management: item.has_executive,
              has_auditor_company: item.has_auditor,
              has_minutes_prev_year: item.has_minutes,
              has_financial_report_prev_year: item.has_finance,
              last_updated_at: new Date().toISOString(),
              notes: item.raw['ملاحظة'] || ''
          };

          saveComplianceRecord(rec);
          updatedRec++;
      });

      alert(`تم إضافة ${addedInst} مؤسسة وتحديث ${updatedRec} سجل امتثال.`);
      refreshData();
      setViewMode('list');
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900">متابعة الامتثال النظامي ({CURRENT_YEAR})</h2>
        <div className="flex gap-2">
            <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900">
                <Upload size={18} /> استيراد (Excel/CSV)
                <input type="file" accept=".xlsx, .csv, .docx" className="hidden" onChange={handleFile} />
            </label>
        </div>
      </div>

      {viewMode === 'import' && (
          <div className="bg-white p-6 rounded-xl shadow-sm">
              <h3 className="text-lg font-bold mb-4">معاينة الاستيراد ({importPreview.length} سجل)</h3>
              <div className="overflow-x-auto">
                  <table className="w-full text-sm text-right border">
                      <thead className="bg-gray-50">
                          <tr>
                              <th className="p-2 border">المؤسسة</th>
                              <th className="p-2 border">الحالة</th>
                              <th className="p-2 border">الخطر المتوقع</th>
                          </tr>
                      </thead>
                      <tbody>
                          {importPreview.map((row, idx) => (
                              <tr key={idx}>
                                  <td className="p-2 border">{row.institution_name}</td>
                                  <td className="p-2 border">{row.institution_status}</td>
                                  <td className="p-2 border text-red-500">
                                      {/* Simplified preview risk logic */}
                                      {!row.has_executive || !row.has_auditor ? 'مرتفع' : 'منخفض'}
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
              <div className="mt-4 flex gap-2">
                  <button onClick={confirmImport} className="bg-teal-600 text-white px-4 py-2 rounded">تأكيد الاستيراد</button>
                  <button onClick={() => setViewMode('list')} className="text-gray-600 px-4 py-2">إلغاء</button>
              </div>
          </div>
      )}

      {viewMode === 'list' && (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <table className="w-full text-right">
            <thead className="bg-navy-50 text-navy-900 font-medium">
                <tr>
                <th className="p-4">المؤسسة</th>
                <th className="p-4">الحالة</th>
                <th className="p-4">مجلس الإدارة</th>
                <th className="p-4 text-center">الإدارة التنفيذية</th>
                <th className="p-4 text-center">التدقيق</th>
                <th className="p-4">مستوى الخطر</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
                {records.map(rec => {
                    const inst = institutions.find(i => i.id === rec.institution_id);
                    const risk = calculateRiskScore(rec);
                    return (
                        <tr key={rec.id} className="hover:bg-gray-50">
                            <td className="p-4 font-bold text-navy-900">{inst?.name || 'غير معروف'}</td>
                            <td className="p-4 text-sm">{rec.institution_status}</td>
                            <td className="p-4 text-sm">{rec.board_status}</td>
                            <td className="p-4 text-center">
                                {rec.has_executive_management ? <Check size={16} className="text-green-500 inline" /> : <XIcon size={16} className="text-red-500 inline" />}
                            </td>
                            <td className="p-4 text-center">
                                {rec.has_auditor_company ? <Check size={16} className="text-green-500 inline" /> : <XIcon size={16} className="text-red-500 inline" />}
                            </td>
                            <td className="p-4">
                                <span className={`px-2 py-1 rounded text-xs font-bold ${risk.color}`}>
                                    {risk.label} ({risk.score})
                                </span>
                            </td>
                        </tr>
                    );
                })}
                 {records.length === 0 && (
                    <tr><td colSpan={6} className="p-8 text-center text-gray-400">لا توجد سجلات امتثال لهذا العام. قم بالاستيراد.</td></tr>
                )}
            </tbody>
            </table>
        </div>
      )}
    </div>
  );
};

export default CompliancePage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getEvaluations, getResponses, getIndicators, generateImprovementPlan, getImprovements } from '../services/db';
import { Institution, Evaluation, ImprovementItem } from '../types';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, ResponsiveContainer } from 'recharts';
import { Printer, Download } from 'lucide-react';

const Reports: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [reportData, setReportData] = useState<any>(null);
  const [improvements, setImprovements] = useState<ImprovementItem[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (!selectedInstId) return;

    // Generate Report Data
    const ev = getEvaluations().find(e => e.institution_id === selectedInstId);
    if (!ev) {
        setReportData(null);
        return;
    }

    const responses = getResponses(ev.id);
    const indicators = getIndicators();

    // Generate improvements if not exist
    generateImprovementPlan(ev.id, responses, indicators);
    setImprovements(getImprovements(ev.id));

    // Calculate Axis Averages for Radar
    const axisScores: Record<string, { total: number, count: number }> = {};
    responses.forEach(r => {
        const ind = indicators.find(i => i.id === r.indicator_id);
        if (ind) {
            if (!axisScores[ind.axis]) axisScores[ind.axis] = { total: 0, count: 0 };
            axisScores[ind.axis].total += r.score;
            axisScores[ind.axis].count += 1;
        }
    });

    const radarData = Object.keys(axisScores).map(axis => ({
        subject: axis,
        A: (axisScores[axis].total / axisScores[axis].count).toFixed(2),
        fullMark: 5
    }));

    setReportData({ radarData, evaluation: ev });

  }, [selectedInstId]);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900">النتائج والتقارير</h2>
        {reportData && (
            <button onClick={() => window.print()} className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900">
                <Printer size={18} /> طباعة التقرير (PDF)
            </button>
        )}
