import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, AreaChart, Area, CartesianGrid } from 'recharts';
import { calculateRiskScore, GOVERNORATES } from '../constants';
import { Building, AlertTriangle, CheckCircle, TrendingUp, MapPin, Shield } from 'lucide-react';

const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#f97316', '#ef4444'];
const RISK_COLORS = ['#10b981', '#f59e0b', '#ef4444']; // Low, Med, High

const InfographicCard = ({ title, value, icon: Icon, gradient, subtext, footer }: any) => (
