const Dashboard: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [compliance, setCompliance] = useState<any[]>([]);
  const [risks, setRisks] = useState<RiskRegisterItem[]>([]);
  const [responses, setResponses] = useState<Response[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions());
    setEvaluations(getEvaluations());
    setCompliance(getComplianceRecords());
    setRisks(getRisks());
    setResponses(getAllResponses());
  }, []);

  // 1. Compliance & Risk Stats
  const riskStats = useMemo(() => {
    let stats = { low: 0, medium: 0, high: 0, critical: 0 };
    compliance.forEach(c => {
      const { score } = calculateRiskScore(c);
      if (score >= 9) stats.critical++;
      else if (score >= 6) stats.high++;
      else if (score >= 3) stats.medium++;
      else stats.low++;
    });
    return stats;
  }, [compliance]);

  // 2. Risk Register Matrix Stats
  const riskMatrix = useMemo(() => {
      let high = 0, med = 0, low = 0;
      risks.forEach(r => {
          const score = r.probability * r.impact;
          if (score >= 15) high++;
          else if (score >= 8) med++;
          else low++;
      });
      return { high, med, low, total: risks.length };
  }, [risks]);

  // 3. Governorate Distribution
  const govStats = useMemo(() => {
      const counts: Record<string, number> = {};
      GOVERNORATES.forEach(g => counts[g] = 0);
      institutions.forEach(i => {
          if (i.governorate && counts[i.governorate] !== undefined) {
              counts[i.governorate]++;
          }
      });
      return Object.keys(counts)
        .map(g => ({ name: g, value: counts[g] }))
        .sort((a, b) => b.value - a.value)
        .filter(g => g.value > 0); // Only show active
  }, [institutions]);

  // 4. Maturity Stats
  const maturityStats = useMemo(() => {
    const stats = [
      { name: 'ممتاز', value: 0 },
      { name: 'جيد جداً', value: 0 },
      { name: 'جيد', value: 0 },
      { name: 'يحتاج تحسين', value: 0 },
      { name: 'ضعيف', value: 0 },
    ];

    const evalScores: Record<string, { total: number, count: number }> = {};
    responses.forEach(r => {
        if (!evalScores[r.evaluation_id]) evalScores[r.evaluation_id] = { total: 0, count: 0 };
        evalScores[r.evaluation_id].total += r.score;
        evalScores[r.evaluation_id].count++;
    });

    Object.values(evalScores).forEach(ev => {
        const avg = ev.total / ev.count;
        if (avg >= 4.5) stats[0].value++;
        else if (avg >= 3.5) stats[1].value++;
        else if (avg >= 2.5) stats[2].value++;
        else if (avg >= 1.5) stats[3].value++;
        else stats[4].value++;
    });

    return stats;
  }, [responses]);

  const averageScore = useMemo(() => {
      if (responses.length === 0) return 0;
      const total = responses.reduce((acc, r) => acc + r.score, 0);
      return (total / responses.length).toFixed(1);
  }, [responses]);

  return (
    <div className="space-y-8 pb-10">
      <div className="flex justify-between items-end mb-6">
         <div>
            <h2 className="text-3xl font-extrabold text-navy-900 tracking-tight">لوحة القيادة التنفيذية</h2>
            <p className="text-gray-500 mt-2 text-lg">تحليل شامل للأداء، الامتثال، والمخاطر للمؤسسات الوقفية</p>
         </div>
         <div className="hidden md:block">
             <div className="bg-white px-4 py-2 rounded-lg shadow-sm border border-gray-200 text-sm font-semibold text-navy-800">
                 آخر تحديث: {new Date().toLocaleDateString('ar-OM')}
             </div>
         </div>
      </div>

      {/* Hero KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <InfographicCard 
          title="إجمالي المؤسسات" 
          value={institutions.length} 
          icon={Building} 
          gradient="bg-gradient-to-br from-navy-800 to-navy-900"
          subtext="إجمالي المؤسسات المسجلة في قاعدة البيانات"
        />
        <InfographicCard 
          title="نسبة الإنجاز" 
          value={`${evaluations.length}`} 
          icon={CheckCircle} 
          gradient="bg-gradient-to-br from-teal-600 to-teal-800"
          subtext={`تم تقييم ${evaluations.length} من أصل ${institutions.length} مؤسسة`}
          footer={<div className="w-full bg-black/20 rounded-full h-1.5 mt-1"><div className="bg-white h-1.5 rounded-full" style={{width: `${institutions.length > 0 ? (evaluations.length/institutions.length)*100 : 0}%`}}></div></div>}
        />
        <InfographicCard 
          title="سجل المخاطر" 
          value={riskMatrix.total} 
          icon={AlertTriangle} 
          gradient="bg-gradient-to-br from-orange-500 to-red-600"
          subtext={`${riskMatrix.high} مخاطر عالية تتطلب معالجة فورية`}
        />
         <InfographicCard 
          title="مؤشر النضج العام" 
          value={averageScore} 
          icon={TrendingUp} 
          gradient="bg-gradient-to-br from-blue-600 to-indigo-700"
          subtext="المتوسط العام (من 5.0) لجميع المؤسسات"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Governorate Distribution (Visual) */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <MapPin className="text-teal-600" /> التوزيع الجغرافي للمؤسسات
                </h3>
            </div>
            <div className="h-80">
                {govStats.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={govStats} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                            <XAxis dataKey="name" axisLine={false} tickLine={false} />
                            <YAxis axisLine={false} tickLine={false} />
                            <Tooltip cursor={{fill: '#f0f4f8'}} contentStyle={{borderRadius: '10px', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.1)'}} />
                            <Bar dataKey="value" fill="#0d9488" radius={[8, 8, 0, 0]} barSize={50} animationDuration={1500}>
                                {govStats.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#0d9488' : '#14b8a6'} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ResponsiveContainer>
                ) : (
                    <div className="h-full flex items-center justify-center text-gray-400 bg-gray-50 rounded-xl border border-dashed">
                        لا توجد بيانات جغرافية كافية
                    </div>
                )}
            </div>
        </div>

        {/* Maturity Donut */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
          <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
             <TrendingUp className="text-blue-600" /> مستويات النضج
          </h3>
          <div className="h-64 relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={maturityStats}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                  stroke="none"
                >
                  {maturityStats.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
            {/* Center Text */}
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                <span className="text-3xl font-bold text-navy-900">{evaluations.length}</span>
                <span className="text-xs text-gray-400">تقييم مكتمل</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Risk Heatmap / Matrix Visual */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <Shield className="text-red-600" /> مصفوفة المخاطر والامتثال
                </h3>
             </div>

             <div className="grid grid-cols-2 gap-6">
                 {/* System Compliance Risks */}
                 <div className="bg-gray-50 p-4 rounded-xl">
                     <h4 className="font-bold text-gray-700 mb-3 text-sm text-center">مخاطر الامتثال النظامي</h4>
                     <div className="h-40 flex items-end justify-center gap-2">
                         <div className="w-1/4 bg-red-100 rounded-t-lg relative group">
                             <div className="absolute bottom-0 w-full bg-red-500 rounded-t-lg transition-all duration-1000" style={{height: `${riskStats.critical * 10}%`, minHeight: riskStats.critical > 0 ? '4px' : '0'}}></div>
                             <span className="absolute -top-6 w-full text-center text-xs font-bold text-red-600">{riskStats.critical}</span>
                             <span className="absolute bottom-1 w-full text-center text-[10px] text-white/90">حرج</span>
                         </div>
                         <div className="w-1/4 bg-orange-100 rounded-t-lg relative group">
                             <div className="absolute bottom-0 w-full bg-orange-500 rounded-t-lg transition-all duration-1000" style={{height: `${riskStats.high * 10}%`, minHeight: riskStats.high > 0 ? '4px' : '0'}}></div>
                             <span className="absolute -top-6 w-full text-center text-xs font-bold text-orange-600">{riskStats.high}</span>
                             <span className="absolute bottom-1 w-full text-center text-[10px] text-white/90">عال</span>
                         </div>
                         <div className="w-1/4 bg-yellow-100 rounded-t-lg relative group">
                             <div className="absolute bottom-0 w-full bg-yellow-500 rounded-t-lg transition-all duration-1000" style={{height: `${riskStats.medium * 10}%`, minHeight: riskStats.medium > 0 ? '4px' : '0'}}></div>
                             <span className="absolute -top-6 w-full text-center text-xs font-bold text-yellow-600">{riskStats.medium}</span>
                         </div>
                         <div className="w-1/4 bg-green-100 rounded-t-lg relative group">
                             <div className="absolute bottom-0 w-full bg-green-500 rounded-t-lg transition-all duration-1000" style={{height: `${riskStats.low * 10}%`, minHeight: riskStats.low > 0 ? '4px' : '0'}}></div>
                             <span className="absolute -top-6 w-full text-center text-xs font-bold text-green-600">{riskStats.low}</span>
                         </div>
                     </div>
                 </div>

                 {/* Operational Risks (Register) */}
                 <div className="bg-gray-50 p-4 rounded-xl">
                     <h4 className="font-bold text-gray-700 mb-3 text-sm text-center">سجل المخاطر التشغيلية</h4>
                     <div className="space-y-3">
                         <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-red-100 shadow-sm">
                             <span className="text-sm font-medium text-gray-600">عالية جداً</span>
                             <span className="bg-red-500 text-white text-xs font-bold px-3 py-1 rounded-full">{riskMatrix.high}</span>
                         </div>
                         <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-orange-100 shadow-sm">
                             <span className="text-sm font-medium text-gray-600">متوسطة</span>
                             <span className="bg-orange-500 text-white text-xs font-bold px-3 py-1 rounded-full">{riskMatrix.med}</span>
                         </div>
                         <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-green-100 shadow-sm">
                             <span className="text-sm font-medium text-gray-600">منخفضة</span>
                             <span className="bg-green-500 text-white text-xs font-bold px-3 py-1 rounded-full">{riskMatrix.low}</span>
                         </div>
                     </div>
                 </div>
             </div>
          </div>

          {/* Radar Chart (Improved) */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <h3 className="text-xl font-bold text-navy-900 mb-6">الأداء الكلي (عينة)</h3>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <RadarChart cx="50%" cy="50%" outerRadius="70%" data={[
                        { subject: 'الشرعي', A: 4, fullMark: 5 },
                        { subject: 'الإداري', A: 3, fullMark: 5 },
                        { subject: 'المالي', A: 3.5, fullMark: 5 },
                        { subject: 'الحوكمة', A: 2.5, fullMark: 5 },
                        { subject: 'الابتكار', A: 2, fullMark: 5 },
                        { subject: 'الاستدامة', A: 4, fullMark: 5 },
                    ]}>
                        <PolarGrid gridType="circle" />
                        <PolarAngleAxis dataKey="subject" tick={{ fill: '#4b5563', fontSize: 12, fontWeight: 'bold' }} />
                        <PolarRadiusAxis angle={30} domain={[0, 5]} tick={false} axisLine={false} />
                        <Radar name="الأداء" dataKey="A" stroke="#2563eb" fill="#3b82f6" fillOpacity={0.5} />
                    </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, getComplianceByInstAndYear, getRisks, saveRisk, deleteRisk } from '../services/db';
import { Institution, ComplianceRecord, RiskRegisterItem } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Save, AlertTriangle, CheckCircle, Info, ShieldAlert, Plus, Trash2, Scale } from 'lucide-react';

const CompliancePage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'compliance' | 'risks'>('compliance');
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');

  // Compliance State
  const [record, setRecord] = useState<Partial<ComplianceRecord>>({});

  // Risk Register State
  const [instRisks, setInstRisks] = useState<RiskRegisterItem[]>([]);
  const [newRisk, setNewRisk] = useState<Partial<RiskRegisterItem>>({});
  const [showRiskForm, setShowRiskForm] = useState(false);

  // Real-time calculated risk based on compliance form
  const complianceRisk = calculateRiskScore(record);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (selectedInstId) {
        // Load Compliance
        const existing = getComplianceByInstAndYear(selectedInstId, CURRENT_YEAR);
        if (existing) {
            setRecord(existing);
        } else {
            setRecord({
                institution_id: selectedInstId,
                cycle_year: CURRENT_YEAR,
                institution_status: 'فاعلة',
                board_status: 'قائم',
                has_executive_management: false,
                has_auditor_company: false,
                has_minutes_prev_year: false,
                has_financial_report_prev_year: false,
                notes: ''
            });
        }

        // Load Risks
        setInstRisks(getRisks(selectedInstId));
    } else {
        setRecord({});
        setInstRisks([]);
    }
  }, [selectedInstId]);

  const handleSaveCompliance = () => {
      if (!selectedInstId) return;
      const toSave: ComplianceRecord = {
          ...record as ComplianceRecord,
          id: record.id || generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          last_updated_at: new Date().toISOString()
      };
      saveComplianceRecord(toSave);
      alert('تم حفظ سجل الامتثال بنجاح');
  };

  const handleSaveRisk = () => {
      if (!selectedInstId || !newRisk.risk_title) return;
      const riskToSave: RiskRegisterItem = {
          id: generateId(),
          institution_id: selectedInstId,
          risk_title: newRisk.risk_title,
          category: newRisk.category || 'Operational',
          probability: Number(newRisk.probability) || 1,
          impact: Number(newRisk.impact) || 1,
          mitigation_plan: newRisk.mitigation_plan || '',
          status: 'Open'
      };
      saveRisk(riskToSave);
      setInstRisks(getRisks(selectedInstId));
      setShowRiskForm(false);
      setNewRisk({});
  };

  const handleDeleteRisk = (id: string) => {
      if(confirm('حذف هذا الخطر؟')) {
          deleteRisk(id);
          setInstRisks(getRisks(selectedInstId));
      }
  };

  const updateComplianceField = (field: keyof ComplianceRecord, value: any) => {
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900">إدارة المخاطر والامتثال ({CURRENT_YEAR})</h2>
      </div>

      {/* Selection */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && (
          <div className="animate-fadeIn">
              {/* Tabs */}
              <div className="flex border-b border-gray-200 mb-6">
                  <button 
                    onClick={() => setActiveTab('compliance')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'compliance' ? 'border-b-2 border-navy-800 text-navy-900' : 'text-gray-500 hover:text-navy-700'}`}
                  >
                      <span className="flex items-center gap-2"><Scale size={16} /> الامتثال النظامي</span>
                  </button>
                  <button 
                    onClick={() => setActiveTab('risks')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'risks' ? 'border-b-2 border-navy-800 text-navy-900' : 'text-gray-500 hover:text-navy-700'}`}
                  >
                      <span className="flex items-center gap-2"><ShieldAlert size={16} /> سجل المخاطر</span>
                  </button>
              </div>

              {/* COMPLIANCE TAB */}
              {activeTab === 'compliance' && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        {/* Status Card */}
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <h3 className="font-bold text-navy-900 mb-4 flex items-center gap-2">
                                <Info size={20} className="text-teal-600" /> الحالة الأساسية
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm text-gray-500 mb-1">حالة المؤسسة</label>
                                    <select className="w-full p-2 border rounded-lg bg-gray-50" value={record.institution_status} onChange={(e) => updateComplianceField('institution_status', e.target.value)}>
                                        <option value="فاعلة">فاعلة</option>
                                        <option value="غير فاعلة">غير فاعلة</option>
                                        <option value="قيد التصفية">قيد التصفية</option>
                                        <option value="متوقفة">متوقفة</option>
                                        <option value="أخرى">أخرى</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm text-gray-500 mb-1">حالة مجلس الإدارة</label>
                                    <select className="w-full p-2 border rounded-lg bg-gray-50" value={record.board_status} onChange={(e) => updateComplianceField('board_status', e.target.value)}>
                                        <option value="قائم">قائم</option>
                                        <option value="منتهي">منتهي الصلاحية</option>
                                        <option value="غير موجود">غير موجود</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Requirements */}
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <h3 className="font-bold text-navy-900 mb-4 flex items-center gap-2">
                                <CheckCircle size={20} className="text-teal-600" /> المتطلبات النظامية
                            </h3>
                            <div className="space-y-4">
                                <ToggleItem label="هل توجد إدارة تنفيذية أو مدير؟" checked={record.has_executive_management} onChange={(v) => updateComplianceField('has_executive_management', v)} />
                                <ToggleItem label="هل تم تعيين شركة تدقيق؟" checked={record.has_auditor_company} onChange={(v) => updateComplianceField('has_auditor_company', v)} />
                                <ToggleItem label="هل توجد محاضر اجتماعات للعام الماضي؟" checked={record.has_minutes_prev_year} onChange={(v) => updateComplianceField('has_minutes_prev_year', v)} />
                                <ToggleItem label="هل يوجد تقرير مالي معتمد للعام الماضي؟" checked={record.has_financial_report_prev_year} onChange={(v) => updateComplianceField('has_financial_report_prev_year', v)} />
                            </div>
                        </div>

                        <button onClick={handleSaveCompliance} className="w-full bg-navy-800 text-white p-4 rounded-xl font-bold shadow-lg hover:bg-navy-900 flex justify-center items-center gap-2">
                            <Save size={20} /> حفظ سجل الامتثال
                        </button>
                    </div>

                    {/* Sidebar Risk */}
                    <div className="lg:col-span-1">
                        <div className={`sticky top-6 p-6 rounded-xl border ${complianceRisk.score >= 6 ? 'bg-red-50 border-red-200' : 'bg-green-50 border-green-200'}`}>
                            <h3 className="text-lg font-bold text-navy-900 mb-2">تحليل المخاطر (الامتثال)</h3>
                            <div className="flex items-center gap-3 mb-6">
                                <div className={`text-4xl font-bold ${complianceRisk.score >= 6 ? 'text-red-600' : 'text-green-600'}`}>{complianceRisk.score}</div>
                                <div><div className="text-xs text-gray-500 uppercase">نقاط الخطر</div><div className={`font-bold ${complianceRisk.score >= 6 ? 'text-red-700' : 'text-green-700'}`}>{complianceRisk.label}</div></div>
                            </div>
                            <div className="space-y-3">
                                <RiskIndicator label="مجلس الإدارة" active={record.board_status !== 'قائم'} points={3} />
                                <RiskIndicator label="الإدارة التنفيذية" active={!record.has_executive_management} points={2} />
                                <RiskIndicator label="شركة التدقيق" active={!record.has_auditor_company} points={2} />
                                <RiskIndicator label="التقرير المالي" active={!record.has_financial_report_prev_year} points={2} />
                            </div>
                        </div>
                    </div>
                </div>
              )}

              {/* RISK REGISTER TAB */}
              {activeTab === 'risks' && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                          <h3 className="text-lg font-bold text-navy-900">قائمة المخاطر المرصودة</h3>
                          <button onClick={() => setShowRiskForm(true)} className="bg-red-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-700 text-sm"><Plus size={16} /> إضافة خطر</button>
                      </div>

                      {showRiskForm && (
                          <div className="bg-gray-50 p-6 rounded-xl border border-gray-200 animate-fadeIn">
                              <h4 className="font-bold mb-4">تسجيل خطر جديد</h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 mb-1">وصف الخطر</label>
                                      <input type="text" className="w-full p-2 border rounded" value={newRisk.risk_title || ''} onChange={e => setNewRisk({...newRisk, risk_title: e.target.value})} placeholder="مثال: نزاع قانوني على أصل وقفي" />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">التصنيف</label>
                                      <select className="w-full p-2 border rounded" value={newRisk.category} onChange={e => setNewRisk({...newRisk, category: e.target.value as any})}>
                                          <option value="Operational">تشغيلي</option>
                                          <option value="Financial">مالي</option>
                                          <option value="Legal">قانوني</option>
                                          <option value="Strategic">استراتيجي</option>
                                      </select>
                                  </div>
                                  <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">الاحتمالية (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded" value={newRisk.probability || ''} onChange={e => setNewRisk({...newRisk, probability: Number(e.target.value)})} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">الأثر (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded" value={newRisk.impact || ''} onChange={e => setNewRisk({...newRisk, impact: Number(e.target.value)})} />
                                    </div>
                                  </div>
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 mb-1">خطة المعالجة</label>
                                      <input type="text" className="w-full p-2 border rounded" value={newRisk.mitigation_plan || ''} onChange={e => setNewRisk({...newRisk, mitigation_plan: e.target.value})} />
                                  </div>
                              </div>
                              <div className="flex gap-2 justify-end">
                                  <button onClick={() => setShowRiskForm(false)} className="px-4 py-2 text-gray-600">إلغاء</button>
                                  <button onClick={handleSaveRisk} className="bg-navy-800 text-white px-4 py-2 rounded">حفظ</button>
                              </div>
                          </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {instRisks.map(risk => {
                              const score = risk.probability * risk.impact;
                              let color = 'bg-green-100 border-green-200';
                              if (score >= 15) color = 'bg-red-50 border-red-200';
                              else if (score >= 8) color = 'bg-orange-50 border-orange-200';

                              return (
                                  <div key={risk.id} className={`p-4 rounded-xl border ${color} relative group`}>
                                      <button onClick={() => handleDeleteRisk(risk.id)} className="absolute top-2 left-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={16}/></button>
                                      <div className="flex justify-between items-start mb-2">
                                          <span className="text-xs font-bold uppercase tracking-wider text-gray-500">{risk.category}</span>
                                          <span className={`text-xs font-bold px-2 py-1 rounded-full ${score >= 15 ? 'bg-red-500 text-white' : (score >= 8 ? 'bg-orange-500 text-white' : 'bg-green-500 text-white')}`}>
                                              {score} (شدة الخطر)
                                          </span>
                                      </div>
                                      <h4 className="font-bold text-navy-900 mb-2">{risk.risk_title}</h4>
                                      <p className="text-sm text-gray-600 mb-3">{risk.mitigation_plan || 'لا توجد خطة معالجة'}</p>
                                      <div className="flex gap-2 text-xs text-gray-500 border-t pt-2 border-gray-200/50">
                                          <span>P: {risk.probability}</span>
                                          <span>I: {risk.impact}</span>
                                      </div>
                                  </div>
                              )
                          })}
                          {instRisks.length === 0 && (
                              <div className="col-span-full py-10 text-center text-gray-400 border border-dashed border-gray-300 rounded-xl">
                                  لا توجد مخاطر مسجلة
                              </div>
                          )}
                      </div>
                  </div>
              )}
          </div>
      )}

      {!selectedInstId && (
        <div className="text-center py-20 text-gray-400 bg-white rounded-xl border border-dashed border-gray-300">
           اختر مؤسسة للبدء
