                                    <span className={`px-2 py-1 rounded text-xs font-bold ${
                                        imp.priority === 'High' ? 'bg-red-100 text-red-800' : 'bg-gray-100 text-gray-800'
                                    }`}>
                                        {imp.priority === 'High' ? 'عالية جداً' : imp.priority}
                                    </span>
                                    <span className="text-xs text-gray-400">{imp.due_date}</span>
                                </div>
                                <h4 className="font-bold text-navy-900 text-sm mb-2 line-clamp-2" title={imp.issue_summary}>{imp.issue_summary}</h4>
                                <div className="bg-gray-50 p-3 rounded-lg mt-2">
                                    <p className="text-xs text-gray-600 leading-relaxed">
                                        <span className="font-bold block mb-1">الإجراء المطلوب:</span>
                                        {imp.recommended_action}
                                    </p>
                                </div>
                                <div className="mt-4 flex items-center gap-2">
                                    <div className="w-6 h-6 rounded-full bg-navy-100 flex items-center justify-center text-xs font-bold text-navy-800">
