import { getInstitutions, getEvaluations, getComplianceRecords, getAllResponses, getRisks } from '../services/db';
import { Institution, Evaluation, Response, RiskRegisterItem } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, AreaChart, Area, CartesianGrid, LineChart, Line, LabelList } from 'recharts';
import { calculateRiskScore, GOVERNORATES } from '../constants';
import { Building, AlertTriangle, CheckCircle, TrendingUp, MapPin, Shield, Wallet, Users, UserCheck, Target, Activity } from 'lucide-react';

const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#f97316', '#ef4444'];
const GOV_COLORS = ['#3366cc', '#dc3912', '#ff9900', '#109618', '#990099', '#0099c6', '#dd4477', '#66aa00', '#b82e2e', '#316395', '#994499'];

const InfographicCard = ({ title, value, icon: Icon, gradient, subtext, footer }: any) => (
  <div className={`relative overflow-hidden rounded-2xl shadow-xl ${gradient} text-white p-6 transition-transform hover:scale-[1.02] duration-300`}>
    <div className="relative z-10 flex justify-between items-start">
        <div>
            <p className="text-blue-100 font-medium mb-1 text-lg">{title}</p>
            <h3 className="text-4xl font-extrabold tracking-tight my-3">{value}</h3>
            {subtext && <p className="text-sm text-white/80 font-light">{subtext}</p>}
        </div>
        <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm shadow-inner">
            <Icon size={32} className="text-white" />
        </div>
    </div>
    {footer && (
        <div className="relative z-10 mt-6 pt-4 border-t border-white/20 text-sm font-medium">
            {footer}
        </div>
    )}
    <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
    <div className="absolute top-10 -left-10 w-20 h-20 bg-black/10 rounded-full blur-2xl"></div>
  </div>
);

// Mock Data for Strategy 2026-2030
const STRATEGY_DATA = [
    { year: '2025', actual: 3.2, target: 3.2 },
    { year: '2026', actual: null, target: 3.5 },
    { year: '2027', actual: null, target: 3.8 },
    { year: '2028', actual: null, target: 4.2 },
    { year: '2029', actual: null, target: 4.5 },
    { year: '2030', actual: null, target: 4.8 },
];

const Dashboard: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [compliance, setCompliance] = useState<any[]>([]);
  const [risks, setRisks] = useState<RiskRegisterItem[]>([]);
  const [responses, setResponses] = useState<Response[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions());
    setEvaluations(getEvaluations());
    setCompliance(getComplianceRecords());
    setRisks(getRisks());
    setResponses(getAllResponses());
  }, []);

  // 1. Institution Types Breakdown
  const typeStats = useMemo(() => {
      const general = institutions.filter(i => i.type === 'وقفية عامة').length;
      const special = institutions.filter(i => i.type === 'وقفية خاصة').length;
      return [
          { name: 'عامة', value: general },
          { name: 'خاصة', value: special }
      ];
  }, [institutions]);

  // 2. Risk Matrix
  const riskMatrix = useMemo(() => {
      let high = 0, med = 0, low = 0;
      risks.forEach(r => {
          const score = r.probability * r.impact;
          if (score >= 15) high++;
          else if (score >= 8) med++;
          else low++;
      });
      return { high, med, low, total: risks.length };
  }, [risks]);

  // 3. Gov Stats (Visual with unique colors)
  const govStats = useMemo(() => {
      const counts: Record<string, number> = {};
      GOVERNORATES.forEach(g => counts[g] = 0);
      institutions.forEach(i => {
          if (i.governorate && counts[i.governorate] !== undefined) {
              counts[i.governorate]++;
          }
      });
      return Object.keys(counts)
        .map((g, idx) => ({ name: g, value: counts[g], fill: GOV_COLORS[idx % GOV_COLORS.length] }))
        .sort((a, b) => b.value - a.value)
        .filter(g => g.value > 0);
  }, [institutions]);

  // 4. Maturity Stats
  const maturityStats = useMemo(() => {
    const stats = [
      { name: 'ممتاز', value: 0 },
      { name: 'جيد جداً', value: 0 },
      { name: 'جيد', value: 0 },
      { name: 'يحتاج تحسين', value: 0 },
      { name: 'ضعيف', value: 0 },
    ];

    const evalScores: Record<string, { total: number, count: number }> = {};
    responses.forEach(r => {
        if (!evalScores[r.evaluation_id]) evalScores[r.evaluation_id] = { total: 0, count: 0 };
        evalScores[r.evaluation_id].total += r.score;
        evalScores[r.evaluation_id].count++;
    });

    Object.values(evalScores).forEach(ev => {
        const avg = ev.total / ev.count;
        if (avg >= 4.5) stats[0].value++;
        else if (avg >= 3.5) stats[1].value++;
        else if (avg >= 2.5) stats[2].value++;
        else if (avg >= 1.5) stats[3].value++;
        else stats[4].value++;
    });

    return stats;
  }, [responses]);

  const averageScore = useMemo(() => {
      if (responses.length === 0) return 0;
      const total = responses.reduce((acc, r) => acc + r.score, 0);
      return (total / responses.length).toFixed(1);
  }, [responses]);

  return (
    <div className="space-y-8 pb-10">
      <div className="flex justify-between items-end mb-6">
         <div>
            <h2 className="text-3xl font-extrabold text-navy-900 tracking-tight">لوحة القيادة الاستراتيجية</h2>
            <p className="text-gray-500 mt-2 text-lg">نظرة شاملة على الأصول البشرية، المالية، ومستويات الأداء</p>
         </div>
      </div>

      {/* Hero Financial & HR KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <InfographicCard 
          title="إجمالي المؤسسات" 
          value={institutions.length} 
          icon={Building} 
          gradient="bg-gradient-to-br from-indigo-900 to-navy-900"
          subtext="المؤسسات الوقفية المسجلة"
          footer={<span className="text-blue-200">نشطة في النظام</span>}
        />

        {/* Public vs Private Visual Indicator */}
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-white p-6 border border-gray-100 flex items-center justify-between">
            <div className="w-1/2">
                <p className="text-gray-500 font-medium mb-1">توزيع المؤسسات</p>
                <div className="space-y-4 mt-4">
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-teal-600"></div>
                        <span className="text-navy-900 font-bold text-xl">{typeStats[0].value}</span>
                        <span className="text-xs text-gray-500">عامة</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-gold-500"></div>
                        <span className="text-navy-900 font-bold text-xl">{typeStats[1].value}</span>
                        <span className="text-xs text-gray-500">خاصة</span>
                    </div>
                </div>
            </div>
            <div className="w-1/2 h-32">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie data={typeStats} innerRadius={25} outerRadius={40} dataKey="value" paddingAngle={5}>
                            <Cell fill="#0d9488" />
                            <Cell fill="#f59e0b" />
                        </Pie>
                    </PieChart>
                </ResponsiveContainer>
            </div>
        </div>

        <InfographicCard 
          title="متوسط الأداء" 
          value={averageScore} 
          icon={Activity} 
          gradient="bg-gradient-to-br from-purple-700 to-purple-900"
          subtext="من 5.0"
        />

        {/* Critical Risks Card - Prominent Number */}
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-gradient-to-br from-red-600 to-red-800 text-white p-6">
            <div className="relative z-10">
                <div className="flex justify-between items-start">
                    <p className="text-red-100 font-medium text-lg">المخاطر الحرجة</p>
                    <div className="bg-white/20 p-2 rounded-lg"><AlertTriangle size={24} /></div>
                </div>
                <div className="flex items-baseline mt-4">
                    <h3 className="text-6xl font-extrabold tracking-tight">{riskMatrix.high}</h3>
                    <span className="mr-2 text-red-200 font-medium">حالة</span>
                </div>
                <p className="text-xs text-red-100 mt-2 opacity-80">تتطلب تدخلاً فورياً</p>
            </div>
             <div className="absolute -bottom-6 -left-6 w-32 h-32 bg-black/10 rounded-full blur-2xl"></div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Geographic Distribution - Vertical & Colored */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <MapPin className="text-teal-600" /> التوزيع الجغرافي (حسب المحافظة)
                </h3>
            </div>
            <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={govStats} margin={{ top: 20, right: 30, left: 20, bottom: 50 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <XAxis dataKey="name" angle={-45} textAnchor="end" interval={0} tick={{fontSize: 12, fill: '#4b5563'}} />
                        <YAxis axisLine={false} tickLine={false} />
                        <Tooltip cursor={{fill: '#f0f4f8'}} contentStyle={{borderRadius: '10px'}} />
                        <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                            {govStats.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.fill} />
                            ))}
                            <LabelList dataKey="value" position="top" fill="#374151" fontSize={14} fontWeight="bold" />
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>

        {/* Maturity Breakdown */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
          <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
             <TrendingUp className="text-blue-600" /> تصنيف الأداء
          </h3>
          <div className="h-64 relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={maturityStats}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                  stroke="none"
                >
                  {maturityStats.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                <span className="text-3xl font-bold text-navy-900">{evaluations.length}</span>
                <span className="text-xs text-gray-400">تقييم مكتمل</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Strategy Chart 2026-2030 */}
           <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <Target className="text-red-600" /> مسار النضج الاستراتيجي
                </h3>
            </div>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={STRATEGY_DATA} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                        <defs>
                            <linearGradient id="colorTarget" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#8884d8" stopOpacity={0.1}/>
                                <stop offset="95%" stopColor="#8884d8" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <XAxis dataKey="year" axisLine={false} tickLine={false} />
                        <YAxis domain={[0, 5]} axisLine={false} tickLine={false} />
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <Tooltip contentStyle={{borderRadius: '10px'}} />
                        <Area type="monotone" dataKey="target" stroke="#8884d8" strokeWidth={3} fillOpacity={1} fill="url(#colorTarget)" name="المستهدف" />
                        <Line type="monotone" dataKey="actual" stroke="#10b981" strokeWidth={3} dot={{r: 6}} name="الفعلي" />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

          {/* Radar Chart with Labels */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
                <Shield className="text-blue-600" /> توازن الأداء المؤسسي
            </h3>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <RadarChart cx="50%" cy="50%" outerRadius="70%" data={[
                        { subject: 'الشرعي', A: 4.2, fullMark: 5 },
                        { subject: 'الإداري', A: 3.5, fullMark: 5 },
                        { subject: 'المالي', A: 3.8, fullMark: 5 },
                        { subject: 'الحوكمة', A: 2.9, fullMark: 5 },
                        { subject: 'الابتكار', A: 2.1, fullMark: 5 },
                        { subject: 'الاستدامة', A: 4.0, fullMark: 5 },
                    ]}>
                        <PolarGrid />
                        <PolarAngleAxis dataKey="subject" tick={{ fill: '#4b5563', fontSize: 12, fontWeight: 'bold' }} />
                        <PolarRadiusAxis angle={30} domain={[0, 5]} tick={false} axisLine={false} />
                        <Radar name="الأداء الحالي" dataKey="A" stroke="#2563eb" fill="#3b82f6" fillOpacity={0.4} />
                        <Tooltip 
                            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                            formatter={(value) => [value, 'النتيجة']}
                        />
                    </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X } from 'lucide-react';

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<Partial<Institution>>({});

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name!,
      type: (formData.type as InstitutionType) || 'وقفية عامة',
      capital_omr: Number(formData.capital_omr) || 0,
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone || '',
      email: formData.email || '',
      governorate: formData.governorate || '',
      wilayat: formData.wilayat || '',
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
    }
  };

  const filtered = list.filter(i => i.name.includes(search));

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900">بيانات المؤسسات</h2>
        <button 
          onClick={() => { setFormData({}); setShowForm(true); }}
          className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900"
        >
          <Plus size={18} /> إضافة مؤسسة
        </button>
      </div>

      {/* Search */}
      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-right">
          <thead className="bg-gray-50 text-gray-600 font-medium">
            <tr>
              <th className="p-4">المؤسسة</th>
              <th className="p-4">النوع</th>
              <th className="p-4">رأس المال (ر.ع)</th>
              <th className="p-4">المحافظة / الولاية</th>
              <th className="p-4">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map(inst => (
              <tr key={inst.id} className="hover:bg-gray-50">
                <td className="p-4 font-medium text-navy-900">{inst.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded text-xs ${inst.type === 'وقفية عامة' ? 'bg-teal-100 text-teal-800' : 'bg-gold-100 text-gold-800'}`}>
                    {inst.type}
                  </span>
                </td>
                <td className="p-4 font-mono">{inst.capital_omr.toLocaleString()}</td>
                <td className="p-4">
                    <div className="text-sm">{inst.governorate}</div>
                    <div className="text-xs text-gray-500">{inst.wilayat}</div>
                </td>
                <td className="p-4 flex gap-2">
                  <button onClick={() => { setFormData(inst); setShowForm(true); }} className="text-blue-600 hover:text-blue-800">
                    <Edit2 size={18} />
                  </button>
                  <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800">
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={5} className="p-8 text-center text-gray-400">لا توجد مؤسسات مطابقة</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b flex justify-between items-center">
              <h3 className="text-xl font-bold">{formData.id ? 'تعديل مؤسسة' : 'إضافة مؤسسة جديدة'}</h3>
              <button onClick={() => setShowForm(false)}><X size={24} /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium mb-1">اسم المؤسسة *</label>
                <input required className="w-full p-2 border rounded" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">النوع *</label>
                <select className="w-full p-2 border rounded" value={formData.type || 'وقفية عامة'} onChange={e => setFormData({...formData, type: e.target.value as any})}>
                  <option value="وقفية عامة">وقفية عامة</option>
                  <option value="وقفية خاصة">وقفية خاصة</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">رأس المال (ر.ع) *</label>
                <input type="number" required className="w-full p-2 border rounded" value={formData.capital_omr || ''} onChange={e => setFormData({...formData, capital_omr: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_omani || ''} onChange={e => setFormData({...formData, employees_omani: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين غير العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_non_omani || ''} onChange={e => setFormData({...formData, employees_non_omani: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الهاتف *</label>
                <input required className="w-full p-2 border rounded" value={formData.contact_phone || ''} onChange={e => setFormData({...formData, contact_phone: e.target.value})} />
              </div>
               <div>
                <label className="block text-sm font-medium mb-1">المحافظة</label>
                <select className="w-full p-2 border rounded" value={formData.governorate || ''} onChange={e => setFormData({...formData, governorate: e.target.value, wilayat: ''})}>
                  <option value="">اختر...</option>
                  {GOVERNORATES.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الولاية</label>
                <select className="w-full p-2 border rounded" value={formData.wilayat || ''} onChange={e => setFormData({...formData, wilayat: e.target.value})} disabled={!formData.governorate}>
                  <option value="">اختر...</option>
                  {availableWilayats.map(w => <option key={w} value={w}>{w}</option>)}
                </select>
              </div>
              <div className="md:col-span-2 mt-4 flex justify-end gap-3">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">إلغاء</button>
                <button type="submit" className="px-6 py-2 bg-navy-800 text-white rounded hover:bg-navy-900">حفظ</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Institutions;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId } from '../services/db';
import { Institution, Indicator, Evaluation, Response } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp } from 'lucide-react';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    // Auto load default indicators
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    if (selectedInstId && indicators.length > 0) {
      // Find or Create Evaluation
      let ev = getEvaluationByInstAndYear(selectedInstId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [selectedInstId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة من الملف. هل أنت متأكد؟')) {
          // Expected columns: "المحور", "وصف التقييم"
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');

          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              alert(`تم استيراد ${newIndicators.length} مؤشر بنجاح`);
          } else {
              alert('لم يتم العثور على بيانات صالحة في الملف. تأكد من وجود أعمدة "المحور" و "وصف التقييم".');
          }
      }
    };
    reader.readAsBinaryString(file);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>

        <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md">
            <Upload size={18} /> تحديث المؤشرات (Excel)
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
        </label>
      </div>

      {/* Institution Selector */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة للتقييم ({CURRENT_YEAR})</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && indicators.length > 0 && (
        <div className="space-y-4 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300">
              <button 
                className={`w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors ${openAxis === axis ? 'bg-navy-50' : ''}`}
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold text-sm">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                {openAxis === axis ? <ChevronUp className="text-navy-800" /> : <ChevronDown className="text-gray-400" />}
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-6 bg-white border-t border-gray-100">
                  {grouped[axis].map(ind => (
                    <div key={ind.id} className="border-b border-gray-50 last:border-0 pb-4 last:pb-0">
                      <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                        <p className="text-gray-700 font-medium leading-relaxed flex-1">{ind.text}</p>

                        <div className="flex gap-2 shrink-0">
                            {[1, 2, 3, 4, 5].map(score => (
                            <button
                                key={score}
                                onClick={() => handleScore(ind.id, score)}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold border-2 transition-all shadow-sm ${
                                responses[ind.id]?.score === score
                                    ? `${RATING_COLORS[score]} scale-110 shadow-md ring-2 ring-offset-2 ring-gray-300`
                                    : 'bg-white text-gray-400 border-gray-200 hover:border-gray-400'
                                }`}
                            >
                                {score}
                            </button>
                            ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          <div className="sticky bottom-4 bg-navy-900 p-4 shadow-xl rounded-xl border border-navy-800 flex justify-between items-center z-20 text-white">
             <div>
                <span className="text-sm text-gray-300">تم تقييم {Object.keys(responses).length} من {indicators.length} مؤشر</span>
                <div className="w-48 h-2 bg-navy-700 rounded-full mt-2">
                    <div className="h-full bg-gold-500 rounded-full transition-all duration-500" style={{width: `${(Object.keys(responses).length / indicators.length) * 100}%`}}></div>
                </div>
             </div>
             <button className="bg-teal-600 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-lg font-bold">
                <Save size={18} /> حفظ التقييم
             </button>
          </div>
        </div>
      )}

      {(!selectedInstId) && (
        <div className="text-center py-20 bg-white rounded-xl border border-dashed border-gray-300">
           <div className="text-gray-400 mb-2">اختر مؤسسة من القائمة أعلاه للبدء في التقييم</div>
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getEvaluations, getResponses, getIndicators, generateImprovementPlan, getImprovements } from '../services/db';
import { Institution, Evaluation, ImprovementItem } from '../types';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Printer, AlertCircle, CheckCircle, Clock, ArrowUpCircle } from 'lucide-react';

const COLORS = ['#ef4444', '#f59e0b', '#10b981']; // High, Medium, Low priority colors

const Reports: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [reportData, setReportData] = useState<any>(null);
  const [improvements, setImprovements] = useState<ImprovementItem[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (!selectedInstId) return;

    // Generate Report Data
    const ev = getEvaluations().find(e => e.institution_id === selectedInstId);
    if (!ev) {
        setReportData(null);
        return;
    }

    const responses = getResponses(ev.id);
    const indicators = getIndicators();

    // Generate improvements if not exist
    generateImprovementPlan(ev.id, responses, indicators);
    setImprovements(getImprovements(ev.id));

    // Calculate Axis Averages for Radar
    const axisScores: Record<string, { total: number, count: number }> = {};
    responses.forEach(r => {
        const ind = indicators.find(i => i.id === r.indicator_id);
        if (ind) {
            if (!axisScores[ind.axis]) axisScores[ind.axis] = { total: 0, count: 0 };
            axisScores[ind.axis].total += r.score;
            axisScores[ind.axis].count += 1;
        }
    });

    const radarData = Object.keys(axisScores).map(axis => ({
        subject: axis,
        A: (axisScores[axis].total / axisScores[axis].count).toFixed(2),
        fullMark: 5
    }));

    setReportData({ radarData, evaluation: ev });

  }, [selectedInstId]);

  // Improvement Stats
  const improvementStats = [
      { name: 'عالية', value: improvements.filter(i => i.priority === 'High').length },
      { name: 'متوسطة', value: improvements.filter(i => i.priority === 'Medium').length },
      { name: 'منخفضة', value: improvements.filter(i => i.priority === 'Low').length },
  ].filter(i => i.value > 0);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900">التقارير وخطة التحسين</h2>
        {reportData && (
            <button onClick={() => window.print()} className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 shadow-md">
                <Printer size={18} /> طباعة التقرير
            </button>
        )}
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 no-print">
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة لعرض التقرير --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {reportData ? (
        <div className="space-y-8 animate-fadeIn">
            {/* Header for Print */}
            <div className="hidden print-only text-center border-b pb-4 mb-8">
                <h1 className="text-2xl font-bold text-navy-900">تقرير الأداء وخطة التحسين</h1>
                <p className="text-gray-500">وزارة الأوقاف والشؤون الدينية</p>
                <p className="mt-2 text-sm font-bold">المؤسسة: {institutions.find(i => i.id === selectedInstId)?.name}</p>
            </div>

            {/* Visual Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Radar Chart */}
                <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 page-break">
                    <h3 className="text-lg font-bold text-navy-900 mb-4 flex items-center gap-2">
                        <ArrowUpCircle className="text-teal-600" /> تحليل الفجوات (Radar)
                    </h3>
                    <div className="h-72">
                        <ResponsiveContainer width="100%" height="100%">
                            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={reportData.radarData}>
                                <PolarGrid />
                                <PolarAngleAxis dataKey="subject" tick={{fontSize: 12, fontWeight: 'bold'}} />
                                <PolarRadiusAxis angle={30} domain={[0, 5]} />
                                <Radar name="المؤسسة" dataKey="A" stroke="#0d9488" fill="#0d9488" fillOpacity={0.6} />
                                <Legend />
                            </RadarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Priorities Donut */}
                <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
                     <h3 className="text-lg font-bold text-navy-900 mb-4 flex items-center gap-2">
                         <AlertCircle className="text-orange-500" /> أولويات التحسين
                     </h3>
                     <div className="flex items-center justify-center h-72 relative">
                        {improvementStats.length > 0 ? (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={improvementStats} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                        {improvementStats.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Legend verticalAlign="bottom" height={36}/>
                                </PieChart>
                            </ResponsiveContainer>
                        ) : (
                            <div className="text-center text-gray-400">
                                <CheckCircle size={48} className="mx-auto mb-2 text-green-500 opacity-50" />
                                <p>أداء ممتاز، لا توجد بنود حرجة</p>
                            </div>
                        )}
                        <div className="absolute font-bold text-2xl text-navy-900">{improvements.length}</div>
                     </div>
                </div>
            </div>

            {/* Visual Improvement Cards (Grid) - Purely Visual, No Procedures */}
            <div className="mt-8 page-break">
                <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
                    <Clock className="text-blue-600" /> خطة التحسين التنفيذية
                </h3>

                {improvements.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {improvements.map(imp => {
                            // Define visual style based on priority
                            let statusColor = 'bg-gray-100 text-gray-600';
                            let statusText = 'متابعة';
                            let borderClass = 'border-l-4 border-l-gray-400';

                            if (imp.priority === 'High') {
                                statusColor = 'bg-red-100 text-red-700';
                                statusText = 'حرج / يتطلب تدخل فوري';
                                borderClass = 'border-l-4 border-l-red-500';
                            } else if (imp.priority === 'Medium') {
                                statusColor = 'bg-orange-100 text-orange-700';
                                statusText = 'خطر متوسط';
                                borderClass = 'border-l-4 border-l-orange-500';
                            } else {
                                statusColor = 'bg-yellow-100 text-yellow-700';
                                statusText = 'تحسين';
                                borderClass = 'border-l-4 border-l-yellow-500';
                            }

                            return (
                                <div key={imp.id} className={`bg-white p-5 rounded-lg shadow-sm hover:shadow-md transition-shadow ${borderClass}`}>
                                    <div className="flex justify-between items-center mb-3">
                                        <span className={`px-2 py-1 rounded-full text-xs font-bold ${statusColor}`}>
                                            {statusText}
                                        </span>
                                    </div>
                                    <h4 className="font-bold text-navy-900 text-sm mb-4 leading-relaxed">
                                        {imp.issue_summary.replace('انخفاض في المؤشر: ', '')}
                                    </h4>
                                    <div className="mt-auto pt-3 border-t border-gray-100 flex justify-between items-center">
                                        <span className="text-xs text-gray-400 font-medium">الإجراء:</span>
                                        <span className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">تحسين مطلوب</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="text-center py-10 bg-white rounded-xl border border-dashed border-gray-300">
                        <CheckCircle size={40} className="mx-auto text-green-500 mb-2" />
                        <p className="text-gray-500">لا توجد إجراءات تحسين مطلوبة حالياً.</p>
                    </div>
                )}
            </div>
        </div>
      ) : (
          <div className="text-center py-20 text-gray-400">
              {selectedInstId ? "لا يوجد تقييم لهذه المؤسسة بعد" : "اختر مؤسسة لعرض خطة التحسين"}
          </div>
      )}
    </div>
  );
};

export default Reports;

