// Mock Data for Strategy 2026-2030
const STRATEGY_DATA = [
    { year: '2025', actual: 3.2, target: 3.2 },
    { year: '2026', actual: null, target: 3.5 },
    { year: '2027', actual: null, target: 3.8 },
    { year: '2028', actual: null, target: 4.2 },
    { year: '2029', actual: null, target: 4.5 },
    { year: '2030', actual: null, target: 4.8 },
];

const Dashboard: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [compliance, setCompliance] = useState<any[]>([]);
  const [risks, setRisks] = useState<RiskRegisterItem[]>([]);
  const [responses, setResponses] = useState<Response[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions());
    setEvaluations(getEvaluations());
    setCompliance(getComplianceRecords());
    setRisks(getRisks());
    setResponses(getAllResponses());
  }, []);

  // 1. Institution Types Breakdown
  const typeStats = useMemo(() => {
      const general = institutions.filter(i => i.type === 'وقفية عامة').length;
      const special = institutions.filter(i => i.type === 'وقفية خاصة').length;
      return [
          { name: 'عامة', value: general },
          { name: 'خاصة', value: special }
      ];
  }, [institutions]);

  // 1.b Capital Stats
  const capitalStats = useMemo(() => {
      const total = institutions.reduce((acc, i) => acc + (i.capital_omr || 0), 0);

      // Breakdown by Range
      const ranges = [
          { name: '< 10k', value: 0, fill: '#60a5fa' },
          { name: '10k-50k', value: 0, fill: '#34d399' },
          { name: '50k-200k', value: 0, fill: '#facc15' },
          { name: '> 200k', value: 0, fill: '#f87171' },
      ];

      institutions.forEach(i => {
          const cap = i.capital_omr || 0;
          if (cap < 10000) ranges[0].value++;
          else if (cap < 50000) ranges[1].value++;
          else if (cap < 200000) ranges[2].value++;
          else ranges[3].value++;
      });

      return { total, ranges: ranges.filter(r => r.value > 0) };
  }, [institutions]);

  // 2. Risk Matrix
  const riskMatrix = useMemo(() => {
      let high = 0, med = 0, low = 0;
      risks.forEach(r => {
          const score = r.probability * r.impact;
          if (score >= 15) high++;
          else if (score >= 8) med++;
          else low++;
      });
      return { high, med, low, total: risks.length };
  }, [risks]);

  // 3. Gov Stats (Visual with unique colors)
  const govStats = useMemo(() => {
      const counts: Record<string, number> = {};
      GOVERNORATES.forEach(g => counts[g] = 0);
      institutions.forEach(i => {
          if (i.governorate && counts[i.governorate] !== undefined) {
              counts[i.governorate]++;
          }
      });
      return Object.keys(counts)
        .map((g, idx) => ({ name: g, value: counts[g], fill: GOV_COLORS[idx % GOV_COLORS.length] }))
        .sort((a, b) => b.value - a.value)
        .filter(g => g.value > 0);
  }, [institutions]);

  // 4. Maturity Stats
  const maturityStats = useMemo(() => {
    const stats = [
      { name: 'ممتاز', value: 0 },
      { name: 'جيد جداً', value: 0 },
      { name: 'جيد', value: 0 },
      { name: 'يحتاج تحسين', value: 0 },
      { name: 'ضعيف', value: 0 },
    ];

    const evalScores: Record<string, { total: number, count: number }> = {};
    responses.forEach(r => {
        if (!evalScores[r.evaluation_id]) evalScores[r.evaluation_id] = { total: 0, count: 0 };
        evalScores[r.evaluation_id].total += r.score;
        evalScores[r.evaluation_id].count++;
    });

    Object.values(evalScores).forEach(ev => {
        const avg = ev.total / ev.count;
        if (avg >= 4.5) stats[0].value++;
        else if (avg >= 3.5) stats[1].value++;
        else if (avg >= 2.5) stats[2].value++;
        else if (avg >= 1.5) stats[3].value++;
        else stats[4].value++;
    });

    return stats;
  }, [responses]);

  const averageScore = useMemo(() => {
      if (responses.length === 0) return 0;
      const total = responses.reduce((acc, r) => acc + r.score, 0);
      return (total / responses.length).toFixed(1);
  }, [responses]);

  return (
    <div className="space-y-8 pb-10">
      <div className="flex justify-between items-end mb-6">
         <div>
            <h2 className="text-3xl font-extrabold text-navy-900 tracking-tight">لوحة القيادة الاستراتيجية</h2>
            <p className="text-gray-500 mt-2 text-lg">نظرة شاملة على الأصول البشرية، المالية، ومستويات الأداء</p>
         </div>
      </div>

      {/* Hero Financial & HR KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">

        {/* Capital Size Card */}
        <InfographicCard 
          title="حجم رأس المال الوقفي" 
          value={`${(capitalStats.total / 1000000).toFixed(2)} M`} 
          icon={Coins} 
          gradient="bg-gradient-to-br from-indigo-900 to-navy-900"
          subtext="ر.ع (القيمة السوقية التقديرية)"
          footer={<span className="text-blue-200">النمو السنوي: +4.2%</span>}
        />

        {/* Public vs Private Visual Indicator */}
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-white p-6 border border-gray-100 flex items-center justify-between">
            <div className="w-1/2">
                <p className="text-gray-500 font-medium mb-1">توزيع المؤسسات</p>
                <div className="space-y-4 mt-4">
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-teal-600"></div>
                        <span className="text-navy-900 font-bold text-xl">{typeStats[0].value}</span>
                        <span className="text-xs text-gray-500">عامة</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-gold-500"></div>
                        <span className="text-navy-900 font-bold text-xl">{typeStats[1].value}</span>
                        <span className="text-xs text-gray-500">خاصة</span>
                    </div>
                </div>
            </div>
            <div className="w-1/2 h-32">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie data={typeStats} innerRadius={25} outerRadius={40} dataKey="value" paddingAngle={5}>
                            <Cell fill="#0d9488" />
                            <Cell fill="#f59e0b" />
                        </Pie>
                    </PieChart>
                </ResponsiveContainer>
            </div>
        </div>

        <InfographicCard 
          title="متوسط الأداء" 
          value={averageScore} 
          icon={Activity} 
          gradient="bg-gradient-to-br from-purple-700 to-purple-900"
          subtext="من 5.0"
        />

        {/* Critical Risks Card - Prominent Number */}
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-gradient-to-br from-red-600 to-red-800 text-white p-6">
            <div className="relative z-10">
                <div className="flex justify-between items-start">
                    <p className="text-red-100 font-medium text-lg">المخاطر الحرجة</p>
                    <div className="bg-white/20 p-2 rounded-lg"><AlertTriangle size={24} /></div>
                </div>
                <div className="flex items-baseline mt-4">
                    <h3 className="text-6xl font-extrabold tracking-tight">{riskMatrix.high}</h3>
                    <span className="mr-2 text-red-200 font-medium">حالة</span>
                </div>
                <p className="text-xs text-red-100 mt-2 opacity-80">تتطلب تدخلاً فورياً</p>
            </div>
             <div className="absolute -bottom-6 -left-6 w-32 h-32 bg-black/10 rounded-full blur-2xl"></div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Geographic Distribution - Vertical & Colored */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <MapPin className="text-teal-600" /> التوزيع الجغرافي (حسب المحافظة)
                </h3>
            </div>
            <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={govStats} margin={{ top: 20, right: 30, left: 20, bottom: 50 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <XAxis dataKey="name" angle={-45} textAnchor="end" interval={0} tick={{fontSize: 12, fill: '#4b5563'}} />
                        <YAxis axisLine={false} tickLine={false} />
                        <Tooltip cursor={{fill: '#f0f4f8'}} contentStyle={{borderRadius: '10px'}} />
                        <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                            {govStats.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.fill} />
                            ))}
                            <LabelList dataKey="value" position="top" fill="#374151" fontSize={14} fontWeight="bold" />
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>

        {/* Capital Distribution Breakdown */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
          <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
             <Wallet className="text-indigo-600" /> فئات رأس المال
          </h3>
          <div className="h-64 relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={capitalStats.ranges}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                  stroke="none"
                >
                  {capitalStats.ranges.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                <span className="text-lg font-bold text-navy-900">{institutions.length}</span>
                <span className="text-xs text-gray-400">مؤسسة</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Strategy Chart 2026-2030 */}
           <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <Target className="text-red-600" /> مسار النضج الاستراتيجي
                </h3>
            </div>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={STRATEGY_DATA} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                        <defs>
                            <linearGradient id="colorTarget" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#8884d8" stopOpacity={0.1}/>
                                <stop offset="95%" stopColor="#8884d8" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <XAxis dataKey="year" axisLine={false} tickLine={false} />
                        <YAxis domain={[0, 5]} axisLine={false} tickLine={false} />
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <Tooltip contentStyle={{borderRadius: '10px'}} />
                        <Area type="monotone" dataKey="target" stroke="#8884d8" strokeWidth={3} fillOpacity={1} fill="url(#colorTarget)" name="المستهدف" />
                        <Line type="monotone" dataKey="actual" stroke="#10b981" strokeWidth={3} dot={{r: 6}} name="الفعلي" />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

          {/* Radar Chart with Labels */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <h3 className="text-xl font-bold text-navy-900 mb-6 flex items-center gap-2">
                <Shield className="text-blue-600" /> توازن الأداء المؤسسي
            </h3>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <RadarChart cx="50%" cy="50%" outerRadius="70%" data={[
                        { subject: 'الشرعي', A: 4.2, fullMark: 5 },
                        { subject: 'الإداري', A: 3.5, fullMark: 5 },
                        { subject: 'المالي', A: 3.8, fullMark: 5 },
                        { subject: 'الحوكمة', A: 2.9, fullMark: 5 },
                        { subject: 'الابتكار', A: 2.1, fullMark: 5 },
                        { subject: 'الاستدامة', A: 4.0, fullMark: 5 },
                    ]}>
