export default Institutions;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId } from '../services/db';
import { Institution, Indicator, Evaluation, Response, InstitutionDocument } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp, Paperclip, FileText, X } from 'lucide-react';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    // Auto load default indicators
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    if (selectedInstId && indicators.length > 0) {
      // Find or Create Evaluation
      let ev = getEvaluationByInstAndYear(selectedInstId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          attachments: [],
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [selectedInstId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && evaluation) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };

          const updatedEval = { 
              ...evaluation, 
              attachments: [...(evaluation.attachments || []), newDoc] 
          };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
      }
  };

  const removeAttachment = (docId: string) => {
      if (!evaluation) return;
      const updatedEval = {
          ...evaluation,
          attachments: evaluation.attachments?.filter(d => d.id !== docId) || []
      };
      setEvaluation(updatedEval);
      saveEvaluation(updatedEval);
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة من الملف. هل أنت متأكد؟')) {
          // Expected columns: "المحور", "وصف التقييم"
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');

          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              alert(`تم استيراد ${newIndicators.length} مؤشر بنجاح`);
          } else {
              alert('لم يتم العثور على بيانات صالحة في الملف. تأكد من وجود أعمدة "المحور" و "وصف التقييم".');
          }
      }
    };
    reader.readAsBinaryString(file);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>

        <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md">
            <Upload size={18} /> تحديث المؤشرات (Excel)
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
        </label>
      </div>

      {/* Institution Selector */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة للتقييم ({CURRENT_YEAR})</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && indicators.length > 0 && (
        <div className="space-y-4 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300">
              <button 
                className={`w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors ${openAxis === axis ? 'bg-navy-50' : ''}`}
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold text-sm">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                {openAxis === axis ? <ChevronUp className="text-navy-800" /> : <ChevronDown className="text-gray-400" />}
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-6 bg-white border-t border-gray-100">
                  {grouped[axis].map(ind => (
                    <div key={ind.id} className="border-b border-gray-50 last:border-0 pb-4 last:pb-0">
                      <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                        <p className="text-gray-700 font-medium leading-relaxed flex-1">{ind.text}</p>

                        <div className="flex gap-2 shrink-0">
                            {[1, 2, 3, 4, 5].map(score => (
                            <button
                                key={score}
                                onClick={() => handleScore(ind.id, score)}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold border-2 transition-all shadow-sm ${
                                responses[ind.id]?.score === score
                                    ? `${RATING_COLORS[score]} scale-110 shadow-md ring-2 ring-offset-2 ring-gray-300`
                                    : 'bg-white text-gray-400 border-gray-200 hover:border-gray-400'
                                }`}
                            >
                                {score}
                            </button>
                            ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          {/* Action Bar */}
          <div className="sticky bottom-4 bg-navy-900 p-4 shadow-xl rounded-xl border border-navy-800 flex flex-col md:flex-row justify-between items-center z-20 text-white gap-4">
             <div>
                <span className="text-sm text-gray-300">تم تقييم {Object.keys(responses).length} من {indicators.length} مؤشر</span>
                <div className="w-48 h-2 bg-navy-700 rounded-full mt-2">
                    <div className="h-full bg-gold-500 rounded-full transition-all duration-500" style={{width: `${(Object.keys(responses).length / indicators.length) * 100}%`}}></div>
                </div>
             </div>

             <div className="flex items-center gap-4">
                 {/* Attachment Section */}
                 <div className="relative">
                     <label className="cursor-pointer bg-navy-700 hover:bg-navy-600 px-4 py-2 rounded-lg flex items-center gap-2 text-sm transition-colors">
                         <Paperclip size={16} /> إرفاق أدلة
                         <input type="file" className="hidden" onChange={handleFileUpload} />
                     </label>
                 </div>

                 <button onClick={() => alert('تم حفظ التقييم بنجاح في قاعدة البيانات')} className="bg-teal-600 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-lg font-bold">
                    <Save size={18} /> حفظ التقييم
                 </button>
             </div>
          </div>

          {/* Attachments List */}
          {evaluation?.attachments && evaluation.attachments.length > 0 && (
             <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
                 <h4 className="font-bold text-gray-700 mb-3 text-sm flex items-center gap-2"><Paperclip size={16}/> المرفقات والأدلة ({evaluation.attachments.length})</h4>
                 <div className="flex flex-wrap gap-2">
                     {evaluation.attachments.map(doc => (
                         <div key={doc.id} className="bg-gray-50 border border-gray-200 px-3 py-2 rounded-lg flex items-center gap-2 text-sm">
                             <FileText size={14} className="text-blue-500" />
                             <span className="truncate max-w-[150px]">{doc.name}</span>
                             <button onClick={() => removeAttachment(doc.id)} className="text-gray-400 hover:text-red-500"><X size={14}/></button>
                         </div>
                     ))}
                 </div>
             </div>
          )}
        </div>
      )}

      {(!selectedInstId) && (
        <div className="text-center py-20 bg-white rounded-xl border border-dashed border-gray-300">
           <div className="text-gray-400 mb-2">اختر مؤسسة من القائمة أعلاه للبدء في التقييم</div>
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import { Institution, Indicator, Evaluation, Response, ComplianceRecord, ImprovementItem, RiskRegisterItem } from '../types';
import { DEFAULT_INDICATORS } from '../constants';

const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const DB_KEYS = {
  INSTITUTIONS: 'waqf_institutions',
  INDICATORS: 'waqf_indicators',
  EVALUATIONS: 'waqf_evaluations',
  RESPONSES: 'waqf_responses',
  COMPLIANCE: 'waqf_compliance',
  IMPROVEMENTS: 'waqf_improvements',
  RISKS: 'waqf_risks',
  SETTINGS: 'waqf_settings'
};

// --- Generic Helper ---
const data = <T>(key: string): T[] => {
  const stored = localStorage.getItem(key);
  return stored ? JSON.parse(stored) : [];
};

const save = <T>(key: string, items: T[]) => {
  localStorage.setItem(key, JSON.stringify(items));
};

// --- Settings ---
export const getSettings = () => {
    const stored = localStorage.getItem(DB_KEYS.SETTINGS);
    return stored ? JSON.parse(stored) : { 
        managerName: 'د. عبدالرحمن النوفلي', 
        darkMode: false,
        orgName: 'وزارة الأوقاف والشؤون الدينية'
    };
};

export const saveSettings = (settings: any) => {
    localStorage.setItem(DB_KEYS.SETTINGS, JSON.stringify(settings));
    window.dispatchEvent(new Event('settingsChanged'));
};

// --- Institutions ---
export const getInstitutions = (): Institution[] => data<Institution>(DB_KEYS.INSTITUTIONS);
export const saveInstitution = (inst: Institution) => {
  const list = getInstitutions();
  const index = list.findIndex(i => i.id === inst.id);
  if (index >= 0) list[index] = inst;
  else list.push(inst);
  save(DB_KEYS.INSTITUTIONS, list);
};
export const deleteInstitution = (id: string) => {
  const list = getInstitutions().filter(i => i.id !== id);
  save(DB_KEYS.INSTITUTIONS, list);
};

// --- Indicators (Imported from Excel or Defaults) ---
export const getIndicators = (): Indicator[] => {
  const stored = data<Indicator>(DB_KEYS.INDICATORS);
  if (stored.length === 0) {
    save(DB_KEYS.INDICATORS, DEFAULT_INDICATORS);
    return DEFAULT_INDICATORS;
  }
  return stored;
};

export const saveIndicators = (indicators: Indicator[]) => {
  save(DB_KEYS.INDICATORS, indicators);
};

// --- Evaluations ---
export const getEvaluations = (year?: number): Evaluation[] => {
  const evals = data<Evaluation>(DB_KEYS.EVALUATIONS);
  if (year) return evals.filter(e => e.cycle_year === year);
  return evals;
};
export const getEvaluationByInstAndYear = (instId: string, year: number) => {
  return getEvaluations().find(e => e.institution_id === instId && e.cycle_year === year);
};
export const saveEvaluation = (evalObj: Evaluation) => {
  const list = getEvaluations();
  const index = list.findIndex(e => e.id === evalObj.id);
  if (index >= 0) list[index] = evalObj;
  else list.push(evalObj);
  save(DB_KEYS.EVALUATIONS, list);
};

// --- Responses ---
export const getResponses = (evalId: string): Response[] => {
  return data<Response>(DB_KEYS.RESPONSES).filter(r => r.evaluation_id === evalId);
};
export const getAllResponses = (): Response[] => {
  return data<Response>(DB_KEYS.RESPONSES);
};
export const saveResponse = (response: Response) => {
  const list = data<Response>(DB_KEYS.RESPONSES);
  const index = list.findIndex(r => r.evaluation_id === response.evaluation_id && r.indicator_id === response.indicator_id);
  if (index >= 0) {
    list[index] = { ...list[index], ...response, updated_at: new Date().toISOString() };
  } else {
    list.push({ ...response, id: generateId(), updated_at: new Date().toISOString() });
  }
  save(DB_KEYS.RESPONSES, list);
};

// --- Compliance ---
export const getComplianceRecords = (year?: number): ComplianceRecord[] => {
  const recs = data<ComplianceRecord>(DB_KEYS.COMPLIANCE);
  if (year) return recs.filter(r => r.cycle_year === year);
  return recs;
};
export const getComplianceByInstAndYear = (instId: string, year: number): ComplianceRecord | undefined => {
    return getComplianceRecords(year).find(r => r.institution_id === instId);
}
export const saveComplianceRecord = (record: ComplianceRecord) => {
  const list = data<ComplianceRecord>(DB_KEYS.COMPLIANCE);
  const index = list.findIndex(r => r.id === record.id);
  if (index >= 0) list[index] = record;
  else list.push(record);
  save(DB_KEYS.COMPLIANCE, list);
};

// --- Risks ---
export const getRisks = (instId?: string): RiskRegisterItem[] => {
    const all = data<RiskRegisterItem>(DB_KEYS.RISKS);
    if (instId) return all.filter(r => r.institution_id === instId);
    return all;
};
export const saveRisk = (risk: RiskRegisterItem) => {
    const list = data<RiskRegisterItem>(DB_KEYS.RISKS);
    const index = list.findIndex(r => r.id === risk.id);
    if (index >= 0) list[index] = risk;
    else list.push(risk);
    save(DB_KEYS.RISKS, list);
};
export const deleteRisk = (id: string) => {
    const list = data<RiskRegisterItem>(DB_KEYS.RISKS).filter(r => r.id !== id);
    save(DB_KEYS.RISKS, list);
};


// --- Improvements ---
export const getImprovements = (evalId: string): ImprovementItem[] => {
    return data<ImprovementItem>(DB_KEYS.IMPROVEMENTS).filter(i => i.evaluation_id === evalId);
};
export const saveImprovement = (item: ImprovementItem) => {
    const list = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS);
    const index = list.findIndex(i => i.id === item.id);
    if (index >= 0) list[index] = item;
    else list.push(item);
    save(DB_KEYS.IMPROVEMENTS, list);
};
export const generateImprovementPlan = (evalId: string, responses: Response[], indicators: Indicator[]) => {
    // Auto-generate items based on low scores
    const weak = responses.filter(r => r.score < 3.5);
    const existing = getImprovements(evalId);

    // Only add if not already exists for this indicator
    const newItems: ImprovementItem[] = [];
    weak.forEach(resp => {
        if (!existing.find(ex => ex.indicator_id === resp.indicator_id)) {
            const ind = indicators.find(i => i.id === resp.indicator_id);
            if (ind) {
                newItems.push({
                    id: generateId(),
                    evaluation_id: evalId,
                    indicator_id: ind.id,
                    priority: resp.score < 2.5 ? 'High' : 'Medium',
                    issue_summary: `انخفاض في المؤشر: ${ind.text}`,
                    recommended_action: 'مراجعة السياسات والإجراءات وتحديد خطة تصحيحية.',
                    owner: 'الإدارة التنفيذية',
                    due_date: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
                    status: 'ToDo',
                    notes: ''
                });
            }
        }
    });

    if (newItems.length > 0) {
        const fullList = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS);
        fullList.push(...newItems);
        save(DB_KEYS.IMPROVEMENTS, fullList);
    }
};

export { generateId };

import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { LayoutDashboard, Building2, ClipboardCheck, Scale, FileBarChart, Menu, X, ShieldAlert, Settings } from 'lucide-react';
import { getSettings } from '../services/db';

const SidebarItem = ({ to, icon: Icon, label, active }: any) => (
  <Link to={to} className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-colors duration-200 ${active ? 'bg-navy-800 text-gold-400' : 'text-white hover:bg-navy-800/50'}`}>
