                </td>
                <td className="p-4 font-mono dark:text-gray-300">{inst.capital_omr.toLocaleString()}</td>
                <td className="p-4 text-sm dark:text-gray-300">{inst.manager_name || '-'}</td>
                <td className="p-4">
                    <div className="text-sm dark:text-gray-300">{inst.governorate}</div>
                    <div className="text-xs text-gray-500">{inst.wilayat}</div>
                </td>
                <td className="p-4 flex gap-2">
                  <button onClick={() => { setFormData(inst); setShowForm(true); }} className="text-blue-600 hover:text-blue-800">
                    <Edit2 size={18} />
                  </button>
                  <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800">
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={6} className="p-8 text-center text-gray-400">لا توجد مؤسسات مطابقة</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold">{formData.id ? 'تعديل مؤسسة' : 'إضافة مؤسسة جديدة'}</h3>
              <button onClick={() => setShowForm(false)}><X size={24} /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

              {/* Basic Info Section */}
              <div className="lg:col-span-3 pb-2 border-b mb-2">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><FileText size={18}/> البيانات الأساسية</h4>
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium mb-1">اسم المؤسسة *</label>
                <input required className="w-full p-2 border rounded" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">النوع *</label>
                <select className="w-full p-2 border rounded" value={formData.type || 'وقفية عامة'} onChange={e => setFormData({...formData, type: e.target.value as any})}>
                  <option value="وقفية عامة">وقفية عامة</option>
                  <option value="وقفية خاصة">وقفية خاصة</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">تاريخ التأسيس</label>
                <div className="relative">
                    <Calendar className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input type="date" className="w-full p-2 pr-8 border rounded" value={formData.establishment_date || ''} onChange={e => setFormData({...formData, establishment_date: e.target.value})} />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">رقم السجل/الترخيص</label>
                <div className="relative">
                    <Hash className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input type="text" className="w-full p-2 pr-8 border rounded" value={formData.license_number || ''} onChange={e => setFormData({...formData, license_number: e.target.value})} />
                </div>
              </div>

              {/* Management & Location */}
              <div className="lg:col-span-3 pb-2 border-b mb-2 mt-4">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><User size={18}/> الإدارة والموقع</h4>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">مدير المؤسسة</label>
                <input type="text" className="w-full p-2 border rounded" value={formData.manager_name || ''} onChange={e => setFormData({...formData, manager_name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">رقم الهاتف *</label>
                <input required className="w-full p-2 border rounded" value={formData.contact_phone || ''} onChange={e => setFormData({...formData, contact_phone: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">البريد الإلكتروني</label>
                <input type="email" className="w-full p-2 border rounded" value={formData.email || ''} onChange={e => setFormData({...formData, email: e.target.value})} />
              </div>
               <div>
                <label className="block text-sm font-medium mb-1">المحافظة</label>
                <select className="w-full p-2 border rounded" value={formData.governorate || ''} onChange={e => setFormData({...formData, governorate: e.target.value, wilayat: ''})}>
                  <option value="">اختر...</option>
                  {GOVERNORATES.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الولاية</label>
                <select className="w-full p-2 border rounded" value={formData.wilayat || ''} onChange={e => setFormData({...formData, wilayat: e.target.value})} disabled={!formData.governorate}>
                  <option value="">اختر...</option>
                  {availableWilayats.map(w => <option key={w} value={w}>{w}</option>)}
                </select>
              </div>

              {/* Financial & HR */}
              <div className="lg:col-span-3 pb-2 border-b mb-2 mt-4">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><Hash size={18}/> البيانات المالية والبشرية</h4>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">رأس المال (ر.ع) *</label>
                <input type="number" required className="w-full p-2 border rounded" value={formData.capital_omr || ''} onChange={e => setFormData({...formData, capital_omr: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_omani || ''} onChange={e => setFormData({...formData, employees_omani: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين غير العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_non_omani || ''} onChange={e => setFormData({...formData, employees_non_omani: Number(e.target.value)})} />
              </div>

              {/* Document Upload */}
              <div className="lg:col-span-3 border-t pt-4 mt-2">
                   <h4 className="font-bold text-sm mb-3">ملفات المؤسسة (السجل التجاري، الصكوك...)</h4>
                   <div className="flex gap-2 mb-3">
                       <label className="cursor-pointer bg-gray-100 hover:bg-gray-200 text-gray-600 px-4 py-2 rounded-lg flex items-center gap-2 text-sm border border-gray-300">
                           <UploadCloud size={16} /> رفع ملف
                           <input type="file" className="hidden" onChange={handleFileUpload} />
                       </label>
                   </div>
                   {formData.documents && formData.documents.length > 0 && (
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                           {formData.documents.map((doc, idx) => (
                               <div key={idx} className="flex justify-between items-center bg-gray-50 p-2 rounded border">
                                   <div className="flex items-center gap-2">
                                       <FileText size={16} className="text-blue-500" />
                                       <span className="text-sm truncate max-w-[150px]">{doc.name}</span>
                                       <span className="text-xs text-gray-400">({doc.size})</span>
                                   </div>
                                   <button type="button" onClick={() => setFormData(p => ({...p, documents: p.documents?.filter((_, i) => i !== idx)}))} className="text-red-500 hover:text-red-700">
                                       <X size={16} />
                                   </button>
                               </div>
                           ))}
                       </div>
                   )}
              </div>

              <div className="lg:col-span-3 mt-4 flex justify-end gap-3 pt-4 border-t">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">إلغاء</button>
                <button type="submit" className="px-6 py-2 bg-navy-800 text-white rounded hover:bg-navy-900 shadow-lg">حفظ المؤسسة</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Institutions;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId } from '../services/db';
import { Institution, Indicator, Evaluation, Response, InstitutionDocument } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp, Paperclip, FileText, X, PlusCircle, PieChart as PieIcon, Trash2 } from 'lucide-react';
import { useUi } from '../contexts/UiContext';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});
  const { showToast } = useUi();

  // New Indicator Modal State
  const [showAddInd, setShowAddInd] = useState(false);
  const [newInd, setNewInd] = useState<Partial<Indicator>>({ axis: 'عام', weight: 1 });

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    // Auto load default indicators
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    if (selectedInstId && indicators.length > 0) {
      // Find or Create Evaluation
      let ev = getEvaluationByInstAndYear(selectedInstId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          attachments: [],
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [selectedInstId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  const handleAddIndicator = () => {
      if(!newInd.text || !newInd.axis) return;

      const indicator: Indicator = {
          id: `IND-MANUAL-${generateId().substr(0,4)}`,
          axis: newInd.axis,
          text: newInd.text,
          weight: newInd.weight || 1,
          active: true
      };

      const updatedList = [...indicators, indicator];
      setIndicators(updatedList);
      saveIndicators(updatedList);
      setShowAddInd(false);
      setNewInd({ axis: 'عام', weight: 1 });
      showToast('تم إضافة المؤشر الجديد بنجاح', 'success');
  };

  const handleDeleteIndicator = (id: string) => {
      if(confirm('هل أنت متأكد من حذف هذا المؤشر؟ سيتم حذفه من القائمة.')) {
          const updatedList = indicators.filter(i => i.id !== id);
          setIndicators(updatedList);
          saveIndicators(updatedList);
          showToast('تم حذف المؤشر', 'info');
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && evaluation) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };

          const updatedEval = { 
              ...evaluation, 
              attachments: [...(evaluation.attachments || []), newDoc] 
          };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم إرفاق الدليل بنجاح', 'success');
      }
  };

  const removeAttachment = (docId: string) => {
      if (!evaluation) return;
      const updatedEval = {
          ...evaluation,
          attachments: evaluation.attachments?.filter(d => d.id !== docId) || []
      };
      setEvaluation(updatedEval);
      saveEvaluation(updatedEval);
      showToast('تم حذف المرفق', 'info');
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة من الملف. هل أنت متأكد؟')) {
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');

          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              showToast(`تم استيراد ${newIndicators.length} مؤشر بنجاح`, 'success');
          } else {
              showToast('لم يتم العثور على بيانات صالحة في الملف.', 'error');
          }
      }
    };
    reader.readAsBinaryString(file);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  // Performance Pie Data
  const responseValues = Object.values(responses) as Response[];
  const performanceData = [
      { name: 'منخفض (1-2)', value: responseValues.filter(r => r.score <= 2).length, fill: '#ef4444' },
      { name: 'متوسط (3)', value: responseValues.filter(r => r.score === 3).length, fill: '#f59e0b' },
      { name: 'مرتفع (4-5)', value: responseValues.filter(r => r.score >= 4).length, fill: '#10b981' },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-6 relative pb-24">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>

        <div className="flex gap-2">
            <button onClick={() => setShowAddInd(true)} className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50 shadow-sm">
                <PlusCircle size={18} /> مؤشر يدوي
            </button>
            <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md">
                <Upload size={18} /> تحديث (Excel)
                <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
            </label>
        </div>
      </div>

      {/* Institution Selector */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة للتقييم ({CURRENT_YEAR})</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {/* Add Indicator Modal */}
      {showAddInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl">
                  <h3 className="text-lg font-bold mb-4">إضافة مؤشر جديد</h3>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium mb-1">المحور</label>
                          <select className="w-full border p-2 rounded" value={newInd.axis} onChange={e => setNewInd({...newInd, axis: e.target.value})}>
                              {Object.keys(grouped).map(a => <option key={a} value={a}>{a}</option>)}
                              <option value="محور جديد">محور جديد (اكتب أدناه)</option>
                          </select>
                          {newInd.axis === 'محور جديد' && (
                              <input type="text" placeholder="اكتب اسم المحور الجديد" className="w-full border p-2 rounded mt-2" onChange={e => setNewInd({...newInd, axis: e.target.value})} />
                          )}
                      </div>
                      <div>
                          <label className="block text-sm font-medium mb-1">نص المؤشر</label>
                          <textarea className="w-full border p-2 rounded h-24" value={newInd.text} onChange={e => setNewInd({...newInd, text: e.target.value})}></textarea>
                      </div>
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowAddInd(false)} className="px-4 py-2 text-gray-600">إلغاء</button>
                      <button onClick={handleAddIndicator} className="px-4 py-2 bg-navy-800 text-white rounded">إضافة</button>
                  </div>
              </div>
          </div>
      )}

      {selectedInstId && indicators.length > 0 && (
        <div className="space-y-4 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300">
              <button 
                className={`w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors ${openAxis === axis ? 'bg-navy-50' : ''}`}
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold text-sm">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                {openAxis === axis ? <ChevronUp className="text-navy-800" /> : <ChevronDown className="text-gray-400" />}
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-6 bg-white border-t border-gray-100">
                  {grouped[axis].map(ind => (
                    <div key={ind.id} className="border-b border-gray-50 last:border-0 pb-4 last:pb-0">
                      <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                        <div className="flex gap-3 flex-1">
                            <button onClick={() => handleDeleteIndicator(ind.id)} className="text-gray-300 hover:text-red-500 mt-1">
                                <Trash2 size={16} />
                            </button>
                            <p className="text-gray-700 font-medium leading-relaxed">{ind.text}</p>
                        </div>

                        <div className="flex gap-2 shrink-0">
                            {[1, 2, 3, 4, 5].map(score => (
                            <button
                                key={score}
                                onClick={() => handleScore(ind.id, score)}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold border-2 transition-all shadow-sm ${
                                responses[ind.id]?.score === score
                                    ? `${RATING_COLORS[score]} scale-110 shadow-md ring-2 ring-offset-2 ring-gray-300`
                                    : 'bg-white text-gray-400 border-gray-200 hover:border-gray-400'
                                }`}
                            >
                                {score}
                            </button>
                            ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          {/* Action Bar & Stats Footer */}
          <div className="fixed bottom-0 left-0 right-0 lg:right-64 bg-white border-t shadow-[0_-4px_10px_rgba(0,0,0,0.1)] p-4 flex flex-col md:flex-row justify-between items-center z-40 gap-4">
             <div className="flex items-center gap-6">
                <div>
                    <span className="text-sm text-gray-500 block">تقدم التقييم</span>
                    <span className="font-bold text-navy-900">{Object.keys(responses).length} / {indicators.length}</span>
                </div>

                {/* Mini Pie Chart for Score Breakdown */}
                {performanceData.length > 0 && (
                    <div className="flex items-center gap-3 border-r pr-6 mr-2">
                         <div className="w-10 h-10 relative">
                             <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={performanceData} dataKey="value" innerRadius={10} outerRadius={20} stroke="none">
                                        {performanceData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.fill} />
                                        ))}
                                    </Pie>
                                </PieChart>
                             </ResponsiveContainer>
                         </div>
                         <div className="text-xs space-y-0.5">
                             {performanceData.map(d => (
                                 <div key={d.name} className="flex items-center gap-1">
                                     <span className="w-2 h-2 rounded-full" style={{backgroundColor: d.fill}}></span>
                                     <span className="text-gray-600">{d.value}</span>
                                 </div>
                             ))}
                         </div>
                    </div>
                )}
             </div>

             <div className="flex items-center gap-4">
                 <div className="relative">
                     <label className="cursor-pointer bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 text-sm transition-colors">
                         <Paperclip size={16} /> إرفاق أدلة
                         <input type="file" className="hidden" onChange={handleFileUpload} />
                     </label>
                 </div>

                 <button onClick={() => showToast('تم حفظ التقييم بنجاح في قاعدة البيانات', 'success')} className="bg-teal-600 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-lg font-bold">
                    <Save size={18} /> حفظ نهائي
                 </button>
             </div>
          </div>

          {/* Attachments List */}
          {evaluation?.attachments && evaluation.attachments.length > 0 && (
             <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200 mb-20">
                 <h4 className="font-bold text-gray-700 mb-3 text-sm flex items-center gap-2"><Paperclip size={16}/> المرفقات والأدلة ({evaluation.attachments.length})</h4>
                 <div className="flex flex-wrap gap-2">
                     {evaluation.attachments.map(doc => (
                         <div key={doc.id} className="bg-gray-50 border border-gray-200 px-3 py-2 rounded-lg flex items-center gap-2 text-sm">
                             <FileText size={14} className="text-blue-500" />
                             <span className="truncate max-w-[150px]">{doc.name}</span>
                             <button onClick={() => removeAttachment(doc.id)} className="text-gray-400 hover:text-red-500"><X size={14}/></button>
                         </div>
                     ))}
                 </div>
             </div>
          )}
        </div>
      )}

      {(!selectedInstId) && (
        <div className="text-center py-20 bg-white rounded-xl border border-dashed border-gray-300">
           <div className="text-gray-400 mb-2">اختر مؤسسة من القائمة أعلاه للبدء في التقييم</div>
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, getComplianceByInstAndYear, getRisks, saveRisk, deleteRisk } from '../services/db';
import { Institution, ComplianceRecord, RiskRegisterItem, CustomRequirement } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Save, AlertTriangle, CheckCircle, Info, ShieldAlert, Plus, Trash2, Scale, X } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

const CompliancePage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'compliance' | 'risks'>('compliance');
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');
  const { showToast } = useUi();

  // Compliance State
  const [record, setRecord] = useState<Partial<ComplianceRecord>>({});
  const [newReqText, setNewReqText] = useState('');
  const [showAddReq, setShowAddReq] = useState(false);

  // Risk Register State
  const [instRisks, setInstRisks] = useState<RiskRegisterItem[]>([]);
  const [newRisk, setNewRisk] = useState<Partial<RiskRegisterItem>>({});
  const [showRiskForm, setShowRiskForm] = useState(false);

  // Real-time calculated risk based on compliance form
  const complianceRisk = calculateRiskScore(record);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (selectedInstId) {
        // Load Compliance
        const existing = getComplianceByInstAndYear(selectedInstId, CURRENT_YEAR);
        if (existing) {
            setRecord(existing);
        } else {
            setRecord({
                institution_id: selectedInstId,
                cycle_year: CURRENT_YEAR,
                institution_status: 'فاعلة',
                board_status: 'قائم',
                has_executive_management: false,
                has_auditor_company: false,
                has_minutes_prev_year: false,
                has_financial_report_prev_year: false,
                custom_requirements: [],
                notes: ''
            });
        }

        // Load Risks
        setInstRisks(getRisks(selectedInstId));
    } else {
        setRecord({});
        setInstRisks([]);
    }
  }, [selectedInstId]);

  const handleSaveCompliance = () => {
      if (!selectedInstId) return;
      const toSave: ComplianceRecord = {
          ...record as ComplianceRecord,
          id: record.id || generateId(),
          institution_id: selectedInstId,
          cycle_year: CURRENT_YEAR,
          last_updated_at: new Date().toISOString()
      };
      saveComplianceRecord(toSave);
      showToast('تم حفظ سجل الامتثال بنجاح', 'success');
  };

  const handleAddRequirement = () => {
      if (!newReqText) return;
      const newReq: CustomRequirement = {
          id: generateId(),
          text: newReqText,
          met: false
      };
      setRecord(prev => ({
          ...prev,
          custom_requirements: [...(prev.custom_requirements || []), newReq]
      }));
      setNewReqText('');
      setShowAddReq(false);
  };

  const handleRemoveRequirement = (id: string) => {
      setRecord(prev => ({
          ...prev,
          custom_requirements: prev.custom_requirements?.filter(r => r.id !== id)
      }));
  };

  const toggleCustomRequirement = (id: string) => {
      setRecord(prev => ({
          ...prev,
          custom_requirements: prev.custom_requirements?.map(r => r.id === id ? { ...r, met: !r.met } : r)
      }));
  };

  const handleSaveRisk = () => {
      if (!selectedInstId || !newRisk.risk_title) return;
      const riskToSave: RiskRegisterItem = {
          id: generateId(),
          institution_id: selectedInstId,
          risk_title: newRisk.risk_title,
          category: newRisk.category || 'Operational',
          probability: Number(newRisk.probability) || 1,
          impact: Number(newRisk.impact) || 1,
          mitigation_plan: newRisk.mitigation_plan || '',
          status: 'Open'
      };
      saveRisk(riskToSave);
      setInstRisks(getRisks(selectedInstId));
      setShowRiskForm(false);
      setNewRisk({});
      showToast('تم إضافة الخطر بنجاح', 'success');
  };

  const handleDeleteRisk = (id: string) => {
      if(confirm('حذف هذا الخطر؟')) {
          deleteRisk(id);
          setInstRisks(getRisks(selectedInstId));
          showToast('تم حذف الخطر', 'info');
      }
  };

  const updateComplianceField = (field: keyof ComplianceRecord, value: any) => {
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900">إدارة المخاطر والامتثال ({CURRENT_YEAR})</h2>
      </div>

      {/* Selection */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <label className="block text-sm font-medium mb-2 text-gray-700">اختر المؤسسة</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && (
          <div className="animate-fadeIn">
              {/* Tabs */}
              <div className="flex border-b border-gray-200 mb-6">
                  <button 
                    onClick={() => setActiveTab('compliance')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'compliance' ? 'border-b-2 border-navy-800 text-navy-900' : 'text-gray-500 hover:text-navy-700'}`}
                  >
                      <span className="flex items-center gap-2"><Scale size={16} /> الامتثال النظامي</span>
                  </button>
                  <button 
                    onClick={() => setActiveTab('risks')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'risks' ? 'border-b-2 border-navy-800 text-navy-900' : 'text-gray-500 hover:text-navy-700'}`}
                  >
                      <span className="flex items-center gap-2"><ShieldAlert size={16} /> سجل المخاطر</span>
                  </button>
              </div>

              {/* COMPLIANCE TAB */}
              {activeTab === 'compliance' && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">
                        {/* Status Card */}
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <h3 className="font-bold text-navy-900 mb-4 flex items-center gap-2">
                                <Info size={20} className="text-teal-600" /> الحالة الأساسية
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm text-gray-500 mb-1">حالة المؤسسة</label>
                                    <select className="w-full p-2 border rounded-lg bg-gray-50" value={record.institution_status} onChange={(e) => updateComplianceField('institution_status', e.target.value)}>
                                        <option value="فاعلة">فاعلة</option>
                                        <option value="غير فاعلة">غير فاعلة</option>
                                        <option value="قيد التصفية">قيد التصفية</option>
                                        <option value="متوقفة">متوقفة</option>
                                        <option value="أخرى">أخرى</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm text-gray-500 mb-1">حالة مجلس الإدارة</label>
                                    <select className="w-full p-2 border rounded-lg bg-gray-50" value={record.board_status} onChange={(e) => updateComplianceField('board_status', e.target.value)}>
                                        <option value="قائم">قائم</option>
                                        <option value="منتهي">منتهي الصلاحية</option>
                                        <option value="غير موجود">غير موجود</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Requirements */}
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <h3 className="font-bold text-navy-900 mb-4 flex items-center gap-2">
                                <CheckCircle size={20} className="text-teal-600" /> المتطلبات النظامية
                            </h3>
                            <div className="space-y-4">
                                <ToggleItem label="هل توجد إدارة تنفيذية أو مدير؟" checked={record.has_executive_management} onChange={(v) => updateComplianceField('has_executive_management', v)} />
                                <ToggleItem label="هل تم تعيين شركة تدقيق؟" checked={record.has_auditor_company} onChange={(v) => updateComplianceField('has_auditor_company', v)} />
                                <ToggleItem label="هل توجد محاضر اجتماعات للعام الماضي؟" checked={record.has_minutes_prev_year} onChange={(v) => updateComplianceField('has_minutes_prev_year', v)} />
                                <ToggleItem label="هل يوجد تقرير مالي معتمد للعام الماضي؟" checked={record.has_financial_report_prev_year} onChange={(v) => updateComplianceField('has_financial_report_prev_year', v)} />
                            </div>

                            {/* Custom Requirements Section */}
                            <div className="mt-8 pt-4 border-t border-gray-100">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="font-bold text-gray-800 text-sm">متطلبات إضافية</h4>
                                    <button onClick={() => setShowAddReq(true)} className="text-blue-600 text-xs flex items-center gap-1 hover:underline"><Plus size={14}/> إضافة متطلب</button>
                                </div>

                                {showAddReq && (
                                    <div className="flex gap-2 mb-4 animate-fadeIn">
                                        <input 
                                            type="text" 
                                            className="flex-1 border p-2 rounded text-sm" 
                                            placeholder="اكتب المتطلب الجديد..." 
                                            value={newReqText} 
                                            onChange={e => setNewReqText(e.target.value)} 
                                        />
                                        <button onClick={handleAddRequirement} className="bg-navy-800 text-white px-3 py-1 rounded text-sm">إضافة</button>
                                        <button onClick={() => setShowAddReq(false)} className="text-gray-500 px-2"><X size={16}/></button>
                                    </div>
                                )}

                                <div className="space-y-2">
                                    {record.custom_requirements?.map(req => (
                                        <div key={req.id} className="flex items-center justify-between group">
                                            <ToggleItem label={req.text} checked={req.met} onChange={() => toggleCustomRequirement(req.id)} className="flex-1" />
                                            <button onClick={() => handleRemoveRequirement(req.id)} className="mr-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    ))}
                                    {(!record.custom_requirements || record.custom_requirements.length === 0) && (
                                        <p className="text-xs text-gray-400 text-center py-2">لا توجد متطلبات إضافية</p>
                                    )}
                                </div>
                            </div>
                        </div>

                        <button onClick={handleSaveCompliance} className="w-full bg-navy-800 text-white p-4 rounded-xl font-bold shadow-lg hover:bg-navy-900 flex justify-center items-center gap-2">
                            <Save size={20} /> حفظ سجل الامتثال
                        </button>
                    </div>

                    {/* Sidebar Risk */}
                    <div className="lg:col-span-1">
                        <div className={`sticky top-6 p-6 rounded-xl border ${complianceRisk.score >= 6 ? 'bg-red-50 border-red-200' : 'bg-green-50 border-green-200'}`}>
                            <h3 className="text-lg font-bold text-navy-900 mb-2">تحليل المخاطر (الامتثال)</h3>
                            <div className="flex items-center gap-3 mb-6">
                                <div className={`text-4xl font-bold ${complianceRisk.score >= 6 ? 'text-red-600' : 'text-green-600'}`}>{complianceRisk.score}</div>
                                <div><div className="text-xs text-gray-500 uppercase">نقاط الخطر</div><div className={`font-bold ${complianceRisk.score >= 6 ? 'text-red-700' : 'text-green-700'}`}>{complianceRisk.label}</div></div>
                            </div>
                            <div className="space-y-3">
                                <RiskIndicator label="مجلس الإدارة" active={record.board_status !== 'قائم'} points={3} />
                                <RiskIndicator label="الإدارة التنفيذية" active={!record.has_executive_management} points={2} />
                                <RiskIndicator label="شركة التدقيق" active={!record.has_auditor_company} points={2} />
                                <RiskIndicator label="التقرير المالي" active={!record.has_financial_report_prev_year} points={2} />
                            </div>
                        </div>
                    </div>
                </div>
              )}

              {/* RISK REGISTER TAB */}
              {activeTab === 'risks' && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                          <h3 className="text-lg font-bold text-navy-900">قائمة المخاطر المرصودة</h3>
                          <button onClick={() => setShowRiskForm(true)} className="bg-red-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-700 text-sm"><Plus size={16} /> إضافة خطر</button>
                      </div>

                      {showRiskForm && (
                          <div className="bg-gray-50 p-6 rounded-xl border border-gray-200 animate-fadeIn">
                              <h4 className="font-bold mb-4">تسجيل خطر جديد</h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 mb-1">وصف الخطر</label>
                                      <input type="text" className="w-full p-2 border rounded" value={newRisk.risk_title || ''} onChange={e => setNewRisk({...newRisk, risk_title: e.target.value})} placeholder="مثال: نزاع قانوني على أصل وقفي" />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">التصنيف</label>
                                      <select className="w-full p-2 border rounded" value={newRisk.category} onChange={e => setNewRisk({...newRisk, category: e.target.value as any})}>
                                          <option value="Operational">تشغيلي</option>
                                          <option value="Financial">مالي</option>
                                          <option value="Legal">قانوني</option>
                                          <option value="Strategic">استراتيجي</option>
                                      </select>
                                  </div>
                                  <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">الاحتمالية (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded" value={newRisk.probability || ''} onChange={e => setNewRisk({...newRisk, probability: Number(e.target.value)})} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">الأثر (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded" value={newRisk.impact || ''} onChange={e => setNewRisk({...newRisk, impact: Number(e.target.value)})} />
                                    </div>
                                  </div>
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 mb-1">خطة المعالجة</label>
                                      <input type="text" className="w-full p-2 border rounded" value={newRisk.mitigation_plan || ''} onChange={e => setNewRisk({...newRisk, mitigation_plan: e.target.value})} />
                                  </div>
                              </div>
                              <div className="flex gap-2 justify-end">
                                  <button onClick={() => setShowRiskForm(false)} className="px-4 py-2 text-gray-600">إلغاء</button>
                                  <button onClick={handleSaveRisk} className="bg-navy-800 text-white px-4 py-2 rounded">حفظ</button>
                              </div>
                          </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {instRisks.map(risk => {
                              const score = risk.probability * risk.impact;
                              let color = 'bg-green-100 border-green-200';
                              if (score >= 15) color = 'bg-red-50 border-red-200';
                              else if (score >= 8) color = 'bg-orange-50 border-orange-200';

                              return (
                                  <div key={risk.id} className={`p-4 rounded-xl border ${color} relative group`}>
                                      <button onClick={() => handleDeleteRisk(risk.id)} className="absolute top-2 left-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={16}/></button>
                                      <div className="flex justify-between items-start mb-2">
                                          <span className="text-xs font-bold uppercase tracking-wider text-gray-500">{risk.category}</span>
                                          <span className={`text-xs font-bold px-2 py-1 rounded-full ${score >= 15 ? 'bg-red-500 text-white' : (score >= 8 ? 'bg-orange-500 text-white' : 'bg-green-500 text-white')}`}>
                                              {score} (شدة الخطر)
                                          </span>
                                      </div>
                                      <h4 className="font-bold text-navy-900 mb-2">{risk.risk_title}</h4>
                                      <p className="text-sm text-gray-600 mb-3">{risk.mitigation_plan || 'لا توجد خطة معالجة'}</p>
                                      <div className="flex gap-2 text-xs text-gray-500 border-t pt-2 border-gray-200/50">
                                          <span>P: {risk.probability}</span>
                                          <span>I: {risk.impact}</span>
                                      </div>
                                  </div>
                              )
                          })}
                          {instRisks.length === 0 && (
                              <div className="col-span-full py-10 text-center text-gray-400 border border-dashed border-gray-300 rounded-xl">
                                  لا توجد مخاطر مسجلة
                              </div>
                          )}
                      </div>
                  </div>
              )}
          </div>
      )}

      {!selectedInstId && (
        <div className="text-center py-20 text-gray-400 bg-white rounded-xl border border-dashed border-gray-300">
           اختر مؤسسة للبدء
        </div>
      )}
    </div>
  );
};

// UI Components
const ToggleItem = ({ label, checked, onChange, className }: any) => (
    <div 
        className={`flex items-center justify-between p-3 rounded-lg border transition-all cursor-pointer ${checked ? 'bg-teal-50 border-teal-200' : 'bg-white border-gray-200 hover:bg-gray-50'} ${className}`}
        onClick={onChange}
    >
        <span className={`font-medium ${checked ? 'text-teal-900' : 'text-gray-600'}`}>{label}</span>
        <div className={`w-12 h-6 rounded-full relative transition-colors ${checked ? 'bg-teal-600' : 'bg-gray-300'}`}>
            <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all shadow-sm ${checked ? 'left-1' : 'right-1'}`}></div>
        </div>
    </div>
);

const RiskIndicator = ({ label, active, points }: any) => (
    <div className={`flex justify-between items-center text-sm ${active ? 'opacity-100' : 'opacity-40'}`}>
        <span className="flex items-center gap-2">
            {active ? <AlertTriangle size={14} className="text-red-500" /> : <CheckCircle size={14} className="text-gray-400" />}
            {label}
        </span>
