        <label className="block text-sm font-medium mb-2 text-gray-700 dark:text-gray-300">اختر المؤسسة</label>
        <select 
          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none dark:bg-gray-700 dark:border-gray-600 dark:text-white"
          value={selectedInstId}
          onChange={(e) => setSelectedInstId(e.target.value)}
        >
          <option value="">-- اختر المؤسسة --</option>
          {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
        </select>
      </div>

      {selectedInstId && (
          <div className="animate-fadeIn">
              {/* Tabs */}
              <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6">
                  <button 
                    onClick={() => setActiveTab('compliance')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'compliance' ? 'border-b-2 border-navy-800 text-navy-900 dark:text-white dark:border-white' : 'text-gray-500 hover:text-navy-700 dark:text-gray-400'}`}
                  >
                      <span className="flex items-center gap-2"><Scale size={16} /> الامتثال النظامي</span>
                  </button>
                  <button 
