// Custom Tick for Radar Chart
const RadarCustomTick = ({ payload, x, y, textAnchor, stroke, radius }: any) => {
    return (
        <g className="recharts-layer recharts-polar-angle-axis-tick">
            <text
                radius={radius}
                stroke={stroke}
                x={x}
                y={y}
                className="recharts-text recharts-polar-angle-axis-tick-value"
                textAnchor={textAnchor}
                fill="#4b5563"
                fontSize="11px"
                fontWeight="bold"
            >
                <tspan x={x} dy="0.355em">{payload.value}</tspan>
            </text>
        </g>
    );
};

const Reports: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { currentWaqfId } = useUi();
  const [reportData, setReportData] = useState<any>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (!currentWaqfId) {
        setReportData(null);
        return;
    }

    const ev = getEvaluations().find(e => e.institution_id === currentWaqfId);
    if (!ev) {
        setReportData(null);
        return;
    }

    const responses = getResponses(ev.id);
    const indicators = getIndicators();

    const axisScores: Record<string, { total: number, count: number }> = {};
    // Pre-seed axes
    const uniqueAxes = Array.from(new Set(indicators.map(i => i.axis)));
    uniqueAxes.forEach(ax => { axisScores[ax] = { total: 0, count: 0 } });

    responses.forEach(r => {
        const ind = indicators.find(i => i.id === r.indicator_id);
        if (ind) {
            if (!axisScores[ind.axis]) axisScores[ind.axis] = { total: 0, count: 0 };
            axisScores[ind.axis].total += r.score;
            axisScores[ind.axis].count += 1;
        }
    });

    const radarData = uniqueAxes.map((axis, index) => {
        const scoreData = axisScores[axis];
        const avg = scoreData.count > 0 ? (scoreData.total / scoreData.count) : 0;
        return {
            subject: `${axis}`,
            A: Number(avg.toFixed(2)),
            fullMark: 5
        };
    });

    // Score Distribution Data
    const distribution = [
        { name: 'ضعيف (1-2)', value: responses.filter(r => r.score <= 2).length, fill: '#ef4444' },
        { name: 'متوسط (3)', value: responses.filter(r => r.score === 3).length, fill: '#f59e0b' },
        { name: 'جيد (4-5)', value: responses.filter(r => r.score >= 4).length, fill: '#10b981' },
    ].filter(d => d.value > 0);

    setReportData({ radarData, distribution, evaluation: ev, totalScore: (responses.reduce((a,b)=>a+b.score,0) / responses.length).toFixed(1) });

  }, [currentWaqfId]);

  const handleDownloadPDF = () => {
      const element = document.getElementById('report-content');
      if (!element) return;

      const opt = {
        margin:       10,
        filename:     `Report-${institutions.find(i => i.id === currentWaqfId)?.name}.pdf`,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2 },
        jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      html2pdf().from(element).set(opt).save();
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">النتائج والتقارير</h2>
        {reportData && (
            <div className="flex gap-2">
                <button onClick={() => window.print()} className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 shadow-md">
                    <Printer size={18} /> طباعة
                </button>
                <button onClick={handleDownloadPDF} className="bg-red-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-800 shadow-md">
                    <Download size={18} /> تصدير PDF
                </button>
            </div>
        )}
      </div>

       {/* Currently Viewing Banner - Replaces Selector */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn no-print">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">التقرير الخاص بـ:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center no-print">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود عرض تقاريرها.</p>
          </div>
      )}

      {reportData ? (
        <div id="report-content" className="space-y-8 animate-fadeIn print-content p-4 bg-white">
            {/* Header for Print/PDF */}
            <div className="text-center border-b pb-4 mb-8">
                <h1 className="text-2xl font-bold text-navy-900">تقرير نتائج الأداء المؤسسي</h1>
                <p className="text-gray-500">وزارة الأوقاف والشؤون الدينية</p>
