                    <div className="text-3xl font-bold text-navy-900">{reportData.totalScore} <span className="text-sm text-gray-400">/ 5.0</span></div>
                </div>
            </div>

            {/* Charts Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Radar Chart */}
                <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 page-break">
