export default Improvements;

import { Institution, Indicator, Evaluation, Response, ComplianceRecord, ImprovementItem, RiskRegisterItem } from '../types';
import { DEFAULT_INDICATORS, SEEDED_INSTITUTIONS } from '../constants';

const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const DB_KEYS = {
  INSTITUTIONS: 'waqf_institutions',
  INDICATORS: 'waqf_indicators',
  EVALUATIONS: 'waqf_evaluations',
  RESPONSES: 'waqf_responses',
  COMPLIANCE: 'waqf_compliance',
  IMPROVEMENTS: 'waqf_improvements',
  RISKS: 'waqf_risks',
  SETTINGS: 'waqf_settings'
};

// --- Generic Helper ---
const data = <T>(key: string): T[] => {
  const stored = localStorage.getItem(key);
  return stored ? JSON.parse(stored) : [];
};

const save = <T>(key: string, items: T[]) => {
  localStorage.setItem(key, JSON.stringify(items));
};

// --- Settings ---
export const getSettings = () => {
    const stored = localStorage.getItem(DB_KEYS.SETTINGS);
    return stored ? JSON.parse(stored) : { 
        managerName: 'د. عبدالرحمن النوفلي', 
        darkMode: false,
        orgName: 'وزارة الأوقاف والشؤون الدينية'
    };
};

export const saveSettings = (settings: any) => {
    localStorage.setItem(DB_KEYS.SETTINGS, JSON.stringify(settings));
    window.dispatchEvent(new Event('settingsChanged'));
};

// --- Institutions ---
export const getInstitutions = (): Institution[] => {
    let stored = data<Institution>(DB_KEYS.INSTITUTIONS);
    if (stored.length === 0) {
        // Seed default institutions
        stored = SEEDED_INSTITUTIONS.map((inst, idx) => ({
            id: `INST-SEED-${idx+1}`,
            name: inst.name!,
            type: inst.type as any,
            capital_omr: 0,
            employees_omani: 0,
            employees_non_omani: 0,
            contact_phone: '',
            created_at: new Date().toISOString()
        }));
        save(DB_KEYS.INSTITUTIONS, stored);
    }
    return stored;
};

export const saveInstitution = (inst: Institution) => {
  const list = getInstitutions();
  const index = list.findIndex(i => i.id === inst.id);
  if (index >= 0) list[index] = inst;
  else list.push(inst);
  save(DB_KEYS.INSTITUTIONS, list);
};
export const deleteInstitution = (id: string) => {
  const list = getInstitutions().filter(i => i.id !== id);
  save(DB_KEYS.INSTITUTIONS, list);
};

// --- Indicators (Imported from Excel or Defaults) ---
export const getIndicators = (): Indicator[] => {
  const stored = data<Indicator>(DB_KEYS.INDICATORS);
  if (stored.length === 0) {
    save(DB_KEYS.INDICATORS, DEFAULT_INDICATORS);
    return DEFAULT_INDICATORS;
  }
  return stored;
};

export const saveIndicators = (indicators: Indicator[]) => {
  save(DB_KEYS.INDICATORS, indicators);
};

// --- Evaluations ---
export const getEvaluations = (year?: number): Evaluation[] => {
  const evals = data<Evaluation>(DB_KEYS.EVALUATIONS);
  if (year) return evals.filter(e => e.cycle_year === year);
  return evals;
};
export const getEvaluationByInstAndYear = (instId: string, year: number) => {
  return getEvaluations().find(e => e.institution_id === instId && e.cycle_year === year);
};
export const saveEvaluation = (evalObj: Evaluation) => {
  const list = getEvaluations();
  const index = list.findIndex(e => e.id === evalObj.id);
  if (index >= 0) list[index] = evalObj;
  else list.push(evalObj);
  save(DB_KEYS.EVALUATIONS, list);
};

// --- Responses ---
export const getResponses = (evalId: string): Response[] => {
  return data<Response>(DB_KEYS.RESPONSES).filter(r => r.evaluation_id === evalId);
};
export const getAllResponses = (): Response[] => {
  return data<Response>(DB_KEYS.RESPONSES);
};
export const saveResponse = (response: Response) => {
  const list = data<Response>(DB_KEYS.RESPONSES);
  const index = list.findIndex(r => r.evaluation_id === response.evaluation_id && r.indicator_id === response.indicator_id);
  if (index >= 0) {
    list[index] = { ...list[index], ...response, updated_at: new Date().toISOString() };
  } else {
    list.push({ ...response, id: generateId(), updated_at: new Date().toISOString() });
  }
  save(DB_KEYS.RESPONSES, list);
};

// --- Compliance ---
export const getComplianceRecords = (year?: number): ComplianceRecord[] => {
  const recs = data<ComplianceRecord>(DB_KEYS.COMPLIANCE);
  if (year) return recs.filter(r => r.cycle_year === year);
  return recs;
};
export const getComplianceByInstAndYear = (instId: string, year: number): ComplianceRecord | undefined => {
    return getComplianceRecords(year).find(r => r.institution_id === instId);
}
export const saveComplianceRecord = (record: ComplianceRecord) => {
  const list = data<ComplianceRecord>(DB_KEYS.COMPLIANCE);
  const index = list.findIndex(r => r.id === record.id);
  if (index >= 0) list[index] = record;
  else list.push(record);
  save(DB_KEYS.COMPLIANCE, list);
};

// --- Risks ---
export const getRisks = (instId?: string): RiskRegisterItem[] => {
    const all = data<RiskRegisterItem>(DB_KEYS.RISKS);
    if (instId) return all.filter(r => r.institution_id === instId);
    return all;
};
export const saveRisk = (risk: RiskRegisterItem) => {
    const list = data<RiskRegisterItem>(DB_KEYS.RISKS);
    const index = list.findIndex(r => r.id === risk.id);
    if (index >= 0) list[index] = risk;
    else list.push(risk);
    save(DB_KEYS.RISKS, list);
};
export const deleteRisk = (id: string) => {
    const list = data<RiskRegisterItem>(DB_KEYS.RISKS).filter(r => r.id !== id);
    save(DB_KEYS.RISKS, list);
};


// --- Improvements ---
export const getImprovements = (evalId: string): ImprovementItem[] => {
    return data<ImprovementItem>(DB_KEYS.IMPROVEMENTS).filter(i => i.evaluation_id === evalId);
};
export const saveImprovement = (item: ImprovementItem) => {
    const list = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS);
    const index = list.findIndex(i => i.id === item.id);
    if (index >= 0) list[index] = item;
    else list.push(item);
    save(DB_KEYS.IMPROVEMENTS, list);
};
export const deleteImprovement = (id: string) => {
    const list = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS).filter(i => i.id !== id);
    save(DB_KEYS.IMPROVEMENTS, list);
};
export const generateImprovementPlan = (evalId: string, responses: Response[], indicators: Indicator[]) => {
    // Legacy support wrapper
    const weak = responses.filter(r => r.score < 3.5);
    const existing = getImprovements(evalId);
    const newItems: ImprovementItem[] = [];
    weak.forEach(resp => {
        if (!existing.find(ex => ex.indicator_id === resp.indicator_id)) {
            const ind = indicators.find(i => i.id === resp.indicator_id);
            if (ind) {
                newItems.push({
                    id: generateId(),
                    evaluation_id: evalId,
                    indicator_id: ind.id,
                    priority: resp.score < 2.5 ? 'High' : 'Medium',
                    issue_summary: `انخفاض في المؤشر: ${ind.text}`,
                    recommended_action: 'مراجعة السياسات والإجراءات وتحديد خطة تصحيحية.',
                    owner: 'الإدارة التنفيذية',
                    due_date: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
                    status: 'ToDo',
                    notes: ''
                });
            }
        }
    });

    if (newItems.length > 0) {
        const fullList = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS);
        fullList.push(...newItems);
        save(DB_KEYS.IMPROVEMENTS, fullList);
    }
};

export { generateId };

import React, { useState, useEffect } from 'react';
import { 
    getInstitutions, getEvaluations, getResponses, getIndicators, 
    getImprovements, saveImprovement, deleteImprovement, 
    getRisks, getComplianceByInstAndYear, generateId 
} from '../services/db';
import { Institution, ImprovementItem } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    Clock, CheckCircle, AlertTriangle, Building, 
    ArrowRight, ArrowLeft, Trash2, Layout, Activity, ShieldAlert, Scale 
} from 'lucide-react';
import { useUi } from '../contexts/UiContext';

type ColumnType = 'ToDo' | 'Doing' | 'Done';

const Improvements: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { currentWaqfId, showToast } = useUi();
  const [institutionName, setInstitutionName] = useState('');

  // Kanban State
  const [columns, setColumns] = useState<{ [key in ColumnType]: ImprovementItem[] }>({
      ToDo: [],
      Doing: [],
      Done: []
  });

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  // Main Data Loading & Auto-Generation Logic
  useEffect(() => {
    if (!currentWaqfId) {
        setColumns({ ToDo: [], Doing: [], Done: [] });
        return;
    }

    const inst = institutions.find(i => i.id === currentWaqfId);
    setInstitutionName(inst?.name || '');

    // Get Evaluation ID (Create dummy if missing to group items)
    const ev = getEvaluations().find(e => e.institution_id === currentWaqfId && e.cycle_year === CURRENT_YEAR);
    const evalId = ev?.id || `TEMP_EVAL_${currentWaqfId}`; 

    // 1. Fetch Existing Improvements
    const existingItems = getImprovements(evalId);

    if (existingItems.length > 0) {
        // Sort into columns
        setColumns({
            ToDo: existingItems.filter(i => i.status === 'ToDo'),
            Doing: existingItems.filter(i => i.status === 'Doing'),
            Done: existingItems.filter(i => i.status === 'Done'),
        });
    } else {
        // 2. Auto-Generate from 3 Sources
        const newItems: ImprovementItem[] = [];
        const indicators = getIndicators();

        // Source A: Performance Weaknesses (Score < 3)
        if (ev) {
            const responses = getResponses(ev.id);
            responses.filter(r => r.score < 3).forEach(r => {
                const ind = indicators.find(i => i.id === r.indicator_id);
                if (ind) {
                    newItems.push({
                        id: generateId(),
                        evaluation_id: evalId,
                        indicator_id: `PERF-${ind.id}`, // Prefix to identify source
                        priority: 'Medium',
                        issue_summary: `ضعف الأداء: ${ind.text.substring(0, 50)}...`,
                        recommended_action: 'تحليل أسباب الانخفاض ووضع خطة تصحيحية.',
                        owner: 'مدير العمليات',
                        due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                        status: 'ToDo',
                        notes: 'تم استيراده تلقائياً من التقييم'
                    });
                }
            });
        }

        // Source B: High Risks (Prob * Impact >= 15)
        const risks = getRisks(currentWaqfId);
        risks.filter(r => (r.probability * r.impact) >= 15).forEach(r => {
            newItems.push({
                id: generateId(),
                evaluation_id: evalId,
                indicator_id: `RISK-${r.id}`,
                priority: 'High',
                issue_summary: `خطر حرج: ${r.risk_title}`,
                recommended_action: r.mitigation_plan || 'تفعيل خطة طوارئ عاجلة.',
                owner: 'لجنة المخاطر',
                due_date: new Date(new Date().setDate(new Date().getDate() + 14)).toISOString().split('T')[0], // 2 weeks
                status: 'ToDo',
                notes: 'تم استيراده تلقائياً من سجل المخاطر'
            });
        });

        // Source C: Compliance Gaps (False/Not Met)
        const comp = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
        if (comp) {
            const gaps = [];
            if (comp.institution_status !== 'فاعلة') gaps.push('حالة المؤسسة غير فاعلة');
            if (comp.board_status !== 'قائم') gaps.push('مجلس الإدارة غير قائم');
            if (!comp.has_executive_management) gaps.push('غياب الإدارة التنفيذية');
            if (!comp.has_auditor_company) gaps.push('لم يتم تعيين مدقق خارجي');

            gaps.forEach((gap, idx) => {
                newItems.push({
                    id: generateId(),
                    evaluation_id: evalId,
                    indicator_id: `COMP-${idx}`,
                    priority: 'High',
                    issue_summary: `قصور امتثال: ${gap}`,
                    recommended_action: 'استيفاء المتطلب النظامي فوراً.',
                    owner: 'أمين السر / المدير',
                    due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                    status: 'ToDo',
                    notes: 'تم استيراده تلقائياً من سجل الامتثال'
                });
            });
        }

        // Save & Set State
        if (newItems.length > 0) {
            newItems.forEach(saveImprovement);
            setColumns(prev => ({ ...prev, ToDo: newItems }));
            showToast(`تم إنشاء ${newItems.length} مهام تحسين تلقائياً`, 'info');
        }
    }

  }, [currentWaqfId, institutions]);

  // Actions
  const moveItem = (item: ImprovementItem, direction: 'forward' | 'backward') => {
      let newStatus: ColumnType = item.status;

      if (direction === 'forward') {
          if (item.status === 'ToDo') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'Done';
      } else {
          if (item.status === 'Done') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'ToDo';
      }

      if (newStatus !== item.status) {
          const updatedItem = { ...item, status: newStatus };
          saveImprovement(updatedItem); // Persist

          // Optimistic UI Update
          setColumns(prev => {
              const sourceList = prev[item.status].filter(i => i.id !== item.id);
              const targetList = [updatedItem, ...prev[newStatus]];
              return { ...prev, [item.status as ColumnType]: sourceList, [newStatus]: targetList };
          });
      }
  };

  const handleDelete = (id: string, status: ColumnType) => {
      if(confirm('هل أنت متأكد من حذف هذه المهمة؟')) {
          deleteImprovement(id);
          setColumns(prev => ({
              ...prev,
              [status]: prev[status].filter(i => i.id !== id)
          }));
          showToast('تم حذف المهمة', 'info');
      }
  };

  const getSourceBadge = (indicatorId: string) => {
      if (indicatorId.startsWith('RISK-')) return { label: 'مخاطر', color: 'bg-red-100 text-red-800', icon: ShieldAlert };
      if (indicatorId.startsWith('COMP-')) return { label: 'امتثال', color: 'bg-purple-100 text-purple-800', icon: Scale };
      return { label: 'أداء', color: 'bg-orange-100 text-orange-800', icon: Activity };
  };

  return (
    <div className="space-y-6 min-h-screen">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white flex items-center gap-2">
            <Layout className="text-teal-600"/> لوحة متابعة التحسين (Kanban)
        </h2>
      </div>

       {/* Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn no-print mb-8">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">خطة المؤسسة:</div>
                      <div className="text-lg font-bold">{institutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center no-print">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى اختيار مؤسسة لعرض مهام التحسين الخاصة بها.</p>
          </div>
      )}

      {currentWaqfId && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full items-start overflow-x-auto pb-10">
            {/* Column 1: To Do */}
            <KanbanColumn 
                title="مهام جديدة" 
                count={columns.ToDo.length} 
                color="border-red-400 bg-red-50 dark:bg-red-900/10"
                icon={<AlertTriangle size={18} className="text-red-600"/>}
            >
                {columns.ToDo.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'ToDo')}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 2: Doing */}
            <KanbanColumn 
                title="جاري المعالجة" 
                count={columns.Doing.length} 
                color="border-yellow-400 bg-yellow-50 dark:bg-yellow-900/10"
                icon={<Clock size={18} className="text-yellow-600"/>}
            >
                {columns.Doing.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'Doing')}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 3: Done */}
            <KanbanColumn 
                title="تم الإنجاز" 
                count={columns.Done.length} 
                color="border-green-400 bg-green-50 dark:bg-green-900/10"
                icon={<CheckCircle size={18} className="text-green-600"/>}
            >
                {columns.Done.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onDelete={() => handleDelete(item.id, 'Done')}
                        badge={getSourceBadge(item.indicator_id)}
                        isDone
                    />
                ))}
            </KanbanColumn>
        </div>
      )}
    </div>
  );
};

// --- Sub Components ---

const KanbanColumn = ({ title, count, children, color, icon }: any) => (
    <div className={`flex flex-col h-full min-h-[500px] rounded-xl border-t-4 ${color} bg-gray-50/50 dark:bg-gray-800 shadow-sm`}>
        <div className="p-4 flex justify-between items-center border-b border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-xl">
            <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">{icon} {title}</h3>
            <span className="bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 text-xs px-2 py-1 rounded-full font-bold">{count}</span>
        </div>
        <div className="p-3 space-y-3 flex-1">
            {children}
            {count === 0 && <div className="text-center py-10 text-gray-400 text-sm italic">لا توجد مهام</div>}
        </div>
    </div>
);

const KanbanCard = ({ item, onMoveBack, onMoveForward, onDelete, badge, isDone }: any) => {
    const Icon = badge.icon;
    return (
        <div className={`bg-white dark:bg-gray-700 p-4 rounded-lg shadow-sm border border-gray-100 dark:border-gray-600 hover:shadow-md transition-shadow relative group ${isDone ? 'opacity-75' : ''}`}>
            {/* Delete Button (Hidden until hover) */}
            <button 
                onClick={onDelete}
                className="absolute top-2 left-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
            >
                <Trash2 size={16} />
            </button>

            {/* Badge */}
            <div className="flex justify-between items-start mb-2">
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1 ${badge.color}`}>
                    <Icon size={12} /> {badge.label}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded border ${item.priority === 'High' ? 'text-red-600 border-red-200 bg-red-50' : 'text-gray-500 border-gray-200'}`}>
                    {item.priority === 'High' ? 'أولوية قصوى' : 'عادية'}
                </span>
            </div>

            {/* Content */}
            <h4 className={`font-bold text-sm text-navy-900 dark:text-white mb-2 ${isDone ? 'line-through text-gray-500' : ''}`}>
                {item.issue_summary}
            </h4>
            <p className="text-xs text-gray-500 dark:text-gray-300 mb-3 leading-relaxed bg-gray-50 dark:bg-gray-800 p-2 rounded">
                {item.recommended_action}
            </p>

            <div className="flex justify-between items-center text-xs text-gray-400 border-t border-gray-100 dark:border-gray-600 pt-2 mb-3">
                <span>{item.owner}</span>
                <span>{item.due_date}</span>
            </div>

            {/* Controls */}
            <div className="flex justify-between items-center gap-2">
                {onMoveForward ? (
                    <button onClick={onMoveForward} className="flex-1 bg-navy-50 text-navy-800 hover:bg-navy-100 dark:bg-navy-900 dark:text-blue-200 dark:hover:bg-navy-800 py-1.5 rounded text-xs font-bold flex justify-center items-center gap-1 transition-colors">
                        نقل للمرحلة التالية <ArrowLeft size={14} />
                    </button>
                ) : <div className="flex-1"></div>}

                {onMoveBack && (
                     <button onClick={onMoveBack} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-500 transition-colors" title="عودة للسابق">
                         <ArrowRight size={16} />
                     </button>
                )}
            </div>
        </div>
    );
};

export default Improvements;

import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { LayoutDashboard, Building2, ClipboardCheck, Scale, FileBarChart, Menu, X, ShieldAlert, Settings, LogOut } from 'lucide-react';
import { getSettings } from '../services/db';
import { useUi } from '../contexts/UiContext';

const SidebarItem = ({ to, icon: Icon, label, active }: any) => (
  <Link to={to} className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-colors duration-200 ${active ? 'bg-navy-800 text-gold-400' : 'text-white hover:bg-navy-800/50'}`}>
    <Icon size={20} />
    <span className="font-medium">{label}</span>
  </Link>
);

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [settings, setSettings] = useState(getSettings());
  const { isAuthenticated, logout, user, role } = useUi();
  const location = useLocation();

  useEffect(() => {
    // Apply Dark Mode
    if (settings.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    const handleSettingsChange = () => {
        const newSettings = getSettings();
        setSettings(newSettings);
        if (newSettings.darkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    };
    window.addEventListener('settingsChanged', handleSettingsChange);
    return () => window.removeEventListener('settingsChanged', handleSettingsChange);
  }, [settings.darkMode]);

  // If not authenticated, render children directly (Login page handles its own layout mostly)
  if (!isAuthenticated) {
      return <>{children}</>;
  }

  // Define All Routes with Roles
  const allNavItems = [
    { to: '/', icon: LayoutDashboard, label: 'الرئيسية (القيادة)', roles: ['admin'] },
    { to: '/institutions', icon: Building2, label: 'بيانات المؤسسة', roles: ['admin', 'user'] },
    { to: '/evaluation', icon: ClipboardCheck, label: 'التقييم', roles: ['admin', 'user'] },
    { to: '/compliance', icon: Scale, label: 'الامتثال النظامي', roles: ['admin', 'user'] },
    { to: '/reports', icon: FileBarChart, label: 'النتائج والتقارير', roles: ['admin'] },
    { to: '/improvements', icon: ShieldAlert, label: 'خطة التحسين', roles: ['admin', 'user'] },
    { to: '/settings', icon: Settings, label: 'إعدادات النظام', roles: ['admin'] },
  ];

  // Filter based on current role
  const navItems = allNavItems.filter(item => role && item.roles.includes(role));

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900 overflow-hidden font-sans text-right" dir="rtl">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-navy-900 dark:bg-black text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0 shadow-2xl ${sidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex items-center justify-between p-6 border-b border-navy-800 h-20">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-white rounded-full p-1 overflow-hidden flex items-center justify-center">
                 <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/5/52/Ministry_of_Endowments_and_Religious_Affairs_%28Oman%29_Logo.png" 
                    className="w-full h-full object-contain" 
                    onError={(e) => {
                        e.currentTarget.style.display = 'none';
                    }}
                 />
             </div>
             <h1 className="text-lg font-bold text-gold-500">نظام الوقف</h1>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-gray-400 hover:text-white">
            <X size={24} />
          </button>
        </div>

        {/* User Role Badge */}
        <div className="px-4 mt-4">
            <div className={`p-2 rounded-lg text-center text-xs font-bold border ${role === 'admin' ? 'bg-navy-800 border-navy-700 text-gold-400' : 'bg-teal-900/50 border-teal-800 text-teal-400'}`}>
                {role === 'admin' ? 'صلاحية: مدير نظام' : 'صلاحية: مؤسسة وقفية'}
            </div>
        </div>

        <nav className="p-4 space-y-2 flex-1 overflow-y-auto mt-2">
          {navItems.map((item) => (
            <SidebarItem key={item.to} {...item} active={location.pathname === item.to} />
          ))}
          <button 
            onClick={logout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors duration-200 text-red-300 hover:bg-navy-800/50 mt-4"
          >
             <LogOut size={20} />
             <span className="font-medium">تسجيل الخروج</span>
          </button>
        </nav>
        <div className="absolute bottom-0 w-full p-4 border-t border-navy-800 text-xs text-gray-400 text-center">
          <p>{settings.orgName}</p>
          <p className="mt-1 text-gold-500">تحت إشراف {settings.managerName}</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="bg-white dark:bg-gray-800 shadow-sm z-10 border-b border-gray-200 dark:border-gray-700 h-20 flex items-center px-6 justify-between print:hidden">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-gray-600 dark:text-gray-200">
                <Menu size={24} />
            </button>

            <div className="flex flex-col items-center flex-1 lg:flex-none lg:items-start">
                <h2 className="text-xl font-bold text-navy-900 dark:text-white">نظام تقييم المؤسسات الوقفية</h2>
                <span className="text-xs text-teal-600 dark:text-teal-400 font-semibold hidden md:block">سلطنة عُمان - {settings.orgName}</span>
            </div>

            <div className="hidden md:flex items-center gap-4">
                <div className="text-left">
                   <p className="text-sm font-bold text-navy-900 dark:text-white">أهلاً، {user}</p>
                   <p className="text-xs text-gold-600 dark:text-gold-400">{role === 'admin' ? 'مدير النظام' : 'مستخدم مؤسسة'}</p>
                </div>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-md ${role === 'admin' ? 'bg-navy-800' : 'bg-teal-600'}`}>
                    {user?.charAt(0).toUpperCase()}
                </div>
            </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-4 lg:p-8 relative dark:text-gray-100">
          {children}

          {/* Footer - Print Only */}
          <div className="hidden print:block fixed bottom-0 left-0 right-0 text-center p-4 border-t text-sm">
             <p>تم استخراج هذا التقرير آلياً من نظام تقييم المؤسسات الوقفية</p>
             <p className="font-bold">تحت إشراف {settings.managerName}</p>
          </div>
        </main>
      </div>

      {/* Overlay for mobile sidebar */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}
    </div>
  );
};

