      {reportData ? (
        <div id="report-content" className="space-y-8 animate-fadeIn print-content p-6 bg-white min-h-screen">
            {/* Header for Print/PDF */}
            <div className="flex justify-between items-end border-b-2 border-gray-100 pb-6 mb-8">
