  // Institution Selection State
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [selectedInstId, setSelectedInstId] = useState('');

  // Load institutions for the dropdown
  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (loginType === 'admin') {
        // --- ADMIN VALIDATION ---
        // Simple mock validation
        if (username.trim().toLowerCase() === 'admin' && password === 'admin') {
            // 1. Set Context (Admin has no specific Waqf context initially)
            setWaqfContext(''); 

            // 2. Perform Login
            login('مدير النظام', 'admin');
            showToast('مرحباً بك، مدير النظام', 'success');
        } else {
            showToast('بيانات المدير غير صحيحة (جرب admin/admin)', 'error');
        }
    } else {
        // --- INSTITUTION VALIDATION ---
        if (!selectedInstId) {
            showToast('يرجى اختيار المؤسسة من القائمة', 'error');
            return;
        }

        const selectedInst = institutions.find(i => i.id === selectedInstId);
        if (!selectedInst) return;

        // Mock password check (allow any password for demo ease, or enforce specific)
        if (password === '1234') {
            // 1. Set Global Context to the selected institution
            setWaqfContext(selectedInst.id);

            // 2. Perform Login with the Institution's Name
            login(selectedInst.name, 'user');

            showToast(`مرحباً، ${selectedInst.name}`, 'success');
        } else {
            showToast('كلمة المرور غير صحيحة (جرب 1234)', 'error');
        }
    }
  };

  const handleTabSwitch = (type: LoginType) => {
      setLoginType(type);
      setUsername(''); 
      setPassword('');
      setSelectedInstId('');
  };

  return (
    <div className="min-h-screen bg-navy-900 flex items-center justify-center p-4" dir="rtl">
      {/* Background decoration */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute -top-[20%] -right-[10%] w-[50%] h-[50%] bg-gold-500/10 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-[20%] -left-[10%] w-[50%] h-[50%] bg-teal-600/10 rounded-full blur-3xl"></div>
      </div>

      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden relative z-10">
        {/* Header */}
        <div className="bg-navy-900 p-8 text-center border-b-4 border-gold-500">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl p-2">
                <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/5/52/Ministry_of_Endowments_and_Religious_Affairs_%28Oman%29_Logo.png" 
                    alt="Logo" 
                    className="w-full h-full object-contain"
                    onError={(e) => { e.currentTarget.style.display = 'none'; }}
                />
            </div>
            <h1 className="text-2xl font-bold text-white mb-1">نظام تقييم الأوقاف</h1>
            <p className="text-navy-100 text-xs tracking-wider opacity-80">بوابة الدخول الموحدة</p>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
            <button 
                type="button"
                onClick={() => handleTabSwitch('admin')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-all ${loginType === 'admin' ? 'text-navy-900 bg-white border-b-2 border-navy-900 shadow-[inset_0_-2px_0_0_#0a1929]' : 'text-gray-400 bg-gray-50 hover:bg-gray-100'}`}
            >
                <ShieldCheck size={18} /> دخول مدير النظام
            </button>
            <button 
                type="button"
                onClick={() => handleTabSwitch('user')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-all ${loginType === 'user' ? 'text-teal-700 bg-white border-b-2 border-teal-600 shadow-[inset_0_-2px_0_0_#0d9488]' : 'text-gray-400 bg-gray-50 hover:bg-gray-100'}`}
            >
                <Building2 size={18} /> دخول المؤسسة الوقفية
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
            <div className="text-center mb-6">
                <h3 className="text-lg font-bold text-gray-800">
                    {loginType === 'admin' ? 'مرحباً بك في لوحة التحكم المركزية' : 'مرحباً بك في بوابة الخدمات الوقفية'}
                </h3>
                <p className="text-sm text-gray-500 mt-1">
                    {loginType === 'admin' ? 'يرجى إدخال بيانات المشرف العام' : 'اختر المؤسسة للوصول إلى بياناتها'}
                </p>
            </div>

            {/* Inputs based on Role */}
            {loginType === 'admin' ? (
                // ADMIN INPUTS
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">اسم المستخدم</label>
                    <div className="relative">
                        <User className="absolute top-3 right-3 text-gray-400" size={20} />
                        <input 
                            type="text" 
                            required
                            className="w-full p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none transition-shadow"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            placeholder="admin"
                        />
                    </div>
                </div>
            ) : (
                // INSTITUTION INPUTS (DROPDOWN)
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">اختر المؤسسة</label>
                    <div className="relative">
                        <select 
                            required
                            className="w-full p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-teal-600 outline-none transition-shadow appearance-none bg-white"
                            value={selectedInstId}
                            onChange={(e) => setSelectedInstId(e.target.value)}
                        >
                            <option value="">-- اختر المؤسسة من القائمة --</option>
                            {institutions.map(inst => (
                                <option key={inst.id} value={inst.id}>{inst.name}</option>
                            ))}
                        </select>
                        <ChevronDown className="absolute top-3.5 left-3 text-gray-400 pointer-events-none" size={18} />
                        <Building2 className="absolute top-3 right-3 text-gray-400" size={20} />
                    </div>
                </div>
            )}

            {/* Password Field (Shared) */}
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">كلمة المرور</label>
                <div className="relative">
                    <Lock className="absolute top-3 right-3 text-gray-400" size={20} />
                    <input 
                        type="password" 
                        required
                        className={`w-full p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 outline-none transition-shadow ${loginType === 'admin' ? 'focus:ring-navy-800' : 'focus:ring-teal-600'}`}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                    />
                </div>
            </div>

            <button 
                type="submit" 
                className={`w-full font-bold py-3 rounded-lg shadow-lg transition-transform active:scale-95 flex items-center justify-center gap-2 text-white
                    ${loginType === 'admin' ? 'bg-navy-900 hover:bg-navy-800' : 'bg-teal-600 hover:bg-teal-700'}
                `}
            >
                تسجيل الدخول <ArrowRight size={18} />
            </button>

            {/* Mock Data Hint */}
            <div className="mt-6 p-4 bg-gray-50 border border-gray-200 rounded-lg text-xs text-center text-gray-500">
                <p className="font-bold mb-2">بيانات الدخول (تجريبية):</p>
                <div className="flex justify-center gap-4">
                    {loginType === 'admin' ? (
                        <div className="text-navy-900 font-bold">
                            Admin: <span className="font-mono">admin / admin</span>
                        </div>
                    ) : (
                        <div className="text-teal-700 font-bold">
                            Password: <span className="font-mono">1234</span>
                        </div>
                    )}
                </div>
            </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType, InstitutionDocument } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X, FileText, UploadCloud, Calendar, Hash, User, CheckCircle2 } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<Partial<Institution>>({});
  const { showToast, role, currentWaqfId, setWaqfContext } = useUi();

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name!,
      type: (formData.type as InstitutionType) || 'وقفية عامة',
      capital_omr: Number(formData.capital_omr) || 0,
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone || '',
      email: formData.email || '',
      governorate: formData.governorate || '',
      wilayat: formData.wilayat || '',

      // New Fields
      establishment_date: formData.establishment_date || '',
      license_number: formData.license_number || '',
      manager_name: formData.manager_name || '',

      documents: formData.documents || [],
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});

    // Auto-set context for user if this is their first create or edit
    if (role === 'user') {
        setWaqfContext(newInst.id);
    }

    showToast('تم حفظ بيانات المؤسسة بنجاح', 'success');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setFormData(prev => ({
              ...prev,
              documents: [...(prev.documents || []), newDoc]
          }));
          showToast('تم إرفاق الملف بنجاح', 'info');
      }
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
      if (currentWaqfId === id) setWaqfContext(''); // Clear context if deleted
      showToast('تم حذف المؤسسة', 'info');
    }
  };

  const handleSelectContext = (id: string) => {
      setWaqfContext(id);
      showToast('تم اختيار المؤسسة للعمل عليها', 'success');
  };

  // --- SECURITY FILTERING ---
  const filtered = list.filter(i => {
      // 1. Isolation: If User, only show own institution
      if (role === 'user') {
          return i.id === currentWaqfId;
      }
      // 2. Search
      return i.name.includes(search);
  });

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">بيانات المؤسسات</h2>
        {/* ADD BUTTON: Render ONLY if Admin */}
        {role === 'admin' && (
            <button 
            onClick={() => { setFormData({}); setShowForm(true); }}
            className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900"
            >
            <Plus size={18} /> إضافة مؤسسة
            </button>
        )}
      </div>

      {/* Search */}
      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <table className="w-full text-right">
          <thead className="bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 font-medium">
            <tr>
              <th className="p-4">المؤسسة</th>
              <th className="p-4">النوع</th>
              <th className="p-4">رأس المال (ر.ع)</th>
              <th className="p-4">مدير المؤسسة</th>
              <th className="p-4">المحافظة</th>
              <th className="p-4">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
            {filtered.map(inst => (
              <tr key={inst.id} className={`transition-colors ${currentWaqfId === inst.id ? 'bg-blue-50 dark:bg-blue-900/20' : ''} ${inst.type === 'وقفية خاصة' ? 'hover:bg-orange-50 dark:hover:bg-orange-900/30' : 'hover:bg-gray-50 dark:hover:bg-gray-700'}`}>
                <td className="p-4 font-medium text-navy-900 dark:text-gray-200">
                    <div className="flex items-center gap-2">
                        {currentWaqfId === inst.id && <CheckCircle2 size={16} className="text-teal-500" />}
                        <div>
                            <div>{inst.name}</div>
                            <div className="text-xs text-gray-400 font-normal">{inst.license_number}</div>
                        </div>
                    </div>
                </td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded text-xs ${inst.type === 'وقفية عامة' ? 'bg-teal-100 text-teal-800' : 'bg-gold-100 text-gold-800'}`}>
                    {inst.type}
                  </span>
                </td>
                <td className="p-4 font-mono dark:text-gray-300">{inst.capital_omr.toLocaleString()}</td>
                <td className="p-4 text-sm dark:text-gray-300">{inst.manager_name || '-'}</td>
                <td className="p-4">
                    <div className="text-sm dark:text-gray-300">{inst.governorate}</div>
                    <div className="text-xs text-gray-500">{inst.wilayat}</div>
                </td>
                <td className="p-4 flex gap-2 items-center">
                  {role === 'user' && currentWaqfId !== inst.id && (
                      <button onClick={() => handleSelectContext(inst.id)} className="text-xs bg-navy-100 text-navy-800 px-2 py-1 rounded hover:bg-navy-200">
                          اختيار
                      </button>
                  )}
                  {/* Edit - Visible to All */}
                  <button onClick={() => { setFormData(inst); setShowForm(true); }} className="text-blue-600 hover:text-blue-800">
                    <Edit2 size={18} />
                  </button>

                  {/* DELETE: Render ONLY if Admin */}
                  {role === 'admin' && (
                    <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800">
                        <Trash2 size={18} />
                    </button>
                  )}
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={6} className="p-8 text-center text-gray-400">لا توجد مؤسسات مطابقة</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold">{formData.id ? 'تعديل مؤسسة' : 'إضافة مؤسسة جديدة'}</h3>
              <button onClick={() => setShowForm(false)}><X size={24} /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

              {/* Basic Info Section */}
              <div className="lg:col-span-3 pb-2 border-b mb-2">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><FileText size={18}/> البيانات الأساسية</h4>
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium mb-1">اسم المؤسسة *</label>
                <input required className="w-full p-2 border rounded" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">النوع *</label>
                <select className="w-full p-2 border rounded" value={formData.type || 'وقفية عامة'} onChange={e => setFormData({...formData, type: e.target.value as any})}>
                  <option value="وقفية عامة">وقفية عامة</option>
                  <option value="وقفية خاصة">وقفية خاصة</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">تاريخ التأسيس</label>
                <div className="relative">
                    <Calendar className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input type="date" className="w-full p-2 pr-8 border rounded" value={formData.establishment_date || ''} onChange={e => setFormData({...formData, establishment_date: e.target.value})} />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">رقم السجل/الترخيص</label>
                <div className="relative">
                    <Hash className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input type="text" className="w-full p-2 pr-8 border rounded" value={formData.license_number || ''} onChange={e => setFormData({...formData, license_number: e.target.value})} />
                </div>
              </div>

              {/* Management & Location */}
              <div className="lg:col-span-3 pb-2 border-b mb-2 mt-4">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><User size={18}/> الإدارة والموقع</h4>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">مدير المؤسسة</label>
                <input type="text" className="w-full p-2 border rounded" value={formData.manager_name || ''} onChange={e => setFormData({...formData, manager_name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">رقم الهاتف *</label>
                <input required className="w-full p-2 border rounded" value={formData.contact_phone || ''} onChange={e => setFormData({...formData, contact_phone: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">البريد الإلكتروني</label>
                <input type="email" className="w-full p-2 border rounded" value={formData.email || ''} onChange={e => setFormData({...formData, email: e.target.value})} />
              </div>
               <div>
                <label className="block text-sm font-medium mb-1">المحافظة</label>
                <select className="w-full p-2 border rounded" value={formData.governorate || ''} onChange={e => setFormData({...formData, governorate: e.target.value, wilayat: ''})}>
                  <option value="">اختر...</option>
                  {GOVERNORATES.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الولاية</label>
                <select className="w-full p-2 border rounded" value={formData.wilayat || ''} onChange={e => setFormData({...formData, wilayat: e.target.value})} disabled={!formData.governorate}>
                  <option value="">اختر...</option>
                  {availableWilayats.map(w => <option key={w} value={w}>{w}</option>)}
                </select>
              </div>

              {/* Financial & HR */}
              <div className="lg:col-span-3 pb-2 border-b mb-2 mt-4">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><Hash size={18}/> البيانات المالية والبشرية</h4>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">رأس المال (ر.ع) *</label>
                <input type="number" required className="w-full p-2 border rounded" value={formData.capital_omr || ''} onChange={e => setFormData({...formData, capital_omr: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_omani || ''} onChange={e => setFormData({...formData, employees_omani: Number(e.target.value)})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">الموظفين غير العمانيين</label>
                <input type="number" className="w-full p-2 border rounded" value={formData.employees_non_omani || ''} onChange={e => setFormData({...formData, employees_non_omani: Number(e.target.value)})} />
              </div>

              {/* Document Upload */}
              <div className="lg:col-span-3 border-t pt-4 mt-2">
                   <h4 className="font-bold text-sm mb-3">ملفات المؤسسة (السجل التجاري، الصكوك...)</h4>
                   <div className="flex gap-2 mb-3">
                       <label className="cursor-pointer bg-gray-100 hover:bg-gray-200 text-gray-600 px-4 py-2 rounded-lg flex items-center gap-2 text-sm border border-gray-300">
                           <UploadCloud size={16} /> رفع ملف
                           <input type="file" className="hidden" onChange={handleFileUpload} />
                       </label>
                   </div>
                   {formData.documents && formData.documents.length > 0 && (
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                           {formData.documents.map((doc, idx) => (
                               <div key={idx} className="flex justify-between items-center bg-gray-50 p-2 rounded border">
                                   <div className="flex items-center gap-2">
                                       <FileText size={16} className="text-blue-500" />
                                       <span className="text-sm truncate max-w-[150px]">{doc.name}</span>
                                       <span className="text-xs text-gray-400">({doc.size})</span>
                                   </div>
                                   <button type="button" onClick={() => setFormData(p => ({...p, documents: p.documents?.filter((_, i) => i !== idx)}))} className="text-red-500 hover:text-red-700">
                                       <X size={16} />
                                   </button>
                               </div>
                           ))}
                       </div>
                   )}
              </div>

              <div className="lg:col-span-3 mt-4 flex justify-end gap-3 pt-4 border-t">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">إلغاء</button>
                <button type="submit" className="px-6 py-2 bg-navy-800 text-white rounded hover:bg-navy-900 shadow-lg">حفظ المؤسسة</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Institutions;

import React, { useState, useEffect } from 'react';
import { 
    getInstitutions, getEvaluations, getResponses, getIndicators, 
    getImprovements, saveImprovement, deleteImprovement, 
    getRisks, getComplianceByInstAndYear, generateId 
} from '../services/db';
import { Institution, ImprovementItem } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    Clock, CheckCircle, AlertTriangle, Building, 
    ArrowRight, ArrowLeft, Trash2, Layout, Activity, ShieldAlert, Scale,
    Save, Download, Printer
} from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// Declare html2pdf for TypeScript
declare const html2pdf: any;

type ColumnType = 'ToDo' | 'Doing' | 'Done';

const Improvements: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { currentWaqfId, showToast } = useUi();
  const [institutionName, setInstitutionName] = useState('');

  // Kanban State
  const [columns, setColumns] = useState<{ [key in ColumnType]: ImprovementItem[] }>({
      ToDo: [],
      Doing: [],
      Done: []
  });

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  // Main Data Loading & Auto-Generation Logic
  useEffect(() => {
    if (!currentWaqfId) {
        setColumns({ ToDo: [], Doing: [], Done: [] });
        return;
    }

    const inst = institutions.find(i => i.id === currentWaqfId);
    setInstitutionName(inst?.name || '');

    // Get Evaluation ID (Create dummy if missing to group items)
    const ev = getEvaluations().find(e => e.institution_id === currentWaqfId && e.cycle_year === CURRENT_YEAR);
    const evalId = ev?.id || `TEMP_EVAL_${currentWaqfId}`; 

    // 1. Fetch Existing Improvements
    const existingItems = getImprovements(evalId);

    if (existingItems.length > 0) {
        // Sort into columns
        setColumns({
            ToDo: existingItems.filter(i => i.status === 'ToDo'),
            Doing: existingItems.filter(i => i.status === 'Doing'),
            Done: existingItems.filter(i => i.status === 'Done'),
        });
    } else {
        // 2. Auto-Generate from 3 Sources
        const newItems: ImprovementItem[] = [];
        const indicators = getIndicators();

        // Source A: Performance Weaknesses (Score < 3)
        if (ev) {
            const responses = getResponses(ev.id);
            responses.filter(r => r.score < 3).forEach(r => {
                const ind = indicators.find(i => i.id === r.indicator_id);
                if (ind) {
                    newItems.push({
                        id: generateId(),
                        evaluation_id: evalId,
                        indicator_id: `PERF-${ind.id}`, // Prefix to identify source
                        priority: 'Medium',
                        issue_summary: `ضعف الأداء: ${ind.text.substring(0, 50)}...`,
                        recommended_action: 'تحليل أسباب الانخفاض ووضع خطة تصحيحية.',
                        owner: 'مدير العمليات',
                        due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                        status: 'ToDo',
                        notes: 'تم استيراده تلقائياً من التقييم'
                    });
                }
            });
        }

        // Source B: High Risks (Prob * Impact >= 15)
        const risks = getRisks(currentWaqfId);
        risks.filter(r => (r.probability * r.impact) >= 15).forEach(r => {
            newItems.push({
                id: generateId(),
                evaluation_id: evalId,
                indicator_id: `RISK-${r.id}`,
                priority: 'High',
                issue_summary: `خطر حرج: ${r.risk_title}`,
                recommended_action: r.mitigation_plan || 'تفعيل خطة طوارئ عاجلة.',
                owner: 'لجنة المخاطر',
                due_date: new Date(new Date().setDate(new Date().getDate() + 14)).toISOString().split('T')[0], // 2 weeks
                status: 'ToDo',
                notes: 'تم استيراده تلقائياً من سجل المخاطر'
            });
        });

        // Source C: Compliance Gaps (False/Not Met)
        const comp = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
        if (comp) {
            const gaps = [];
            if (comp.institution_status !== 'فاعلة') gaps.push('حالة المؤسسة غير فاعلة');
            if (comp.board_status !== 'قائم') gaps.push('مجلس الإدارة غير قائم');
            if (!comp.has_executive_management) gaps.push('غياب الإدارة التنفيذية');
            if (!comp.has_auditor_company) gaps.push('لم يتم تعيين مدقق خارجي');

            gaps.forEach((gap, idx) => {
                newItems.push({
                    id: generateId(),
                    evaluation_id: evalId,
                    indicator_id: `COMP-${idx}`,
                    priority: 'High',
                    issue_summary: `قصور امتثال: ${gap}`,
                    recommended_action: 'استيفاء المتطلب النظامي فوراً.',
                    owner: 'أمين السر / المدير',
                    due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                    status: 'ToDo',
                    notes: 'تم استيراده تلقائياً من سجل الامتثال'
                });
            });
        }

        // Save & Set State
        if (newItems.length > 0) {
            newItems.forEach(saveImprovement);
            setColumns(prev => ({ ...prev, ToDo: newItems }));
            showToast(`تم إنشاء ${newItems.length} مهام تحسين تلقائياً`, 'info');
        }
    }

  }, [currentWaqfId, institutions]);

  // Actions
  const moveItem = (item: ImprovementItem, direction: 'forward' | 'backward') => {
      let newStatus: ColumnType = item.status;

      if (direction === 'forward') {
          if (item.status === 'ToDo') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'Done';
      } else {
          if (item.status === 'Done') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'ToDo';
      }

      if (newStatus !== item.status) {
          const updatedItem = { ...item, status: newStatus };
          saveImprovement(updatedItem); // Persist

          // Optimistic UI Update
          setColumns(prev => {
              const sourceList = prev[item.status].filter(i => i.id !== item.id);
              const targetList = [updatedItem, ...prev[newStatus]];
              return { ...prev, [item.status as ColumnType]: sourceList, [newStatus]: targetList };
          });
      }
  };

  const handleDelete = (id: string, status: ColumnType) => {
      if(confirm('هل أنت متأكد من حذف هذه المهمة؟')) {
          deleteImprovement(id);
          setColumns(prev => ({
              ...prev,
              [status]: prev[status].filter(i => i.id !== id)
          }));
          showToast('تم حذف المهمة', 'info');
      }
  };

  const handleManualSave = () => {
      // Re-save all items (redundant but gives user peace of mind)
      const allItems = [...columns.ToDo, ...columns.Doing, ...columns.Done];
      if (allItems.length > 0) {
          allItems.forEach(saveImprovement);
          showToast('تم حفظ كافة التغييرات بنجاح', 'success');
      } else {
          showToast('لا توجد مهام للحفظ', 'info');
      }
  };

  const handleDownloadPDF = () => {
      const element = document.getElementById('kanban-board');
      if (!element) return;

      const opt = {
        margin:       5,
        filename:     `Improvement-Plan-${institutionName}.pdf`,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2, useCORS: true },
        jsPDF:        { unit: 'mm', format: 'a4', orientation: 'landscape' } // Landscape for Kanban
      };

      html2pdf().from(element).set(opt).save();
  };

  const getSourceBadge = (indicatorId: string) => {
      if (indicatorId.startsWith('RISK-')) return { label: 'مخاطر', color: 'bg-red-100 text-red-800', icon: ShieldAlert };
      if (indicatorId.startsWith('COMP-')) return { label: 'امتثال', color: 'bg-purple-100 text-purple-800', icon: Scale };
      return { label: 'أداء', color: 'bg-orange-100 text-orange-800', icon: Activity };
  };

  return (
    <div className="space-y-6 min-h-screen">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white flex items-center gap-2">
            <Layout className="text-teal-600"/> لوحة متابعة التحسين (Kanban)
        </h2>
        {currentWaqfId && (
            <div className="flex gap-2">
                <button 
                    onClick={handleManualSave} 
                    className="bg-teal-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-md transition-colors font-bold text-sm"
                >
                    <Save size={18} /> حفظ
                </button>
                <button 
                    onClick={handleDownloadPDF} 
                    className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 shadow-md transition-colors font-bold text-sm"
                >
                    <Download size={18} /> تصدير PDF
                </button>
            </div>
        )}
      </div>

       {/* Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn no-print mb-8">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">خطة المؤسسة:</div>
                      <div className="text-lg font-bold">{institutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center no-print">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى اختيار مؤسسة لعرض مهام التحسين الخاصة بها.</p>
          </div>
      )}

      {currentWaqfId && (
        <div id="kanban-board" className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full items-start overflow-x-auto pb-10 bg-white/50 p-4 rounded-xl">
            {/* Column 1: To Do */}
            <KanbanColumn 
                title="مهام جديدة" 
                count={columns.ToDo.length} 
                color="border-red-400 bg-red-50 dark:bg-red-900/10"
                icon={<AlertTriangle size={18} className="text-red-600"/>}
            >
                {columns.ToDo.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'ToDo')}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 2: Doing */}
            <KanbanColumn 
                title="جاري المعالجة" 
                count={columns.Doing.length} 
                color="border-yellow-400 bg-yellow-50 dark:bg-yellow-900/10"
                icon={<Clock size={18} className="text-yellow-600"/>}
            >
                {columns.Doing.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'Doing')}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 3: Done */}
            <KanbanColumn 
                title="تم الإنجاز" 
                count={columns.Done.length} 
                color="border-green-400 bg-green-50 dark:bg-green-900/10"
                icon={<CheckCircle size={18} className="text-green-600"/>}
            >
                {columns.Done.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onDelete={() => handleDelete(item.id, 'Done')}
                        badge={getSourceBadge(item.indicator_id)}
                        isDone
                    />
                ))}
            </KanbanColumn>
        </div>
      )}
    </div>
  );
};

// --- Sub Components ---

const KanbanColumn = ({ title, count, children, color, icon }: any) => (
    <div className={`flex flex-col h-full min-h-[500px] rounded-xl border-t-4 ${color} bg-gray-50/50 dark:bg-gray-800 shadow-sm`}>
        <div className="p-4 flex justify-between items-center border-b border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-xl">
            <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">{icon} {title}</h3>
            <span className="bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 text-xs px-2 py-1 rounded-full font-bold">{count}</span>
        </div>
        <div className="p-3 space-y-3 flex-1">
            {children}
            {count === 0 && <div className="text-center py-10 text-gray-400 text-sm italic">لا توجد مهام</div>}
        </div>
    </div>
);

const KanbanCard = ({ item, onMoveBack, onMoveForward, onDelete, badge, isDone }: any) => {
    const Icon = badge.icon;
    return (
        <div className={`bg-white dark:bg-gray-700 p-4 rounded-lg shadow-sm border border-gray-100 dark:border-gray-600 hover:shadow-md transition-shadow relative group ${isDone ? 'opacity-75' : ''}`}>
            {/* Delete Button (Hidden until hover) */}
            <button 
                onClick={onDelete}
                className="absolute top-2 left-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity no-print"
            >
                <Trash2 size={16} />
            </button>

            {/* Badge */}
            <div className="flex justify-between items-start mb-2">
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1 ${badge.color}`}>
                    <Icon size={12} /> {badge.label}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded border ${item.priority === 'High' ? 'text-red-600 border-red-200 bg-red-50' : 'text-gray-500 border-gray-200'}`}>
                    {item.priority === 'High' ? 'أولوية قصوى' : 'عادية'}
                </span>
            </div>

            {/* Content */}
            <h4 className={`font-bold text-sm text-navy-900 dark:text-white mb-2 ${isDone ? 'line-through text-gray-500' : ''}`}>
                {item.issue_summary}
            </h4>
            <p className="text-xs text-gray-500 dark:text-gray-300 mb-3 leading-relaxed bg-gray-50 dark:bg-gray-800 p-2 rounded">
                {item.recommended_action}
            </p>

            <div className="flex justify-between items-center text-xs text-gray-400 border-t border-gray-100 dark:border-gray-600 pt-2 mb-3">
                <span>{item.owner}</span>
                <span>{item.due_date}</span>
            </div>

            {/* Controls */}
            <div className="flex justify-between items-center gap-2 no-print">
                {onMoveForward ? (
                    <button onClick={onMoveForward} className="flex-1 bg-navy-50 text-navy-800 hover:bg-navy-100 dark:bg-navy-900 dark:text-blue-200 dark:hover:bg-navy-800 py-1.5 rounded text-xs font-bold flex justify-center items-center gap-1 transition-colors">
                        نقل للمرحلة التالية <ArrowLeft size={14} />
                    </button>
                ) : <div className="flex-1"></div>}

                {onMoveBack && (
                     <button onClick={onMoveBack} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-500 transition-colors" title="عودة للسابق">
                         <ArrowRight size={16} />
                     </button>
                )}
            </div>
        </div>
    );
};

export default Improvements;

import React, { useState, useEffect } from 'react';
import { 
    getInstitutions, getEvaluations, getResponses, getIndicators, 
    getImprovements, saveImprovement, deleteImprovement, 
    getRisks, getComplianceByInstAndYear, generateId 
} from '../services/db';
import { Institution, ImprovementItem } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    Clock, CheckCircle, AlertTriangle, Building, 
    ArrowRight, ArrowLeft, Trash2, Layout, Activity, ShieldAlert, Scale,
    Save, Download, Printer
} from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// Declare html2pdf for TypeScript
declare const html2pdf: any;

type ColumnType = 'ToDo' | 'Doing' | 'Done';

const Improvements: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { currentWaqfId, showToast } = useUi();
  const [institutionName, setInstitutionName] = useState('');

  // Kanban State
  const [columns, setColumns] = useState<{ [key in ColumnType]: ImprovementItem[] }>({
      ToDo: [],
      Doing: [],
      Done: []
  });

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  // Main Data Loading & Auto-Generation Logic
  useEffect(() => {
    if (!currentWaqfId) {
        setColumns({ ToDo: [], Doing: [], Done: [] });
        return;
    }

    const inst = institutions.find(i => i.id === currentWaqfId);
    setInstitutionName(inst?.name || '');

    // Get Evaluation ID (Create dummy if missing to group items)
    const ev = getEvaluations().find(e => e.institution_id === currentWaqfId && e.cycle_year === CURRENT_YEAR);
    const evalId = ev?.id || `TEMP_EVAL_${currentWaqfId}`; 

    // 1. Fetch Existing Improvements
    const existingItems = getImprovements(evalId);

    if (existingItems.length > 0) {
        // Sort into columns
        setColumns({
            ToDo: existingItems.filter(i => i.status === 'ToDo'),
            Doing: existingItems.filter(i => i.status === 'Doing'),
            Done: existingItems.filter(i => i.status === 'Done'),
        });
    } else {
        // 2. Auto-Generate from 3 Sources
        const newItems: ImprovementItem[] = [];
        const indicators = getIndicators();

        // Source A: Performance Weaknesses (Score < 3)
        if (ev) {
            const responses = getResponses(ev.id);
            responses.filter(r => r.score < 3).forEach(r => {
                const ind = indicators.find(i => i.id === r.indicator_id);
                if (ind) {
                    newItems.push({
                        id: generateId(),
                        evaluation_id: evalId,
                        indicator_id: `PERF-${ind.id}`, // Prefix to identify source
                        priority: 'Medium',
                        issue_summary: `ضعف الأداء: ${ind.text.substring(0, 50)}...`,
                        recommended_action: 'تحليل أسباب الانخفاض ووضع خطة تصحيحية.',
                        owner: 'مدير العمليات',
                        due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                        status: 'ToDo',
                        notes: 'تم استيراده تلقائياً من التقييم'
                    });
                }
            });
        }

        // Source B: High Risks (Prob * Impact >= 15)
        const risks = getRisks(currentWaqfId);
        risks.filter(r => (r.probability * r.impact) >= 15).forEach(r => {
            newItems.push({
                id: generateId(),
                evaluation_id: evalId,
                indicator_id: `RISK-${r.id}`,
