              axisScores[ind.axis].count += 1;
          }
      });

      return Object.keys(axisScores).map((axis, index) => {
          const data = axisScores[axis];
          return {
              id: index,
              subject: axis,
              A: Number((data.total / data.count).toFixed(1)),
              fullMark: 5
          };
      });
  }, [filteredResponses, indicators]);


  return (
