  notes?: string;
  documents?: InstitutionDocument[];
  created_at: string;
}

export interface Indicator {
  id: string;
  axis: string; // المحور
  text: string; // وصف التقييم
  weight: number;
  active: boolean;
}

export interface Evaluation {
  id: string;
  institution_id: string;
  cycle_year: number;
  cycle_date: string;
  evaluator_name?: string;
  status: 'draft' | 'final';
  attachments?: InstitutionDocument[];
