  id: string;
  evaluation_id: string;
  indicator_id: string;
  score: number; // 1-5
  evidence_text?: string;
  updated_at: string;
}

export interface CustomRequirement {
    id: string;
    text: string;
    met: boolean;
}

export interface ComplianceRecord {
  id: string;
  institution_id: string;
  cycle_year: number;
  institution_status: 'فاعلة' | 'غير فاعلة' | 'قيد التصفية' | 'متوقفة' | 'أخرى';
