export const calculateRiskScore = (rec: any): { score: number; label: string; color: string } => {
  let score = 0;

  // Check if fields are hidden (deleted by user)
  const hidden = rec.hidden_core_requirements || [];

  if (rec.board_status === 'منتهي' || rec.board_status === 'غير موجود') score += 3;
  if (rec.institution_status !== 'فاعلة') score += 3;

  // Add points only if the requirement is NOT met AND NOT hidden
  if (!hidden.includes('has_executive_management') && !rec.has_executive_management) score += 2;
  if (!hidden.includes('has_auditor_company') && !rec.has_auditor_company) score += 2;
  if (!hidden.includes('has_financial_report_prev_year') && !rec.has_financial_report_prev_year) score += 2;
  if (!hidden.includes('has_minutes_prev_year') && !rec.has_minutes_prev_year) score += 1;

  let label = 'منخفض';
  let color = 'bg-green-100 text-green-800'; // Default / Low

  if (score >= 9) {
    label = 'حرج';
    color = 'bg-red-100 text-red-800';
  } else if (score >= 6) {
    label = 'مرتفع';
    color = 'bg-orange-100 text-orange-800';
  } else if (score >= 3) {
    label = 'متوسط';
    color = 'bg-yellow-100 text-yellow-800';
  }

  return { score, label, color };
};

