                            {/* Add New Section (Only in Edit Mode) */}
                            {isEditMode && (
                                <div className="mt-6 pt-6 border-t border-amber-200 animate-slideIn">
                                    <h4 className="text-sm font-bold text-amber-800 mb-3 flex items-center gap-2"><Plus size={16}/> إضافة معيار جديد</h4>
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            className="flex-1 border border-amber-300 p-2.5 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 outline-none" 
                                            placeholder="أدخل نص المعيار الجديد هنا..." 
                                            value={newReqText} 
                                            onChange={e => setNewReqText(e.target.value)} 
                                            onKeyDown={(e) => e.key === 'Enter' && handleAddRequirement()}
                                        />
                                        <button onClick={handleAddRequirement} className="bg-amber-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-amber-700 shadow-sm">
