    { to: '/reports', icon: FileBarChart, label: 'النتائج والتقارير', roles: ['admin'] },
    { to: '/settings', icon: Settings, label: 'إعدادات النظام', roles: ['admin'] },
  ];

  // Filter based on current role
  const navItems = allNavItems.filter(item => role && item.roles.includes(role));

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900 overflow-hidden font-sans text-right" dir="rtl">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-navy-900 dark:bg-black text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0 shadow-2xl ${sidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex items-center justify-between p-4 border-b border-navy-800 min-h-[5rem]">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 min-w-[2.5rem] bg-white rounded-full p-1 overflow-hidden flex items-center justify-center shadow-md">
                 <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/5/52/Ministry_of_Endowments_and_Religious_Affairs_%28Oman%29_Logo.png" 
                    className="w-full h-full object-contain" 
                    onError={(e) => {
                        e.currentTarget.style.display = 'none';
                    }}
                 />
             </div>
             <div className="flex flex-col">
                 <h1 className="text-sm font-bold text-white leading-tight">نظام تقييم المؤسسات الوقفية</h1>
                 <span className="text-[10px] text-gray-400 mt-1 font-medium">وزارة الأوقاف والشؤون الدينية</span>
             </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-gray-400 hover:text-white">
            <X size={24} />
          </button>
        </div>

        {/* User Role Badge */}
        <div className="px-4 mt-4">
            <div className={`p-2 rounded-lg text-center text-xs font-bold border ${role === 'admin' ? 'bg-navy-800 border-navy-700 text-gold-400' : 'bg-teal-900/50 border-teal-800 text-teal-400'}`}>
                {role === 'admin' ? 'صلاحية: مدير نظام' : 'صلاحية: مؤسسة وقفية'}
            </div>
        </div>

        <nav className="p-4 space-y-2 flex-1 overflow-y-auto mt-2">
          {navItems.map((item) => {
              const locked = isRouteLocked(item.to, role, progress);
              return (
                  <SidebarItem 
                    key={item.to} 
                    {...item} 
                    active={location.pathname === item.to} 
                    locked={locked}
                  />
              );
          })}
          <button 
            onClick={logout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors duration-200 text-red-300 hover:bg-navy-800/50 mt-4"
          >
             <LogOut size={20} />
             <span className="font-medium">تسجيل الخروج</span>
          </button>
        </nav>
        <div className="absolute bottom-0 w-full p-4 border-t border-navy-800 text-xs text-gray-400 text-center">
          <p>{settings.orgName}</p>
          <p className="mt-1 text-gold-500">تحت إشراف {settings.managerName}</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="bg-white dark:bg-gray-800 shadow-sm z-10 border-b border-gray-200 dark:border-gray-700 h-20 flex items-center px-6 justify-between print:hidden">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-gray-600 dark:text-gray-200">
                <Menu size={24} />
            </button>

            <div className="flex flex-col items-center flex-1 lg:flex-none lg:items-start">
                <h2 className="text-xl font-bold text-navy-900 dark:text-white">نظام تقييم المؤسسات الوقفية</h2>
                <span className="text-xs text-teal-600 dark:text-teal-400 font-semibold hidden md:block">سلطنة عُمان - {settings.orgName}</span>
            </div>

            <div className="hidden md:flex items-center gap-4">
                <div className="text-left">
                   <p className="text-sm font-bold text-navy-900 dark:text-white">أهلاً، {user}</p>
                   <p className="text-xs text-gold-600 dark:text-gold-400">{role === 'admin' ? 'مدير النظام' : 'مستخدم مؤسسة'}</p>
                </div>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-md ${role === 'admin' ? 'bg-navy-800' : 'bg-teal-600'}`}>
                    {user?.charAt(0).toUpperCase()}
                </div>
            </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-4 lg:p-8 relative dark:text-gray-100">
          {children}

          {/* Footer - Print Only */}
          <div className="hidden print:block fixed bottom-0 left-0 right-0 text-center p-4 border-t text-sm">
             <p>تم استخراج هذا التقرير آلياً من نظام تقييم المؤسسات الوقفية</p>
             <p className="font-bold">تحت إشراف {settings.managerName}</p>
          </div>
        </main>
      </div>

      {/* Overlay for mobile sidebar */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, getComplianceByInstAndYear, getRisks, saveRisk, deleteRisk } from '../services/db';
import { Institution, ComplianceRecord, RiskRegisterItem, CustomRequirement } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Save, AlertTriangle, CheckCircle, Info, ShieldAlert, Plus, Trash2, Scale, X, Building, Settings, Lock, Edit2, CheckSquare } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

const CORE_REQUIREMENTS = [
    { key: 'has_executive_management', label: 'هل توجد إدارة تنفيذية أو مدير؟' },
    { key: 'has_auditor_company', label: 'هل تم تعيين شركة تدقيق؟' },
    { key: 'has_minutes_prev_year', label: 'هل توجد محاضر اجتماعات للعام الماضي؟' },
    { key: 'has_financial_report_prev_year', label: 'هل يوجد تقرير مالي معتمد للعام الماضي؟' },
];

const CompliancePage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'compliance' | 'risks'>('compliance');
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { showToast, currentWaqfId, role } = useUi();

  // Compliance State
  const [record, setRecord] = useState<Partial<ComplianceRecord>>({});
  const [newReqText, setNewReqText] = useState('');

  // Admin Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Risk Register State
  const [instRisks, setInstRisks] = useState<RiskRegisterItem[]>([]);
  const [newRisk, setNewRisk] = useState<Partial<RiskRegisterItem>>({});
  const [showRiskForm, setShowRiskForm] = useState(false);

  // Real-time calculated risk based on compliance form
  const complianceRisk = calculateRiskScore(record);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (currentWaqfId) {
        // Load Compliance
        const existing = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
        if (existing) {
            setRecord(existing);
        } else {
            setRecord({
                institution_id: currentWaqfId,
                cycle_year: CURRENT_YEAR,
                institution_status: 'فاعلة',
                board_status: 'قائم',
                has_executive_management: false,
                has_auditor_company: false,
                has_minutes_prev_year: false,
                has_financial_report_prev_year: false,
                custom_requirements: [],
                hidden_core_requirements: [],
                renamed_core_requirements: {},
                notes: ''
            });
        }

        // Load Risks
        setInstRisks(getRisks(currentWaqfId));
    } else {
        setRecord({});
        setInstRisks([]);
    }
    // Reset edit mode when changing institution
    setIsEditMode(false);
  }, [currentWaqfId]);

  const handleSaveCompliance = () => {
      if (!currentWaqfId) return;

      // Ensure ID exists or generate new one
      const recordId = record.id || generateId();

      const toSave: ComplianceRecord = {
          ...record as ComplianceRecord,
          id: recordId,
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          last_updated_at: new Date().toISOString()
      };

      saveComplianceRecord(toSave);
      setRecord(toSave); 
      setIsEditMode(false); // Exit edit mode on save
      showToast('تم حفظ سجل الامتثال بنجاح', 'success');
  };

  // --- CUSTOM REQUIREMENTS HANDLERS ---
  const handleAddRequirement = () => {
      if (!newReqText) return;
      const newReq: CustomRequirement = {
          id: generateId(),
          text: newReqText,
          met: false
      };
      setRecord(prev => ({
          ...prev,
          custom_requirements: [...(prev.custom_requirements || []), newReq]
      }));
      setNewReqText('');
      showToast('تم إضافة المعيار الجديد', 'success');
  };

  const handleRemoveRequirement = (id: string) => {
      if(confirm('هل أنت متأكد من حذف هذا المعيار؟')) {
        setRecord(prev => ({
            ...prev,
            custom_requirements: prev.custom_requirements?.filter(r => r.id !== id)
        }));
      }
  };

  const toggleCustomRequirement = (id: string) => {
      if (isEditMode) return; // Disable toggling in edit mode
      setRecord(prev => ({
          ...prev,
          custom_requirements: prev.custom_requirements?.map(r => r.id === id ? { ...r, met: !r.met } : r)
      }));
  };

  // --- CORE REQUIREMENTS EDIT HANDLERS ---
  const handleRemoveCoreReq = (key: string) => {
      if(confirm('حذف هذا المعيار الأساسي؟ سيتم إخفاؤه من القائمة ولن يدخل في حساب المخاطر.')) {
          const currentHidden = record.hidden_core_requirements || [];
          setRecord(prev => ({
              ...prev,
              hidden_core_requirements: [...currentHidden, key]
          }));
      }
  };

  const handleRenameCoreReq = (key: string, newText: string) => {
      const currentRenamed = record.renamed_core_requirements || {};
      setRecord(prev => ({
          ...prev,
          renamed_core_requirements: { ...currentRenamed, [key]: newText }
      }));
  };


  // --- RISK HANDLERS ---
  const handleSaveRisk = () => {
      if (!currentWaqfId || !newRisk.risk_title) return;
      const riskToSave: RiskRegisterItem = {
          id: generateId(),
          institution_id: currentWaqfId,
          risk_title: newRisk.risk_title!,
          category: newRisk.category || 'Operational',
          probability: Number(newRisk.probability) || 1,
          impact: Number(newRisk.impact) || 1,
          mitigation_plan: newRisk.mitigation_plan || '',
          status: 'Open'
      };
      saveRisk(riskToSave);
      setInstRisks(getRisks(currentWaqfId));
      setShowRiskForm(false);
      setNewRisk({});
      showToast('تم إضافة الخطر بنجاح', 'success');
  };

  const handleDeleteRisk = (id: string) => {
      if(confirm('حذف هذا الخطر؟')) {
          deleteRisk(id);
          setInstRisks(getRisks(currentWaqfId));
          showToast('تم حذف الخطر', 'info');
      }
  };

  const updateComplianceField = (field: keyof ComplianceRecord, value: any) => {
      if (isEditMode) return; // Prevent changing values while editing structure
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6 pb-12">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">الامتثال والمخاطر ({CURRENT_YEAR})</h2>
      </div>

      {/* Currently Viewing Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري إدارة امتثال:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود العمل عليها.</p>
          </div>
      )}

      {currentWaqfId && (
          <div className="animate-fadeIn">
              {/* Tabs */}
              <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6">
                  <button 
                    onClick={() => setActiveTab('compliance')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'compliance' ? 'border-b-2 border-navy-800 text-navy-900 dark:text-white dark:border-white' : 'text-gray-500 hover:text-navy-700 dark:text-gray-400'}`}
                  >
                      <span className="flex items-center gap-2"><Scale size={16} /> الامتثال النظامي</span>
                  </button>
                  <button 
                    onClick={() => setActiveTab('risks')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'risks' ? 'border-b-2 border-navy-800 text-navy-900 dark:text-white dark:border-white' : 'text-gray-500 hover:text-navy-700 dark:text-gray-400'}`}
                  >
                      <span className="flex items-center gap-2"><ShieldAlert size={16} /> سجل المخاطر</span>
                  </button>
              </div>

              {/* COMPLIANCE TAB */}
              {activeTab === 'compliance' && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">

                        {/* Status Card */}
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                            <h3 className="font-bold text-navy-900 dark:text-white mb-4 flex items-center gap-2">
                                <Info size={20} className="text-teal-600" /> الحالة الأساسية
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة المؤسسة</label>
                                    <select 
                                        disabled={isEditMode}
                                        className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                        value={record.institution_status || 'فاعلة'} 
                                        onChange={(e) => updateComplianceField('institution_status', e.target.value)}
                                    >
                                        <option value="فاعلة">فاعلة</option>
                                        <option value="غير فاعلة">غير فاعلة</option>
                                        <option value="قيد التصفية">قيد التصفية</option>
                                        <option value="متوقفة">متوقفة</option>
                                        <option value="أخرى">أخرى</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة مجلس الإدارة</label>
                                    <select 
                                        disabled={isEditMode}
                                        className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                        value={record.board_status || 'قائم'} 
                                        onChange={(e) => updateComplianceField('board_status', e.target.value)}
                                    >
                                        <option value="قائم">قائم</option>
                                        <option value="منتهي">منتهي الصلاحية</option>
                                        <option value="غير موجود">غير موجود</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Requirements List Container */}
                        <div className={`bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border transition-all ${isEditMode ? 'border-amber-400 ring-2 ring-amber-100' : 'border-gray-100 dark:border-gray-700'}`}>
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">
                                    <CheckCircle size={20} className="text-teal-600" /> المتطلبات النظامية
                                </h3>

                                {role === 'admin' && (
                                    <button 
                                        onClick={() => setIsEditMode(!isEditMode)}
                                        className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${isEditMode ? 'bg-amber-100 text-amber-800 hover:bg-amber-200' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                    >
                                        {isEditMode ? (
                                            <> <CheckSquare size={16}/> إنهاء التعديل </>
                                        ) : (
                                            <> <Settings size={16}/> تعديل المعايير </>
                                        )}
                                    </button>
                                )}
                            </div>

                            {/* 1. Core Requirements (With Edit/Delete Support) */}
                            <div className="space-y-4 mb-6">
                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">المعايير الأساسية</h4>
                                {CORE_REQUIREMENTS.map((req) => {
                                    // Check if this core requirement is hidden
                                    if (record.hidden_core_requirements?.includes(req.key)) return null;

                                    // Get renamed label if exists
                                    const displayLabel = record.renamed_core_requirements?.[req.key] || req.label;

                                    return (
                                        <div key={req.key} className="flex items-center gap-3 relative animate-fadeIn">
                                            {isEditMode ? (
                                                <div className="flex-1 flex gap-2 items-center bg-gray-50 border border-gray-200 p-2 rounded-lg">
                                                    <input 
                                                        type="text" 
                                                        className="flex-1 bg-white border border-gray-300 rounded px-2 py-1 text-sm focus:ring-2 focus:ring-amber-500 outline-none"
                                                        value={displayLabel}
                                                        onChange={(e) => handleRenameCoreReq(req.key, e.target.value)}
                                                    />
                                                    <button 
                                                        onClick={() => handleRemoveCoreReq(req.key)} 
                                                        className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                                                        title="حذف هذا المعيار الأساسي"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            ) : (
                                                <ToggleItem 
                                                    label={displayLabel} 
                                                    checked={!!(record as any)[req.key]} 
                                                    onChange={() => updateComplianceField(req.key as keyof ComplianceRecord, !(record as any)[req.key])} 
                                                    className={`flex-1`}
                                                />
                                            )}
                                        </div>
                                    );
                                })}
                                {record.hidden_core_requirements?.length === CORE_REQUIREMENTS.length && (
                                     <p className="text-xs text-gray-400 text-center py-4 border border-dashed border-gray-200 rounded-lg">تم حذف جميع المعايير الأساسية</p>
                                )}
                            </div>

                            {/* 2. Custom Requirements (Dynamic) */}
                            <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider">المعايير الإضافية</h4>
                                </div>

                                <div className="space-y-2">
                                    {record.custom_requirements?.map(req => (
                                        <div key={req.id} className="flex items-center gap-2 animate-fadeIn">
                                            {isEditMode ? (
                                                // Edit Mode for Custom Requirements
                                                <div className="flex-1 flex gap-2 items-center bg-amber-50 border border-amber-200 p-2 rounded-lg">
                                                    <span className="flex-1 text-sm text-gray-700 px-2">{req.text}</span>
                                                    <button 
                                                        onClick={() => handleRemoveRequirement(req.id)} 
                                                        className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                                                        title="حذف المعيار"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            ) : (
                                                // View Mode
                                                <ToggleItem 
                                                    label={req.text} 
                                                    checked={req.met} 
                                                    onChange={() => toggleCustomRequirement(req.id)} 
                                                    className="flex-1"
                                                />
                                            )}
                                        </div>
                                    ))}
                                    {(!record.custom_requirements || record.custom_requirements.length === 0) && (
                                        <p className="text-xs text-gray-400 text-center py-4 border border-dashed border-gray-200 rounded-lg">لا توجد معايير إضافية</p>
                                    )}
                                </div>
                            </div>

                            {/* Add New Section (Only in Edit Mode) */}
                            {isEditMode && (
                                <div className="mt-6 pt-6 border-t border-amber-200 animate-slideIn">
                                    <h4 className="text-sm font-bold text-amber-800 mb-3 flex items-center gap-2"><Plus size={16}/> إضافة معيار جديد</h4>
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            className="flex-1 border border-amber-300 p-2.5 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 outline-none" 
                                            placeholder="أدخل نص المعيار الجديد هنا..." 
                                            value={newReqText} 
                                            onChange={e => setNewReqText(e.target.value)} 
                                            onKeyDown={(e) => e.key === 'Enter' && handleAddRequirement()}
                                        />
                                        <button onClick={handleAddRequirement} className="bg-amber-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-amber-700 shadow-sm">
                                            إضافة
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>

                        {!isEditMode && (
                            <button onClick={handleSaveCompliance} className="w-full bg-navy-800 text-white p-4 rounded-xl font-bold shadow-lg hover:bg-navy-900 flex justify-center items-center gap-2 transition-transform active:scale-95">
                                <Save size={20} /> حفظ سجل الامتثال
                            </button>
                        )}

                        {isEditMode && (
                             <div className="bg-amber-50 border border-amber-200 text-amber-800 p-4 rounded-xl flex items-center justify-between">
                                 <span className="text-sm font-medium">أنت في وضع التعديل. قم بإضافة أو حذف أو تعديل المؤشرات ثم اضغط إنهاء.</span>
                                 <button onClick={() => setIsEditMode(false)} className="bg-white border border-amber-300 px-4 py-2 rounded-lg text-sm font-bold hover:bg-amber-100">
                                     إنهاء التعديل
                                 </button>
                             </div>
                        )}
                    </div>

                    {/* Sidebar Risk */}
                    <div className="lg:col-span-1">
                        <div className={`sticky top-6 p-6 rounded-xl border ${complianceRisk.score >= 6 ? 'bg-red-50 border-red-200 dark:bg-red-900/20 dark:border-red-900' : 'bg-green-50 border-green-200 dark:bg-green-900/20 dark:border-green-900'}`}>
                            <h3 className="text-lg font-bold text-navy-900 dark:text-white mb-2">تحليل المخاطر (الامتثال)</h3>
                            <div className="flex items-center gap-3 mb-6">
                                <div className={`text-4xl font-bold ${complianceRisk.score >= 6 ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>{complianceRisk.score}</div>
                                <div><div className="text-xs text-gray-500 dark:text-gray-400 uppercase">نقاط الخطر</div><div className={`font-bold ${complianceRisk.score >= 6 ? 'text-red-700 dark:text-red-300' : 'text-green-700 dark:text-green-300'}`}>{complianceRisk.label}</div></div>
                            </div>
                            <div className="space-y-3">
                                <RiskIndicator 
                                    label="مجلس الإدارة" 
                                    active={record.board_status !== 'قائم'} 
                                    points={3} 
                                />

                                {/* Core Requirements in Risk Panel - Hide if Deleted */}
                                {!record.hidden_core_requirements?.includes('has_executive_management') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_executive_management'] || "الإدارة التنفيذية"} 
                                        active={!record.has_executive_management} 
                                        points={2} 
                                    />
                                )}
                                {!record.hidden_core_requirements?.includes('has_auditor_company') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_auditor_company'] || "شركة التدقيق"} 
                                        active={!record.has_auditor_company} 
                                        points={2} 
                                    />
                                )}
                                {!record.hidden_core_requirements?.includes('has_financial_report_prev_year') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_financial_report_prev_year'] || "التقرير المالي"} 
                                        active={!record.has_financial_report_prev_year} 
                                        points={2} 
                                    />
                                )}
                            </div>
                        </div>
                    </div>
                </div>
              )}

              {/* RISK REGISTER TAB */}
              {activeTab === 'risks' && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                          <h3 className="text-lg font-bold text-navy-900 dark:text-white">قائمة المخاطر المرصودة</h3>
                          <button onClick={() => setShowRiskForm(true)} className="bg-red-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-700 text-sm shadow-md"><Plus size={16} /> إضافة خطر</button>
                      </div>

                      {showRiskForm && (
                          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-xl border border-gray-200 dark:border-gray-700 animate-fadeIn">
                              <h4 className="font-bold mb-4 dark:text-white">تسجيل خطر جديد</h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">وصف الخطر</label>
                                      <input type="text" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.risk_title || ''} onChange={e => setNewRisk({...newRisk, risk_title: e.target.value})} placeholder="مثال: نزاع قانوني على أصل وقفي" />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">التصنيف</label>
                                      <select className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.category} onChange={e => setNewRisk({...newRisk, category: e.target.value as any})}>
                                          <option value="Operational">تشغيلي</option>
                                          <option value="Financial">مالي</option>
                                          <option value="Legal">قانوني</option>
                                          <option value="Strategic">استراتيجي</option>
                                      </select>
                                  </div>
                                  <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">الاحتمالية (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.probability || ''} onChange={e => setNewRisk({...newRisk, probability: Number(e.target.value)})} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">الأثر (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.impact || ''} onChange={e => setNewRisk({...newRisk, impact: Number(e.target.value)})} />
                                    </div>
                                  </div>
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">خطة المعالجة</label>
                                      <input type="text" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.mitigation_plan || ''} onChange={e => setNewRisk({...newRisk, mitigation_plan: e.target.value})} />
                                  </div>
                              </div>
                              <div className="flex gap-2 justify-end">
                                  <button onClick={() => setShowRiskForm(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded dark:text-gray-300 dark:hover:bg-gray-700">إلغاء</button>
                                  <button onClick={handleSaveRisk} className="bg-navy-800 text-white px-4 py-2 rounded hover:bg-navy-900">حفظ</button>
                              </div>
                          </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {instRisks.map(risk => {
                              const score = risk.probability * risk.impact;
                              let color = 'bg-green-100 border-green-200 dark:bg-green-900/30 dark:border-green-800';
                              if (score >= 15) color = 'bg-red-50 border-red-200 dark:bg-red-900/30 dark:border-red-800';
                              else if (score >= 8) color = 'bg-orange-50 border-orange-200 dark:bg-orange-900/30 dark:border-orange-800';

                              return (
                                  <div key={risk.id} className={`p-4 rounded-xl border ${color} relative group`}>
                                      <button onClick={() => handleDeleteRisk(risk.id)} className="absolute top-2 left-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                                      <div className="flex justify-between items-start mb-2">
                                          <span className="text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400">{risk.category}</span>
                                          <span className={`text-xs font-bold px-2 py-1 rounded-full ${score >= 15 ? 'bg-red-500 text-white' : (score >= 8 ? 'bg-orange-500 text-white' : 'bg-green-500 text-white')}`}>
                                              {score} (شدة الخطر)
                                          </span>
                                      </div>
                                      <h4 className="font-bold text-navy-900 dark:text-white mb-2">{risk.risk_title}</h4>
                                      <p className="text-sm text-gray-600 dark:text-gray-300 mb-3">{risk.mitigation_plan || 'لا توجد خطة معالجة'}</p>
                                      <div className="flex gap-2 text-xs text-gray-500 dark:text-gray-400 border-t pt-2 border-gray-200/50 dark:border-gray-700">
                                          <span>P: {risk.probability}</span>
                                          <span>I: {risk.impact}</span>
                                      </div>
                                  </div>
                              )
                          })}
                          {instRisks.length === 0 && (
                              <div className="col-span-full py-10 text-center text-gray-400 border border-dashed border-gray-300 dark:border-gray-600 rounded-xl">
                                  لا توجد مخاطر مسجلة
                              </div>
                          )}
                      </div>
                  </div>
              )}
          </div>
      )}
    </div>
  );
};

// UI Components
const ToggleItem = ({ label, checked, onChange, className, disabled }: any) => (
    <div 
        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${disabled ? 'cursor-not-allowed bg-gray-50' : 'cursor-pointer'} ${checked ? 'bg-teal-50 border-teal-200 dark:bg-teal-900/30 dark:border-teal-800' : 'bg-white border-gray-200 hover:bg-gray-50 dark:bg-gray-800 dark:border-gray-700 dark:hover:bg-gray-700'} ${className}`}
        onClick={!disabled ? onChange : undefined}
    >
        <span className={`font-medium ${checked ? 'text-teal-900 dark:text-teal-300' : 'text-gray-600 dark:text-gray-300'}`}>{label}</span>
        <div className={`w-12 h-6 rounded-full relative transition-colors ${checked ? 'bg-teal-600' : 'bg-gray-300 dark:bg-gray-600'}`}>
            <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all shadow-sm ${checked ? 'left-1' : 'right-1'}`}></div>
        </div>
    </div>
);

const RiskIndicator = ({ label, active, points }: any) => (
    <div className={`flex justify-between items-center text-sm ${active ? 'opacity-100' : 'opacity-40'}`}>
        <span className="flex items-center gap-2 dark:text-gray-300">
            {active ? <AlertTriangle size={14} className="text-red-500" /> : <CheckCircle size={14} className="text-gray-400" />}
            {label}
        </span>
        <span className="font-mono text-xs bg-white dark:bg-gray-700 dark:text-gray-300 px-2 py-0.5 rounded border dark:border-gray-600">+{points}</span>
    </div>
);

export default CompliancePage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType, InstitutionDocument } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X, FileText, UploadCloud, Calendar, Hash, User, CheckCircle2, Phone, AlertCircle, Building } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// توسيع الواجهة محلياً لتشمل تاريخ الانتهاء للعرض فقط
interface ExtendedFormData extends Partial<Institution> {
  expiry_date?: string;
}

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<ExtendedFormData>({});
  const { showToast, role, currentWaqfId, setWaqfContext } = useUi();

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  // دالة حساب تاريخ الانتهاء (4 سنوات) تلقائياً
  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const estDate = e.target.value;
    let expiryDate = '';

    if (estDate) {
      const date = new Date(estDate);
      if (!isNaN(date.getTime())) {
        date.setFullYear(date.getFullYear() + 4);
        expiryDate = date.toISOString().split('T')[0];
      }
    }

    setFormData(prev => ({
      ...prev,
      establishment_date: estDate,
      expiry_date: expiryDate
    }));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // التحقق الصارم من جميع الحقول
    if (
        !formData.name || 
        !formData.type || 
        formData.capital_omr === undefined || 
        !formData.contact_phone || 
        !formData.email || 
        !formData.governorate || 
        !formData.wilayat || 
        !formData.establishment_date || 
        !formData.license_number || 
        !formData.manager_name
    ) {
        showToast('عذراً، جميع الحقول إجبارية بما فيها رقم الهاتف وتاريخ المجلس.', 'error');
        return;
    }

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name,
      type: (formData.type as InstitutionType),
      capital_omr: Number(formData.capital_omr),
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone,
      email: formData.email,
      governorate: formData.governorate,
      wilayat: formData.wilayat,

      establishment_date: formData.establishment_date,
      license_number: formData.license_number,
      manager_name: formData.manager_name,

      documents: formData.documents || [],
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});

    // تحديث السياق وإعطاء صلاحية الدخول
    if (role === 'user') {
        setWaqfContext(newInst.id);
        localStorage.setItem('isProfileCompleted', 'true'); 
    }

    showToast('تم حفظ بيانات المؤسسة وتفعيل صلاحية التقييم', 'success');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setFormData(prev => ({
              ...prev,
              documents: [...(prev.documents || []), newDoc]
          }));
          showToast('تم إرفاق الملف بنجاح', 'info');
      }
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
      if (currentWaqfId === id) setWaqfContext('');
      showToast('تم حذف المؤسسة', 'info');
    }
  };

  const handleSelectContext = (id: string) => {
      setWaqfContext(id);
      localStorage.setItem('isProfileCompleted', 'true');
      showToast('تم اختيار المؤسسة للعمل عليها', 'success');
  };

  // --- Filtering Logic Update ---
  const filtered = list.filter(i => {
      // 1. Text Search Filter (Always applies)
      if (!i.name.includes(search)) return false;

      // 2. Global Context Filter
      // If currentWaqfId is set (User OR Admin who selected specific institution), filter by ID.
      if (currentWaqfId) {
          return i.id === currentWaqfId;
      }

      // 3. If no ID is set (Admin selected "All Institutions"), show everything.
      return true;
  });

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

  const currentInstitutionName = list.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">بيانات المؤسسات</h2>
        {role === 'admin' && (
            <button 
            onClick={() => { setFormData({}); setShowForm(true); }}
            className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900"
            >
            <Plus size={18} /> إضافة مؤسسة
            </button>
        )}
      </div>

      {/* Context Banner for Admins */}
      {currentWaqfId && (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">تصفية العرض حسب:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
              {role === 'admin' && (
                  <button 
                    onClick={() => setWaqfContext('')}
                    className="text-xs bg-white border border-blue-300 px-3 py-1.5 rounded-lg hover:bg-blue-50 text-blue-700"
                  >
                      عرض الكل
                  </button>
              )}
          </div>
      )}

      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <table className="w-full text-right">
          <thead className="bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 font-medium">
            <tr>
              <th className="p-4">المؤسسة</th>
              <th className="p-4">النوع</th>
              <th className="p-4">رقم القيد</th>
              <th className="p-4">تأسيس المجلس</th>
              <th className="p-4">المحافظة</th>
              <th className="p-4">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
            {filtered.length > 0 ? (
                filtered.map(inst => (
                <tr key={inst.id} className={`transition-colors ${currentWaqfId === inst.id ? 'bg-blue-50 dark:bg-blue-900/20' : ''}`}>
                    <td className="p-4 font-medium text-navy-900 dark:text-gray-200">
                        <div className="flex items-center gap-2">
                            {currentWaqfId === inst.id && <CheckCircle2 size={16} className="text-teal-500" />}
                            <div>
                                <div>{inst.name}</div>
                                <div className="text-xs text-gray-400 font-normal">{inst.contact_phone}</div>
                            </div>
                        </div>
                    </td>
                    <td className="p-4">
                    <span className={`px-2 py-1 rounded text-xs ${inst.type === 'وقفية عامة' ? 'bg-teal-100 text-teal-800' : 'bg-gold-100 text-gold-800'}`}>
                        {inst.type}
                    </span>
                    </td>
                    <td className="p-4 font-mono dark:text-gray-300">{inst.license_number}</td>
                    <td className="p-4 text-sm dark:text-gray-300">{inst.establishment_date}</td>
                    <td className="p-4">
                        <div className="text-sm dark:text-gray-300">{inst.governorate}</div>
                        <div className="text-xs text-gray-500">{inst.wilayat}</div>
                    </td>
                    <td className="p-4 flex gap-2 items-center">
                    {role === 'user' && currentWaqfId !== inst.id && (
                        <button onClick={() => handleSelectContext(inst.id)} className="text-xs bg-navy-100 text-navy-800 px-2 py-1 rounded hover:bg-navy-200">
                            اختيار
                        </button>
                    )}
                    <button onClick={() => { 
                        let expDate = '';
                        if (inst.establishment_date) {
                            const d = new Date(inst.establishment_date);
                            d.setFullYear(d.getFullYear() + 4);
                            expDate = d.toISOString().split('T')[0];
                        }
                        setFormData({...inst, expiry_date: expDate}); 
                        setShowForm(true); 
                        }} className="text-blue-600 hover:text-blue-800">
                        <Edit2 size={18} />
                    </button>
                    {role === 'admin' && (
                        <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800">
                            <Trash2 size={18} />
                        </button>
                    )}
                    </td>
                </tr>
                ))
            ) : (
                <tr>
                    <td colSpan={6} className="p-8 text-center text-gray-400">
                        لا توجد مؤسسات تطابق معايير البحث أو التصفية الحالية.
                        {currentWaqfId && role === 'admin' && (
                             <div className="mt-2">
                                 <button onClick={() => setWaqfContext('')} className="text-blue-600 underline text-sm">عرض جميع المؤسسات</button>
                             </div>
                        )}
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold">{formData.id ? 'تعديل مؤسسة' : 'إضافة مؤسسة جديدة'}</h3>
              <button onClick={() => setShowForm(false)}><X size={24} /></button>
            </div>

            <div className="bg-blue-50 p-4 border-b border-blue-100 flex gap-2 items-start text-sm text-blue-800">
                <AlertCircle className="w-5 h-5 shrink-0" />
                <p>تنبيه: لن تتمكن من الدخول إلى صفحة "تقييم نضج الحوكمة" إلا بعد تعبئة وحفظ كافة البيانات.</p>
            </div>

            <form onSubmit={handleSave} className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

              <div className="lg:col-span-3 pb-2 border-b mb-2">
                  <h4 className="text-navy-900 font-bold flex items-center gap-2"><FileText size={18}/> البيانات الأساسية</h4>
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium mb-1">اسم المؤسسة *</label>
                <input required className="w-full p-2 border rounded" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">النوع *</label>
                <select className="w-full p-2 border rounded" value={formData.type || 'وقفية عامة'} onChange={e => setFormData({...formData, type: e.target.value as any})}>
                  <option value="وقفية عامة">وقفية عامة</option>
                  <option value="وقفية خاصة">وقفية خاصة</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">رقم القيد *</label>
                <div className="relative">
                    <Hash className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input required type="text" placeholder="مثال: 10223" className="w-full p-2 pr-8 border rounded" value={formData.license_number || ''} onChange={e => setFormData({...formData, license_number: e.target.value})} />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">تاريخ تأسيس مجلس الإدارة *</label>
                <div className="relative">
                    <Calendar className="absolute top-2.5 right-2 text-gray-400" size={16} />
                    <input required type="date" className="w-full p-2 pr-8 border rounded" value={formData.establishment_date || ''} onChange={handleDateChange} />
                </div>
              </div>

               <div>
                <label className="block text-sm font-medium mb-1 text-red-600">تاريخ انتهاء المجلس (تلقائي)</label>
                <div className="relative">
                    <Calendar className="absolute top-2.5 right-2 text-red-300" size={16} />
