// Profile Configuration for Data Generation
// This ensures data consistency (Excellent institution gets high scores and low risks)
const PROFILES: Record<string, { 
    targetScore: number, 
    complianceIssues: number, 
    riskProfile: 'Low' | 'Medium' | 'High' | 'Critical',
    improvementProgress: 'Advanced' | 'Mixed' | 'Behind'
}> = {
    'INST-001': { targetScore: 4.8, complianceIssues: 0, riskProfile: 'Low', improvementProgress: 'Advanced' }, // Excellent
    'INST-002': { targetScore: 3.9, complianceIssues: 1, riskProfile: 'Medium', improvementProgress: 'Mixed' }, // Good
    'INST-003': { targetScore: 3.2, complianceIssues: 2, riskProfile: 'Medium', improvementProgress: 'Mixed' }, // Average
    'INST-004': { targetScore: 2.5, complianceIssues: 3, riskProfile: 'High', improvementProgress: 'Behind' }, // Struggling
    'INST-005': { targetScore: 1.8, complianceIssues: 4, riskProfile: 'Critical', improvementProgress: 'Behind' }, // Weak
};

// --- SEEDING FUNCTION ---
const seedDatabase = () => {
    console.log("Seeding Database with Demo Data...");

    // 1. Institutions
    localStorage.setItem(DB_KEYS.INSTITUTIONS, JSON.stringify(SEED_INSTITUTIONS));

    // 2. Indicators (Use Defaults)
    const indicators = DEFAULT_INDICATORS;
    localStorage.setItem(DB_KEYS.INDICATORS, JSON.stringify(indicators));

    // Prepare Collections
    const evaluations: Evaluation[] = [];
    const responses: Response[] = [];
    const complianceRecords: ComplianceRecord[] = [];
    const risks: RiskRegisterItem[] = [];
    const improvements: ImprovementItem[] = [];

    // Loop through each institution to generate related data
    SEED_INSTITUTIONS.forEach(inst => {
        const profile = PROFILES[inst.id];

        // A. Evaluation & Responses
        const evalId = `EVAL-${inst.id}-${CURRENT_YEAR}`;
        evaluations.push({
            id: evalId,
            institution_id: inst.id,
            cycle_year: CURRENT_YEAR,
            cycle_date: new Date().toISOString(),
            status: 'final',
            created_at: new Date().toISOString()
        });

        // Generate Responses based on Target Score +/- variance
        indicators.forEach(ind => {
            let baseScore = profile.targetScore;
            // Add randomness: +/- 1.0 depending on indicator to vary the radar chart
            const variance = (Math.random() * 1.5) - 0.5; 
            let finalScore = Math.round(baseScore + variance);
            if (finalScore > 5) finalScore = 5;
            if (finalScore < 1) finalScore = 1;

            responses.push({
                id: generateId(),
                evaluation_id: evalId,
                indicator_id: ind.id,
                score: finalScore,
                updated_at: new Date().toISOString()
            });
        });

        // B. Compliance Record
        // 0 issues = Fully Compliant, 4 issues = Non Compliant
        complianceRecords.push({
            id: generateId(),
            institution_id: inst.id,
            cycle_year: CURRENT_YEAR,
            institution_status: profile.complianceIssues >= 4 ? 'غير فاعلة' : 'فاعلة',
            board_status: profile.complianceIssues >= 3 ? 'منتهي' : 'قائم',
            has_executive_management: profile.complianceIssues < 2,
            has_auditor_company: profile.complianceIssues < 1,
            has_minutes_prev_year: profile.complianceIssues < 3,
            has_financial_report_prev_year: profile.complianceIssues < 1, // Crucial
            custom_requirements: [],
            last_updated_at: new Date().toISOString()
        });

        // C. Risks (Generate 3-4 risks based on profile)
        const riskTemplates = [
            { t: 'تقلبات الأسواق المالية', c: 'Financial' },
            { t: 'نزاع قانوني على أصل وقفي', c: 'Legal' },
            { t: 'تقادم المباني وصعوبة الصيانة', c: 'Operational' },
            { t: 'ضعف الكادر الإداري', c: 'Strategic' }
        ];

        riskTemplates.forEach((rt, idx) => {
            let prob = 1, impact = 1;

            if (profile.riskProfile === 'Critical') { prob = 5; impact = 5; } // 25
            else if (profile.riskProfile === 'High') { prob = 4; impact = 4; } // 16
            else if (profile.riskProfile === 'Medium') { prob = 3; impact = 3; } // 9
            else { prob = 2; impact = 1; } // 2

            // Vary slightly per risk
            if (idx % 2 === 0) prob = Math.max(1, prob - 1);

            risks.push({
                id: generateId(),
                institution_id: inst.id,
                risk_title: rt.t,
                category: rt.c as any,
                probability: prob,
                impact: impact,
                mitigation_plan: 'جاري العمل على خطة التصحيح',
                status: 'Open'
            });
        });

        // D. Improvements (Linked to Evaluation ID)
        // Advanced = Mostly Done, Behind = Mostly ToDo
        const improvementTemplates = [
            { s: 'تحديث اللوائح الداخلية', o: 'الموارد البشرية' },
            { s: 'أتمتة النظام المالي', o: 'المالية' },
            { s: 'تعيين مدقق خارجي', o: 'مجلس الإدارة' },
            { s: 'صيانة العقار رقم 105', o: 'التشغيل' }
        ];

        improvementTemplates.forEach((it, idx) => {
            let status: 'ToDo' | 'Doing' | 'Done' = 'ToDo';
            let priority: 'High' | 'Medium' | 'Low' = 'Medium';

            if (profile.improvementProgress === 'Advanced') {
                status = idx === 0 ? 'Doing' : 'Done';
                priority = 'Low';
            } else if (profile.improvementProgress === 'Mixed') {
                status = idx % 2 === 0 ? 'Done' : 'Doing';
            } else {
                status = idx === 0 ? 'Doing' : 'ToDo';
                priority = 'High';
            }

            improvements.push({
                id: generateId(),
                evaluation_id: evalId, // Linked to the eval
                indicator_id: `DEMO-${idx}`,
                issue_summary: it.s,
                recommended_action: 'تنفيذ الإجراء المعتمد في الخطة',
                owner: it.o,
                due_date: new Date(new Date().setMonth(new Date().getMonth() + 2)).toISOString().split('T')[0],
                status: status,
                priority: priority,
                notes: 'بند تلقائي من النظام'
            });
        });
    });

    // Save All Collections
    localStorage.setItem(DB_KEYS.EVALUATIONS, JSON.stringify(evaluations));
    localStorage.setItem(DB_KEYS.RESPONSES, JSON.stringify(responses));
    localStorage.setItem(DB_KEYS.COMPLIANCE, JSON.stringify(complianceRecords));
    localStorage.setItem(DB_KEYS.RISKS, JSON.stringify(risks));
    localStorage.setItem(DB_KEYS.IMPROVEMENTS, JSON.stringify(improvements));

    // Save Default Settings
    localStorage.setItem(DB_KEYS.SETTINGS, JSON.stringify({ 
        managerName: 'د. عبدالرحمن النوفلي', 
        darkMode: false,
        orgName: 'وزارة الأوقاف والشؤون الدينية'
    }));

    // Flag needed to prevent re-seeding if we didn't want to check array lengths
    localStorage.setItem('waqf_seeded', 'true');
};


// --- DB ACCESS FUNCTIONS ---

const data = <T>(key: string): T[] => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : [];
};

const save = <T>(key: string, items: T[]) => {
    localStorage.setItem(key, JSON.stringify(items));
};

// --- Institutions ---
export const getInstitutions = (): Institution[] => {
    const stored = data<Institution>(DB_KEYS.INSTITUTIONS);
    if (stored.length === 0) {
        seedDatabase(); // AUTO SEED TRIGGER
        return data<Institution>(DB_KEYS.INSTITUTIONS);
    }
    return stored;
};

export const saveInstitution = (inst: Institution) => {
    const list = getInstitutions();
    const index = list.findIndex(i => i.id === inst.id);
    if (index >= 0) list[index] = inst;
    else list.push(inst);
    save(DB_KEYS.INSTITUTIONS, list);
};

export const deleteInstitution = (id: string) => {
    const list = getInstitutions().filter(i => i.id !== id);
    save(DB_KEYS.INSTITUTIONS, list);
};

// --- Indicators ---
export const getIndicators = (): Indicator[] => {
    let stored = data<Indicator>(DB_KEYS.INDICATORS);
    if (stored.length === 0) {
        save(DB_KEYS.INDICATORS, DEFAULT_INDICATORS);
        stored = DEFAULT_INDICATORS;
    }
    return stored;
};

export const saveIndicators = (indicators: Indicator[]) => {
    save(DB_KEYS.INDICATORS, indicators);
};

