             <div className="relative group">
                 <select 
                    className="w-full p-3 pl-10 border border-gray-300 rounded-xl shadow-sm focus:ring-2 focus:ring-navy-800 outline-none appearance-none bg-white dark:bg-gray-800 dark:text-white dark:border-gray-600 transition-all duration-300 group-hover:shadow-md"
                    value={currentWaqfId || ''}
                    onChange={(e) => setWaqfContext(e.target.value)}
                 >
                     <option value="">جميع المؤسسات (نظرة عامة)</option>
                     {institutions.map(inst => (
                         <option key={inst.id} value={inst.id}>{inst.name}</option>
                     ))}
                 </select>
                 <div className="absolute left-3 top-3.5 pointer-events-none text-gray-500 transition-transform group-hover:scale-110">
                     <Building size={18} />
