          footer={<span className="text-blue-200">النمو السنوي: +4.2%</span>}
        />

        {/* Public vs Private Visual Indicator - Colorized */}
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-white dark:bg-gray-800 p-6 border border-gray-100 dark:border-gray-700 flex items-center justify-between transition-all duration-300 hover:scale-105 hover:shadow-2xl hover:-translate-y-1">
