        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 transition-all duration-300 hover:shadow-xl hover:-translate-y-1">
          <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-6 flex items-center gap-2">
