            <span className="bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 text-xs px-2 py-1 rounded-full font-bold">{count}</span>
        </div>
        <div className="p-3 space-y-3 flex-1">
            {children}
            {count === 0 && <div className="text-center py-10 text-gray-400 text-sm italic">لا توجد مهام</div>}
        </div>
    </div>
);

const KanbanCard = ({ item, onMoveBack, onMoveForward, onDelete, onAttachEvidence, onRemoveEvidence, badge, isDone }: any) => {
    const Icon = badge.icon;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0] && onAttachEvidence) {
            onAttachEvidence(item, e.target.files[0]);
        }
    };

    return (
        <div className={`bg-white dark:bg-gray-700 p-4 rounded-lg shadow-sm border border-gray-100 dark:border-gray-600 transition-all duration-300 hover:shadow-lg hover:-translate-y-1 hover:scale-[1.02] relative group cursor-grab active:cursor-grabbing ${isDone ? 'opacity-90 hover:opacity-100' : ''}`}>
            {/* Delete Button (Hidden until hover) */}
            <button 
                onClick={onDelete}
                className="absolute top-2 left-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity no-print hover:scale-110"
            >
                <Trash2 size={16} />
            </button>

            {/* Badge */}
            <div className="flex justify-between items-start mb-2">
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1 ${badge.color}`}>
                    <Icon size={12} /> {badge.label}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded border ${item.priority === 'High' ? 'text-red-600 border-red-200 bg-red-50' : 'text-gray-500 border-gray-200'}`}>
                    {item.priority === 'High' ? 'أولوية قصوى' : 'عادية'}
                </span>
            </div>

            {/* Content */}
            <h4 className={`font-bold text-sm text-navy-900 dark:text-white mb-2 ${isDone ? 'text-gray-500 line-through decoration-2 decoration-gray-400' : ''}`}>
                {item.issue_summary}
            </h4>
            <p className={`text-xs text-gray-500 dark:text-gray-300 mb-3 leading-relaxed bg-gray-50 dark:bg-gray-800 p-2 rounded ${isDone ? 'line-through opacity-75' : ''}`}>
                {item.recommended_action}
            </p>

            <div className="flex justify-between items-center text-xs text-gray-400 border-t border-gray-100 dark:border-gray-600 pt-2 mb-3">
                <span>{item.owner}</span>
                <span>{item.due_date}</span>
            </div>

            {/* Evidence Attachment (Only for Done items) */}
            {isDone && (
                <div className="mb-3">
                    {item.evidence_doc ? (
                        <div className="flex justify-between items-center bg-green-50 border border-green-100 p-2 rounded-lg text-xs text-green-800">
                            <span className="flex items-center gap-1 truncate font-medium">
                                <FileText size={12}/> {item.evidence_doc.name}
                            </span>
                            <button 
                                onClick={() => onRemoveEvidence(item)} 
                                className="text-gray-400 hover:text-red-500 transition-transform hover:scale-110"
                                title="حذف الدليل"
                            >
                                <X size={12}/>
                            </button>
                        </div>
                    ) : (
                        <label className="cursor-pointer border border-dashed border-blue-300 bg-blue-50 hover:bg-blue-100 text-blue-700 p-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all hover:scale-105 active:scale-95">
                            <Paperclip size={14} /> إرفاق دليل الإنجاز
                            <input type="file" className="hidden" onChange={handleFileChange} />
                        </label>
                    )}
                </div>
            )}

            {/* Controls */}
            <div className="flex justify-between items-center gap-2 no-print">
                {onMoveForward ? (
                    <button onClick={onMoveForward} className="flex-1 bg-navy-50 text-navy-800 hover:bg-navy-100 dark:bg-navy-900 dark:text-blue-200 dark:hover:bg-navy-800 py-1.5 rounded text-xs font-bold flex justify-center items-center gap-1 transition-colors hover:shadow-sm">
                        نقل للمرحلة التالية <ArrowLeft size={14} />
                    </button>
                ) : <div className="flex-1"></div>}

                {onMoveBack && (
                     <button onClick={onMoveBack} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-500 transition-colors hover:scale-110" title="عودة للسابق">
                         <ArrowRight size={16} />
                     </button>
                )}
            </div>
        </div>
    );
};

export default Improvements;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType, InstitutionDocument } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X, FileText, UploadCloud, Calendar, Hash, User, CheckCircle2, Phone, AlertCircle, Building, AlertTriangle } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// توسيع الواجهة محلياً لتشمل تاريخ الانتهاء للعرض فقط
interface ExtendedFormData extends Partial<Institution> {
  expiry_date?: string;
}

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<ExtendedFormData>({});
  const { showToast, role, currentWaqfId, setWaqfContext } = useUi();

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  // Check if current user profile is incomplete
  const isCurrentProfileIncomplete = currentWaqfId && list.find(i => i.id === currentWaqfId)?.profile_completed !== true;

  // دالة حساب تاريخ الانتهاء (4 سنوات) تلقائياً
  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const estDate = e.target.value;
    let expiryDate = '';

    if (estDate) {
      const date = new Date(estDate);
      if (!isNaN(date.getTime())) {
        date.setFullYear(date.getFullYear() + 4);
        expiryDate = date.toISOString().split('T')[0];
      }
    }

    setFormData(prev => ({
      ...prev,
      establishment_date: estDate,
      expiry_date: expiryDate
    }));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // التحقق الصارم من جميع الحقول
    if (
        !formData.name || 
        !formData.type || 
        formData.capital_omr === undefined || 
        !formData.contact_phone || 
        !formData.email || 
        !formData.governorate || 
        !formData.wilayat || 
        !formData.establishment_date || 
        !formData.license_number || 
        !formData.manager_name
    ) {
        showToast('عذراً، جميع الحقول إجبارية بما فيها رقم الهاتف وتاريخ المجلس.', 'error');
        return;
    }

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name,
      type: (formData.type as InstitutionType),
      capital_omr: Number(formData.capital_omr),
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone,
      email: formData.email,
      governorate: formData.governorate,
      wilayat: formData.wilayat,

      establishment_date: formData.establishment_date,
      license_number: formData.license_number,
      manager_name: formData.manager_name,

      // IMPORTANT: Mark profile as completed on save
      profile_completed: true,

      documents: formData.documents || [],
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});

    // تحديث السياق وإعطاء صلاحية الدخول
    if (role === 'user') {
        setWaqfContext(newInst.id);
        // We rely on profile_completed in DB now, localstorage flag is less relevant but kept for legacy
        localStorage.setItem('isProfileCompleted', 'true'); 
    }

    showToast('تم حفظ بيانات المؤسسة وتفعيل صلاحية التقييم', 'success');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setFormData(prev => ({
              ...prev,
              documents: [...(prev.documents || []), newDoc]
          }));
          showToast('تم إرفاق الملف بنجاح', 'info');
      }
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
      if (currentWaqfId === id) setWaqfContext('');
      showToast('تم حذف المؤسسة', 'info');
    }
  };

  const handleSelectContext = (id: string) => {
      setWaqfContext(id);
      showToast('تم اختيار المؤسسة للعمل عليها', 'success');
  };

  // --- Filtering Logic Update ---
  const filtered = list.filter(i => {
      // 1. Text Search Filter (Always applies)
      if (!i.name.includes(search)) return false;

      // 2. Global Context Filter
      // If currentWaqfId is set (User OR Admin who selected specific institution), filter by ID.
      if (currentWaqfId) {
          return i.id === currentWaqfId;
      }

      // 3. If no ID is set (Admin selected "All Institutions"), show everything.
      return true;
  });

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

  const currentInstitutionName = list.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">بيانات المؤسسات</h2>
        {role === 'admin' && (
            <button 
            onClick={() => { setFormData({}); setShowForm(true); }}
            className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 transition-all duration-300 hover:scale-105 active:scale-95 shadow-md"
            >
            <Plus size={18} /> إضافة مؤسسة
            </button>
        )}
      </div>

      {/* WARNING BANNER IF PROFILE INCOMPLETE */}
      {isCurrentProfileIncomplete && role === 'user' && (
           <div className="bg-red-50 border-r-4 border-red-500 p-4 rounded-lg shadow-sm animate-pulse">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="text-red-500 mt-0.5" size={24} />
                   <div>
                       <h3 className="font-bold text-red-800 text-lg">إجراء مطلوب: تحديث البيانات</h3>
                       <p className="text-red-700 text-sm">
                           لم تقم بتأكيد بيانات المؤسسة بعد. يجب عليك الضغط على زر التعديل <Edit2 size={12} className="inline"/>، مراجعة البيانات، ثم الضغط على "حفظ" لتفعيل باقي صفحات النظام.
                       </p>
                   </div>
               </div>
           </div>
      )}

      {/* Context Banner for Admins */}
      {currentWaqfId && (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn transition-transform hover:scale-[1.01] duration-300">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">تصفية العرض حسب:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
              {role === 'admin' && (
                  <button 
                    onClick={() => setWaqfContext('')}
                    className="text-xs bg-white border border-blue-300 px-3 py-1.5 rounded-lg hover:bg-blue-50 text-blue-700 transition-colors"
                  >
                      عرض الكل
                  </button>
              )}
          </div>
      )}

      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none transition-shadow focus:shadow-md"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <table className="w-full text-right">
          <thead className="bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 font-medium">
            <tr>
              <th className="p-4">المؤسسة</th>
              <th className="p-4">النوع</th>
              <th className="p-4">رقم القيد</th>
              <th className="p-4">تأسيس المجلس</th>
              <th className="p-4">المحافظة</th>
              <th className="p-4">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
            {filtered.length > 0 ? (
                filtered.map(inst => (
                <tr key={inst.id} className={`transition-colors duration-200 ${currentWaqfId === inst.id ? 'bg-blue-50 dark:bg-blue-900/20' : 'hover:bg-blue-50/50 dark:hover:bg-gray-700/50'}`}>
                    <td className="p-4 font-medium text-navy-900 dark:text-gray-200">
                        <div className="flex items-center gap-2">
                            {currentWaqfId === inst.id && <CheckCircle2 size={16} className="text-teal-500" />}
                            <div>
                                <div>{inst.name}</div>
                                <div className="text-xs text-gray-400 font-normal">{inst.contact_phone}</div>
                            </div>
                        </div>
                    </td>
                    <td className="p-4">
                    <span className={`px-2 py-1 rounded text-xs ${inst.type === 'وقفية عامة' ? 'bg-teal-100 text-teal-800' : 'bg-gold-100 text-gold-800'}`}>
                        {inst.type}
                    </span>
                    </td>
                    <td className="p-4 font-mono dark:text-gray-300">{inst.license_number}</td>
                    <td className="p-4 text-sm dark:text-gray-300">{inst.establishment_date}</td>
                    <td className="p-4">
                        <div className="text-sm dark:text-gray-300">{inst.governorate}</div>
                        <div className="text-xs text-gray-500">{inst.wilayat}</div>
                    </td>
                    <td className="p-4 flex gap-2 items-center">
                    {role === 'user' && currentWaqfId !== inst.id && (
                        <button onClick={() => handleSelectContext(inst.id)} className="text-xs bg-navy-100 text-navy-800 px-2 py-1 rounded hover:bg-navy-200 transition-colors">
                            اختيار
                        </button>
                    )}
                    <button onClick={() => { 
                        let expDate = '';
                        if (inst.establishment_date) {
                            const d = new Date(inst.establishment_date);
                            d.setFullYear(d.getFullYear() + 4);
                            expDate = d.toISOString().split('T')[0];
                        }
                        setFormData({...inst, expiry_date: expDate}); 
                        setShowForm(true); 
                        }} 
                        className={`text-blue-600 hover:text-blue-800 flex items-center gap-1 transition-transform hover:scale-110 ${!inst.profile_completed && role === 'user' ? 'animate-bounce font-bold' : ''}`}
                    >
                        <Edit2 size={18} /> {(!inst.profile_completed && role === 'user') ? 'تعديل وتفعيل' : ''}
                    </button>
                    {role === 'admin' && (
                        <button onClick={() => handleDelete(inst.id)} className="text-red-600 hover:text-red-800 transition-transform hover:scale-110">
                            <Trash2 size={18} />
                        </button>
                    )}
                    </td>
                </tr>
                ))
            ) : (
                <tr>
                    <td colSpan={6} className="p-8 text-center text-gray-400">
                        لا توجد مؤسسات تطابق معايير البحث أو التصفية الحالية.
                        {currentWaqfId && role === 'admin' && (
                             <div className="mt-2">
                                 <button onClick={() => setWaqfContext('')} className="text-blue-600 underline text-sm">عرض جميع المؤسسات</button>
                             </div>
                        )}
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto animate-scaleIn">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold">{formData.id ? 'تعديل مؤسسة' : 'إضافة مؤسسة جديدة'}</h3>
              <button onClick={() => setShowForm(false)} className="hover:rotate-90 transition-transform"><X size={24} /></button>
            </div>

            <div className="bg-blue-50 p-4 border-b border-blue-100 flex gap-2 items-start text-sm text-blue-800">
                <AlertCircle className="w-5 h-5 shrink-0" />
