                scores[instId].count++;
              }
          }
      });

      const avgScores = Object.values(scores).map(s => ({
          name: s.name,
          score: Number((s.total / s.count).toFixed(2))
      }));

      return avgScores.sort((a, b) => b.score - a.score).slice(0, 5);
