import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import Institutions from './pages/Institutions';
import EvaluationPage from './pages/Evaluation';
import CompliancePage from './pages/Compliance';
import Reports from './pages/Reports';
import Improvements from './pages/Improvements';
import Settings from './pages/Settings';
import Login from './pages/Login';
import ReviewSubmit from './pages/ReviewSubmit';
import ApprovalRequests from './pages/ApprovalRequests';
import { UiProvider, useUi } from './contexts/UiContext';
import { getInstitutionProgress } from './services/db';
import { Lock } from 'lucide-react';

// Protected Route Component handling Auth and Role Check
const ProtectedRoute: React.FC<{ children: React.ReactNode, requiredRole?: 'admin' | 'user' }> = ({ children, requiredRole }) => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) {
        return <Login />;
    }

    // If route requires admin but user is not admin
    if (requiredRole === 'admin' && role !== 'admin') {
        return <Navigate to="/institutions" replace />;
    }

    return <>{children}</>;
};

// Sequential Workflow Guard for Users
const SequentialRoute: React.FC<{ 
    children: React.ReactNode, 
    prereq: 'data' | 'evaluation' | 'compliance' 
}> = ({ children, prereq }) => {
    const { role, currentWaqfId } = useUi();
    const progress = getInstitutionProgress(currentWaqfId);

    // Admins bypass sequence
    if (role === 'admin') return <>{children}</>;

    let isAllowed = false;
    let redirectPath = '/institutions';
    let message = 'يرجى استكمال البيانات السابقة أولاً';

    if (prereq === 'data') {
        // Checking if we can enter Evaluation
        isAllowed = progress.dataComplete;
        redirectPath = '/institutions';
        message = 'يرجى استكمال وحفظ بيانات المؤسسة أولاً للدخول إلى التقييم.';
    } else if (prereq === 'evaluation') {
        // Checking if we can enter Compliance
        isAllowed = progress.evalFinalized;
        redirectPath = '/evaluation';
        message = 'يرجى اعتماد التقييم النهائي أولاً للدخول إلى الامتثال والمخاطر.';
    } else if (prereq === 'compliance') {
        // Checking if we can enter Improvements / Submit
        isAllowed = progress.complianceDone;
        redirectPath = '/compliance';
        message = 'يرجى مراجعة صفحة الامتثال والمخاطر أولاً.';
    }

    if (!isAllowed) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10 mx-auto max-w-2xl animate-fadeIn">
                <div className="bg-gray-100 p-6 rounded-full mb-6">
                    <Lock size={48} className="text-gray-400" />
                </div>
                <h2 className="text-2xl font-bold text-navy-900 mb-2">هذه الصفحة مغلقة حالياً</h2>
                <p className="text-gray-500 mb-8 max-w-md">{message}</p>
                <a href={`#${redirectPath}`} className="bg-navy-800 text-white px-6 py-3 rounded-lg hover:bg-navy-900 font-bold shadow-lg transition-transform active:scale-95">
                    الذهاب للخطوة السابقة
                </a>
            </div>
        );
    }

    return <>{children}</>;
};

// Root Redirect based on Role
const HomeRedirect: React.FC = () => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) return <Login />;

    // Admin goes to Strategic Dashboard
    if (role === 'admin') return <Dashboard />;

    // User goes to their Institution Data
    return <Navigate to="/institutions" replace />;
};

const AppRoutes: React.FC = () => {
    return (
        <Routes>
          <Route path="/" element={<HomeRedirect />} />

          {/* Admin Only Routes */}
          <Route path="/reports" element={<ProtectedRoute requiredRole="admin"><Reports /></ProtectedRoute>} />
          <Route path="/settings" element={<ProtectedRoute requiredRole="admin"><Settings /></ProtectedRoute>} />
          <Route path="/approval-requests" element={<ProtectedRoute requiredRole="admin"><ApprovalRequests /></ProtectedRoute>} />

          {/* Shared Routes (Admin & User) */}
          <Route path="/institutions" element={<ProtectedRoute><Institutions /></ProtectedRoute>} />

          <Route path="/evaluation" element={
              <ProtectedRoute>
                  <SequentialRoute prereq="data">
                      <EvaluationPage />
                  </SequentialRoute>
              </ProtectedRoute>
          } />

          <Route path="/compliance" element={
              <ProtectedRoute>
                  <SequentialRoute prereq="evaluation">
                      <CompliancePage />
                  </SequentialRoute>
              </ProtectedRoute>
          } />

          <Route path="/improvements" element={
              <ProtectedRoute>
                  <SequentialRoute prereq="compliance">
                      <Improvements />
                  </SequentialRoute>
              </ProtectedRoute>
          } />

           <Route path="/review-submit" element={
              <ProtectedRoute>
                  <SequentialRoute prereq="compliance">
                      <ReviewSubmit />
                  </SequentialRoute>
              </ProtectedRoute>
          } />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
    );
};

const App: React.FC = () => {
  return (
    <UiProvider>
        <Router>
          <Layout>
            <AppRoutes />
          </Layout>
        </Router>
    </UiProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId, getInstitutionProgress } from '../services/db';
import { Institution, Indicator, Evaluation, Response, InstitutionDocument } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp, Paperclip, FileText, X, PlusCircle, PieChart as PieIcon, Trash2, MinusCircle, Building, SaveAll, Lock } from 'lucide-react';
import { useUi } from '../contexts/UiContext';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  // Use Global Context instead of local state for selection
  const { showToast, currentWaqfId, role } = useUi();

  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});

  // Locking State
  const [isLocked, setIsLocked] = useState(false);

  // New Indicator Modal State
  const [showAddInd, setShowAddInd] = useState(false);
  const [newIndAxis, setNewIndAxis] = useState('');
  const [customAxis, setCustomAxis] = useState('');
  const [newIndText, setNewIndText] = useState('');

  // Delete Indicator Modal State
  const [showDeleteInd, setShowDeleteInd] = useState(false);
  const [deleteAxis, setDeleteAxis] = useState('');
  const [deleteIndId, setDeleteIndId] = useState('');

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    // Auto load default indicators
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    // Check if global context is set
    if (currentWaqfId && indicators.length > 0) {
      // Check locking status
      const progress = getInstitutionProgress(currentWaqfId);
      setIsLocked(progress.isLocked);

      // Find or Create Evaluation for the current global institution
      let ev = getEvaluationByInstAndYear(currentWaqfId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          workflow_status: 'draft',
          attachments: [],
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [currentWaqfId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation || isLocked) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  const handleAddIndicator = () => {
      const finalAxis = newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' ? customAxis : newIndAxis;

      if(!newIndText || !finalAxis) {
          showToast('يرجى تعبئة جميع الحقول', 'error');
          return;
      }

      const indicator: Indicator = {
          id: `IND-MANUAL-${generateId().substring(0,6)}`,
          axis: finalAxis,
          text: newIndText,
          weight: 1,
          active: true
      };

      const updatedList = [...indicators, indicator];
      setIndicators(updatedList);
      saveIndicators(updatedList);

      setShowAddInd(false);
      setNewIndAxis('');
      setCustomAxis('');
      setNewIndText('');
      showToast('تم إضافة المؤشر الجديد بنجاح', 'success');
  };

  const handleDeleteIndicator = () => {
      if (!deleteIndId) {
          showToast('يرجى اختيار المؤشر للحذف', 'error');
          return;
      }

      if(confirm('هل أنت متأكد من حذف هذا المؤشر؟ سيتم حذفه من القائمة.')) {
          const updatedList = indicators.filter(i => i.id !== deleteIndId);
          setIndicators(updatedList);
          saveIndicators(updatedList);

          setShowDeleteInd(false);
          setDeleteIndId('');
          setDeleteAxis('');
          showToast('تم حذف المؤشر', 'info');
      }
  };

  const openDeleteModal = () => {
      setDeleteAxis('');
      setDeleteIndId('');
      setShowDeleteInd(true);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (isLocked) return;
      if (e.target.files && e.target.files[0] && evaluation) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };

          const updatedEval = { 
              ...evaluation, 
              attachments: [...(evaluation.attachments || []), newDoc] 
          };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم إرفاق الدليل بنجاح', 'success');
      }
  };

  const removeAttachment = (docId: string) => {
      if (!evaluation || isLocked) return;
      const updatedEval = {
          ...evaluation,
          attachments: evaluation.attachments?.filter(d => d.id !== docId) || []
      };
      setEvaluation(updatedEval);
      saveEvaluation(updatedEval);
      showToast('تم حذف المرفق', 'info');
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isLocked) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة من الملف. هل أنت متأكد؟')) {
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');

          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              showToast(`تم استيراد ${newIndicators.length} مؤشر بنجاح`, 'success');
          } else {
              showToast('لم يتم العثور على بيانات صالحة في الملف.', 'error');
          }
      }
    };
    reader.readAsBinaryString(file);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  // Available Axes for Dropdowns
  const availableAxes = Object.keys(grouped);

  // Performance Pie Data
  const responseValues = Object.values(responses) as Response[];
  const performanceData = [
      { name: 'منخفض (1-2)', value: responseValues.filter(r => r.score <= 2).length, fill: '#ef4444' },
      { name: 'متوسط (3)', value: responseValues.filter(r => r.score === 3).length, fill: '#f59e0b' },
      { name: 'مرتفع (4-5)', value: responseValues.filter(r => r.score >= 4).length, fill: '#10b981' },
  ].filter(d => d.value > 0);

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  // Save Handlers
  const handleDraftSave = () => {
      if (isLocked) return;
      showToast('تم حفظ التغييرات كمسودة', 'info');
  };

  const handleFinalSave = () => {
      if (isLocked) return;
      // Check which indicators do NOT have a response
      const missingIndicators = indicators.filter(ind => !responses[ind.id]);

      if (missingIndicators.length > 0) {
          const missingNumbers = missingIndicators.map(ind => indicators.indexOf(ind) + 1);
          let missingStr = missingNumbers.join('، ');
          if (missingNumbers.length > 15) {
              missingStr = missingNumbers.slice(0, 15).join('، ') + ' ...وغيرها';
          }
          showToast(`عذراً، لا يمكن الاعتماد النهائي. يرجى استكمال تقييم المؤشرات أرقام: (${missingStr})`, 'error');
          return;
      }

      if (evaluation) {
          const updatedEval = { ...evaluation, status: 'final' as const };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم اعتماد التقييم النهائي بنجاح', 'success');
      }
  };

  return (
    <div className="space-y-6 relative pb-24">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>
            {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
        </div>

        {role === 'admin' && !isLocked && (
          <div className="flex gap-2">
              <button onClick={() => { setNewIndAxis(availableAxes[0] || 'عام'); setShowAddInd(true); }} className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50 shadow-sm transition-transform hover:scale-105 active:scale-95">
                  <PlusCircle size={18} /> إضافة مؤشر
              </button>
              <button onClick={openDeleteModal} className="bg-white border border-red-200 text-red-600 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-50 shadow-sm transition-transform hover:scale-105 active:scale-95">
                  <MinusCircle size={18} /> حذف مؤشر
              </button>
              <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md transition-transform hover:scale-105 active:scale-95">
                  <Upload size={18} /> تحديث (Excel)
                  <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
              </label>
          </div>
        )}
      </div>

      {/* Currently Viewing Banner - Replaces Selector */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn transition-all hover:shadow-md">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري عرض بيانات تقييم:</div>
                      <div className="text-lg font-bold">{currentInstitutionName} ({CURRENT_YEAR})</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود العمل عليها.</p>
          </div>
      )}

      {/* Add Indicator Modal */}
      {showAddInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4">
                      <h3 className="text-lg font-bold">إضافة مؤشر جديد</h3>
                      <button onClick={() => setShowAddInd(false)} className="hover:rotate-90 transition-transform"><X size={20}/></button>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium mb-1">المحور</label>
                          <select 
                            className="w-full border p-2 rounded" 
                            value={newIndAxis} 
                            onChange={e => setNewIndAxis(e.target.value)}
                          >
                              {availableAxes.map(a => <option key={a} value={a}>{a}</option>)}
                              <option value="NEW_AXIS_CUSTOM_VALUE">محور جديد (اكتب أدناه)</option>
                          </select>
                          {newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' && (
                              <input 
                                type="text" 
                                placeholder="اكتب اسم المحور الجديد" 
                                className="w-full border p-2 rounded mt-2" 
                                value={customAxis}
                                onChange={e => setCustomAxis(e.target.value)} 
                              />
                          )}
                      </div>
                      <div>
                          <label className="block text-sm font-medium mb-1">نص المؤشر</label>
                          <textarea 
                            className="w-full border p-2 rounded h-24" 
                            value={newIndText} 
                            onChange={e => setNewIndText(e.target.value)}
                          ></textarea>
                      </div>
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowAddInd(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded transition-colors">إلغاء</button>
                      <button onClick={handleAddIndicator} className="px-4 py-2 bg-navy-800 text-white rounded hover:bg-navy-900 transition-colors">إضافة</button>
                  </div>
              </div>
          </div>
      )}

      {/* Delete Indicator Modal */}
      {showDeleteInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4">
                      <h3 className="text-lg font-bold text-red-600">حذف مؤشر</h3>
                      <button onClick={() => setShowDeleteInd(false)} className="hover:rotate-90 transition-transform"><X size={20}/></button>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium mb-1">اختر المحور</label>
                          <select 
                            className="w-full border p-2 rounded" 
                            value={deleteAxis} 
                            onChange={e => { setDeleteAxis(e.target.value); setDeleteIndId(''); }}
                          >
                              <option value="">-- اختر --</option>
                              {availableAxes.map(a => <option key={a} value={a}>{a}</option>)}
                          </select>
                      </div>
                      {deleteAxis && (
                          <div>
                              <label className="block text-sm font-medium mb-1">اختر المؤشر للحذف</label>
                              <select 
                                className="w-full border p-2 rounded" 
                                value={deleteIndId} 
                                onChange={e => setDeleteIndId(e.target.value)}
                              >
                                  <option value="">-- اختر --</option>
                                  {grouped[deleteAxis]?.map(ind => (
                                      <option key={ind.id} value={ind.id}>{ind.text.substring(0, 60)}...</option>
                                  ))}
                              </select>
                          </div>
                      )}
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowDeleteInd(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded transition-colors">إلغاء</button>
                      <button 
                        onClick={handleDeleteIndicator} 
                        disabled={!deleteIndId}
                        className={`px-4 py-2 text-white rounded transition-colors ${!deleteIndId ? 'bg-gray-300 cursor-not-allowed' : 'bg-red-600 hover:bg-red-700'}`}
                      >
                          حذف
                      </button>
                  </div>
              </div>
          </div>
      )}

      {currentWaqfId && indicators.length > 0 && (
        <div className="space-y-4 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300 hover:shadow-md">
              <button 
                className={`w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors ${openAxis === axis ? 'bg-navy-50' : ''}`}
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold text-sm transform transition-transform duration-300 group-hover:scale-110">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg group-hover:translate-x-1 transition-transform">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                <div className={`transition-transform duration-300 ${openAxis === axis ? 'rotate-180' : ''}`}>
                    {openAxis === axis ? <ChevronUp className="text-navy-800" /> : <ChevronDown className="text-gray-400" />}
                </div>
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-6 bg-white border-t border-gray-100">
                  {grouped[axis].map((ind) => {
                    const globalIndex = indicators.findIndex(x => x.id === ind.id) + 1;
                    return (
                        <div key={ind.id} className="border-b border-gray-50 last:border-0 pb-4 last:pb-0 transition-colors hover:bg-gray-50/50 p-2 rounded-lg">
                        <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                            <div className="flex gap-2 flex-1">
                                <span className="font-bold text-teal-600 min-w-[24px] select-none">{globalIndex}.</span>
                                <p className="text-gray-700 font-medium leading-relaxed">{ind.text}</p>
                            </div>

                            <div className="flex gap-2 shrink-0">
                                {[1, 2, 3, 4, 5].map(score => (
                                <button
                                    key={score}
                                    onClick={() => handleScore(ind.id, score)}
                                    disabled={isLocked}
                                    className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold border-2 transition-all duration-200 shadow-sm transform ${!isLocked && 'hover:scale-110 active:scale-95'} ${
                                    responses[ind.id]?.score === score
                                        ? `${RATING_COLORS[score]} scale-110 shadow-md ring-2 ring-offset-2 ring-gray-300`
                                        : 'bg-white text-gray-400 border-gray-200 ' + (isLocked ? 'cursor-not-allowed opacity-50' : 'hover:border-gray-400 hover:text-gray-600')
                                    }`}
                                >
                                    {score}
                                </button>
                                ))}
                            </div>
                        </div>
                        </div>
                    );
                  })}
                </div>
              )}
            </div>
          ))}

          {/* Action Bar & Stats Footer */}
          <div className="fixed bottom-0 left-0 right-0 lg:right-64 bg-white border-t shadow-[0_-4px_10px_rgba(0,0,0,0.1)] p-4 flex flex-col md:flex-row justify-between items-center z-40 gap-4">
             <div className="flex items-center gap-6">
                <div>
                    <span className="text-sm text-gray-500 block">تقدم التقييم</span>
                    <span className="font-bold text-navy-900">{Object.keys(responses).length} / {indicators.length}</span>
                </div>

                {/* Mini Pie Chart for Score Breakdown */}
                {performanceData.length > 0 && (
                    <div className="flex items-center gap-3 border-r pr-6 mr-2">
                         <div className="w-10 h-10 relative hover:scale-110 transition-transform">
                             <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={performanceData} dataKey="value" innerRadius={10} outerRadius={20} stroke="none">
                                        {performanceData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.fill} />
                                        ))}
                                    </Pie>
                                </PieChart>
                             </ResponsiveContainer>
                         </div>
                         <div className="text-xs space-y-0.5">
                             {performanceData.map(d => (
                                 <div key={d.name} className="flex items-center gap-1">
                                     <span className="w-2 h-2 rounded-full" style={{backgroundColor: d.fill}}></span>
                                     <span className="text-gray-600">{d.value}</span>
                                 </div>
                             ))}
                         </div>
                    </div>
                )}
             </div>

             <div className="flex items-center gap-4">
                 <div className="relative">
                     <label className={`cursor-pointer bg-gray-100 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 text-sm transition-all ${isLocked ? 'opacity-50 cursor-not-allowed' : 'hover:bg-gray-200 hover:scale-105 active:scale-95'}`}>
                         <Paperclip size={16} /> إرفاق أدلة
                         <input type="file" className="hidden" onChange={handleFileUpload} disabled={isLocked} />
                     </label>
                 </div>

                 {/* NEW: Draft Save Button */}
                 {!isLocked && (
                    <button onClick={handleDraftSave} className="bg-gray-200 text-gray-800 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-300 shadow-sm font-bold text-sm transition-all hover:scale-105 active:scale-95">
                        <SaveAll size={18} /> حفظ التغييرات
                    </button>
                 )}

                 {/* FINAL SAVE: Checks for completion */}
                 {!isLocked && (
                    <button onClick={handleFinalSave} className="bg-teal-600 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-lg font-bold transition-all hover:scale-105 active:scale-95">
                        <Save size={18} /> حفظ واعتماد
                    </button>
                 )}
             </div>
          </div>

          {/* Attachments List */}
          {evaluation?.attachments && evaluation.attachments.length > 0 && (
             <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200 mb-20 transition-all hover:shadow-md">
                 <h4 className="font-bold text-gray-700 mb-3 text-sm flex items-center gap-2"><Paperclip size={16}/> المرفقات والأدلة ({evaluation.attachments.length})</h4>
                 <div className="flex flex-wrap gap-2">
                     {evaluation.attachments.map(doc => (
                         <div key={doc.id} className="bg-gray-50 border border-gray-200 px-3 py-2 rounded-lg flex items-center gap-2 text-sm hover:bg-gray-100 transition-colors">
                             <FileText size={14} className="text-blue-500" />
                             <span className="truncate max-w-[150px]">{doc.name}</span>
                             <button onClick={() => removeAttachment(doc.id)} disabled={isLocked} className={`text-gray-400 hover:text-red-500 transition-colors hover:scale-110 ${isLocked ? 'hidden' : ''}`}><X size={14}/></button>
                         </div>
                     ))}
                 </div>
             </div>
          )}
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, getComplianceByInstAndYear, getRisks, saveRisk, deleteRisk, getInstitutionProgress } from '../services/db';
import { Institution, ComplianceRecord, RiskRegisterItem, CustomRequirement } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Save, AlertTriangle, CheckCircle, Info, ShieldAlert, Plus, Trash2, Scale, X, Building, Settings, Lock, Edit2, CheckSquare } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

const CORE_REQUIREMENTS = [
    { key: 'has_executive_management', label: 'هل توجد إدارة تنفيذية أو مدير؟' },
    { key: 'has_auditor_company', label: 'هل تم تعيين شركة تدقيق؟' },
    { key: 'has_minutes_prev_year', label: 'هل توجد محاضر اجتماعات للعام الماضي؟' },
    { key: 'has_financial_report_prev_year', label: 'هل يوجد تقرير مالي معتمد للعام الماضي؟' },
];

const CompliancePage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'compliance' | 'risks'>('compliance');
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { showToast, currentWaqfId, role } = useUi();

  // Compliance State
  const [record, setRecord] = useState<Partial<ComplianceRecord>>({});
  const [newReqText, setNewReqText] = useState('');

  // Locking State
  const [isLocked, setIsLocked] = useState(false);

  // Admin Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Risk Register State
  const [instRisks, setInstRisks] = useState<RiskRegisterItem[]>([]);
  const [newRisk, setNewRisk] = useState<Partial<RiskRegisterItem>>({});
  const [showRiskForm, setShowRiskForm] = useState(false);

  // Real-time calculated risk based on compliance form
  const complianceRisk = calculateRiskScore(record);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (currentWaqfId) {
        // Check Lock Status
        const progress = getInstitutionProgress(currentWaqfId);
        setIsLocked(progress.isLocked);

        // Load Compliance
        const existing = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
        if (existing) {
            setRecord(existing);
        } else {
            setRecord({
                institution_id: currentWaqfId,
                cycle_year: CURRENT_YEAR,
                institution_status: 'فاعلة',
                board_status: 'قائم',
                has_executive_management: false,
                has_auditor_company: false,
                has_minutes_prev_year: false,
                has_financial_report_prev_year: false,
                custom_requirements: [],
                hidden_core_requirements: [],
                renamed_core_requirements: {},
                notes: ''
            });
        }

        // Load Risks
        setInstRisks(getRisks(currentWaqfId));
    } else {
        setRecord({});
        setInstRisks([]);
    }
    // Reset edit mode when changing institution
    setIsEditMode(false);
  }, [currentWaqfId]);

  const handleSaveCompliance = () => {
      if (!currentWaqfId || isLocked) return;

      // Ensure ID exists or generate new one
      const recordId = record.id || generateId();

      const toSave: ComplianceRecord = {
          ...record as ComplianceRecord,
          id: recordId,
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          last_updated_at: new Date().toISOString()
      };

      saveComplianceRecord(toSave);
      setRecord(toSave); 
      setIsEditMode(false); // Exit edit mode on save
      showToast('تم حفظ سجل الامتثال بنجاح', 'success');
  };

  // --- CUSTOM REQUIREMENTS HANDLERS ---
  const handleAddRequirement = () => {
      if (!newReqText || isLocked) return;
      const newReq: CustomRequirement = {
          id: generateId(),
          text: newReqText,
          met: false
      };
      setRecord(prev => ({
          ...prev,
          custom_requirements: [...(prev.custom_requirements || []), newReq]
      }));
      setNewReqText('');
      showToast('تم إضافة المعيار الجديد', 'success');
  };

  const handleRemoveRequirement = (id: string) => {
      if(isLocked) return;
      if(confirm('هل أنت متأكد من حذف هذا المعيار؟')) {
        setRecord(prev => ({
            ...prev,
            custom_requirements: prev.custom_requirements?.filter(r => r.id !== id)
        }));
      }
  };

  const toggleCustomRequirement = (id: string) => {
      if (isEditMode || isLocked) return; // Disable toggling in edit mode
      setRecord(prev => ({
          ...prev,
          custom_requirements: prev.custom_requirements?.map(r => r.id === id ? { ...r, met: !r.met } : r)
      }));
  };

  // --- CORE REQUIREMENTS EDIT HANDLERS ---
  const handleRemoveCoreReq = (key: string) => {
      if(isLocked) return;
      if(confirm('حذف هذا المعيار الأساسي؟ سيتم إخفاؤه من القائمة ولن يدخل في حساب المخاطر.')) {
          const currentHidden = record.hidden_core_requirements || [];
          setRecord(prev => ({
              ...prev,
              hidden_core_requirements: [...currentHidden, key]
          }));
      }
  };

  const handleRenameCoreReq = (key: string, newText: string) => {
      if(isLocked) return;
      const currentRenamed = record.renamed_core_requirements || {};
      setRecord(prev => ({
          ...prev,
          renamed_core_requirements: { ...currentRenamed, [key]: newText }
      }));
  };


  // --- RISK HANDLERS ---
  const handleSaveRisk = () => {
      if (!currentWaqfId || !newRisk.risk_title || isLocked) {
          if(!newRisk.risk_title) showToast('يرجى إدخال عنوان الخطر', 'error');
          return;
      }

      // Check if we are updating (id exists) or creating new
      const riskId = newRisk.id || generateId();
      const isUpdate = !!newRisk.id;

      const riskToSave: RiskRegisterItem = {
          id: riskId,
          institution_id: currentWaqfId,
          risk_title: newRisk.risk_title!,
          category: newRisk.category || 'Operational',
          probability: Number(newRisk.probability) || 1,
          impact: Number(newRisk.impact) || 1,
          mitigation_plan: newRisk.mitigation_plan || '',
          status: newRisk.status || 'Open'
      };

      saveRisk(riskToSave);
      setInstRisks(getRisks(currentWaqfId));
      setShowRiskForm(false);
      setNewRisk({});

      showToast(isUpdate ? 'تم حفظ التعديلات على الخطر' : 'تم إضافة الخطر بنجاح', 'success');
  };

  const handleEditRisk = (risk: RiskRegisterItem) => {
      if(isLocked) return;
      setNewRisk(risk);
      setShowRiskForm(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteRisk = (id: string) => {
      if(isLocked) return;
      if(confirm('هل أنت متأكد من حذف هذا الخطر؟')) {
          deleteRisk(id);
          setInstRisks(getRisks(currentWaqfId));
          showToast('تم حذف الخطر', 'info');
      }
  };

  const updateComplianceField = (field: keyof ComplianceRecord, value: any) => {
      if (isEditMode || isLocked) return; // Prevent changing values while editing structure
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6 pb-12">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-navy-900 dark:text-white">الامتثال والمخاطر ({CURRENT_YEAR})</h2>
            {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
        </div>
      </div>

      {/* Currently Viewing Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري إدارة امتثال:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود العمل عليها.</p>
          </div>
      )}

      {currentWaqfId && (
          <div className="animate-fadeIn">
              {/* Tabs */}
              <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6">
                  <button 
                    onClick={() => setActiveTab('compliance')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'compliance' ? 'border-b-2 border-navy-800 text-navy-900 dark:text-white dark:border-white' : 'text-gray-500 hover:text-navy-700 dark:text-gray-400'}`}
                  >
                      <span className="flex items-center gap-2"><Scale size={16} /> الامتثال النظامي</span>
                  </button>
                  <button 
                    onClick={() => setActiveTab('risks')}
                    className={`pb-3 px-6 font-bold text-sm transition-colors ${activeTab === 'risks' ? 'border-b-2 border-navy-800 text-navy-900 dark:text-white dark:border-white' : 'text-gray-500 hover:text-navy-700 dark:text-gray-400'}`}
                  >
                      <span className="flex items-center gap-2"><ShieldAlert size={16} /> سجل المخاطر</span>
                  </button>
              </div>

              {/* COMPLIANCE TAB */}
              {activeTab === 'compliance' && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2 space-y-6">

                        {/* Status Card */}
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                            <h3 className="font-bold text-navy-900 dark:text-white mb-4 flex items-center gap-2">
                                <Info size={20} className="text-teal-600" /> الحالة الأساسية
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة المؤسسة</label>
                                    <select 
                                        disabled={isEditMode || isLocked}
                                        className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                        value={record.institution_status || 'فاعلة'} 
                                        onChange={(e) => updateComplianceField('institution_status', e.target.value)}
                                    >
                                        <option value="فاعلة">فاعلة</option>
                                        <option value="غير فاعلة">غير فاعلة</option>
                                        <option value="قيد التصفية">قيد التصفية</option>
                                        <option value="متوقفة">متوقفة</option>
                                        <option value="أخرى">أخرى</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة مجلس الإدارة</label>
                                    <select 
                                        disabled={isEditMode || isLocked}
                                        className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                        value={record.board_status || 'قائم'} 
                                        onChange={(e) => updateComplianceField('board_status', e.target.value)}
                                    >
                                        <option value="قائم">قائم</option>
                                        <option value="منتهي">منتهي الصلاحية</option>
                                        <option value="غير موجود">غير موجود</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Requirements List Container */}
                        <div className={`bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border transition-all ${isEditMode ? 'border-amber-400 ring-2 ring-amber-100' : 'border-gray-100 dark:border-gray-700'}`}>
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">
                                    <CheckCircle size={20} className="text-teal-600" /> المتطلبات النظامية
                                </h3>

                                {role === 'admin' && !isLocked && (
                                    <button 
                                        onClick={() => setIsEditMode(!isEditMode)}
                                        className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${isEditMode ? 'bg-amber-100 text-amber-800 hover:bg-amber-200' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                    >
                                        {isEditMode ? (
                                            <> <CheckSquare size={16}/> إنهاء التعديل </>
                                        ) : (
                                            <> <Settings size={16}/> تعديل المعايير </>
                                        )}
                                    </button>
                                )}
                            </div>

                            {/* 1. Core Requirements (With Edit/Delete Support) */}
                            <div className="space-y-4 mb-6">
                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">المعايير الأساسية</h4>
                                {CORE_REQUIREMENTS.map((req) => {
                                    // Check if this core requirement is hidden
                                    if (record.hidden_core_requirements?.includes(req.key)) return null;

                                    // Get renamed label if exists
                                    const displayLabel = record.renamed_core_requirements?.[req.key] || req.label;

                                    return (
                                        <div key={req.key} className="flex items-center gap-3 relative animate-fadeIn">
                                            {isEditMode ? (
                                                <div className="flex-1 flex gap-2 items-center bg-gray-50 border border-gray-200 p-2 rounded-lg">
                                                    <input 
                                                        type="text" 
                                                        className="flex-1 bg-white border border-gray-300 rounded px-2 py-1 text-sm focus:ring-2 focus:ring-amber-500 outline-none"
                                                        value={displayLabel}
                                                        onChange={(e) => handleRenameCoreReq(req.key, e.target.value)}
                                                    />
                                                    <button 
                                                        onClick={() => handleRemoveCoreReq(req.key)} 
                                                        className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                                                        title="حذف هذا المعيار الأساسي"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            ) : (
                                                <ToggleItem 
                                                    label={displayLabel} 
                                                    checked={!!(record as any)[req.key]} 
                                                    onChange={() => updateComplianceField(req.key as keyof ComplianceRecord, !(record as any)[req.key])} 
                                                    className={`flex-1`}
                                                    disabled={isLocked}
                                                />
                                            )}
                                        </div>
                                    );
                                })}
                                {record.hidden_core_requirements?.length === CORE_REQUIREMENTS.length && (
                                     <p className="text-xs text-gray-400 text-center py-4 border border-dashed border-gray-200 rounded-lg">تم حذف جميع المعايير الأساسية</p>
                                )}
                            </div>

                            {/* 2. Custom Requirements (Dynamic) */}
                            <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider">المعايير الإضافية</h4>
                                </div>

                                <div className="space-y-2">
                                    {record.custom_requirements?.map(req => (
                                        <div key={req.id} className="flex items-center gap-2 animate-fadeIn">
                                            {isEditMode ? (
                                                // Edit Mode for Custom Requirements
                                                <div className="flex-1 flex gap-2 items-center bg-amber-50 border border-amber-200 p-2 rounded-lg">
                                                    <span className="flex-1 text-sm text-gray-700 px-2">{req.text}</span>
                                                    <button 
                                                        onClick={() => handleRemoveRequirement(req.id)} 
                                                        className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                                                        title="حذف المعيار"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            ) : (
                                                // View Mode
                                                <ToggleItem 
                                                    label={req.text} 
                                                    checked={req.met} 
                                                    onChange={() => toggleCustomRequirement(req.id)} 
                                                    className="flex-1"
                                                    disabled={isLocked}
                                                />
                                            )}
                                        </div>
                                    ))}
                                    {(!record.custom_requirements || record.custom_requirements.length === 0) && (
                                        <p className="text-xs text-gray-400 text-center py-4 border border-dashed border-gray-200 rounded-lg">لا توجد معايير إضافية</p>
                                    )}
                                </div>
                            </div>

                            {/* Add New Section (Only in Edit Mode) */}
                            {isEditMode && (
                                <div className="mt-6 pt-6 border-t border-amber-200 animate-slideIn">
                                    <h4 className="text-sm font-bold text-amber-800 mb-3 flex items-center gap-2"><Plus size={16}/> إضافة معيار جديد</h4>
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            className="flex-1 border border-amber-300 p-2.5 rounded-lg text-sm focus:ring-2 focus:ring-amber-500 outline-none" 
                                            placeholder="أدخل نص المعيار الجديد هنا..." 
                                            value={newReqText} 
                                            onChange={e => setNewReqText(e.target.value)} 
                                            onKeyDown={(e) => e.key === 'Enter' && handleAddRequirement()}
                                        />
                                        <button onClick={handleAddRequirement} className="bg-amber-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-amber-700 shadow-sm">
                                            إضافة
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>

                        {!isEditMode && !isLocked && (
                            <button onClick={handleSaveCompliance} className="w-full bg-navy-800 text-white p-4 rounded-xl font-bold shadow-lg hover:bg-navy-900 flex justify-center items-center gap-2 transition-transform active:scale-95">
                                <Save size={20} /> حفظ سجل الامتثال
                            </button>
                        )}

                        {isEditMode && (
                             <div className="bg-amber-50 border border-amber-200 text-amber-800 p-4 rounded-xl flex items-center justify-between">
                                 <span className="text-sm font-medium">أنت في وضع التعديل. قم بإضافة أو حذف أو تعديل المؤشرات ثم اضغط إنهاء.</span>
                                 <button onClick={() => setIsEditMode(false)} className="bg-white border border-amber-300 px-4 py-2 rounded-lg text-sm font-bold hover:bg-amber-100">
                                     إنهاء التعديل
                                 </button>
                             </div>
                        )}
                    </div>

                    {/* Sidebar Risk */}
                    <div className="lg:col-span-1">
                        <div className={`sticky top-6 p-6 rounded-xl border ${complianceRisk.score >= 6 ? 'bg-red-50 border-red-200 dark:bg-red-900/20 dark:border-red-900' : 'bg-green-50 border-green-200 dark:bg-green-900/20 dark:border-green-900'}`}>
                            <h3 className="text-lg font-bold text-navy-900 dark:text-white mb-2">تحليل المخاطر (الامتثال)</h3>
                            <div className="flex items-center gap-3 mb-6">
                                <div className={`text-4xl font-bold ${complianceRisk.score >= 6 ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>{complianceRisk.score}</div>
                                <div><div className="text-xs text-gray-500 dark:text-gray-400 uppercase">نقاط الخطر</div><div className={`font-bold ${complianceRisk.score >= 6 ? 'text-red-700 dark:text-red-300' : 'text-green-700 dark:text-green-300'}`}>{complianceRisk.label}</div></div>
                            </div>
                            <div className="space-y-3">
                                <RiskIndicator 
                                    label="مجلس الإدارة" 
                                    active={record.board_status !== 'قائم'} 
                                    points={3} 
                                />

                                {/* Core Requirements in Risk Panel - Hide if Deleted */}
                                {!record.hidden_core_requirements?.includes('has_executive_management') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_executive_management'] || "الإدارة التنفيذية"} 
                                        active={!record.has_executive_management} 
                                        points={2} 
                                    />
                                )}
                                {!record.hidden_core_requirements?.includes('has_auditor_company') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_auditor_company'] || "شركة التدقيق"} 
                                        active={!record.has_auditor_company} 
                                        points={2} 
                                    />
                                )}
                                {!record.hidden_core_requirements?.includes('has_financial_report_prev_year') && (
                                    <RiskIndicator 
                                        label={record.renamed_core_requirements?.['has_financial_report_prev_year'] || "التقرير المالي"} 
                                        active={!record.has_financial_report_prev_year} 
                                        points={2} 
                                    />
                                )}
                            </div>
                        </div>
                    </div>
                </div>
              )}

              {/* RISK REGISTER TAB */}
              {activeTab === 'risks' && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                          <h3 className="text-lg font-bold text-navy-900 dark:text-white">قائمة المخاطر المرصودة</h3>
                          {!isLocked && (
                             <button onClick={() => { setNewRisk({}); setShowRiskForm(true); }} className="bg-red-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-700 text-sm shadow-md"><Plus size={16} /> إضافة خطر</button>
                          )}
                      </div>

                      {showRiskForm && (
                          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-xl border border-gray-200 dark:border-gray-700 animate-fadeIn mb-6">
                              <h4 className="font-bold mb-4 dark:text-white">{newRisk.id ? 'تعديل بيانات الخطر' : 'تسجيل خطر جديد'}</h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">وصف الخطر</label>
                                      <input type="text" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.risk_title || ''} onChange={e => setNewRisk({...newRisk, risk_title: e.target.value})} placeholder="مثال: نزاع قانوني على أصل وقفي" />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">التصنيف</label>
                                      <select className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.category} onChange={e => setNewRisk({...newRisk, category: e.target.value as any})}>
                                          <option value="Operational">تشغيلي</option>
                                          <option value="Financial">مالي</option>
                                          <option value="Legal">قانوني</option>
                                          <option value="Strategic">استراتيجي</option>
                                      </select>
                                  </div>
                                  <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">الاحتمالية (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.probability || ''} onChange={e => setNewRisk({...newRisk, probability: Number(e.target.value)})} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">الأثر (1-5)</label>
                                        <input type="number" min="1" max="5" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.impact || ''} onChange={e => setNewRisk({...newRisk, impact: Number(e.target.value)})} />
                                    </div>
                                  </div>
                                  <div className="col-span-2">
                                      <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">خطة المعالجة</label>
                                      <input type="text" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600 dark:text-white" value={newRisk.mitigation_plan || ''} onChange={e => setNewRisk({...newRisk, mitigation_plan: e.target.value})} />
                                  </div>
                              </div>
                              <div className="flex gap-2 justify-end">
                                  <button onClick={() => setShowRiskForm(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded dark:text-gray-300 dark:hover:bg-gray-700">إلغاء</button>
                                  <button onClick={handleSaveRisk} className="bg-navy-800 text-white px-4 py-2 rounded hover:bg-navy-900">{newRisk.id ? 'حفظ التعديلات' : 'إضافة'}</button>
                              </div>
                          </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {instRisks.map(risk => {
                              const score = risk.probability * risk.impact;
                              let color = 'bg-green-100 border-green-200 dark:bg-green-900/30 dark:border-green-800';
                              if (score >= 15) color = 'bg-red-50 border-red-200 dark:bg-red-900/30 dark:border-red-800';
                              else if (score >= 8) color = 'bg-orange-50 border-orange-200 dark:bg-orange-900/30 dark:border-orange-800';

                              return (
                                  <div key={risk.id} className={`p-4 rounded-xl border ${color} relative group hover:shadow-md transition-all`}>
                                      <div className="flex justify-between items-start mb-2">
                                          <span className="text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400">{risk.category}</span>
                                          <span className={`text-xs font-bold px-2 py-1 rounded-full ${score >= 15 ? 'bg-red-500 text-white' : (score >= 8 ? 'bg-orange-500 text-white' : 'bg-green-500 text-white')}`}>
                                              {score} (شدة الخطر)
                                          </span>
                                      </div>
                                      <h4 className="font-bold text-navy-900 dark:text-white mb-2">{risk.risk_title}</h4>
                                      <p className="text-sm text-gray-600 dark:text-gray-300 mb-3">{risk.mitigation_plan || 'لا توجد خطة معالجة'}</p>

                                      <div className="flex gap-2 text-xs text-gray-500 dark:text-gray-400 border-t pt-2 border-gray-200/50 dark:border-gray-700 mb-2">
                                          <span>P: {risk.probability}</span>
                                          <span>I: {risk.impact}</span>
                                      </div>

                                      {/* Action Buttons */}
                                      {!isLocked && (
                                        <div className="flex gap-2 mt-2 pt-2 border-t border-gray-200/50 dark:border-gray-700">
                                                <button 
                                                    onClick={() => handleEditRisk(risk)} 
                                                    className="flex-1 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded py-1.5 text-xs font-bold text-blue-600 hover:bg-blue-50 dark:hover:bg-gray-600 flex items-center justify-center gap-1 transition-colors"
                                                >
                                                    <Edit2 size={12}/> تعديل
                                                </button>
                                                <button 
                                                    onClick={() => handleDeleteRisk(risk.id)} 
                                                    className="flex-1 bg-white dark:bg-gray-700 border border-red-200 dark:border-red-900 rounded py-1.5 text-xs font-bold text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center justify-center gap-1 transition-colors"
                                                >
                                                    <Trash2 size={12}/> حذف
                                                </button>
                                        </div>
                                      )}
                                  </div>
                              )
                          })}
                          {instRisks.length === 0 && !showRiskForm && (
                              <div className="col-span-full py-10 text-center text-gray-400 border border-dashed border-gray-300 dark:border-gray-600 rounded-xl">
                                  لا توجد مخاطر مسجلة
                              </div>
                          )}
                      </div>
                  </div>
              )}
          </div>
      )}
    </div>
  );
};

// UI Components
const ToggleItem = ({ label, checked, onChange, className, disabled }: any) => (
    <div 
        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${disabled ? 'cursor-not-allowed bg-gray-50' : 'cursor-pointer'} ${checked ? 'bg-teal-50 border-teal-200 dark:bg-teal-900/30 dark:border-teal-800' : 'bg-white border-gray-200 hover:bg-gray-50 dark:bg-gray-800 dark:border-gray-700 dark:hover:bg-gray-700'} ${className}`}
        onClick={!disabled ? onChange : undefined}
    >
        <span className={`font-medium ${checked ? 'text-teal-900 dark:text-teal-300' : 'text-gray-600 dark:text-gray-300'}`}>{label}</span>
        <div className={`w-12 h-6 rounded-full relative transition-colors ${checked ? 'bg-teal-600' : 'bg-gray-300 dark:bg-gray-600'}`}>
            <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all shadow-sm ${checked ? 'left-1' : 'right-1'}`}></div>
        </div>
    </div>
