// --- Financial Governance Logic (The Brain) ---
export const analyzeFinancialHealth = (record: FinancialRecord): { isValid: boolean, status: 'Submitted' | 'Flagged', flags: string[], errors: string[] } => {
    const flags: string[] = [];
    const errors: string[] = [];

    // 1. Validation Rule: Accounting Equation (Assets - Liabilities = Net Assets)
    // Allow for small rounding difference (e.g., < 1 OMR)
    const calculatedNet = record.total_assets - record.total_liabilities;
    const diff = Math.abs(calculatedNet - record.net_waqf_assets);

    if (diff > 1) {
        errors.push(`خطأ محاسبي: المعادلة غير متزنة. (الأصول - الالتزامات = ${calculatedNet.toLocaleString()}) بينما المدخل (${record.net_waqf_assets.toLocaleString()}). الفارق: ${diff.toFixed(3)}`);
    }

    // 2. Governance Flag 1: Admin Ratio > 20%
    if (record.total_expenses > 0) {
        const ratio = (record.admin_general_expenses / record.total_expenses) * 100;
        if (ratio > 20) {
            flags.push(`تنبيه: المصاريف الإدارية والعمومية مرتفعة (${ratio.toFixed(1)}% من إجمالي المصاريف). الحد المسموح 20%.`);
        }
    }

    // 3. Governance Flag 2: Sustainability (Deficit)
    if (record.total_expenses > record.total_revenues) {
        flags.push('تنبيه: عجز تشغيلي (المصاريف تتجاوز الإيرادات)، مما يهدد استدامة الوقف.');
    }

    // 4. Governance Flag 3: Capital Erosion
    if (record.net_waqf_assets < 0) {
        flags.push('خطر حرج: تآكل رأس المال الوقفي (صافي الأصول بالسالب).');
    }

    const isValid = errors.length === 0;
    const status = flags.length > 0 ? 'Flagged' : 'Submitted';

    return { isValid, status, flags, errors };
};

