                          <input type="number" className="w-full p-3 pl-10 border border-gray-200 rounded-lg bg-gray-50 focus:bg-white focus:ring-2 focus:ring-teal-500 outline-none transition-colors" 
                              value={record.total_revenues || ''} onChange={(e) => handleInputChange('total_revenues', Number(e.target.value))} />
                          <span className="absolute left-3 top-3 text-gray-400 text-xs font-bold">ر.ع</span>
                      </div>
                  </div>
                  <div>
                      <label className="block text-sm font-bold text-gray-600 mb-1">إجمالي المصروفات (Expenses)</label>
                      <div className="relative">
                          <input type="number" className="w-full p-3 pl-10 border border-gray-200 rounded-lg bg-gray-50 focus:bg-white focus:ring-2 focus:ring-teal-500 outline-none transition-colors" 
