  const riskMatrix = useMemo(() => {
      let high = 0, med = 0, low = 0;
      filteredRisks.forEach(r => {
          const score = r.probability * r.impact;
          if (score >= 15) high++;
          else if (score >= 8) med++;
          else low++;
      });
      return { high, med, low, total: filteredRisks.length };
