          // Only include recent years to be relevant (Current or Previous)
          return f.fiscal_year === CURRENT_YEAR || f.fiscal_year === CURRENT_YEAR - 1;
      });

      // Initialize Aggregates
      let totalAssets = 0;
      let totalSurplus = 0;
      let totalCash = 0;
      let totalRevenues = 0;
      let totalExpenses = 0;
      let totalHealthScore = 0;
      let count = 0;

      relevantRecords.forEach(rec => {
           // Aggregate Values (Handle undefined/null with || 0)
           totalAssets += (rec.total_assets || 0);
           totalSurplus += (rec.surplus_deficit || 0);
           totalCash += (rec.cash_end_period || 0);
           totalRevenues += (rec.total_revenues || 0);
           totalExpenses += (rec.total_expenses || 0);

           // Calculate a simple health score for this record (0-100)
           let score = 100;
           // Deduct for Deficit
           if ((rec.surplus_deficit || 0) < 0) score -= 30;
           // Deduct for High Admin Expenses (> 20%)
           const expenses = rec.total_expenses || 0;
           const admin = rec.admin_general_expenses || 0;
           if (expenses > 0 && (admin / expenses) > 0.20) score -= 20;
           // Deduct for negative net assets
           if ((rec.net_waqf_assets || 0) < 0) score -= 40;
           // Cap at 0
           totalHealthScore += Math.max(0, score);
           count++;
      });

      const avgHealth = count > 0 ? Math.round(totalHealthScore / count) : 0;

      return {
          assets: totalAssets,
          surplus: totalSurplus,
          cash: totalCash,
          revenues: totalRevenues,
          expenses: totalExpenses,
          health: avgHealth,
          hasData: count > 0
