                              <div>
                                  <span className="text-sm font-bold block">{pdfFile.name}</span>
                                  <span className="text-xs opacity-70">{pdfFile.size} - تم الرفع</span>
                              </div>
                          </div>
                          <button onClick={() => setPdfFile(null)} className="text-red-500 hover:bg-red-100 p-2 rounded-full transition-colors"><XCircle size={20}/></button>
                      </div>
                  ) : (
                      <label className="flex flex-col items-center justify-center gap-3 w-full h-32 border-2 border-dashed border-gray-300 rounded-xl bg-gray-50 text-gray-500 cursor-pointer hover:bg-gray-100 hover:border-blue-400 transition-all group">
                          <div className="p-3 bg-white rounded-full shadow-sm group-hover:scale-110 transition-transform">
                              <UploadCloud size={24} className="text-blue-500" />
                          </div>
                          <span className="text-sm font-medium">اضغط هنا لرفع ملف التقرير</span>
                          <input type="file" accept="application/pdf" className="hidden" onChange={handleFileUpload} />
                      </label>
                  )}
                  <p className="text-xs text-gray-400 mt-2">يجب أن يكون الملف بصيغة PDF وموقعاً من مكتب التدقيق المعتمد.</p>
              </div>

              {/* Right Column: Declaration */}
              <div className="bg-amber-50 rounded-xl p-5 border border-amber-100 flex flex-col justify-center">
                  <h4 className="font-bold text-amber-900 mb-3 flex items-center gap-2">
                      <ShieldCheck size={18}/> إقرار صحة البيانات
                  </h4>
                  <p className="text-sm text-amber-800 mb-4 leading-relaxed opacity-90">
                      بصفتي مخولاً عن المؤسسة الوقفية، أقر بأن جميع البيانات المالية المدخلة أعلاه صحيحة ومطابقة تماماً لتقرير المدقق المالي المرفق، وأتحمل المسؤولية القانونية في حال ثبوت خلاف ذلك.
                  </p>
                  <label className="flex items-center gap-3 cursor-pointer bg-white p-3 rounded-lg border border-amber-200 shadow-sm hover:border-amber-400 transition-colors">
                      <input type="checkbox" className="w-5 h-5 text-navy-900 rounded focus:ring-navy-900" 
                          checked={isConfirmed} onChange={(e) => setIsConfirmed(e.target.checked)} />
                      <span className="text-sm font-bold text-navy-900">
                          نعم، أقر بصحة البيانات ومطابقتها.
                      </span>
                  </label>
              </div>
          </div>
      </div>

      {/* Action Bar */}
      <div className="flex justify-end pt-4 border-t border-gray-200">
          <button 
              disabled={loading || !isConfirmed}
              onClick={handleSubmit}
              className={`flex items-center gap-2 px-8 py-3 rounded-xl font-bold text-white shadow-lg transition-transform active:scale-95 ${loading || !isConfirmed ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900'}`}
          >
              <Save size={20} /> {loading ? 'جاري الحفظ...' : 'حفظ وإرسال البيانات المالية'}
          </button>
      </div>

    </div>
  );
};

export default FinancialReports;

import React, { useState, useEffect } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType, InstitutionDocument } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X, FileText, UploadCloud, Calendar, Hash, User, CheckCircle2, Phone, AlertCircle, Building, AlertTriangle, Briefcase, MapPin, Mail, DollarSign, Users, LayoutGrid } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// توسيع الواجهة محلياً لتشمل تاريخ الانتهاء للعرض فقط
interface ExtendedFormData extends Partial<Institution> {
  expiry_date?: string;
}

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<ExtendedFormData>({});
  const { showToast, role, currentWaqfId, setWaqfContext } = useUi();

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  // Check if current user profile is incomplete
  const isCurrentProfileIncomplete = currentWaqfId && list.find(i => i.id === currentWaqfId)?.profile_completed !== true;

  // دالة حساب تاريخ الانتهاء (4 سنوات) تلقائياً
  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const estDate = e.target.value;
    let expiryDate = '';

    if (estDate) {
      const date = new Date(estDate);
      if (!isNaN(date.getTime())) {
        date.setFullYear(date.getFullYear() + 4);
        expiryDate = date.toISOString().split('T')[0];
      }
    }

    setFormData(prev => ({
      ...prev,
      establishment_date: estDate,
      expiry_date: expiryDate
    }));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // التحقق الصارم من جميع الحقول
    if (
        !formData.name || 
        !formData.type || 
        formData.capital_omr === undefined || 
        !formData.contact_phone || 
        !formData.email || 
        !formData.governorate || 
        !formData.wilayat || 
        !formData.establishment_date || 
        !formData.license_number || 
        !formData.manager_name
    ) {
        showToast('عذراً، جميع الحقول إجبارية بما فيها رقم الهاتف وتاريخ المجلس.', 'error');
        return;
    }

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name,
      type: (formData.type as InstitutionType),
      capital_omr: Number(formData.capital_omr),
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone,
      email: formData.email,
      governorate: formData.governorate,
      wilayat: formData.wilayat,

      establishment_date: formData.establishment_date,
      license_number: formData.license_number,
      manager_name: formData.manager_name,

      // IMPORTANT: Mark profile as completed on save
      profile_completed: true,

      documents: formData.documents || [],
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});

    // تحديث السياق وإعطاء صلاحية الدخول
    if (role === 'user') {
        setWaqfContext(newInst.id);
        // We rely on profile_completed in DB now, localstorage flag is less relevant but kept for legacy
        localStorage.setItem('isProfileCompleted', 'true'); 
    }

    showToast('تم حفظ بيانات المؤسسة وتفعيل صلاحية التقييم', 'success');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setFormData(prev => ({
              ...prev,
              documents: [...(prev.documents || []), newDoc]
          }));
          showToast('تم إرفاق الملف بنجاح', 'info');
      }
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
      if (currentWaqfId === id) setWaqfContext('');
      showToast('تم حذف المؤسسة', 'info');
    }
  };

  const handleSelectContext = (id: string) => {
      setWaqfContext(id);
      showToast('تم اختيار المؤسسة للعمل عليها', 'success');
  };

  // --- Filtering Logic Update ---
  const filtered = list.filter(i => {
      // 1. Text Search Filter (Always applies)
      if (!i.name.includes(search)) return false;

      // 2. Global Context Filter
      // If currentWaqfId is set (User OR Admin who selected specific institution), filter by ID.
      if (currentWaqfId) {
          return i.id === currentWaqfId;
      }

      // 3. If no ID is set (Admin selected "All Institutions"), show everything.
      return true;
  });

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

