                        </div>
                    </div>
                </div>

                {/* SECTION 2: MANAGEMENT & LOCATION */}
                <div className="lg:col-span-3 mt-4">
                    <div className="flex items-center gap-2 mb-6 pb-2 border-b border-gray-100">
