import React, { Suspense, lazy } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import { UiProvider, useUi } from './contexts/UiContext';
import { getInstitutionProgress } from './services/db';
import { Lock, Loader2 } from 'lucide-react';
import Login from './pages/Login';

// --- Lazy Load Pages ---
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Institutions = lazy(() => import('./pages/Institutions'));
const EvaluationPage = lazy(() => import('./pages/Evaluation'));
const CompliancePage = lazy(() => import('./pages/Compliance'));
const Reports = lazy(() => import('./pages/Reports'));
const Improvements = lazy(() => import('./pages/Improvements'));
const Settings = lazy(() => import('./pages/Settings'));
const ReviewSubmit = lazy(() => import('./pages/ReviewSubmit'));
const ApprovalRequests = lazy(() => import('./pages/ApprovalRequests'));
const FinancialReports = lazy(() => import('./pages/FinancialReports'));

// Loading Component
const PageLoader = () => (
  <div className="flex flex-col items-center justify-center h-[80vh] text-navy-800">
    <Loader2 size={48} className="animate-spin mb-4 text-teal-600" />
    <p className="text-gray-500 font-bold">جاري تحميل النظام...</p>
  </div>
);

// Protected Route Component handling Auth and Role Check
const ProtectedRoute: React.FC<{ children: React.ReactNode, requiredRole?: 'admin' | 'user' }> = ({ children, requiredRole }) => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) {
        return <Login />;
    }

    // If route requires admin but user is not admin
    if (requiredRole === 'admin' && role !== 'admin') {
        return <Navigate to="/institutions" replace />;
    }

    return <>{children}</>;
};

// Sequential Workflow Guard for Users
const SequentialRoute: React.FC<{ 
    children: React.ReactNode, 
    prereq: 'data' | 'evaluation' | 'compliance' 
}> = ({ children, prereq }) => {
    const { role, currentWaqfId } = useUi();
    const progress = getInstitutionProgress(currentWaqfId);

    // Admins bypass sequence
    if (role === 'admin') return <>{children}</>;

    let isAllowed = false;
    let redirectPath = '/institutions';
    let message = 'يرجى استكمال البيانات السابقة أولاً';

    if (prereq === 'data') {
        // Checking if we can enter Evaluation / Financials
        isAllowed = progress.dataComplete;
        redirectPath = '/institutions';
        message = 'يرجى استكمال وحفظ بيانات المؤسسة أولاً للدخول إلى التقييم.';
    } else if (prereq === 'evaluation') {
        // Checking if we can enter Compliance
        isAllowed = progress.evalFinalized;
        redirectPath = '/evaluation';
        message = 'يرجى اعتماد التقييم النهائي أولاً للدخول إلى الامتثال والمخاطر.';
    } else if (prereq === 'compliance') {
        // Checking if we can enter Improvements / Submit
        isAllowed = progress.complianceDone;
        redirectPath = '/compliance';
        message = 'يرجى مراجعة صفحة الامتثال والمخاطر أولاً.';
    }

    if (!isAllowed) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10 mx-auto max-w-2xl animate-fadeIn">
                <div className="bg-gray-100 p-6 rounded-full mb-6">
                    <Lock size={48} className="text-gray-400" />
                </div>
                <h2 className="text-2xl font-bold text-navy-900 mb-2">هذه الصفحة مغلقة حالياً</h2>
                <p className="text-gray-500 mb-8 max-w-md">{message}</p>
                <a href={`#${redirectPath}`} className="bg-navy-800 text-white px-6 py-3 rounded-lg hover:bg-navy-900 font-bold shadow-lg transition-transform active:scale-95">
                    الذهاب للخطوة السابقة
                </a>
            </div>
        );
    }

    return <>{children}</>;
};

// Root Redirect based on Role
const HomeRedirect: React.FC = () => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) return <Login />;

    // Admin goes to Strategic Dashboard
    if (role === 'admin') return <Dashboard />;

    // User goes to their Institution Data
    return <Navigate to="/institutions" replace />;
};

const AppRoutes: React.FC = () => {
    return (
        <Suspense fallback={<PageLoader />}>
            <Routes>
            <Route path="/" element={<HomeRedirect />} />

            {/* Admin Only Routes */}
            <Route path="/reports" element={<ProtectedRoute requiredRole="admin"><Reports /></ProtectedRoute>} />
            <Route path="/settings" element={<ProtectedRoute requiredRole="admin"><Settings /></ProtectedRoute>} />
            <Route path="/approval-requests" element={<ProtectedRoute requiredRole="admin"><ApprovalRequests /></ProtectedRoute>} />

            {/* Shared Routes (Admin & User) */}
            <Route path="/institutions" element={<ProtectedRoute><Institutions /></ProtectedRoute>} />

            {/* NEW MODULE ROUTE */}
            <Route path="/financial-reports" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="data">
                        <FinancialReports />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/evaluation" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="data">
                        <EvaluationPage />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/compliance" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="evaluation">
                        <CompliancePage />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/improvements" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="compliance">
                        <Improvements />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/review-submit" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="compliance">
                        <ReviewSubmit />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
        </Suspense>
    );
};

const App: React.FC = () => {
  return (
    <UiProvider>
        <Router>
          <Layout>
            <AppRoutes />
          </Layout>
        </Router>
    </UiProvider>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { getInstitutions, saveInstitution, deleteInstitution, generateId } from '../services/db';
import { Institution, InstitutionType, InstitutionDocument } from '../types';
import { GOVERNORATES, OMAN_LOCATIONS } from '../constants';
import { Plus, Search, Edit2, Trash2, X, FileText, UploadCloud, Calendar, Hash, User, CheckCircle2, Phone, AlertCircle, Building, AlertTriangle, Briefcase, MapPin, Mail, DollarSign, Users, LayoutGrid, ChevronLeft, ChevronRight } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// توسيع الواجهة محلياً لتشمل تاريخ الانتهاء للعرض فقط
interface ExtendedFormData extends Partial<Institution> {
  expiry_date?: string;
}

const ITEMS_PER_PAGE = 10;

const Institutions: React.FC = () => {
  const [list, setList] = useState<Institution[]>([]);
  const [search, setSearch] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<ExtendedFormData>({});
  const { showToast, role, currentWaqfId, setWaqfContext } = useUi();

  useEffect(() => {
    setList(getInstitutions());
  }, []);

  // Check if current user profile is incomplete
  const isCurrentProfileIncomplete = currentWaqfId && list.find(i => i.id === currentWaqfId)?.profile_completed !== true;

  // دالة حساب تاريخ الانتهاء (4 سنوات) تلقائياً
  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const estDate = e.target.value;
    let expiryDate = '';

    if (estDate) {
      const date = new Date(estDate);
      if (!isNaN(date.getTime())) {
        date.setFullYear(date.getFullYear() + 4);
        expiryDate = date.toISOString().split('T')[0];
      }
    }

    setFormData(prev => ({
      ...prev,
      establishment_date: estDate,
      expiry_date: expiryDate
    }));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // التحقق الصارم من جميع الحقول
    if (
        !formData.name || 
        !formData.type || 
        formData.capital_omr === undefined || 
        !formData.contact_phone || 
        !formData.email || 
        !formData.governorate || 
        !formData.wilayat || 
        !formData.establishment_date || 
        !formData.license_number || 
        !formData.manager_name
    ) {
        showToast('عذراً، جميع الحقول إجبارية بما فيها رقم الهاتف وتاريخ المجلس.', 'error');
        return;
    }

    const newInst: Institution = {
      id: formData.id || generateId(),
      name: formData.name,
      type: (formData.type as InstitutionType),
      capital_omr: Number(formData.capital_omr),
      employees_omani: Number(formData.employees_omani) || 0,
      employees_non_omani: Number(formData.employees_non_omani) || 0,
      contact_phone: formData.contact_phone,
      email: formData.email,
      governorate: formData.governorate,
      wilayat: formData.wilayat,

      establishment_date: formData.establishment_date,
      license_number: formData.license_number,
      manager_name: formData.manager_name,

      // IMPORTANT: Mark profile as completed on save
      profile_completed: true,

      documents: formData.documents || [],
      created_at: formData.created_at || new Date().toISOString(),
    };

    saveInstitution(newInst);
    setList(getInstitutions());
    setShowForm(false);
    setFormData({});

    // تحديث السياق وإعطاء صلاحية الدخول
    if (role === 'user') {
        setWaqfContext(newInst.id);
        // We rely on profile_completed in DB now, localstorage flag is less relevant but kept for legacy
        localStorage.setItem('isProfileCompleted', 'true'); 
    }

    showToast('تم حفظ بيانات المؤسسة وتفعيل صلاحية التقييم', 'success');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setFormData(prev => ({
              ...prev,
              documents: [...(prev.documents || []), newDoc]
          }));
          showToast('تم إرفاق الملف بنجاح', 'info');
      }
  };

  const handleDelete = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المؤسسة؟')) {
      deleteInstitution(id);
      setList(getInstitutions());
      if (currentWaqfId === id) setWaqfContext('');
      showToast('تم حذف المؤسسة', 'info');
    }
  };

  const handleSelectContext = (id: string) => {
      setWaqfContext(id);
      showToast('تم اختيار المؤسسة للعمل عليها', 'success');
  };

  // --- Filtering & Pagination Logic ---
  const filtered = useMemo(() => {
    return list.filter(i => {
        if (!i.name.includes(search)) return false;
        if (currentWaqfId) {
            return i.id === currentWaqfId;
        }
        return true;
    });
  }, [list, search, currentWaqfId]);

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  const paginatedData = useMemo(() => {
      const start = (currentPage - 1) * ITEMS_PER_PAGE;
      return filtered.slice(start, start + ITEMS_PER_PAGE);
  }, [filtered, currentPage]);

  const goToPage = (page: number) => {
      if (page >= 1 && page <= totalPages) {
          setCurrentPage(page);
      }
  };

  const availableWilayats = formData.governorate && OMAN_LOCATIONS[formData.governorate] 
    ? OMAN_LOCATIONS[formData.governorate] 
    : [];

  const currentInstitutionName = list.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white">بيانات المؤسسات</h2>
        {role === 'admin' && (
            <button 
            onClick={() => { setFormData({}); setShowForm(true); }}
            className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 transition-all duration-300 hover:scale-105 active:scale-95 shadow-md"
            >
            <Plus size={18} /> إضافة مؤسسة
            </button>
        )}
      </div>

      {/* WARNING BANNER IF PROFILE INCOMPLETE */}
      {isCurrentProfileIncomplete && role === 'user' && (
           <div className="bg-red-50 border-r-4 border-red-500 p-4 rounded-lg shadow-sm animate-pulse">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="text-red-500 mt-0.5" size={24} />
                   <div>
                       <h3 className="font-bold text-red-800 text-lg">إجراء مطلوب: تحديث البيانات</h3>
                       <p className="text-red-700 text-sm">
                           لم تقم بتأكيد بيانات المؤسسة بعد. يجب عليك الضغط على زر التعديل <Edit2 size={12} className="inline"/>، مراجعة البيانات، ثم الضغط على "حفظ" لتفعيل باقي صفحات النظام.
                       </p>
                   </div>
               </div>
           </div>
      )}

      {/* Context Banner for Admins */}
      {currentWaqfId && (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn transition-transform hover:scale-[1.01] duration-300">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">تصفية العرض حسب:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
              {role === 'admin' && (
                  <button 
                    onClick={() => { setWaqfContext(''); setCurrentPage(1); }}
                    className="text-xs bg-white border border-blue-300 px-3 py-1.5 rounded-lg hover:bg-blue-50 text-blue-700 transition-colors"
                  >
                      عرض الكل
                  </button>
              )}
          </div>
      )}

      <div className="relative">
        <input
          type="text"
          placeholder="بحث عن مؤسسة..."
          className="w-full md:w-1/3 p-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-navy-800 outline-none transition-shadow focus:shadow-md"
          value={search}
          onChange={(e) => { setSearch(e.target.value); setCurrentPage(1); }}
        />
        <Search className="absolute top-3.5 right-3 text-gray-400" size={18} />
