      </div>
    </div>
  );
};

export default ApprovalRequests;

import React, { Suspense, lazy } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import { UiProvider, useUi } from './contexts/UiContext';
import { getInstitutionProgress } from './services/db';
import { Lock, Loader2 } from 'lucide-react';
import Login from './pages/Login';

// --- Lazy Load Pages ---
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Institutions = lazy(() => import('./pages/Institutions'));
const EvaluationPage = lazy(() => import('./pages/Evaluation'));
const CompliancePage = lazy(() => import('./pages/Compliance'));
const Reports = lazy(() => import('./pages/Reports'));
const Improvements = lazy(() => import('./pages/Improvements'));
const Settings = lazy(() => import('./pages/Settings'));
const ReviewSubmit = lazy(() => import('./pages/ReviewSubmit'));
const ApprovalRequests = lazy(() => import('./pages/ApprovalRequests'));
const FinancialReports = lazy(() => import('./pages/FinancialReports'));

// Loading Component
const PageLoader = () => (
  <div className="flex flex-col items-center justify-center h-[80vh] text-navy-800">
    <Loader2 size={48} className="animate-spin mb-4 text-teal-600" />
    <p className="text-gray-500 font-bold">جاري تحميل النظام...</p>
  </div>
);

// Protected Route Component handling Auth and Role Check
const ProtectedRoute: React.FC<{ children: React.ReactNode, requiredRole?: 'admin' | 'user' }> = ({ children, requiredRole }) => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) {
        return <Login />;
    }

    // If route requires admin but user is not admin
    if (requiredRole === 'admin' && role !== 'admin') {
        return <Navigate to="/institutions" replace />;
    }

    return <>{children}</>;
};

// Sequential Workflow Guard for Users
const SequentialRoute: React.FC<{ 
    children: React.ReactNode, 
    prereq: 'data' | 'evaluation' | 'compliance' 
}> = ({ children, prereq }) => {
    const { role, currentWaqfId } = useUi();
    const progress = getInstitutionProgress(currentWaqfId);

    // Admins bypass sequence
    if (role === 'admin') return <>{children}</>;

    let isAllowed = false;
    let redirectPath = '/institutions';
    let message = 'يرجى استكمال البيانات السابقة أولاً';

    if (prereq === 'data') {
        // Checking if we can enter Evaluation / Financials
        isAllowed = progress.dataComplete;
        redirectPath = '/institutions';
        message = 'يرجى استكمال وحفظ بيانات المؤسسة أولاً للدخول إلى التقييم.';
    } else if (prereq === 'evaluation') {
        // Checking if we can enter Compliance
        isAllowed = progress.evalFinalized;
        redirectPath = '/evaluation';
        message = 'يرجى اعتماد التقييم النهائي أولاً للدخول إلى الامتثال والمخاطر.';
    } else if (prereq === 'compliance') {
        // Checking if we can enter Improvements / Submit
        isAllowed = progress.complianceDone;
        redirectPath = '/compliance';
        message = 'يرجى مراجعة صفحة الامتثال والمخاطر أولاً.';
    }

    if (!isAllowed) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10 mx-auto max-w-2xl animate-fadeIn">
                <div className="bg-gray-100 p-6 rounded-full mb-6">
                    <Lock size={48} className="text-gray-400" />
                </div>
                <h2 className="text-2xl font-bold text-navy-900 mb-2">هذه الصفحة مغلقة حالياً</h2>
                <p className="text-gray-500 mb-8 max-w-md">{message}</p>
                <a href={`#${redirectPath}`} className="bg-navy-800 text-white px-6 py-3 rounded-lg hover:bg-navy-900 font-bold shadow-lg transition-transform active:scale-95">
                    الذهاب للخطوة السابقة
                </a>
            </div>
        );
    }

    return <>{children}</>;
};

// Root Redirect based on Role
const HomeRedirect: React.FC = () => {
    const { isAuthenticated, role } = useUi();

    if (!isAuthenticated) return <Login />;

    // Admin goes to Strategic Dashboard
    if (role === 'admin') return <Dashboard />;

    // User goes to their Institution Data
    return <Navigate to="/institutions" replace />;
};

const AppRoutes: React.FC = () => {
    return (
        <Suspense fallback={<PageLoader />}>
            <Routes>
            <Route path="/" element={<HomeRedirect />} />

            {/* Admin Only Routes */}
            <Route path="/reports" element={<ProtectedRoute requiredRole="admin"><Reports /></ProtectedRoute>} />
            <Route path="/settings" element={<ProtectedRoute requiredRole="admin"><Settings /></ProtectedRoute>} />
            <Route path="/approval-requests" element={<ProtectedRoute requiredRole="admin"><ApprovalRequests /></ProtectedRoute>} />

            {/* Shared Routes (Admin & User) */}
            <Route path="/institutions" element={<ProtectedRoute><Institutions /></ProtectedRoute>} />

            {/* NEW MODULE ROUTE */}
            <Route path="/financial-reports" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="data">
                        <FinancialReports />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/evaluation" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="data">
                        <EvaluationPage />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/compliance" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="evaluation">
                        <CompliancePage />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/improvements" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="compliance">
                        <Improvements />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="/review-submit" element={
                <ProtectedRoute>
                    <SequentialRoute prereq="compliance">
                        <ReviewSubmit />
                    </SequentialRoute>
                </ProtectedRoute>
            } />

            <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
        </Suspense>
    );
};

const App: React.FC = () => {
  return (
    <UiProvider>
        <Router>
          <Layout>
            <AppRoutes />
          </Layout>
        </Router>
    </UiProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { LayoutDashboard, Building2, ClipboardCheck, Scale, FileBarChart, Menu, X, ShieldAlert, Settings, LogOut, Lock, Send, Inbox, CheckCircle, RotateCcw, Landmark, RefreshCw } from 'lucide-react';
import { getSettings, getInstitutionProgress, getPendingEvaluationsCount, getEvaluationByInstAndYear, saveEvaluation } from '../services/db';
import { CURRENT_YEAR } from '../constants';
import { useUi } from '../contexts/UiContext';

// Helper to determine if a route is locked
const isRouteLocked = (path: string, role: string | null, progress: any) => {
    if (role === 'admin') return false; // Admin can access everything

    // Logic: 
    // /institutions -> Always Open
    // /financial-reports -> Locked if Data Not Complete
    // /evaluation -> Locked if Financials Not Submitted (Optional constraint, let's keep it open for now or tie to Data) -> Tie to Data
    // /compliance -> Locked if Evaluation Not Finalized
    // /improvements -> Locked if Compliance Not Done
    // /review-submit -> Locked if Compliance Not Done

    if (path === '/financial-reports' && !progress.dataComplete) return true;
    if (path === '/evaluation' && !progress.dataComplete) return true;
    if (path === '/compliance' && !progress.evalFinalized) return true;
    if (path === '/improvements' && !progress.complianceDone) return true;
    if (path === '/review-submit' && !progress.complianceDone) return true;

    return false;
};

const SidebarItem = ({ to, icon: Icon, label, active, locked, badge }: any) => (
  <Link 
    to={locked ? '#' : to} 
    className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-300 ease-in-out transform
        ${active ? 'bg-navy-800 text-gold-400 scale-105 shadow-lg' : 'text-white hover:bg-navy-800/50 hover:scale-105 hover:translate-x-1'} 
        ${locked ? 'opacity-50 cursor-not-allowed grayscale hover:scale-100 hover:translate-x-0' : ''}
    `}
    onClick={(e) => locked && e.preventDefault()}
  >
    <div className="relative">
        <Icon size={20} className={`transition-transform duration-300 ${active ? 'scale-110' : ''}`} />
        {badge > 0 && (
            <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full animate-pulse">
                {badge}
            </span>
        )}
    </div>
    <span className="font-medium flex-1">{label}</span>
    {locked && <Lock size={14} className="text-gray-400" />}
  </Link>
);

const AdminActionBar = ({ waqfId, showToast }: any) => {
    const [ev, setEv] = useState<any>(null);
    const [showReturnModal, setShowReturnModal] = useState(false);
    const [reason, setReason] = useState('');

    useEffect(() => {
        if(waqfId) setEv(getEvaluationByInstAndYear(waqfId, CURRENT_YEAR));
    }, [waqfId]);

    if (!ev || ev.workflow_status !== 'submitted') return null;

    const handleApprove = () => {
        if(confirm('هل أنت متأكد من اعتماد هذا التقييم؟ لا يمكن التراجع عن هذا الإجراء.')) {
            saveEvaluation({...ev, workflow_status: 'approved'});
            showToast('تم اعتماد التقييم بنجاح', 'success');
            setEv({...ev, workflow_status: 'approved'});
        }
    };

    const handleReturn = () => {
        if(!reason) { showToast('يرجى كتابة سبب الإعادة', 'error'); return; }
        saveEvaluation({...ev, workflow_status: 'returned', admin_feedback: reason});
        showToast('تم إعادة الملف للمؤسسة للتعديل', 'info');
        setShowReturnModal(false);
        setEv({...ev, workflow_status: 'returned'});
    };

    return (
        <div className="bg-navy-900 text-white p-3 px-6 flex justify-between items-center shadow-lg animate-slideDown z-20 sticky top-0">
            <div className="flex items-center gap-2">
                <Lock size={18} className="text-gold-500" />
                <span className="font-bold text-sm">هذا الملف قيد المراجعة (للاعتماد)</span>
            </div>
            <div className="flex gap-2">
                <button 
                    onClick={() => setShowReturnModal(true)}
                    className="bg-red-700 hover:bg-red-800 text-white px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors"
                >
                    <RotateCcw size={16} /> إعادة للتعديل
                </button>
                <button 
                    onClick={handleApprove}
                    className="bg-green-600 hover:bg-green-700 text-white px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-md"
                >
                    <CheckCircle size={16} /> اعتماد التقييم
                </button>
            </div>

            {/* Return Modal */}
            {showReturnModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 text-gray-800">
                    <div className="bg-white rounded-xl p-6 w-full max-w-md animate-scaleIn">
                        <h3 className="font-bold text-lg mb-4">إعادة الملف للتعديل</h3>
                        <textarea 
                            className="w-full border p-3 rounded-lg h-32 mb-4" 
                            placeholder="اكتب ملاحظات التعديل المطلوبة هنا..."
                            value={reason}
                            onChange={(e) => setReason(e.target.value)}
                        />
                        <div className="flex gap-2 justify-end">
                            <button onClick={() => setShowReturnModal(false)} className="text-gray-500 hover:bg-gray-100 px-4 py-2 rounded">إلغاء</button>
                            <button onClick={handleReturn} className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700">تأكيد الإعادة</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

