export const performSmartCleanup = () => {
  try {
    console.log("Starting Smart Cleanup...");

    // Ensure we have data to clean
    let allInsts = getInstitutions();
    if (!allInsts || allInsts.length === 0) {
        initializeDatabase();
        allInsts = getInstitutions();
    }

    if (allInsts.length === 0) {
        alert("لم يتم العثور على بيانات لتنظيفها.");
        return;
    }

    // 1. Identify VIPs (First 5)
    const vipInsts = allInsts.slice(0, 5);
    const vipIds = vipInsts.map(i => i.id);

    // 2. Clean Institutions (Keep names, remove heavy nested data for non-VIPs)
    const cleanedInsts = allInsts.map(inst => {
      if (vipIds.includes(inst.id)) return inst;
      return {
        ...inst,
        financial_reports: [],
        documents: [],
        profile_completed: false 
      };
    });

    // 3. Clean Tables
    const cleanTable = <T extends { institution_id?: string, evaluation_id?: string }>(key: string, isEvalRelated = false) => {
        const items = data<any>(key);
        if (isEvalRelated) {
             // For responses/improvements, we filter by valid evaluation IDs later
             return items; 
        }
        return items.filter(i => vipIds.includes(i.institution_id));
    };

    const cleanedFinancials = cleanTable(DB_KEYS.FINANCIALS);
    const cleanedRisks = cleanTable(DB_KEYS.RISKS);
    const cleanedCompliance = cleanTable(DB_KEYS.COMPLIANCE);

    // Evaluations need special handling to get valid IDs for responses
    const allEvals = data<Evaluation>(DB_KEYS.EVALUATIONS);
    const cleanedEvals = allEvals.filter(e => vipIds.includes(e.institution_id));
    const validEvalIds = cleanedEvals.map(e => e.id);

    // Filter Response/Improvement based on valid evaluations
    const allResponses = data<Response>(DB_KEYS.RESPONSES);
    const cleanedResponses = allResponses.filter(r => validEvalIds.includes(r.evaluation_id));

    const allImprovements = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS);
    const cleanedImprovements = allImprovements.filter(i => validEvalIds.includes(i.evaluation_id));

    // 4. Save Back
    save(DB_KEYS.INSTITUTIONS, cleanedInsts);
    save(DB_KEYS.FINANCIALS, cleanedFinancials);
    save(DB_KEYS.RISKS, cleanedRisks);
    save(DB_KEYS.COMPLIANCE, cleanedCompliance);
    save(DB_KEYS.EVALUATIONS, cleanedEvals);
    save(DB_KEYS.RESPONSES, cleanedResponses);
    save(DB_KEYS.IMPROVEMENTS, cleanedImprovements);

    console.log("Smart Cleanup Complete!");
    alert(`✅ تم تسريع النظام بنجاح!\n\n- المؤسسات النشطة: 5\n- المؤسسات المؤرشفة: ${cleanedInsts.length - 5}\n\nسيتم تحديث الصفحة الآن.`);

    setTimeout(() => {
        window.location.reload();
    }, 500);

  } catch (error) {
    console.error("Cleanup Failed:", error);
    alert("حدث خطأ أثناء محاولة تسريع النظام. يرجى تجربة 'إعادة ضبط المصنع' إذا استمرت المشكلة.");
  }
};

