// --- Other Exports ---
export const saveInstitution = (inst: Institution) => {
  const list = getInstitutions();
  const index = list.findIndex(i => i.id === inst.id);
  if (index >= 0) list[index] = inst; else list.push(inst);
  save(DB_KEYS.INSTITUTIONS, list);
};
export const deleteInstitution = (id: string) => {
  const list = getInstitutions().filter(i => i.id !== id);
  save(DB_KEYS.INSTITUTIONS, list);
};
export const getFinancialRecords = (instId?: string): FinancialRecord[] => {
  const all = data<FinancialRecord>(DB_KEYS.FINANCIALS);
  if (instId) return all.filter(f => f.institution_id === instId);
  return all;
};
export const analyzeFinancialHealth = (record: FinancialRecord) => {
  const flags: string[] = [], errors: string[] = [];
  const calculatedNet = record.total_assets - record.total_liabilities;
  const diff = Math.abs(calculatedNet - record.net_waqf_assets);
  if (diff > 1) errors.push(`خطأ محاسبي: المعادلة غير متزنة.`);
  if (record.total_expenses > 0 && ((record.admin_general_expenses / record.total_expenses) * 100 > 20)) flags.push(`تنبيه: المصاريف الإدارية مرتفعة.`);
  if (record.total_expenses > record.total_revenues) flags.push('تنبيه: عجز تشغيلي.');
  if (record.net_waqf_assets < 0) flags.push('خطر حرج: تآكل رأس المال.');
  return { isValid: errors.length === 0, status: flags.length > 0 ? 'Flagged' : 'Submitted' as const, flags, errors };
};
export const saveFinancialRecord = (record: FinancialRecord) => {
  const list = data<FinancialRecord>(DB_KEYS.FINANCIALS);
  const index = list.findIndex(r => r.id === record.id);
  if (index >= 0) list[index] = record; else list.push(record);
  save(DB_KEYS.FINANCIALS, list);
};
export const deleteFinancialRecord = (id: string) => {
  const list = data<FinancialRecord>(DB_KEYS.FINANCIALS).filter(r => r.id !== id);
  save(DB_KEYS.FINANCIALS, list);
};
export const getIndicators = () => { let s = data<Indicator>(DB_KEYS.INDICATORS); if(!s.length) { save(DB_KEYS.INDICATORS, DEFAULT_INDICATORS); s = DEFAULT_INDICATORS; } return s; };
export const saveIndicators = (i: Indicator[]) => save(DB_KEYS.INDICATORS, i);
export const getEvaluations = (y?: number) => { const e = data<Evaluation>(DB_KEYS.EVALUATIONS); return y ? e.filter(x => x.cycle_year === y) : e; };
export const getEvaluationByInstAndYear = (id: string, y: number) => getEvaluations().find(e => e.institution_id === id && e.cycle_year === y);
export const saveEvaluation = (e: Evaluation) => { const l = getEvaluations(); const i = l.findIndex(x => x.id === e.id); if(i>=0) l[i] = e; else l.push(e); save(DB_KEYS.EVALUATIONS, l); };
export const getPendingEvaluationsCount = () => getEvaluations(CURRENT_YEAR).filter(e => e.workflow_status === 'submitted').length;
export const getResponses = (id: string) => data<Response>(DB_KEYS.RESPONSES).filter(r => r.evaluation_id === id);
export const getAllResponses = () => data<Response>(DB_KEYS.RESPONSES);
export const saveResponse = (r: Response) => { const l = data<Response>(DB_KEYS.RESPONSES); const i = l.findIndex(x => x.evaluation_id === r.evaluation_id && x.indicator_id === r.indicator_id); if(i>=0) l[i] = { ...l[i], ...r }; else l.push({ ...r, id: generateId() }); save(DB_KEYS.RESPONSES, l); };
export const getComplianceRecords = (y?: number) => { const r = data<ComplianceRecord>(DB_KEYS.COMPLIANCE); return y ? r.filter(x => x.cycle_year === y) : r; };
export const getComplianceByInstAndYear = (id: string, y: number) => getComplianceRecords(y).find(r => r.institution_id === id);
export const saveComplianceRecord = (r: ComplianceRecord) => { const l = data<ComplianceRecord>(DB_KEYS.COMPLIANCE); const i = l.findIndex(x => x.id === r.id); if(i>=0) l[i] = r; else l.push(r); save(DB_KEYS.COMPLIANCE, l); };
export const getRisks = (id?: string) => { const a = data<RiskRegisterItem>(DB_KEYS.RISKS); return id ? a.filter(r => r.institution_id === id) : a; };
export const saveRisk = (r: RiskRegisterItem) => { const l = data<RiskRegisterItem>(DB_KEYS.RISKS); const i = l.findIndex(x => x.id === r.id); if(i>=0) l[i] = r; else l.push(r); save(DB_KEYS.RISKS, l); };
export const deleteRisk = (id: string) => save(DB_KEYS.RISKS, data<RiskRegisterItem>(DB_KEYS.RISKS).filter(x => x.id !== id));
export const getImprovements = (id: string) => data<ImprovementItem>(DB_KEYS.IMPROVEMENTS).filter(i => i.evaluation_id === id);
export const saveImprovement = (i: ImprovementItem) => { const l = data<ImprovementItem>(DB_KEYS.IMPROVEMENTS); const x = l.findIndex(z => z.id === i.id); if(x>=0) l[x] = i; else l.push(i); save(DB_KEYS.IMPROVEMENTS, l); };
export const deleteImprovement = (id: string) => save(DB_KEYS.IMPROVEMENTS, data<ImprovementItem>(DB_KEYS.IMPROVEMENTS).filter(x => x.id !== id));
export const getSettings = () => { const s = localStorage.getItem(DB_KEYS.SETTINGS); return safeParse(s, { managerName: 'د. عبدالرحمن النوفلي', darkMode: false, orgName: 'وزارة الأوقاف والشؤون الدينية' }); };
export const saveSettings = (s: any) => { localStorage.setItem(DB_KEYS.SETTINGS, JSON.stringify(s)); window.dispatchEvent(new Event('settingsChanged')); };

// --- UPDATED PROGRESS TRACKER ---
export const getInstitutionProgress = (id: string | null) => {
  if (!id) return { dataComplete: false, financialsDone: false, evalFinalized: false, complianceDone: false, workflowStatus: 'draft' as const, isLocked: false };

  const i = getInstitutions().find(x => x.id === id);
  const e = getEvaluations().find(x => x.institution_id === id && x.cycle_year === CURRENT_YEAR);
  const c = getComplianceRecords().find(x => x.institution_id === id && x.cycle_year === CURRENT_YEAR);

  // Check if financials exist for this year (or prev)
  const f = getFinancialRecords(id).find(r => r.fiscal_year === CURRENT_YEAR || r.fiscal_year === CURRENT_YEAR - 1);

  return { 
      dataComplete: !!(i?.profile_completed), 
      financialsDone: !!f, // New Flag
      evalFinalized: !!(e?.status === 'final'), 
      complianceDone: !!c, 
      workflowStatus: e?.workflow_status || 'draft', 
      isLocked: e?.workflow_status === 'submitted' || e?.workflow_status === 'approved' 
  };
};

import React, { useState, useEffect } from 'react';
import { useUi } from '../contexts/UiContext';
import { getInstitutions, saveFinancialRecord, getFinancialRecords, analyzeFinancialHealth, generateId } from '../services/db';
import { FinancialRecord, InstitutionDocument } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    TrendingUp, TrendingDown, UploadCloud, Save, AlertTriangle, 
    FileText, CheckCircle2, XCircle, Landmark, Briefcase, Scale,
    Banknote, ArrowRightLeft, Paperclip, ShieldCheck
} from 'lucide-react';

const FinancialReports: React.FC = () => {
  const { currentWaqfId, showToast } = useUi();
  const [loading, setLoading] = useState(false);
  const [institutions, setInstitutions] = useState<any[]>([]);

  // Form State
  const [record, setRecord] = useState<Partial<FinancialRecord>>({
      fiscal_year: CURRENT_YEAR - 1,
      auditor_name: '',
      total_assets: 0,
      total_liabilities: 0,
      net_waqf_assets: 0,
      total_revenues: 0,
      total_expenses: 0,
      admin_general_expenses: 0,
      surplus_deficit: 0,
      operating_cash_flow: 0,
      investing_cash_flow: 0,
      financing_cash_flow: 0,
      cash_end_period: 0
  });

  const [pdfFile, setPdfFile] = useState<InstitutionDocument | null>(null);
  const [isConfirmed, setIsConfirmed] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<{isValid: boolean, status: string, flags: string[], errors: string[]} | null>(null);

  useEffect(() => {
      setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
      if (currentWaqfId) {
          const records = getFinancialRecords(currentWaqfId);
          const existing = records.find(r => r.fiscal_year === record.fiscal_year);
          if (existing) {
              setRecord(existing);
              setPdfFile(existing.audit_report_pdf || null);
              setAnalysisResult(analyzeFinancialHealth(existing));
          } else {
              setRecord({
                  fiscal_year: record.fiscal_year,
                  auditor_name: '',
                  total_assets: 0,
                  total_liabilities: 0,
                  net_waqf_assets: 0,
                  total_revenues: 0,
                  total_expenses: 0,
                  admin_general_expenses: 0,
                  surplus_deficit: 0,
                  operating_cash_flow: 0,
                  investing_cash_flow: 0,
                  financing_cash_flow: 0,
                  cash_end_period: 0
              });
              setPdfFile(null);
              setAnalysisResult(null);
              setIsConfirmed(false);
          }
      }
  }, [currentWaqfId, record.fiscal_year]);

  // Auto-calculate Surplus/Deficit
  useEffect(() => {
      const revenue = Number(record.total_revenues) || 0;
      const expenses = Number(record.total_expenses) || 0;
      const computedSurplus = revenue - expenses;

      if (computedSurplus !== record.surplus_deficit) {
          setRecord(prev => ({ ...prev, surplus_deficit: computedSurplus }));
      }
  }, [record.total_revenues, record.total_expenses]);

  // Auto-calculate Net Assets (Assets - Liabilities)
  useEffect(() => {
      const assets = Number(record.total_assets) || 0;
      const liabilities = Number(record.total_liabilities) || 0;
      const computedNet = assets - liabilities;

      if (computedNet !== record.net_waqf_assets) {
          setRecord(prev => ({ ...prev, net_waqf_assets: computedNet }));
      }
  }, [record.total_assets, record.total_liabilities]);

  const handleInputChange = (field: keyof FinancialRecord, value: any) => {
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setPdfFile(newDoc);
          showToast('تم إرفاق التقرير المالي', 'success');
      }
  };

  const handleSubmit = () => {
      if (!currentWaqfId) return;
      if (!isConfirmed) {
          showToast('يرجى الإقرار بصحة البيانات قبل الحفظ', 'error');
          return;
      }

      setLoading(true);

      const fullRecord: FinancialRecord = {
          ...record as FinancialRecord,
          id: record.id || generateId(),
          institution_id: currentWaqfId,
          audit_report_pdf: pdfFile || undefined,
          submission_date: new Date().toISOString(),
          status: 'Submitted',
          flags: []
      };

      const analysis = analyzeFinancialHealth(fullRecord);
      fullRecord.status = analysis.status as any;
      fullRecord.flags = analysis.flags;

      saveFinancialRecord(fullRecord);
      setAnalysisResult(analysis);
      setLoading(false);

      showToast('تم حفظ البيانات المالية بنجاح', 'success');
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  if (!currentWaqfId) return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10">
          <div className="bg-blue-50 p-6 rounded-full mb-6 text-blue-600"><Landmark size={48} /></div>
          <h2 className="text-2xl font-bold text-navy-900 mb-2">التقارير المالية</h2>
          <p className="text-gray-500">يرجى اختيار مؤسسة من القائمة العلوية لإدخال البيانات المالية</p>
      </div>
  );

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20 animate-fadeIn">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-gray-200 pb-6">
          <div>
              <h2 className="text-2xl font-bold text-navy-900 flex items-center gap-2">
                  <Landmark className="text-teal-600"/> القوائم المالية والحوكمة
              </h2>
              <p className="text-gray-500 mt-1">إدخال البيانات المالية لـ: <span className="font-bold text-navy-800">{currentInstitutionName}</span></p>
          </div>
          <div className="flex gap-4">
              <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">السنة المالية</label>
                  <select 
                    className="border border-gray-300 rounded-lg p-2 bg-white text-navy-900 font-bold outline-none focus:ring-2 focus:ring-teal-500"
                    value={record.fiscal_year}
                    onChange={(e) => handleInputChange('fiscal_year', Number(e.target.value))}
                  >
                      {Array.from({length: 5}, (_, i) => CURRENT_YEAR - i).map(y => (
                          <option key={y} value={y}>{y}</option>
                      ))}
                  </select>
              </div>
              <div className="min-w-[200px]">
                  <label className="block text-xs font-bold text-gray-500 mb-1">مكتب التدقيق الخارجي</label>
                  <input 
                    type="text" 
                    placeholder="اسم المكتب / المدقق"
                    className="w-full border border-gray-300 rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-teal-500"
                    value={record.auditor_name}
                    onChange={(e) => handleInputChange('auditor_name', e.target.value)}
                  />
              </div>
          </div>
      </div>

      {/* Analysis Feedback Area */}
      {analysisResult && (
          <div className={`p-4 rounded-xl border-l-4 shadow-sm animate-scaleIn ${analysisResult.status === 'Flagged' || !analysisResult.isValid ? 'bg-red-50 border-red-500' : 'bg-green-50 border-green-500'}`}>
              <div className="flex items-start gap-3">
                  {analysisResult.isValid && analysisResult.status === 'Submitted' ? (
                      <CheckCircle2 className="text-green-600 mt-1" />
                  ) : (
                      <AlertTriangle className="text-red-600 mt-1" />
                  )}
                  <div>
                      <h4 className={`font-bold ${analysisResult.status === 'Flagged' ? 'text-red-800' : 'text-green-800'}`}>
                          {analysisResult.status === 'Flagged' ? 'تم رصد ملاحظات حوكمة' : (!analysisResult.isValid ? 'خطأ في البيانات' : 'البيانات سليمة')}
                      </h4>
                      <ul className="mt-2 space-y-1 text-sm list-disc list-inside">
                          {analysisResult.errors.map((err, i) => <li key={`e-${i}`} className="text-red-700 font-bold">{err}</li>)}
                          {analysisResult.flags.map((flag, i) => <li key={`f-${i}`} className="text-red-600">{flag}</li>)}
                          {analysisResult.isValid && analysisResult.flags.length === 0 && (
                              <li className="text-green-700">المعادلة المحاسبية متزنة والمصروفات الإدارية في الحدود المسموحة.</li>
                          )}
                      </ul>
                  </div>
              </div>
          </div>
      )}

      {/* Main Form Grid (4 Cards) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

          {/* Card A: Financial Position */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-blue-900 to-navy-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Briefcase size={18}/> المركز المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الأصول</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none" 
                          value={record.total_assets || ''} onChange={(e) => handleInputChange('total_assets', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الالتزامات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none" 
                          value={record.total_liabilities || ''} onChange={(e) => handleInputChange('total_liabilities', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">صافي الأصول (المال الوقفي)</label>
                      <input 
                        type="number" 
                        readOnly
                        className="w-full p-2 border border-gray-300 rounded-lg font-bold bg-gray-100 text-navy-900 outline-none"
                        value={record.net_waqf_assets || 0} 
                      />
                      <p className="text-[10px] text-gray-400 mt-1">يتم الاحتساب تلقائياً: (الأصول - الالتزامات)</p>
                  </div>
              </div>
          </div>

          {/* Card B: Performance */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-teal-700 to-teal-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><TrendingUp size={18}/> الأداء المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الإيرادات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none" 
                          value={record.total_revenues || ''} onChange={(e) => handleInputChange('total_revenues', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي المصروفات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none" 
                          value={record.total_expenses || ''} onChange={(e) => handleInputChange('total_expenses', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">الفائض / العجز</label>
                      <input disabled type="text" className={`w-full p-2 border rounded-lg font-bold bg-gray-100 ${(record.surplus_deficit || 0) < 0 ? 'text-red-600' : 'text-green-600'}`} 
                          value={record.surplus_deficit?.toLocaleString() || '0'} />
                  </div>
              </div>
          </div>

          {/* Card C: Cash Flows */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-orange-700 to-red-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><ArrowRightLeft size={18}/> التدفقات النقدية</h3>
                  <span className="text-xs bg-white/20 px-2 py-1 rounded">السيولة</span>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">صافي النقد التشغيلي</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none" 
                          value={record.operating_cash_flow || ''} onChange={(e) => handleInputChange('operating_cash_flow', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">صافي النقد الاستثماري</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none" 
                          value={record.investing_cash_flow || ''} onChange={(e) => handleInputChange('investing_cash_flow', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1 flex items-center gap-1"><Banknote size={14}/> النقد وما في حكمه (نهاية السنة)</label>
                      <input type="number" className="w-full p-2 border-2 border-orange-100 rounded-lg font-bold text-orange-900 outline-none focus:border-orange-500"
                          value={record.cash_end_period || ''} onChange={(e) => handleInputChange('cash_end_period', Number(e.target.value))} />
                  </div>
              </div>
          </div>

          {/* Card D: Governance (Simplified) */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-purple-800 to-indigo-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Scale size={18}/> الحوكمة المالية</h3>
              </div>
              <div className="p-4 space-y-4 h-full">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">المصروفات الإدارية</label>
                      <input type="number" className="w-full p-2 border border-gray-200 rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-purple-500 outline-none" 
                          value={record.admin_general_expenses || ''} onChange={(e) => handleInputChange('admin_general_expenses', Number(e.target.value))} />

                      {(record.total_expenses || 0) > 0 && (
                          <div className={`mt-2 p-2 rounded text-xs font-bold text-center ${((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100) > 20 ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-green-50 text-green-600 border border-green-200'}`}>
                              نسبة الإدارية: {((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100).toFixed(1)}% <br/>
                              (الحد الأقصى المسموح 20%)
                          </div>
                      )}
                  </div>

                  {/* Placeholder for visual balance */}
                  <div className="pt-2 border-t border-gray-100 text-center text-gray-400 text-xs">
                      <ShieldCheck size={48} className="mx-auto mb-2 opacity-20" />
                      <p>مؤشر الالتزام بضوابط الصرف</p>
                  </div>
              </div>
          </div>
      </div>

      {/* NEW: Attachments & Declaration Section (Full Width) */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="bg-gray-50 p-4 border-b border-gray-200 flex items-center gap-2">
              <Paperclip size={20} className="text-navy-900"/>
              <h3 className="font-bold text-navy-900">المرفقات والإقرار</h3>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Left Column: Upload */}
              <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">إرفاق تقرير المدقق المالي (PDF)</label>
                  {pdfFile ? (
                      <div className="flex items-center justify-between bg-blue-50 p-4 rounded-xl border border-blue-200 text-blue-900">
                          <div className="flex items-center gap-3">
                              <div className="bg-white p-2 rounded-lg text-red-500 shadow-sm"><FileText size={24}/></div>
                              <div>
                                  <span className="text-sm font-bold block">{pdfFile.name}</span>
                                  <span className="text-xs opacity-70">{pdfFile.size} - تم الرفع</span>
                              </div>
                          </div>
                          <button onClick={() => setPdfFile(null)} className="text-red-500 hover:bg-red-100 p-2 rounded-full transition-colors"><XCircle size={20}/></button>
                      </div>
                  ) : (
                      <label className="flex flex-col items-center justify-center gap-3 w-full h-32 border-2 border-dashed border-gray-300 rounded-xl bg-gray-50 text-gray-500 cursor-pointer hover:bg-gray-100 hover:border-blue-400 transition-all group">
                          <div className="p-3 bg-white rounded-full shadow-sm group-hover:scale-110 transition-transform">
                              <UploadCloud size={24} className="text-blue-500" />
                          </div>
                          <span className="text-sm font-medium">اضغط هنا لرفع ملف التقرير</span>
                          <input type="file" accept="application/pdf" className="hidden" onChange={handleFileUpload} />
                      </label>
                  )}
                  <p className="text-xs text-gray-400 mt-2">يجب أن يكون الملف بصيغة PDF وموقعاً من مكتب التدقيق المعتمد.</p>
              </div>

              {/* Right Column: Declaration */}
              <div className="bg-amber-50 rounded-xl p-5 border border-amber-100 flex flex-col justify-center">
                  <h4 className="font-bold text-amber-900 mb-3 flex items-center gap-2">
                      <ShieldCheck size={18}/> إقرار صحة البيانات
                  </h4>
                  <p className="text-sm text-amber-800 mb-4 leading-relaxed opacity-90">
                      بصفتي مخولاً عن المؤسسة الوقفية، أقر بأن جميع البيانات المالية المدخلة أعلاه صحيحة ومطابقة تماماً لتقرير المدقق المالي المرفق، وأتحمل المسؤولية القانونية في حال ثبوت خلاف ذلك.
                  </p>
                  <label className="flex items-center gap-3 cursor-pointer bg-white p-3 rounded-lg border border-amber-200 shadow-sm hover:border-amber-400 transition-colors">
                      <input type="checkbox" className="w-5 h-5 text-navy-900 rounded focus:ring-navy-900" 
                          checked={isConfirmed} onChange={(e) => setIsConfirmed(e.target.checked)} />
                      <span className="text-sm font-bold text-navy-900">
                          نعم، أقر بصحة البيانات ومطابقتها.
                      </span>
                  </label>
              </div>
          </div>
      </div>

      {/* Action Bar */}
      <div className="flex justify-end pt-4 border-t border-gray-200">
          <button 
              disabled={loading || !isConfirmed}
              onClick={handleSubmit}
              className={`flex items-center gap-2 px-8 py-3 rounded-xl font-bold text-white shadow-lg transition-transform active:scale-95 ${loading || !isConfirmed ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900'}`}
          >
              <Save size={20} /> {loading ? 'جاري الحفظ...' : 'حفظ وإرسال البيانات المالية'}
          </button>
      </div>

    </div>
  );
};

export default FinancialReports;

import React, { useState, useEffect } from 'react';
import { useUi } from '../contexts/UiContext';
import { getInstitutions, saveFinancialRecord, getFinancialRecords, analyzeFinancialHealth, generateId } from '../services/db';
import { FinancialRecord, InstitutionDocument } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    TrendingUp, TrendingDown, UploadCloud, Save, AlertTriangle, 
    FileText, CheckCircle2, XCircle, Landmark, Briefcase, Scale,
    Banknote, ArrowRightLeft, Paperclip, ShieldCheck
} from 'lucide-react';

const FinancialReports: React.FC = () => {
  const { currentWaqfId, showToast } = useUi();
  const [loading, setLoading] = useState(false);
  const [institutions, setInstitutions] = useState<any[]>([]);

  // Form State
  const [record, setRecord] = useState<Partial<FinancialRecord>>({
      fiscal_year: CURRENT_YEAR - 1,
      auditor_name: '',
      total_assets: 0,
      total_liabilities: 0,
      net_waqf_assets: 0,
      total_revenues: 0,
      total_expenses: 0,
      admin_general_expenses: 0,
      surplus_deficit: 0,
      operating_cash_flow: 0,
      investing_cash_flow: 0,
      financing_cash_flow: 0,
      cash_end_period: 0
  });

  const [pdfFile, setPdfFile] = useState<InstitutionDocument | null>(null);
  const [isConfirmed, setIsConfirmed] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<{isValid: boolean, status: string, flags: string[], errors: string[]} | null>(null);

  useEffect(() => {
      setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
      if (currentWaqfId) {
          const records = getFinancialRecords(currentWaqfId);
          const existing = records.find(r => r.fiscal_year === record.fiscal_year);
          if (existing) {
              setRecord(existing);
              setPdfFile(existing.audit_report_pdf || null);
              setAnalysisResult(analyzeFinancialHealth(existing));
          } else {
              setRecord({
                  fiscal_year: record.fiscal_year,
                  auditor_name: '',
                  total_assets: 0,
                  total_liabilities: 0,
                  net_waqf_assets: 0,
                  total_revenues: 0,
                  total_expenses: 0,
                  admin_general_expenses: 0,
                  surplus_deficit: 0,
                  operating_cash_flow: 0,
                  investing_cash_flow: 0,
                  financing_cash_flow: 0,
                  cash_end_period: 0
              });
              setPdfFile(null);
              setAnalysisResult(null);
              setIsConfirmed(false);
          }
      }
  }, [currentWaqfId, record.fiscal_year]);

  // Auto-calculate Surplus/Deficit
  useEffect(() => {
      const revenue = Number(record.total_revenues) || 0;
      const expenses = Number(record.total_expenses) || 0;
      const computedSurplus = revenue - expenses;

      if (computedSurplus !== record.surplus_deficit) {
          setRecord(prev => ({ ...prev, surplus_deficit: computedSurplus }));
      }
  }, [record.total_revenues, record.total_expenses]);

  // Sync Operating Cash Flow with Surplus (Logical Default)
  useEffect(() => {
      // We set operating cash flow to match surplus by default as a starting point
      const surplus = Number(record.surplus_deficit) || 0;
      setRecord(prev => ({ ...prev, operating_cash_flow: surplus }));
  }, [record.surplus_deficit]);

  // Auto-calculate Net Assets (Assets - Liabilities)
  useEffect(() => {
      const assets = Number(record.total_assets) || 0;
      const liabilities = Number(record.total_liabilities) || 0;
      const computedNet = assets - liabilities;

      if (computedNet !== record.net_waqf_assets) {
          setRecord(prev => ({ ...prev, net_waqf_assets: computedNet }));
      }
  }, [record.total_assets, record.total_liabilities]);

  // Auto-calculate Cash End of Period (Sum of Flows)
  useEffect(() => {
      const op = Number(record.operating_cash_flow) || 0;
      const inv = Number(record.investing_cash_flow) || 0;
      const fin = Number(record.financing_cash_flow) || 0;
      const totalCash = op + inv + fin;

      if (totalCash !== record.cash_end_period) {
          setRecord(prev => ({ ...prev, cash_end_period: totalCash }));
      }
  }, [record.operating_cash_flow, record.investing_cash_flow, record.financing_cash_flow]);

  const handleInputChange = (field: keyof FinancialRecord, value: any) => {
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setPdfFile(newDoc);
          showToast('تم إرفاق التقرير المالي', 'success');
      }
  };

  const handleSubmit = () => {
      if (!currentWaqfId) return;
      if (!isConfirmed) {
          showToast('يرجى الإقرار بصحة البيانات قبل الحفظ', 'error');
          return;
      }

      setLoading(true);

      const fullRecord: FinancialRecord = {
          ...record as FinancialRecord,
          id: record.id || generateId(),
          institution_id: currentWaqfId,
          audit_report_pdf: pdfFile || undefined,
          submission_date: new Date().toISOString(),
          status: 'Submitted',
          flags: []
      };

      const analysis = analyzeFinancialHealth(fullRecord);
      fullRecord.status = analysis.status as any;
      fullRecord.flags = analysis.flags;

      saveFinancialRecord(fullRecord);
      setAnalysisResult(analysis);
      setLoading(false);

      showToast('تم حفظ البيانات المالية بنجاح', 'success');
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  if (!currentWaqfId) return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10">
          <div className="bg-blue-50 p-6 rounded-full mb-6 text-blue-600"><Landmark size={48} /></div>
          <h2 className="text-2xl font-bold text-navy-900 mb-2">التقارير المالية</h2>
          <p className="text-gray-500">يرجى اختيار مؤسسة من القائمة العلوية لإدخال البيانات المالية</p>
      </div>
  );

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20 animate-fadeIn">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-gray-200 pb-6">
          <div>
              <h2 className="text-2xl font-bold text-navy-900 flex items-center gap-2">
                  <Landmark className="text-teal-600"/> القوائم المالية والحوكمة
              </h2>
              <p className="text-gray-500 mt-1">إدخال البيانات المالية لـ: <span className="font-bold text-navy-800">{currentInstitutionName}</span></p>
          </div>
          <div className="flex gap-4">
              <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">السنة المالية</label>
                  <select 
                    className="border border-gray-300 rounded-lg p-2 bg-white text-navy-900 font-bold outline-none focus:ring-2 focus:ring-teal-500"
                    value={record.fiscal_year}
                    onChange={(e) => handleInputChange('fiscal_year', Number(e.target.value))}
                  >
                      {Array.from({length: 5}, (_, i) => CURRENT_YEAR - i).map(y => (
                          <option key={y} value={y}>{y}</option>
                      ))}
                  </select>
              </div>
              <div className="min-w-[200px]">
                  <label className="block text-xs font-bold text-gray-500 mb-1">مكتب التدقيق الخارجي</label>
                  <input 
                    type="text" 
                    placeholder="اسم المكتب / المدقق"
                    className="w-full border border-gray-300 rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-teal-500"
                    value={record.auditor_name}
                    onChange={(e) => handleInputChange('auditor_name', e.target.value)}
                  />
              </div>
          </div>
      </div>

      {/* Analysis Feedback Area */}
      {analysisResult && (
          <div className={`p-4 rounded-xl border-l-4 shadow-sm animate-scaleIn ${analysisResult.status === 'Flagged' || !analysisResult.isValid ? 'bg-red-50 border-red-500' : 'bg-green-50 border-green-500'}`}>
              <div className="flex items-start gap-3">
                  {analysisResult.isValid && analysisResult.status === 'Submitted' ? (
                      <CheckCircle2 className="text-green-600 mt-1" />
                  ) : (
                      <AlertTriangle className="text-red-600 mt-1" />
                  )}
                  <div>
                      <h4 className={`font-bold ${analysisResult.status === 'Flagged' ? 'text-red-800' : 'text-green-800'}`}>
                          {analysisResult.status === 'Flagged' ? 'تم رصد ملاحظات حوكمة' : (!analysisResult.isValid ? 'خطأ في البيانات' : 'البيانات سليمة')}
                      </h4>
                      <ul className="mt-2 space-y-1 text-sm list-disc list-inside">
                          {analysisResult.errors.map((err, i) => <li key={`e-${i}`} className="text-red-700 font-bold">{err}</li>)}
                          {analysisResult.flags.map((flag, i) => <li key={`f-${i}`} className="text-red-600">{flag}</li>)}
                          {analysisResult.isValid && analysisResult.flags.length === 0 && (
                              <li className="text-green-700">المعادلة المحاسبية متزنة والمصروفات الإدارية في الحدود المسموحة.</li>
                          )}
                      </ul>
                  </div>
              </div>
          </div>
      )}

      {/* Main Form Grid (4 Cards) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

          {/* Card A: Financial Position */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-blue-900 to-navy-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Briefcase size={18}/> المركز المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الأصول</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none" 
                          value={record.total_assets || ''} onChange={(e) => handleInputChange('total_assets', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الالتزامات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none" 
                          value={record.total_liabilities || ''} onChange={(e) => handleInputChange('total_liabilities', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">صافي الأصول (المال الوقفي)</label>
                      <input 
                        type="number" 
                        readOnly
                        className="w-full p-2 border border-gray-300 rounded-lg font-bold bg-gray-100 text-navy-900 outline-none"
                        value={record.net_waqf_assets || 0} 
                      />
                      <p className="text-[10px] text-gray-400 mt-1">يتم الاحتساب تلقائياً: (الأصول - الالتزامات)</p>
                  </div>
              </div>
          </div>

          {/* Card B: Performance */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-teal-700 to-teal-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><TrendingUp size={18}/> الأداء المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الإيرادات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none" 
                          value={record.total_revenues || ''} onChange={(e) => handleInputChange('total_revenues', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي المصروفات</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none" 
                          value={record.total_expenses || ''} onChange={(e) => handleInputChange('total_expenses', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">الفائض / العجز</label>
                      <input disabled type="text" className={`w-full p-2 border rounded-lg font-bold bg-gray-100 ${(record.surplus_deficit || 0) < 0 ? 'text-red-600' : 'text-green-600'}`} 
                          value={record.surplus_deficit?.toLocaleString() || '0'} />
                  </div>
              </div>
          </div>

          {/* Card C: Cash Flows */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-orange-700 to-red-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><ArrowRightLeft size={18}/> التدفقات النقدية</h3>
                  <span className="text-xs bg-white/20 px-2 py-1 rounded">السيولة</span>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">صافي النقد التشغيلي</label>
                      <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none" 
                          value={record.operating_cash_flow || ''} onChange={(e) => handleInputChange('operating_cash_flow', Number(e.target.value))} />
                      <p className="text-[9px] text-gray-400 mt-0.5">يُقترح مطابقته للفائض (قابل للتعديل)</p>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                      <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1">الاستثماري</label>
                        <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none" 
                            value={record.investing_cash_flow || ''} onChange={(e) => handleInputChange('investing_cash_flow', Number(e.target.value))} />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1">التمويلي</label>
                        <input type="number" className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none" 
                            value={record.financing_cash_flow || ''} onChange={(e) => handleInputChange('financing_cash_flow', Number(e.target.value))} />
                      </div>
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1 flex items-center gap-1"><Banknote size={14}/> صافي النقد (نهاية السنة)</label>
                      <input type="number" readOnly className="w-full p-2 border border-gray-300 rounded-lg font-bold bg-gray-100 text-orange-900 outline-none"
                          value={record.cash_end_period || 0} />
                      <p className="text-[10px] text-gray-400 mt-1">يتم الاحتساب تلقائياً: (تشغيلي + استثماري + تمويلي)</p>
                  </div>
              </div>
          </div>

          {/* Card D: Governance (Simplified) */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-purple-800 to-indigo-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Scale size={18}/> الحوكمة المالية</h3>
              </div>
              <div className="p-4 space-y-4 h-full">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">المصروفات الإدارية</label>
                      <input type="number" className="w-full p-2 border border-gray-200 rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-purple-500 outline-none" 
                          value={record.admin_general_expenses || ''} onChange={(e) => handleInputChange('admin_general_expenses', Number(e.target.value))} />

                      {(record.total_expenses || 0) > 0 && (
                          <div className={`mt-2 p-2 rounded text-xs font-bold text-center ${((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100) > 20 ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-green-50 text-green-600 border border-green-200'}`}>
                              نسبة الإدارية: {((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100).toFixed(1)}% <br/>
                              (الحد الأقصى المسموح 20%)
                          </div>
                      )}
                  </div>

                  {/* Placeholder for visual balance */}
                  <div className="pt-2 border-t border-gray-100 text-center text-gray-400 text-xs">
                      <ShieldCheck size={48} className="mx-auto mb-2 opacity-20" />
                      <p>مؤشر الالتزام بضوابط الصرف</p>
                  </div>
              </div>
          </div>
      </div>

      {/* NEW: Attachments & Declaration Section (Full Width) */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="bg-gray-50 p-4 border-b border-gray-200 flex items-center gap-2">
              <Paperclip size={20} className="text-navy-900"/>
              <h3 className="font-bold text-navy-900">المرفقات والإقرار</h3>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Left Column: Upload */}
              <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">إرفاق تقرير المدقق المالي (PDF)</label>
                  {pdfFile ? (
                      <div className="flex items-center justify-between bg-blue-50 p-4 rounded-xl border border-blue-200 text-blue-900">
                          <div className="flex items-center gap-3">
                              <div className="bg-white p-2 rounded-lg text-red-500 shadow-sm"><FileText size={24}/></div>
                              <div>
                                  <span className="text-sm font-bold block">{pdfFile.name}</span>
                                  <span className="text-xs opacity-70">{pdfFile.size} - تم الرفع</span>
                              </div>
                          </div>
                          <button onClick={() => setPdfFile(null)} className="text-red-500 hover:bg-red-100 p-2 rounded-full transition-colors"><XCircle size={20}/></button>
                      </div>
                  ) : (
                      <label className="flex flex-col items-center justify-center gap-3 w-full h-32 border-2 border-dashed border-gray-300 rounded-xl bg-gray-50 text-gray-500 cursor-pointer hover:bg-gray-100 hover:border-blue-400 transition-all group">
                          <div className="p-3 bg-white rounded-full shadow-sm group-hover:scale-110 transition-transform">
                              <UploadCloud size={24} className="text-blue-500" />
                          </div>
                          <span className="text-sm font-medium">اضغط هنا لرفع ملف التقرير</span>
                          <input type="file" accept="application/pdf" className="hidden" onChange={handleFileUpload} />
                      </label>
                  )}
                  <p className="text-xs text-gray-400 mt-2">يجب أن يكون الملف بصيغة PDF وموقعاً من مكتب التدقيق المعتمد.</p>
              </div>

              {/* Right Column: Declaration */}
              <div className="bg-amber-50 rounded-xl p-5 border border-amber-100 flex flex-col justify-center">
                  <h4 className="font-bold text-amber-900 mb-3 flex items-center gap-2">
                      <ShieldCheck size={18}/> إقرار صحة البيانات
                  </h4>
                  <p className="text-sm text-amber-800 mb-4 leading-relaxed opacity-90">
                      بصفتي مخولاً عن المؤسسة الوقفية، أقر بأن جميع البيانات المالية المدخلة أعلاه صحيحة ومطابقة تماماً لتقرير المدقق المالي المرفق، وأتحمل المسؤولية القانونية في حال ثبوت خلاف ذلك.
                  </p>
                  <label className="flex items-center gap-3 cursor-pointer bg-white p-3 rounded-lg border border-amber-200 shadow-sm hover:border-amber-400 transition-colors">
                      <input type="checkbox" className="w-5 h-5 text-navy-900 rounded focus:ring-navy-900" 
                          checked={isConfirmed} onChange={(e) => setIsConfirmed(e.target.checked)} />
                      <span className="text-sm font-bold text-navy-900">
                          نعم، أقر بصحة البيانات ومطابقتها.
                      </span>
                  </label>
              </div>
          </div>
      </div>

      {/* Action Bar */}
      <div className="flex justify-end pt-4 border-t border-gray-200">
          <button 
              disabled={loading || !isConfirmed}
              onClick={handleSubmit}
              className={`flex items-center gap-2 px-8 py-3 rounded-xl font-bold text-white shadow-lg transition-transform active:scale-95 ${loading || !isConfirmed ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900'}`}
          >
              <Save size={20} /> {loading ? 'جاري الحفظ...' : 'حفظ وإرسال البيانات المالية'}
          </button>
      </div>

    </div>
  );
};

export default FinancialReports;

import React, { useState, useEffect, useCallback } from 'react';
import { 
    getInstitutions, getEvaluations, getResponses, getIndicators, 
    getImprovements, saveImprovement, deleteImprovement, 
    getRisks, getComplianceByInstAndYear, generateId 
} from '../services/db';
import { Institution, ImprovementItem, InstitutionDocument } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    Clock, CheckCircle, AlertTriangle, Building, 
    ArrowRight, ArrowLeft, Trash2, Layout, Activity, ShieldAlert, Scale,
    Save, Download, RefreshCw, Paperclip, FileText, X, GripVertical
} from 'lucide-react';
import { useUi } from '../contexts/UiContext';

// Declare html2pdf for TypeScript
declare const html2pdf: any;

type ColumnType = 'ToDo' | 'Doing' | 'Done';

const Improvements: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { currentWaqfId, showToast } = useUi();
  const [institutionName, setInstitutionName] = useState('');

  // Drag and Drop State
  const [draggedItem, setDraggedItem] = useState<ImprovementItem | null>(null);

  // Kanban State
  const [columns, setColumns] = useState<{ [key in ColumnType]: ImprovementItem[] }>({
      ToDo: [],
      Doing: [],
      Done: []
  });

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  const loadImprovements = useCallback(() => {
      if (!currentWaqfId) {
          setColumns({ ToDo: [], Doing: [], Done: [] });
          return [];
      }

      const ev = getEvaluations().find(e => e.institution_id === currentWaqfId && e.cycle_year === CURRENT_YEAR);
      const evalId = ev?.id || `TEMP_EVAL_${currentWaqfId}`;
      const items = getImprovements(evalId);

      setColumns({
          ToDo: items.filter(i => i.status === 'ToDo'),
          Doing: items.filter(i => i.status === 'Doing'),
          Done: items.filter(i => i.status === 'Done'),
      });

      return items;
  }, [currentWaqfId]);

  // Sync Logic
  const syncWithSources = useCallback((manual = false) => {
    if (!currentWaqfId) return;

    const inst = getInstitutions().find(i => i.id === currentWaqfId);
    setInstitutionName(inst?.name || '');

    const ev = getEvaluations().find(e => e.institution_id === currentWaqfId && e.cycle_year === CURRENT_YEAR);
    const evalId = ev?.id || `TEMP_EVAL_${currentWaqfId}`;

    // Get currently existing items to prevent duplicates
    const existingItems = getImprovements(evalId);
    const newItems: ImprovementItem[] = [];
    const indicators = getIndicators();

    // Helper: Check if item exists based on Source ID
    const exists = (sourceId: string) => existingItems.some(i => i.indicator_id === sourceId) || newItems.some(i => i.indicator_id === sourceId);

    // 1. Source: Performance Weaknesses (Score < 3)
    if (ev) {
        const responses = getResponses(ev.id);
        responses.filter(r => r.score < 3).forEach(r => {
            const compositeId = `PERF-${r.indicator_id}`; // Stable ID linking to source
            if (!exists(compositeId)) {
                // Find index to show "Indicator Number X"
                const indIndex = indicators.findIndex(i => i.id === r.indicator_id);
                const ind = indicators[indIndex];

                if (ind) {
                    const globalIndNum = indIndex + 1; // 1-based index
                    newItems.push({
                        id: generateId(),
                        evaluation_id: evalId,
                        indicator_id: compositeId,
                        priority: 'Medium',
                        issue_summary: `ضعف الأداء: ${ind.text.substring(0, 50)}...`,
                        recommended_action: `مرتبط بمؤشر رقم ${globalIndNum}`,
                        owner: 'مدير العمليات',
                        due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                        status: 'ToDo',
                        notes: `الدرجة الحالية: ${r.score}`
                    });
                }
            }
        });
    }

    // 2. Source: High Risks (Score >= 15)
    const risks = getRisks(currentWaqfId);
    risks.filter(r => (r.probability * r.impact) >= 15).forEach(r => {
        const compositeId = `RISK-${r.id}`;
        if (!exists(compositeId)) {
            newItems.push({
                id: generateId(),
                evaluation_id: evalId,
                indicator_id: compositeId,
                priority: 'High',
                issue_summary: `خطر حرج: ${r.risk_title}`,
                recommended_action: r.mitigation_plan || 'تفعيل خطة طوارئ عاجلة.',
                owner: 'لجنة المخاطر',
                due_date: new Date(new Date().setDate(new Date().getDate() + 14)).toISOString().split('T')[0],
                status: 'ToDo',
                notes: `شدة الخطر: ${r.probability * r.impact}`
            });
        }
    });

    // 3. Source: Compliance Gaps
    const comp = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
    if (comp) {
        const gaps: {key: string, label: string}[] = [];
        if (comp.institution_status !== 'فاعلة') gaps.push({key: 'status', label: 'حالة المؤسسة غير فاعلة'});
        if (comp.board_status !== 'قائم') gaps.push({key: 'board', label: 'مجلس الإدارة غير قائم'});

        // Check Core Requirements (skip hidden ones)
        if (!comp.has_executive_management && !comp.hidden_core_requirements?.includes('has_executive_management')) 
            gaps.push({key: 'exec', label: 'غياب الإدارة التنفيذية'});

        if (!comp.has_auditor_company && !comp.hidden_core_requirements?.includes('has_auditor_company')) 
            gaps.push({key: 'audit', label: 'لم يتم تعيين مدقق خارجي'});

        if (!comp.has_minutes_prev_year && !comp.hidden_core_requirements?.includes('has_minutes_prev_year')) 
            gaps.push({key: 'minutes', label: 'نقص محاضر الاجتماعات'});

        if (!comp.has_financial_report_prev_year && !comp.hidden_core_requirements?.includes('has_financial_report_prev_year')) 
            gaps.push({key: 'finance', label: 'غياب التقرير المالي'});

        // Check Custom Requirements
        comp.custom_requirements?.forEach(req => {
            if (!req.met) {
                gaps.push({key: `custom_${req.id}`, label: `متطلب إضافي: ${req.text}`});
            }
        });

        gaps.forEach(gap => {
            const compositeId = `COMP-${gap.key}`;
            if (!exists(compositeId)) {
                newItems.push({
                    id: generateId(),
                    evaluation_id: evalId,
                    indicator_id: compositeId,
                    priority: 'High',
                    issue_summary: `قصور امتثال: ${gap.label}`,
                    recommended_action: 'استيفاء المتطلب النظامي فوراً.',
                    owner: 'أمين السر / المدير',
                    due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                    status: 'ToDo',
                    notes: 'مطلب قانوني إلزامي'
                });
            }
        });
    }

    if (newItems.length > 0) {
        newItems.forEach(saveImprovement);
        loadImprovements(); // Refresh UI
        showToast(manual ? `تم استيراد ${newItems.length} مهام جديدة` : `تم إنشاء ${newItems.length} مهام تلقائياً`, 'success');
    } else if (manual) {
        showToast('جميع المهام محدثة، لا يوجد عناصر جديدة للاستيراد', 'info');
    }
  }, [currentWaqfId, loadImprovements, showToast]);

  // Initial Load & Auto-Sync if empty
  useEffect(() => {
    if (currentWaqfId) {
        const items = loadImprovements();
        // Only auto-sync if list is completely empty
        if (items.length === 0) {
            syncWithSources(false);
        }
    }
  }, [currentWaqfId, loadImprovements, syncWithSources]);

  // --- Drag and Drop Handlers ---
  const handleDragStart = (e: React.DragEvent, item: ImprovementItem) => {
      setDraggedItem(item);
      // Optional: Set drag image or data
      e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); // Necessary to allow dropping
  };

  const handleDrop = (e: React.DragEvent, targetStatus: ColumnType) => {
      e.preventDefault();

      if (!draggedItem || draggedItem.status === targetStatus) {
          setDraggedItem(null);
          return;
      }

      // Update Item logic similar to moveItem
      const updatedItem = { ...draggedItem, status: targetStatus };
      saveImprovement(updatedItem); // Persist

      // Optimistic UI Update
      setColumns(prev => {
          // Remove from old column (using the status from draggedItem before update)
          const sourceList = prev[draggedItem.status as ColumnType].filter(i => i.id !== draggedItem.id);
          // Add to new column
          const targetList = [updatedItem, ...prev[targetStatus]];
          return { ...prev, [draggedItem.status as ColumnType]: sourceList, [targetStatus]: targetList };
      });

      setDraggedItem(null);
  };

  // Actions
  const moveItem = (item: ImprovementItem, direction: 'forward' | 'backward') => {
      let newStatus: ColumnType = item.status;

      if (direction === 'forward') {
          if (item.status === 'ToDo') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'Done';
      } else {
          if (item.status === 'Done') newStatus = 'Doing';
          else if (item.status === 'Doing') newStatus = 'ToDo';
      }

      if (newStatus !== item.status) {
          const updatedItem = { ...item, status: newStatus };
          saveImprovement(updatedItem); // Persist

          // Optimistic UI Update
          setColumns(prev => {
              const sourceList = prev[item.status].filter(i => i.id !== item.id);
              const targetList = [updatedItem, ...prev[newStatus]];
              return { ...prev, [item.status as ColumnType]: sourceList, [newStatus]: targetList };
          });
      }
  };

  const handleDelete = (id: string, status: ColumnType) => {
      if(confirm('هل أنت متأكد من حذف هذه المهمة؟')) {
          deleteImprovement(id);
          setColumns(prev => ({
              ...prev,
              [status]: prev[status].filter(i => i.id !== id)
          }));
          showToast('تم حذف المهمة', 'info');
      }
  };

  // Attach Evidence Logic
  const handleAttachEvidence = (item: ImprovementItem, file: File) => {
      const newDoc: InstitutionDocument = {
          id: generateId(),
          name: file.name,
          type: file.type,
          size: (file.size / 1024).toFixed(1) + ' KB',
          upload_date: new Date().toLocaleDateString('ar-OM')
      };

      const updatedItem = { ...item, evidence_doc: newDoc };
      saveImprovement(updatedItem);

      // Update UI
      setColumns(prev => ({
          ...prev,
          Done: prev.Done.map(i => i.id === item.id ? updatedItem : i)
      }));

      showToast('تم إرفاق دليل الإنجاز بنجاح', 'success');
  };

  const handleRemoveEvidence = (item: ImprovementItem) => {
      if(confirm('هل أنت متأكد من حذف دليل الإنجاز؟')) {
          const updatedItem = { ...item, evidence_doc: undefined };
          saveImprovement(updatedItem);

          setColumns(prev => ({
              ...prev,
              Done: prev.Done.map(i => i.id === item.id ? updatedItem : i)
          }));
          showToast('تم حذف الدليل', 'info');
      }
  };

  const handleManualSave = () => {
      // Re-save all items (redundant but gives user peace of mind)
      const allItems = [...columns.ToDo, ...columns.Doing, ...columns.Done];
      if (allItems.length > 0) {
          allItems.forEach(saveImprovement);
          showToast('تم حفظ كافة التغييرات بنجاح', 'success');
      } else {
          showToast('لا توجد مهام للحفظ', 'info');
      }
  };

  const handleDownloadPDF = () => {
      const element = document.getElementById('kanban-board');
      if (!element) return;

      const opt = {
        margin:       5,
        filename:     `Improvement-Plan-${institutionName}.pdf`,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2, useCORS: true },
        jsPDF:        { unit: 'mm', format: 'a4', orientation: 'landscape' } // Landscape for Kanban
      };

      html2pdf().from(element).set(opt).save();
  };

  const getSourceBadge = (indicatorId: string) => {
      if (indicatorId.startsWith('RISK-')) return { label: 'مخاطر', color: 'bg-red-100 text-red-800', icon: ShieldAlert };
      if (indicatorId.startsWith('COMP-')) return { label: 'امتثال', color: 'bg-purple-100 text-purple-800', icon: Scale };
      if (indicatorId.startsWith('PERF-')) return { label: 'أداء', color: 'bg-orange-100 text-orange-800', icon: Activity };
      return { label: 'يدوي', color: 'bg-gray-100 text-gray-800', icon: Activity };
  };

  return (
    <div className="space-y-6 min-h-screen">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-navy-900 dark:text-white flex items-center gap-2">
            <Layout className="text-teal-600"/> لوحة متابعة التحسين
        </h2>
        {currentWaqfId && (
            <div className="flex gap-2">
                <button 
                    onClick={() => syncWithSources(true)} 
                    className="bg-white border border-teal-600 text-teal-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-50 shadow-sm transition-all duration-300 hover:scale-105 active:scale-95 font-bold text-sm"
                    title="سحب المهام الجديدة من التقييم والمخاطر والامتثال"
                >
                    <RefreshCw size={18} /> تحديث من المصادر
                </button>
                <button 
                    onClick={handleManualSave} 
                    className="bg-teal-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-md transition-all duration-300 hover:scale-105 active:scale-95 font-bold text-sm"
                >
                    <Save size={18} /> حفظ
                </button>
                <button 
                    onClick={handleDownloadPDF} 
                    className="bg-navy-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-navy-900 shadow-md transition-all duration-300 hover:scale-105 active:scale-95 font-bold text-sm"
                >
                    <Download size={18} /> تصدير PDF
                </button>
            </div>
        )}
      </div>

       {/* Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn no-print mb-8 hover:shadow-md transition-shadow">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">خطة المؤسسة:</div>
                      <div className="text-lg font-bold">{institutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center no-print">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى اختيار مؤسسة لعرض مهام التحسين الخاصة بها.</p>
          </div>
      )}

      {currentWaqfId && (
        <div id="kanban-board" className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full items-start overflow-x-auto pb-10 bg-white/50 p-4 rounded-xl">
            {/* Column 1: To Do */}
            <KanbanColumn 
                title="مهام جديدة" 
                count={columns.ToDo.length} 
                color="border-red-400 bg-red-50 dark:bg-red-900/10"
                icon={<AlertTriangle size={18} className="text-red-600"/>}
                status="ToDo"
                onDrop={handleDrop}
                onDragOver={handleDragOver}
            >
                {columns.ToDo.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'ToDo')}
                        onDragStart={handleDragStart}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 2: Doing */}
            <KanbanColumn 
                title="جاري المعالجة" 
                count={columns.Doing.length} 
                color="border-yellow-400 bg-yellow-50 dark:bg-yellow-900/10"
                icon={<Clock size={18} className="text-yellow-600"/>}
                status="Doing"
                onDrop={handleDrop}
                onDragOver={handleDragOver}
            >
                {columns.Doing.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onMoveForward={() => moveItem(item, 'forward')}
                        onDelete={() => handleDelete(item.id, 'Doing')}
                        onDragStart={handleDragStart}
                        badge={getSourceBadge(item.indicator_id)}
                    />
                ))}
            </KanbanColumn>

            {/* Column 3: Done */}
            <KanbanColumn 
                title="تم الإنجاز" 
                count={columns.Done.length} 
                color="border-green-400 bg-green-50 dark:bg-green-900/10"
                icon={<CheckCircle size={18} className="text-green-600"/>}
                status="Done"
                onDrop={handleDrop}
                onDragOver={handleDragOver}
            >
                {columns.Done.map(item => (
                    <KanbanCard 
                        key={item.id} 
                        item={item} 
                        onMoveBack={() => moveItem(item, 'backward')}
                        onDelete={() => handleDelete(item.id, 'Done')}
                        onAttachEvidence={handleAttachEvidence}
                        onRemoveEvidence={handleRemoveEvidence}
                        onDragStart={handleDragStart}
                        badge={getSourceBadge(item.indicator_id)}
                        isDone
                    />
                ))}
            </KanbanColumn>
        </div>
      )}
    </div>
  );
};

// --- Sub Components ---

const KanbanColumn = ({ title, count, children, color, icon, onDrop, onDragOver, status }: any) => (
    <div 
        className={`flex flex-col h-full min-h-[500px] rounded-xl border-t-4 ${color} bg-gray-50/50 dark:bg-gray-800 shadow-sm transition-all hover:shadow-md`}
        onDragOver={onDragOver}
        onDrop={(e) => onDrop(e, status)}
    >
        <div className="p-4 flex justify-between items-center border-b border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-xl">
            <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">{icon} {title}</h3>
            <span className="bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 text-xs px-2 py-1 rounded-full font-bold">{count}</span>
        </div>
        <div className="p-3 space-y-3 flex-1 transition-colors hover:bg-opacity-50 hover:bg-gray-100/50">
            {children}
            {count === 0 && <div className="text-center py-10 text-gray-400 text-sm italic border-2 border-dashed border-gray-200 rounded-lg m-2">اسحب المهام هنا</div>}
        </div>
    </div>
);

const KanbanCard = ({ item, onMoveBack, onMoveForward, onDelete, onAttachEvidence, onRemoveEvidence, onDragStart, badge, isDone }: any) => {
    const Icon = badge.icon;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0] && onAttachEvidence) {
            onAttachEvidence(item, e.target.files[0]);
        }
    };

    return (
        <div 
            draggable={true}
            onDragStart={(e) => onDragStart(e, item)}
            className={`bg-white dark:bg-gray-700 p-4 rounded-lg shadow-sm border border-gray-100 dark:border-gray-600 transition-all duration-300 hover:shadow-lg hover:-translate-y-1 hover:scale-[1.02] relative group cursor-grab active:cursor-grabbing ${isDone ? 'opacity-90 hover:opacity-100' : ''}`}
        >
            {/* Delete Button (Hidden until hover) */}
            <button 
                onClick={onDelete}
                className="absolute top-2 left-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity no-print hover:scale-110"
            >
                <Trash2 size={16} />
            </button>

            {/* Badge & Drag Handle */}
            <div className="flex justify-between items-start mb-2">
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1 ${badge.color}`}>
                    <Icon size={12} /> {badge.label}
                </span>
                <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-2 py-0.5 rounded border ${item.priority === 'High' ? 'text-red-600 border-red-200 bg-red-50' : 'text-gray-500 border-gray-200'}`}>
                        {item.priority === 'High' ? 'أولوية قصوى' : 'عادية'}
                    </span>
                    {/* Visual Grip Handle */}
                    <GripVertical size={14} className="text-gray-300 cursor-grab active:cursor-grabbing" />
                </div>
            </div>

            {/* Content */}
            <h4 className={`font-bold text-sm text-navy-900 dark:text-white mb-2 ${isDone ? 'text-gray-500 line-through decoration-2 decoration-gray-400' : ''}`}>
                {item.issue_summary}
            </h4>
            <p className={`text-xs text-gray-500 dark:text-gray-300 mb-3 leading-relaxed bg-gray-50 dark:bg-gray-800 p-2 rounded ${isDone ? 'line-through opacity-75' : ''}`}>
                {item.recommended_action}
            </p>

            <div className="flex justify-between items-center text-xs text-gray-400 border-t border-gray-100 dark:border-gray-600 pt-2 mb-3">
                <span>{item.owner}</span>
                <span>{item.due_date}</span>
            </div>

            {/* Evidence Attachment (Only for Done items) */}
            {isDone && (
                <div className="mb-3">
                    {item.evidence_doc ? (
                        <div className="flex justify-between items-center bg-green-50 border border-green-100 p-2 rounded-lg text-xs text-green-800">
                            <span className="flex items-center gap-1 truncate font-medium">
                                <FileText size={12}/> {item.evidence_doc.name}
                            </span>
                            <button 
                                onClick={() => onRemoveEvidence(item)} 
                                className="text-gray-400 hover:text-red-500 transition-transform hover:scale-110"
                                title="حذف الدليل"
                            >
                                <X size={12}/>
                            </button>
                        </div>
                    ) : (
                        <label className="cursor-pointer border border-dashed border-blue-300 bg-blue-50 hover:bg-blue-100 text-blue-700 p-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all hover:scale-105 active:scale-95">
                            <Paperclip size={14} /> إرفاق دليل الإنجاز
                            <input type="file" className="hidden" onChange={handleFileChange} />
                        </label>
                    )}
                </div>
            )}

            {/* Controls */}
            <div className="flex justify-between items-center gap-2 no-print">
                {onMoveForward ? (
                    <button onClick={onMoveForward} className="flex-1 bg-navy-50 text-navy-800 hover:bg-navy-100 dark:bg-navy-900 dark:text-blue-200 dark:hover:bg-navy-800 py-1.5 rounded text-xs font-bold flex justify-center items-center gap-1 transition-colors hover:shadow-sm">
                        نقل للمرحلة التالية <ArrowLeft size={14} />
                    </button>
                ) : <div className="flex-1"></div>}

                {onMoveBack && (
                     <button onClick={onMoveBack} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-500 transition-colors hover:scale-110" title="عودة للسابق">
                         <ArrowRight size={16} />
                     </button>
                )}
            </div>
        </div>
    );
};

export default Improvements;

import { Institution, Indicator, Evaluation, Response, ComplianceRecord, ImprovementItem, RiskRegisterItem, FinancialRecord } from '../types';
import { DEFAULT_INDICATORS, CURRENT_YEAR, SEEDED_INSTITUTIONS, GOVERNORATES } from '../constants';

// --- Keys ---
const DB_KEYS = {
  INSTITUTIONS: 'waqf_institutions',
  LEGACY_INSTITUTIONS: 'institutions',
  INDICATORS: 'waqf_indicators',
  EVALUATIONS: 'waqf_evaluations',
  RESPONSES: 'waqf_responses',
  COMPLIANCE: 'waqf_compliance',
  IMPROVEMENTS: 'waqf_improvements',
  RISKS: 'waqf_risks',
  FINANCIALS: 'waqf_financials',
  SETTINGS: 'waqf_settings'
};

// --- In-Memory Cache ---
const cache: Record<string, any> = {};

// --- Helper: Generators ---
export const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;
const getRandomItem = <T>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];
const SIMPLE_NAMES = ['محمد', 'علي', 'أحمد', 'سالم', 'خالد', 'سعيد', 'عبدالله', 'ناصر', 'يوسف', 'عمر'];

// --- Helper: Location Logic ---
const inferDetailsByName = (name: string) => {
  const n = name;
  if (n.includes('صحار')) return { gov: 'شمال الباطنة', wil: 'صحار' };
  if (n.includes('نزوى') || n.includes('علاية نزوى') || n.includes('سعال') || n.includes('كرشاء')) return { gov: 'الداخلية', wil: 'نزوى' };
  if (n.includes('صلالة')) return { gov: 'ظفار', wil: 'صلالة' };
  if (n.includes('البريمي')) return { gov: 'البريمي', wil: 'البريمي' };
  if (n.includes('صور')) return { gov: 'جنوب الشرقية', wil: 'صور' };
  if (n.includes('الرستاق')) return { gov: 'جنوب الباطنة', wil: 'الرستاق' };
  if (n.includes('بهلاء')) return { gov: 'الداخلية', wil: 'بهلاء' };
  if (n.includes('عبري')) return { gov: 'الظاهرة', wil: 'عبري' };
  if (n.includes('إبراء')) return { gov: 'شمال الشرقية', wil: 'إبراء' };
  if (n.includes('السيب')) return { gov: 'مسقط', wil: 'السيب' };
  if (n.includes('بوشر')) return { gov: 'مسقط', wil: 'بوشر' };
  if (n.includes('العامرات')) return { gov: 'مسقط', wil: 'العامرات' };
  if (n.includes('سمائل')) return { gov: 'الداخلية', wil: 'سمائل' };
  if (n.includes('المضيبي') || n.includes('سناو')) return { gov: 'شمال الشرقية', wil: 'المضيبي' };
  if (n.includes('السويق')) return { gov: 'شمال الباطنة', wil: 'السويق' };
  if (n.includes('محضة')) return { gov: 'البريمي', wil: 'محضة' };
  if (n.includes('جعلان')) return { gov: 'جنوب الشرقية', wil: 'جعلان بني بو علي' };
  return { gov: 'مسقط', wil: 'بوشر' };
};

// --- Helper: Financial Data Generator ---
const generateDummyFinancials = (instId: string, year: number, type: 'GOOD' | 'AVERAGE' | 'BAD'): FinancialRecord => {
    const baseAssets = getRandomInt(100000, 5000000); 
    const assets = year === 2025 ? Math.floor(baseAssets * 1.05) : baseAssets; 

    const liabilities = Math.floor(assets * (getRandomInt(1, 10) / 100)); 
    const netAssets = assets - liabilities;

    let revenue = 0, expenses = 0, adminExpenses = 0;

    if (type === 'GOOD') {
        revenue = Math.floor(assets * 0.15); 
        expenses = Math.floor(revenue * 0.70); 
        adminExpenses = Math.floor(expenses * 0.10); 
    } else if (type === 'AVERAGE') {
        revenue = Math.floor(assets * 0.08); 
        expenses = Math.floor(revenue * 0.95); 
        adminExpenses = Math.floor(expenses * 0.18); 
    } else { // BAD
        revenue = Math.floor(assets * 0.03); 
        expenses = Math.floor(revenue * 1.5); 
        adminExpenses = Math.floor(expenses * 0.40); 
    }

    return {
        id: generateId(),
        institution_id: instId,
        fiscal_year: year,
        auditor_name: type === 'GOOD' ? 'مكتب ديلويت للتدقيق' : (type === 'BAD' ? 'مكتب المحاسبة العامة' : 'مكتب النزاهة'),
        total_assets: assets,
        total_liabilities: liabilities,
        net_waqf_assets: netAssets,
        total_revenues: revenue,
        total_expenses: expenses,
        admin_general_expenses: adminExpenses,
        surplus_deficit: revenue - expenses,
        // Added realistic cash flow for new dashboard design
        cash_end_period: Math.floor(revenue * 0.2), 
        operating_cash_flow: Math.floor(revenue * 0.25),
        status: type === 'BAD' ? 'Flagged' : 'Submitted',
        flags: [],
        submission_date: new Date().toISOString()
    };
};

// --- SAFE PARSE HELPER ---
const safeParse = <T>(json: string | null, fallback: T): T => {
    if (!json) return fallback;
    try {
        return JSON.parse(json);
    } catch (e) {
        console.warn("Recovered from corrupted data:", e);
        return fallback;
    }
};

// --- DB ACCESS FUNCTIONS ---
const data = <T>(key: string): T[] => {
  if (cache[key]) return cache[key];
  const stored = localStorage.getItem(key);
  const parsed = safeParse<T[]>(stored, []);
  cache[key] = parsed;
  return parsed;
};

const save = <T>(key: string, items: T[]) => {
  cache[key] = items;
  // Use try-catch to prevent quota exceeded errors from crashing the app
  try {
      localStorage.setItem(key, JSON.stringify(items));
  } catch (e) {
      console.error("Storage quota exceeded or error saving:", e);
  }
};

// --- INITIALIZATION (LITE MODE: 5 VIPs Only) ---
const initializeDatabase = () => {
    // Check if data exists. If yes, DO NOTHING (to preserve speed).
    // The user must use "Factory Reset" to regenerate.
    if (localStorage.getItem(DB_KEYS.INSTITUTIONS)) {
        return; 
    }

    console.log("Initializing LITE Database (5 VIPs)...");

    // Load financials map for syncing
    const currentFinancials: FinancialRecord[] = [];
    const mergedMap = new Map<string, Institution>();
    let financialsChanged = false;

    // Process Seed Data
    SEEDED_INSTITUTIONS.forEach((seedInst: any, index) => {
        const id = seedInst.id || generateId(); 
        const location = inferDetailsByName(seedInst.name);
        const simpleManager = getRandomItem(SIMPLE_NAMES);

        // --- THE MAGIC: ONLY TOP 5 GET DATA ---
        // FIX: Start VIP from index 1 (Indices 1 to 5), so index 0 (First User) is empty for testing flow
        const isVIP = index > 0 && index <= 5; 

        const mod = index % 10;
        let type: 'GOOD' | 'AVERAGE' | 'BAD' = 'GOOD';
        if (mod > 7) type = 'BAD';       
        else if (mod > 5) type = 'AVERAGE'; 

        const instObj: Institution = {
            ...seedInst,
            id: id,
            governorate: seedInst.governorate || location.gov,
            wilayat: seedInst.wilayat || location.wil,
            manager_name: seedInst.manager_name || simpleManager,
            phone: seedInst.phone || `9${getRandomInt(1000000, 9999999)}`,
            email: seedInst.email || `info@waqf.om`,
            establishment_date: seedInst.establishment_date || `20${getRandomInt(15, 23)}-01-01`,
            license_number: seedInst.license_number || `${getRandomInt(1000, 9999)}`,
            capital_omr: seedInst.capital_omr || getRandomInt(100000, 5000000),
            employees_omani: seedInst.employees_omani || getRandomInt(2, 15),
            employees_non_omani: seedInst.employees_non_omani || getRandomInt(0, 5),
            // ONLY VIPs look "Active/Completed"
            profile_completed: isVIP, 
            institution_status: 'فاعلة',
            board_status: 'قائم',
            has_executive_management: true,
            has_auditor_company: true,
            has_financial_report_prev_year: true,
            has_minutes_prev_year: true,
            financial_reports: [], // Will be synced separately
            created_at: new Date().toISOString(),
            documents: [] // Keep empty for lightness
        };

        // ONLY generate financials for VIPs (Index 1-5)
        if (isVIP) {
            const fin2024 = generateDummyFinancials(id, 2024, type);
            const fin2025 = generateDummyFinancials(id, 2025, type);
            instObj.financial_reports = [fin2024, fin2025];
        }

        mergedMap.set(seedInst.name, instObj);
    });

    const finalResults = Array.from(mergedMap.values());

    // Sync Financials to separate table (Only for VIPs found above)
    finalResults.forEach(inst => {
        if (inst.financial_reports && inst.financial_reports.length > 0) {
            inst.financial_reports.forEach(report => {
                const fullRecord: FinancialRecord = {
                    ...report,
                    id: report.id || generateId(),
                    institution_id: inst.id,
                    fiscal_year: report.fiscal_year || CURRENT_YEAR,
                    auditor_name: report.auditor_name || 'غير محدد',
                    total_assets: report.total_assets || 0,
                    total_liabilities: report.total_liabilities || 0,
                    net_waqf_assets: report.net_waqf_assets || 0,
                    total_revenues: report.total_revenues || 0,
                    total_expenses: report.total_expenses || 0,
                    admin_general_expenses: report.admin_general_expenses || 0,
                    surplus_deficit: report.surplus_deficit || 0,
                    status: (report.status as any) || 'Submitted',
                    flags: report.flags || [],
                    submission_date: report.submission_date || new Date().toISOString()
                };
                currentFinancials.push(fullRecord);
                financialsChanged = true;
            });
        }
    });

    save(DB_KEYS.INSTITUTIONS, finalResults);

    if (financialsChanged || currentFinancials.length === 0) {
        save(DB_KEYS.FINANCIALS, currentFinancials);
    } else {
        cache[DB_KEYS.FINANCIALS] = currentFinancials;
    }
};

