// --- Components ---
const InfographicCard = ({ title, value, icon: Icon, gradient, subtext, footer }: any) => (
  <div className={`relative overflow-hidden rounded-2xl shadow-xl ${gradient} text-white p-6 transition-all duration-300 hover:scale-105 hover:shadow-2xl hover:-translate-y-1`}>
    <div className="relative z-10 flex justify-between items-start">
        <div>
            <p className="text-blue-100 font-medium mb-1 text-lg">{title}</p>
            <h3 className="text-4xl font-extrabold tracking-tight my-3">{value}</h3>
            {subtext && <p className="text-sm text-white/80 font-light">{subtext}</p>}
        </div>
        <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm shadow-inner transition-transform duration-500 hover:rotate-12">
            <Icon size={32} className="text-white" />
        </div>
    </div>
    {footer && (
        <div className="relative z-10 mt-6 pt-4 border-t border-white/20 text-sm font-medium">
            {footer}
        </div>
    )}
    <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl transition-transform duration-700 hover:scale-150"></div>
    <div className="absolute top-10 -left-10 w-20 h-20 bg-black/10 rounded-full blur-2xl"></div>
  </div>
);

const RadarCustomTick = ({ payload, x, y, cx, cy, textAnchor, stroke, radius }: any) => {
    const shiftX = x > cx ? 25 : x < cx ? -25 : 0;
    const shiftY = y > cy ? 15 : y < cy ? -15 : 0;
    return (
        <g className="recharts-layer recharts-polar-angle-axis-tick">
            <text radius={radius} stroke={stroke} x={x + shiftX} y={y + shiftY} className="recharts-text recharts-polar-angle-axis-tick-value" textAnchor={textAnchor} fill="#374151" fontSize="12px" fontWeight="bold">
                <tspan x={x + shiftX} dy="0.355em">{payload.value}</tspan>
            </text>
        </g>
    );
};

const TopListItem = ({ rank, name, score, maxScore = 5 }: any) => {
    const percentage = (score / maxScore) * 100;
    const rankColor = RANK_COLORS[rank - 1] || RANK_COLORS[RANK_COLORS.length - 1];
    const Icon = rank <= 3 ? Trophy : Star;
    return (
        <div className="flex items-center gap-4 p-3 bg-gray-50 dark:bg-gray-700/50 rounded-xl transition-all duration-300 hover:bg-gray-100 dark:hover:bg-gray-700 hover:scale-[1.02] hover:shadow-md cursor-default">
            <div className={`flex items-center justify-center w-10 h-10 rounded-full font-bold text-white shrink-0 shadow-sm transition-transform hover:scale-110`} style={{ backgroundColor: rankColor }}>
                {rank <= 3 ? <Icon size={18} /> : <span>{rank}</span>}
            </div>
            <div className="flex-1 min-w-0">
                <div className="flex justify-between mb-1">
                    <span className="text-sm font-bold text-navy-900 dark:text-white truncate" title={name}>{name}</span>
                    <span className="text-sm font-extrabold text-teal-600 dark:text-teal-400">{score.toFixed(2)}</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-600 overflow-hidden">
                    <div className="bg-teal-500 h-2.5 rounded-full transition-all duration-1000 ease-out" style={{ width: `${percentage}%` }}></div>
                </div>
            </div>
        </div>
    );
};

const STRATEGY_DATA = [
    { year: '2025', actual: 3.2, target: 3.2 },
    { year: '2026', actual: null, target: 3.5 },
    { year: '2027', actual: null, target: 3.8 },
    { year: '2028', actual: null, target: 4.2 },
    { year: '2029', actual: null, target: 4.5 },
    { year: '2030', actual: null, target: 4.8 },
];

const Dashboard: React.FC = () => {
  const { currentWaqfId, setWaqfContext } = useUi();
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [risks, setRisks] = useState<RiskRegisterItem[]>([]);
  const [responses, setResponses] = useState<Response[]>([]);
  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [financials, setFinancials] = useState<FinancialRecord[]>([]);

  useEffect(() => {
    setInstitutions(getInstitutions() || []);
    setEvaluations(getEvaluations() || []);
    setRisks(getRisks() || []);
    setResponses(getAllResponses() || []);
    setIndicators(getIndicators() || []);
    setFinancials(getFinancialRecords() || []);
  }, []);

  const filteredInstitutions = useMemo(() => currentWaqfId ? institutions.filter(i => i.id === currentWaqfId) : institutions, [currentWaqfId, institutions]);
  const filteredEvaluations = useMemo(() => currentWaqfId ? evaluations.filter(e => e.institution_id === currentWaqfId) : evaluations, [currentWaqfId, evaluations]);
  const filteredRisks = useMemo(() => currentWaqfId ? risks.filter(r => r.institution_id === currentWaqfId) : risks, [currentWaqfId, risks]);
  const filteredResponses = useMemo(() => {
      if (!currentWaqfId) return responses;
      const evalIds = filteredEvaluations.map(e => e.id);
      return responses.filter(r => evalIds.includes(r.evaluation_id));
  }, [currentWaqfId, responses, filteredEvaluations]);

  // --- FINANCIAL SUMMARY CALCULATION ---
  const financialStats = useMemo(() => {
     if (!financials || financials.length === 0) return { hasData: false, adminRatio: 0, surplus: 0, cash: 0, netAssets: 0 };

     const recordsToProcess = currentWaqfId 
        ? financials.filter(r => r.institution_id === currentWaqfId)
        : financials;

     if (recordsToProcess.length === 0) return { hasData: false, adminRatio: 0, surplus: 0, cash: 0, netAssets: 0 };

     const latestMap = new Map();
     recordsToProcess.forEach(r => {
        const current = latestMap.get(r.institution_id);
        if (!current || (r.fiscal_year > current.fiscal_year)) {
            latestMap.set(r.institution_id, r);
        }
     });

     const latestRecords = Array.from(latestMap.values());

     let totalSurplus = 0;
     let totalCash = 0;
     let totalExpenses = 0;
     let totalAdmin = 0;
     let totalNetAssets = 0;

     latestRecords.forEach(r => {
        totalSurplus += (Number(r.surplus_deficit) || 0);
        totalCash += (Number(r.cash_end_period) || 0);
        totalExpenses += (Number(r.total_expenses) || 0);
        totalAdmin += (Number(r.admin_general_expenses) || 0);
        totalNetAssets += (Number(r.net_waqf_assets) || 0);
     });

     const avgAdminRatio = totalExpenses > 0 ? (totalAdmin / totalExpenses) * 100 : 0;

     return {
        hasData: true,
        adminRatio: avgAdminRatio,
        surplus: totalSurplus,
        cash: totalCash,
        netAssets: totalNetAssets
     };
  }, [currentWaqfId, financials]);

  // --- Other Data Memos ---
  const typeStats = useMemo(() => {
      const general = filteredInstitutions.filter(i => i.type === 'وقفية عامة').length;
      const special = filteredInstitutions.filter(i => i.type === 'وقفية خاصة').length;
      return [ { name: 'عامة', value: general, fill: '#0d9488' }, { name: 'خاصة', value: special, fill: '#f59e0b' } ];
  }, [filteredInstitutions]);

  const totalCapital = useMemo(() => filteredInstitutions.reduce((acc, i) => acc + (i.capital_omr || 0), 0), [filteredInstitutions]);

  const topInstitutions = useMemo(() => {
      const scores: Record<string, { total: number, count: number, name: string }> = {};
      const instMap = new Map<string, string>(filteredInstitutions.map(i => [i.id, i.name] as [string, string]));
      filteredResponses.forEach(r => {
          const evalRec = filteredEvaluations.find(e => e.id === r.evaluation_id);
          if(evalRec && instMap.has(evalRec.institution_id)) {
             const id = evalRec.institution_id;
             if(!scores[id]) scores[id] = { total: 0, count: 0, name: instMap.get(id) || '' };
             scores[id].total += r.score;
             scores[id].count++;
          }
      });
      return Object.values(scores).map(s => ({ name: s.name, score: Number((s.total / s.count).toFixed(2)) })).sort((a, b) => b.score - a.score).slice(0, 5);
  }, [filteredResponses, filteredInstitutions, filteredEvaluations]);

  const employeeStats = useMemo(() => {
      const omani = filteredInstitutions.reduce((acc, i) => acc + (i.employees_omani || 0), 0);
      const nonOmani = filteredInstitutions.reduce((acc, i) => acc + (i.employees_non_omani || 0), 0);
      const total = omani + nonOmani;
      const rate = total > 0 ? (omani / total) * 100 : 0;
      return { omani, nonOmani, total, rate: Number(rate.toFixed(1)), pieData: [{ name: 'عماني', value: omani, fill: '#10b981' }, { name: 'غير عماني', value: nonOmani, fill: '#e5e7eb' }] };
  }, [filteredInstitutions]);

  const capitalStats = useMemo(() => {
      let lessThan1M = 0; let between1Mand5M = 0; let moreThan5M = 0;
      filteredInstitutions.forEach(i => {
          const cap = i.capital_omr || 0;
          if (cap <= 0) return;
          if (cap < 1000000) lessThan1M++; else if (cap >= 1000000 && cap <= 5000000) between1Mand5M++; else moreThan5M++;
      });
      return [ { name: 'أقل من مليون', value: lessThan1M, fill: '#3b82f6' }, { name: 'من مليون إلى 5 ملايين', value: between1Mand5M, fill: '#f97316' }, { name: 'أكثر من 5 ملايين', value: moreThan5M, fill: '#10b981' } ];
  }, [filteredInstitutions]);

  const riskMatrix = useMemo(() => {
      let high = 0;
      filteredRisks.forEach(r => { if ((r.probability * r.impact) >= 15) high++; });
      return { high };
  }, [filteredRisks]);

  const govStats = useMemo(() => {
      const counts: Record<string, number> = {};
      GOVERNORATES.forEach(g => counts[g] = 0);
      filteredInstitutions.forEach(i => { if (i.governorate && counts[i.governorate] !== undefined) counts[i.governorate]++; });
      return GOVERNORATES.map((g, idx) => ({ name: g, value: counts[g], fill: GOV_COLORS[idx % GOV_COLORS.length] }));
  }, [filteredInstitutions]);

  const averageScore = useMemo(() => {
      if (filteredResponses.length === 0) return 0;
      return (filteredResponses.reduce((acc, r) => acc + r.score, 0) / filteredResponses.length).toFixed(1);
  }, [filteredResponses]);

  const benchmarkData = useMemo(() => {
      const allTotal = getAllResponses().reduce((acc, r) => acc + r.score, 0);
      const systemAverage = responses.length > 0 ? (allTotal / responses.length) : 0;
      return [ { name: 'المتوسط العام', value: Number(systemAverage.toFixed(2)), fill: '#94a3b8' }, { name: 'المؤسسة الحالية', value: Number(averageScore), fill: '#3b82f6' } ];
  }, [averageScore, responses]);

  const radarData = useMemo(() => {
      if (filteredResponses.length === 0) return [ { subject: 'الشرعي', A: 0, fullMark: 5 }, { subject: 'الإداري', A: 0, fullMark: 5 }, { subject: 'المالي', A: 0, fullMark: 5 }, { subject: 'الحوكمة', A: 0, fullMark: 5 }, { subject: 'الابتكار', A: 0, fullMark: 5 }, { subject: 'الاستدامة', A: 0, fullMark: 5 }];
      const axisScores: Record<string, { total: number, count: number }> = {};
      filteredResponses.forEach(r => {
          const ind = indicators.find(i => i.id === r.indicator_id);
          if (ind) {
              if (!axisScores[ind.axis]) axisScores[ind.axis] = { total: 0, count: 0 };
              axisScores[ind.axis].total += r.score;
              axisScores[ind.axis].count += 1;
          }
      });
      return Object.keys(axisScores).map((axis, i) => ({ id: i, subject: axis, A: Number((axisScores[axis].total / axisScores[axis].count).toFixed(1)), fullMark: 5 }));
  }, [filteredResponses, indicators]);

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-6 gap-4">
         <div>
            <h2 className="text-3xl font-extrabold text-navy-900 dark:text-white tracking-tight">لوحة القيادة الاستراتيجية</h2>
            <p className="text-gray-500 dark:text-gray-400 mt-2 text-lg">نظرة شاملة على الأصول البشرية، المالية، ومستويات الأداء</p>
         </div>
         <div className="w-full md:w-auto min-w-[300px]">
             <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 flex items-center gap-2">
                 <Filter size={16} /> تصفية البيانات حسب المؤسسة
             </label>
             <div className="relative group">
                 <select 
                    className="w-full p-3 pl-10 border border-gray-300 rounded-xl shadow-sm focus:ring-2 focus:ring-navy-800 outline-none appearance-none bg-white font-bold"
                    value={currentWaqfId || ''} onChange={(e) => setWaqfContext(e.target.value)}
                 >
                     <option value="">جميع المؤسسات (نظرة عامة)</option>
                     {institutions.map(inst => <option key={inst.id} value={inst.id}>{inst.name}</option>)}
                 </select>
                 <div className="absolute left-3 top-3.5 pointer-events-none text-gray-500"><Building size={18} /></div>
             </div>
             {currentWaqfId && <p className="text-xs text-teal-600 mt-1 font-bold">تم تثبيت العرض على المؤسسة المختارة</p>}
         </div>
      </div>

      {/* 1. TOP CARDS (HERO) */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <InfographicCard title="حجم رأس المال الوقفي" value={`${totalCapital.toLocaleString()} ر.ع.`} icon={Coins} gradient="bg-gradient-to-br from-indigo-900 to-navy-900" subtext="القيمة السوقية التقديرية" footer={<span className="text-blue-200">النمو السنوي: +4.2%</span>}/>

        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-white dark:bg-gray-800 p-6 border border-gray-100 dark:border-gray-700 flex items-center justify-between transition-all hover:scale-105">
            <div className="w-1/2">
                <p className="text-gray-500 dark:text-gray-400 font-medium mb-1">توزيع المؤسسات</p>
                <div className="space-y-4 mt-4">
                    <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-teal-600"></div><span className="text-navy-900 font-bold text-xl">{typeStats[0].value}</span><span className="text-xs text-gray-500">عامة</span></div>
                    <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-amber-500"></div><span className="text-navy-900 font-bold text-xl">{typeStats[1].value}</span><span className="text-xs text-gray-500">خاصة</span></div>
                </div>
            </div>
            <div className="w-1/2 h-32"><ResponsiveContainer><PieChart><Pie data={typeStats} innerRadius={25} outerRadius={40} dataKey="value" paddingAngle={5}>{typeStats.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} />)}</Pie></PieChart></ResponsiveContainer></div>
        </div>

        <InfographicCard title="متوسط الأداء" value={averageScore} icon={Activity} gradient="bg-gradient-to-br from-purple-700 to-purple-900" subtext="من 5.0"/>
        <div className="relative overflow-hidden rounded-2xl shadow-xl bg-gradient-to-br from-red-600 to-red-800 text-white p-6 hover:scale-105 transition-all">
            <div className="relative z-10"><div className="flex justify-between items-start"><p className="text-red-100 font-medium text-lg">المخاطر الحرجة</p><div className="bg-white/20 p-2 rounded-lg"><AlertTriangle size={24} /></div></div><div className="flex items-baseline mt-4"><h3 className="text-6xl font-extrabold tracking-tight">{riskMatrix.high}</h3><span className="mr-2 text-red-200 font-medium">حالة</span></div><p className="text-xs text-red-100 mt-2 opacity-80">تتطلب تدخلاً فورياً</p></div>
        </div>
      </div>

      {/* 2. === NEW: DESIGN 2 (Corrected Colors & Logic) === */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-navy-900 flex items-center gap-2">
                    <Wallet className="text-blue-600" /> الملخص المالي (الموقف التشغيلي)
                </h3>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

                {/* 1. Right: Financial Position (Net Assets) */}
                <div className="bg-blue-50/50 rounded-2xl p-4 flex flex-col items-center justify-center border border-blue-100">
                    <h4 className="text-blue-800 font-bold mb-3 flex items-center gap-2"><Layers size={18}/> المركز المالي (صافي الأصول)</h4>
                    <div className="relative h-40 w-40 transition-transform duration-500 hover:scale-110">
                        <ResponsiveContainer>
                            <PieChart>
                                <Pie
                                    data={[{ name: 'صافي الأصول', value: financialStats.netAssets }]} 
                                    cx="50%" cy="50%" innerRadius={55} outerRadius={70}
                                    startAngle={90} endAngle={-270}
                                    dataKey="value" stroke="none"
                                >
                                    <Cell fill="#3b82f6" />
                                </Pie>
                                <Tooltip position={{ x: 0, y: 0 }} contentStyle={{ borderRadius: '8px', direction: 'rtl' }} />
                            </PieChart>
                        </ResponsiveContainer>
                        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                             <Briefcase className="text-blue-500 mb-1" size={24} />
                             <span className="text-xl font-black text-navy-900">{(financialStats.netAssets / 1000000).toFixed(2)}M</span>
                             <span className="text-[10px] text-gray-500">مليون ر.ع</span>
                        </div>
                    </div>
                </div>

                {/* 2. Center: Performance (Surplus) */}
                <div className={`rounded-2xl p-4 flex flex-col items-center justify-center border ${financialStats.surplus >= 0 ? 'bg-emerald-50/50 border-emerald-100' : 'bg-red-50/50 border-red-100'}`}>
                    <h4 className={`font-bold mb-3 flex items-center gap-2 ${financialStats.surplus >= 0 ? 'text-emerald-800' : 'text-red-800'}`}><TrendingUp size={18}/> الأداء المالي (الفائض)</h4>
                    <div className="relative h-40 w-40 transition-transform duration-500 hover:scale-110">
                        <ResponsiveContainer>
                            <PieChart>
                                <Pie
                                    data={[{ name: 'الفائض/العجز', value: Math.abs(financialStats.surplus) }]} 
                                    cx="50%" cy="50%" innerRadius={55} outerRadius={70}
                                    startAngle={90} endAngle={-270}
                                    dataKey="value" stroke="none"
                                >
                                    <Cell fill={financialStats.surplus >= 0 ? '#10b981' : '#ef4444'} />
                                </Pie>
                                <Tooltip position={{ x: 0, y: 0 }} contentStyle={{ borderRadius: '8px', direction: 'rtl' }} />
                            </PieChart>
                        </ResponsiveContainer>
                        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                             {financialStats.surplus >= 0 ? <TrendingUp size={24} className="text-emerald-500 mb-1"/> : <TrendingDown size={24} className="text-red-500 mb-1"/>}
                             <span className="text-xl font-black text-navy-900">{(financialStats.surplus / 1000).toFixed(1)}K</span>
                             <span className="text-[10px] text-gray-500">ألف ر.ع</span>
                        </div>
                    </div>
                </div>

                {/* 3. Left: Efficiency (Admin Expenses) */}
                <div className="bg-orange-50/50 rounded-2xl p-4 flex flex-col items-center justify-center border border-orange-100">
                    <h4 className="text-orange-800 font-bold mb-3 flex items-center gap-2"><Banknote size={18}/> المصاريف الإدارية والرواتب</h4>
                    <div className="relative h-40 w-40 transition-transform duration-500 hover:scale-110">
                        <ResponsiveContainer>
                            <PieChart>
                                <Pie
                                    data={[{ name: 'المصاريف الإدارية', value: financialStats.adminRatio }, { name: 'المصاريف التشغيلية', value: 100 - financialStats.adminRatio }]}
                                    cx="50%" cy="50%" innerRadius={55} outerRadius={70}
                                    startAngle={180} endAngle={0} // Half Circle (Gauge)
                                    dataKey="value" stroke="none"
                                >
                                    <Cell fill={financialStats.adminRatio > 20 ? '#ef4444' : '#f97316'} />
                                    <Cell fill="#fed7aa" />
                                </Pie>
                                <Tooltip position={{ x: 0, y: 0 }} contentStyle={{ borderRadius: '8px', direction: 'rtl' }} />
                            </PieChart>
                        </ResponsiveContainer>
                        <div className="absolute inset-0 flex flex-col items-center justify-center pt-8 pointer-events-none">
                             <span className="text-2xl font-black text-navy-900">{financialStats.adminRatio.toFixed(1)}%</span>
                             <span className="text-[10px] text-gray-500 mt-1">من إجمالي المصروفات</span>
                             <span className="text-[9px] text-orange-600 font-bold mt-1">الحد الأقصى 20%</span>
                        </div>
                    </div>
                </div>

            </div>
      </div>
      {/* ====================================================== */}

      {/* 3. ROW: Geographic + Top 5 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 lg:col-span-2 hover:shadow-xl transition-all">
            <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-6 flex items-center gap-2"><MapPin className="text-teal-600" /> التوزيع الجغرافي</h3>
            <div className="h-96"><ResponsiveContainer width="100%" height="100%"><BarChart data={govStats} margin={{ top: 20, right: 30, left: 20, bottom: 120 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" /><XAxis dataKey="name" angle={-45} textAnchor="end" interval={0} tick={{fontSize: 12, fill: '#4b5563', dy: 10}}/><YAxis axisLine={false} tickLine={false} allowDecimals={false}/><Tooltip cursor={{fill: '#f0f4f8'}} contentStyle={{borderRadius: '10px'}} /><Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>{govStats.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} />)}<LabelList dataKey="value" position="top" fill="#374151" fontSize={14} fontWeight="bold" /></Bar></BarChart></ResponsiveContainer></div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
          <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-6 flex items-center gap-2"><Medal className="text-gold-500" /> الأعلى أداءً (التوب 5)</h3>
          <div className="h-96 overflow-y-auto pr-2 scrollbar-thin">
             {topInstitutions.length > 0 ? ( <div className="space-y-3">{topInstitutions.map((inst, index) => <TopListItem key={inst.name} rank={index + 1} name={inst.name} score={inst.score} />)}</div> ) : ( <div className="flex flex-col items-center justify-center h-full text-gray-400"><Trophy size={48} className="text-gray-300 mb-4" /><p>لا توجد بيانات</p></div> )}
          </div>
        </div>
      </div>

      {/* 4. ROW: Capital Donut & Radar */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
             <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-6 flex items-center gap-2"><Briefcase className="text-blue-600" /> تصنيف المؤسسات حسب رأس المال</h3>
             <div className="h-96"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={capitalStats} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={5} dataKey="value">{capitalStats.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} strokeWidth={0} />)}</Pie><Tooltip contentStyle={{borderRadius: '10px'}} /><Legend verticalAlign="bottom" height={36} iconType="circle" /></PieChart></ResponsiveContainer></div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
            <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-6 flex items-center gap-2"><Shield className="text-blue-600" /> توازن الأداء المؤسسي</h3>
            <div className="h-96"><ResponsiveContainer width="100%" height="100%"><RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}><PolarGrid gridType="polygon" stroke="#e5e7eb" /><PolarAngleAxis dataKey="subject" tick={RadarCustomTick} /><PolarRadiusAxis angle={30} domain={[0, 5]} tick={false} axisLine={false} /><Radar name="الأداء الحالي" dataKey="A" stroke="#2563eb" strokeWidth={3} fill="#3b82f6" fillOpacity={0.6} /><Tooltip contentStyle={{ borderRadius: '12px' }} /></RadarChart></ResponsiveContainer></div>
        </div>
      </div>

      {/* 5. ROW: Employees & Benchmark */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
            <h3 className="text-xl font-bold text-navy-900 dark:text-white mb-2 flex items-center gap-2"><Users className="text-teal-600" /> تكوين القوى البشرية</h3>
            <div className="h-72 relative flex flex-col justify-center items-center overflow-hidden">
                <div className="w-full h-full absolute inset-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={employeeStats.pieData} cx="50%" cy="70%" startAngle={180} endAngle={0} innerRadius="60%" outerRadius="85%" paddingAngle={0} dataKey="value" stroke="none">{employeeStats.pieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} />)}</Pie><Tooltip contentStyle={{borderRadius: '10px'}} /></PieChart></ResponsiveContainer></div>
                <div className="absolute inset-0 pointer-events-none"><div className="absolute left-1/2 top-[70%] w-0 h-0"><div className="w-1 h-24 bg-gray-800 absolute left-[-2px] bottom-0 rounded-t-full origin-bottom transition-transform duration-1000 ease-out" style={{ transform: `rotate(${-90 + (employeeStats.rate / 100) * 180}deg)` }}></div><div className="w-4 h-4 bg-navy-900 rounded-full absolute -left-2 -top-2 border-2 border-white shadow-md"></div></div></div>
                <div className="absolute top-[75%] left-1/2 transform -translate-x-1/2 text-center"><span className="text-3xl font-black text-navy-900 block">{employeeStats.rate}%</span><span className="text-xs text-gray-500 font-bold uppercase tracking-wider">نسبة التعمين</span></div>
            </div>
            <div className="w-full flex justify-around mt-2 pt-4 border-t border-gray-100"><div className="text-center"><p className="text-xs text-gray-400">الإجمالي</p><p className="text-lg font-bold text-navy-900">{employeeStats.total}</p></div><div className="text-center border-x border-gray-100 px-6"><p className="text-xs text-gray-400">عماني</p><p className="text-lg font-bold text-teal-600">{employeeStats.omani}</p></div><div className="text-center"><p className="text-xs text-gray-400">غير عماني</p><p className="text-lg font-bold text-indigo-500">{employeeStats.nonOmani}</p></div></div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
             <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-navy-900 flex items-center gap-2"><BarChart2 className="text-teal-600" /> مقارنة الأداء المعياري</h3></div>
             <div className="h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={benchmarkData} barSize={60}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" /><XAxis dataKey="name" tick={{fontSize: 14, fontWeight: 'bold'}} axisLine={false} tickLine={false} /><YAxis domain={[0, 5]} axisLine={false} tickLine={false} /><Tooltip cursor={{fill: '#f0f4f8'}} contentStyle={{borderRadius: '10px'}} /><Bar dataKey="value" radius={[8, 8, 0, 0]}>{benchmarkData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} />)}<LabelList dataKey="value" position="top" fill="#374151" fontSize={16} fontWeight="bold" /></Bar></BarChart></ResponsiveContainer></div>
        </div>
      </div>

      {/* 6. ROW: Strategy */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 hover:shadow-xl transition-all">
        <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-navy-900 flex items-center gap-2"><Target className="text-red-600" /> مسار النضج الاستراتيجي</h3></div>
        <div className="h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={STRATEGY_DATA} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}><defs><linearGradient id="colorTarget" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#8884d8" stopOpacity={0.1}/><stop offset="95%" stopColor="#8884d8" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="year" axisLine={false} tickLine={false} /><YAxis domain={[0, 5]} axisLine={false} tickLine={false} /><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" /><Tooltip contentStyle={{borderRadius: '10px'}} /><Area type="monotone" dataKey="target" stroke="#8884d8" strokeWidth={3} fillOpacity={1} fill="url(#colorTarget)" name="المستهدف" /><Line type="monotone" dataKey="actual" stroke="#10b981" strokeWidth={3} dot={{r: 6}} name="الفعلي" /></AreaChart></ResponsiveContainer></div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { useUi } from '../contexts/UiContext';
import { getInstitutions, saveFinancialRecord, getFinancialRecords, analyzeFinancialHealth, generateId, getInstitutionProgress } from '../services/db';
import { FinancialRecord, InstitutionDocument } from '../types';
import { CURRENT_YEAR } from '../constants';
import { 
    TrendingUp, TrendingDown, UploadCloud, Save, AlertTriangle, 
    FileText, CheckCircle2, XCircle, Landmark, Briefcase, Scale,
    Banknote, ArrowRightLeft, Paperclip, ShieldCheck, Lock
} from 'lucide-react';

const FinancialReports: React.FC = () => {
  const { currentWaqfId, showToast } = useUi();
  const [loading, setLoading] = useState(false);
  const [institutions, setInstitutions] = useState<any[]>([]);

  // Lock state
  const [isLocked, setIsLocked] = useState(false);

  // Form State
  const [record, setRecord] = useState<Partial<FinancialRecord>>({
      fiscal_year: CURRENT_YEAR - 1,
      auditor_name: '',
      total_assets: 0,
      total_liabilities: 0,
      net_waqf_assets: 0,
      total_revenues: 0,
      total_expenses: 0,
      admin_general_expenses: 0,
      surplus_deficit: 0,
      operating_cash_flow: 0,
      investing_cash_flow: 0,
      financing_cash_flow: 0,
      cash_end_period: 0
  });

  const [pdfFile, setPdfFile] = useState<InstitutionDocument | null>(null);
  const [isConfirmed, setIsConfirmed] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<{isValid: boolean, status: string, flags: string[], errors: string[]} | null>(null);

  useEffect(() => {
      setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
      if (currentWaqfId) {
          // Check lock status
          const progress = getInstitutionProgress(currentWaqfId);
          setIsLocked(progress.isLocked);

          const records = getFinancialRecords(currentWaqfId);
          const existing = records.find(r => r.fiscal_year === record.fiscal_year);
          if (existing) {
              setRecord(existing);
              setPdfFile(existing.audit_report_pdf || null);
              setAnalysisResult(analyzeFinancialHealth(existing));
              setIsConfirmed(true); // If loaded, assume confirmed previously
          } else {
              setRecord({
                  fiscal_year: record.fiscal_year,
                  auditor_name: '',
                  total_assets: 0,
                  total_liabilities: 0,
                  net_waqf_assets: 0,
                  total_revenues: 0,
                  total_expenses: 0,
                  admin_general_expenses: 0,
                  surplus_deficit: 0,
                  operating_cash_flow: 0,
                  investing_cash_flow: 0,
                  financing_cash_flow: 0,
                  cash_end_period: 0
              });
              setPdfFile(null);
              setAnalysisResult(null);
              setIsConfirmed(false);
          }
      }
  }, [currentWaqfId, record.fiscal_year]);

  // Auto-calculate Surplus/Deficit
  useEffect(() => {
      const revenue = Number(record.total_revenues) || 0;
      const expenses = Number(record.total_expenses) || 0;
      const computedSurplus = revenue - expenses;

      if (computedSurplus !== record.surplus_deficit) {
          setRecord(prev => ({ ...prev, surplus_deficit: computedSurplus }));
      }
  }, [record.total_revenues, record.total_expenses]);

  // Sync Operating Cash Flow with Surplus (Logical Default)
  useEffect(() => {
      if (isLocked) return;
      // We set operating cash flow to match surplus by default as a starting point
      const surplus = Number(record.surplus_deficit) || 0;
      setRecord(prev => ({ ...prev, operating_cash_flow: surplus }));
  }, [record.surplus_deficit, isLocked]);

  // Auto-calculate Net Assets (Assets - Liabilities)
  useEffect(() => {
      const assets = Number(record.total_assets) || 0;
      const liabilities = Number(record.total_liabilities) || 0;
      const computedNet = assets - liabilities;

      if (computedNet !== record.net_waqf_assets) {
          setRecord(prev => ({ ...prev, net_waqf_assets: computedNet }));
      }
  }, [record.total_assets, record.total_liabilities]);

  // Auto-calculate Cash End of Period (Sum of Flows)
  useEffect(() => {
      const op = Number(record.operating_cash_flow) || 0;
      const inv = Number(record.investing_cash_flow) || 0;
      const fin = Number(record.financing_cash_flow) || 0;
      const totalCash = op + inv + fin;

      if (totalCash !== record.cash_end_period) {
          setRecord(prev => ({ ...prev, cash_end_period: totalCash }));
      }
  }, [record.operating_cash_flow, record.investing_cash_flow, record.financing_cash_flow]);

  const handleInputChange = (field: keyof FinancialRecord, value: any) => {
      if (isLocked) return;
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (isLocked) return;
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };
          setPdfFile(newDoc);
          showToast('تم إرفاق التقرير المالي', 'success');
      }
  };

  const handleSubmit = () => {
      if (!currentWaqfId || isLocked) return;
      if (!isConfirmed) {
          showToast('يرجى الإقرار بصحة البيانات قبل الحفظ', 'error');
          return;
      }

      setLoading(true);

      const fullRecord: FinancialRecord = {
          ...record as FinancialRecord,
          id: record.id || generateId(),
          institution_id: currentWaqfId,
          audit_report_pdf: pdfFile || undefined,
          submission_date: new Date().toISOString(),
          status: 'Submitted',
          flags: []
      };

      const analysis = analyzeFinancialHealth(fullRecord);
      fullRecord.status = analysis.status as any;
      fullRecord.flags = analysis.flags;

      saveFinancialRecord(fullRecord);
      setAnalysisResult(analysis);
      setLoading(false);

      showToast('تم حفظ البيانات المالية بنجاح', 'success');
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  if (!currentWaqfId) return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100 mt-10">
          <div className="bg-blue-50 p-6 rounded-full mb-6 text-blue-600"><Landmark size={48} /></div>
          <h2 className="text-2xl font-bold text-navy-900 mb-2">التقارير المالية</h2>
          <p className="text-gray-500">يرجى اختيار مؤسسة من القائمة العلوية لإدخال البيانات المالية</p>
      </div>
  );

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-20 animate-fadeIn">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-gray-200 pb-6">
          <div className="flex items-center gap-3">
              <div>
                <h2 className="text-2xl font-bold text-navy-900 flex items-center gap-2">
                    <Landmark className="text-teal-600"/> القوائم المالية والحوكمة
                </h2>
                <p className="text-gray-500 mt-1">إدخال البيانات المالية لـ: <span className="font-bold text-navy-800">{currentInstitutionName}</span></p>
              </div>
              {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
          </div>
          <div className="flex gap-4">
              <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">السنة المالية</label>
                  <select 
                    disabled={isLocked}
                    className="border border-gray-300 rounded-lg p-2 bg-white text-navy-900 font-bold outline-none focus:ring-2 focus:ring-teal-500 disabled:bg-gray-100 disabled:text-gray-500"
                    value={record.fiscal_year}
                    onChange={(e) => handleInputChange('fiscal_year', Number(e.target.value))}
                  >
                      {Array.from({length: 5}, (_, i) => CURRENT_YEAR - i).map(y => (
                          <option key={y} value={y}>{y}</option>
                      ))}
                  </select>
              </div>
              <div className="min-w-[200px]">
                  <label className="block text-xs font-bold text-gray-500 mb-1">مكتب التدقيق الخارجي</label>
                  <input 
                    type="text" 
                    disabled={isLocked}
                    placeholder="اسم المكتب / المدقق"
                    className="w-full border border-gray-300 rounded-lg p-2 text-sm outline-none focus:ring-2 focus:ring-teal-500 disabled:bg-gray-100 disabled:text-gray-500"
                    value={record.auditor_name}
                    onChange={(e) => handleInputChange('auditor_name', e.target.value)}
                  />
              </div>
          </div>
      </div>

      {/* Analysis Feedback Area */}
      {analysisResult && (
          <div className={`p-4 rounded-xl border-l-4 shadow-sm animate-scaleIn ${analysisResult.status === 'Flagged' || !analysisResult.isValid ? 'bg-red-50 border-red-500' : 'bg-green-50 border-green-500'}`}>
              <div className="flex items-start gap-3">
                  {analysisResult.isValid && analysisResult.status === 'Submitted' ? (
                      <CheckCircle2 className="text-green-600 mt-1" />
                  ) : (
                      <AlertTriangle className="text-red-600 mt-1" />
                  )}
                  <div>
                      <h4 className={`font-bold ${analysisResult.status === 'Flagged' ? 'text-red-800' : 'text-green-800'}`}>
                          {analysisResult.status === 'Flagged' ? 'تم رصد ملاحظات حوكمة' : (!analysisResult.isValid ? 'خطأ في البيانات' : 'البيانات سليمة')}
                      </h4>
                      <ul className="mt-2 space-y-1 text-sm list-disc list-inside">
                          {analysisResult.errors.map((err, i) => <li key={`e-${i}`} className="text-red-700 font-bold">{err}</li>)}
                          {analysisResult.flags.map((flag, i) => <li key={`f-${i}`} className="text-red-600">{flag}</li>)}
                          {analysisResult.isValid && analysisResult.flags.length === 0 && (
                              <li className="text-green-700">المعادلة المحاسبية متزنة والمصروفات الإدارية في الحدود المسموحة.</li>
                          )}
                      </ul>
                  </div>
              </div>
          </div>
      )}

      {/* Main Form Grid (4 Cards) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

          {/* Card A: Financial Position */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-blue-900 to-navy-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Briefcase size={18}/> المركز المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الأصول</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.total_assets || ''} onChange={(e) => handleInputChange('total_assets', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الالتزامات</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.total_liabilities || ''} onChange={(e) => handleInputChange('total_liabilities', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">صافي الأصول (المال الوقفي)</label>
                      <input 
                        type="number" 
                        readOnly
                        className="w-full p-2 border border-gray-300 rounded-lg font-bold bg-gray-100 text-navy-900 outline-none"
                        value={record.net_waqf_assets || 0} 
                      />
                      <p className="text-[10px] text-gray-400 mt-1">يتم الاحتساب تلقائياً: (الأصول - الالتزامات)</p>
                  </div>
              </div>
          </div>

          {/* Card B: Performance */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-teal-700 to-teal-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><TrendingUp size={18}/> الأداء المالي</h3>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي الإيرادات</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.total_revenues || ''} onChange={(e) => handleInputChange('total_revenues', Number(e.target.value))} />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">إجمالي المصروفات</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-teal-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.total_expenses || ''} onChange={(e) => handleInputChange('total_expenses', Number(e.target.value))} />
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1">الفائض / العجز</label>
                      <input disabled type="text" className={`w-full p-2 border rounded-lg font-bold bg-gray-100 ${(record.surplus_deficit || 0) < 0 ? 'text-red-600' : 'text-green-600'}`} 
                          value={record.surplus_deficit?.toLocaleString() || '0'} />
                  </div>
              </div>
          </div>

          {/* Card C: Cash Flows */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-orange-700 to-red-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><ArrowRightLeft size={18}/> التدفقات النقدية</h3>
                  <span className="text-xs bg-white/20 px-2 py-1 rounded">السيولة</span>
              </div>
              <div className="p-4 space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">صافي النقد التشغيلي</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.operating_cash_flow || ''} onChange={(e) => handleInputChange('operating_cash_flow', Number(e.target.value))} />
                      <p className="text-[9px] text-gray-400 mt-0.5">يُقترح مطابقته للفائض (قابل للتعديل)</p>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                      <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1">الاستثماري</label>
                        <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                            value={record.investing_cash_flow || ''} onChange={(e) => handleInputChange('investing_cash_flow', Number(e.target.value))} />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-600 mb-1">التمويلي</label>
                        <input type="number" disabled={isLocked} className="w-full p-2 border rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-orange-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                            value={record.financing_cash_flow || ''} onChange={(e) => handleInputChange('financing_cash_flow', Number(e.target.value))} />
                      </div>
                  </div>
                  <div className="pt-2 border-t border-gray-100">
                      <label className="block text-xs font-bold text-navy-900 mb-1 flex items-center gap-1"><Banknote size={14}/> صافي النقد (نهاية السنة)</label>
                      <input type="number" readOnly className="w-full p-2 border border-gray-300 rounded-lg font-bold bg-gray-100 text-orange-900 outline-none"
                          value={record.cash_end_period || 0} />
                      <p className="text-[10px] text-gray-400 mt-1">يتم الاحتساب تلقائياً: (تشغيلي + استثماري + تمويلي)</p>
                  </div>
              </div>
          </div>

          {/* Card D: Governance (Simplified) */}
          <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition-shadow">
              <div className="bg-gradient-to-r from-purple-800 to-indigo-900 p-4 text-white flex justify-between items-center">
                  <h3 className="font-bold flex items-center gap-2"><Scale size={18}/> الحوكمة المالية</h3>
              </div>
              <div className="p-4 space-y-4 h-full">
                  <div>
                      <label className="block text-xs font-bold text-gray-600 mb-1">المصروفات الإدارية والرواتب</label>
                      <input type="number" disabled={isLocked} className="w-full p-2 border border-gray-200 rounded-lg bg-gray-50 focus:bg-white focus:ring-1 focus:ring-purple-500 outline-none disabled:bg-gray-100 disabled:text-gray-500" 
                          value={record.admin_general_expenses || ''} onChange={(e) => handleInputChange('admin_general_expenses', Number(e.target.value))} />

                      {(record.total_expenses || 0) > 0 && (
                          <div className={`mt-2 p-2 rounded text-xs font-bold text-center ${((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100) > 20 ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-green-50 text-green-600 border border-green-200'}`}>
                              نسبة الإدارية: {((record.admin_general_expenses || 0) / (record.total_expenses || 1) * 100).toFixed(1)}% <br/>
                              (الحد الأقصى المسموح 20%)
                          </div>
                      )}
                  </div>

                  {/* Placeholder for visual balance */}
                  <div className="pt-2 border-t border-gray-100 text-center text-gray-400 text-xs">
                      <ShieldCheck size={48} className="mx-auto mb-2 opacity-20" />
                      <p>مؤشر الالتزام بضوابط الصرف</p>
                  </div>
              </div>
          </div>
      </div>

      {/* NEW: Attachments & Declaration Section (Full Width) */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="bg-gray-50 p-4 border-b border-gray-200 flex items-center gap-2">
              <Paperclip size={20} className="text-navy-900"/>
              <h3 className="font-bold text-navy-900">المرفقات والإقرار</h3>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Left Column: Upload */}
              <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">إرفاق تقرير المدقق المالي (PDF)</label>
                  {pdfFile ? (
                      <div className="flex items-center justify-between bg-blue-50 p-4 rounded-xl border border-blue-200 text-blue-900">
                          <div className="flex items-center gap-3">
                              <div className="bg-white p-2 rounded-lg text-red-500 shadow-sm"><FileText size={24}/></div>
                              <div>
                                  <span className="text-sm font-bold block">{pdfFile.name}</span>
                                  <span className="text-xs opacity-70">{pdfFile.size} - تم الرفع</span>
                              </div>
                          </div>
                          {!isLocked && <button onClick={() => setPdfFile(null)} className="text-red-500 hover:bg-red-100 p-2 rounded-full transition-colors"><XCircle size={20}/></button>}
                      </div>
                  ) : (
                      <label className={`flex flex-col items-center justify-center gap-3 w-full h-32 border-2 border-dashed border-gray-300 rounded-xl bg-gray-50 text-gray-500 cursor-pointer hover:bg-gray-100 hover:border-blue-400 transition-all group ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}>
                          <div className="p-3 bg-white rounded-full shadow-sm group-hover:scale-110 transition-transform">
                              <UploadCloud size={24} className="text-blue-500" />
                          </div>
                          <span className="text-sm font-medium">اضغط هنا لرفع ملف التقرير</span>
                          <input type="file" accept="application/pdf" className="hidden" onChange={handleFileUpload} disabled={isLocked} />
                      </label>
                  )}
                  <p className="text-xs text-gray-400 mt-2">يجب أن يكون الملف بصيغة PDF وموقعاً من مكتب التدقيق المعتمد.</p>
              </div>

              {/* Right Column: Declaration */}
              <div className="bg-amber-50 rounded-xl p-5 border border-amber-100 flex flex-col justify-center">
                  <h4 className="font-bold text-amber-900 mb-3 flex items-center gap-2">
                      <ShieldCheck size={18}/> إقرار صحة البيانات
                  </h4>
                  <p className="text-sm text-amber-800 mb-4 leading-relaxed opacity-90">
                      بصفتي مخولاً عن المؤسسة الوقفية، أقر بأن جميع البيانات المالية المدخلة أعلاه صحيحة ومطابقة تماماً لتقرير المدقق المالي المرفق، وأتحمل المسؤولية القانونية في حال ثبوت خلاف ذلك.
                  </p>
                  <label className="flex items-center gap-3 cursor-pointer bg-white p-3 rounded-lg border border-amber-200 shadow-sm hover:border-amber-400 transition-colors">
                      <input type="checkbox" disabled={isLocked} className="w-5 h-5 text-navy-900 rounded focus:ring-navy-900 disabled:opacity-50" 
                          checked={isConfirmed} onChange={(e) => setIsConfirmed(e.target.checked)} />
                      <span className="text-sm font-bold text-navy-900">
                          نعم، أقر بصحة البيانات ومطابقتها.
                      </span>
                  </label>
              </div>
          </div>
      </div>

      {/* Action Bar */}
      <div className="flex justify-end pt-4 border-t border-gray-200">
          {!isLocked && (
            <button 
                disabled={loading || !isConfirmed}
                onClick={handleSubmit}
                className={`flex items-center gap-2 px-8 py-3 rounded-xl font-bold text-white shadow-lg transition-transform active:scale-95 ${loading || !isConfirmed ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900'}`}
            >
                <Save size={20} /> {loading ? 'جاري الحفظ...' : 'حفظ وإرسال البيانات المالية'}
            </button>
          )}
      </div>

    </div>
  );
};

export default FinancialReports;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getComplianceRecords, saveComplianceRecord, generateId, getComplianceByInstAndYear, getRisks, saveRisk, deleteRisk, getInstitutionProgress } from '../services/db';
import { Institution, ComplianceRecord, RiskRegisterItem, CustomRequirement } from '../types';
import { CURRENT_YEAR, calculateRiskScore } from '../constants';
import { Save, AlertTriangle, CheckCircle, Info, ShieldAlert, Plus, Trash2, Scale, X, Building, Settings, Lock, Edit2, CheckSquare, AlertCircle, ArrowDown } from 'lucide-react';
import { useUi } from '../contexts/UiContext';

const CORE_REQUIREMENTS = [
    { key: 'has_executive_management', label: 'هل توجد إدارة تنفيذية أو مدير؟' },
    { key: 'has_auditor_company', label: 'هل تم تعيين شركة تدقيق؟' },
    { key: 'has_minutes_prev_year', label: 'هل توجد محاضر اجتماعات للعام الماضي؟' },
    { key: 'has_financial_report_prev_year', label: 'هل يوجد تقرير مالي معتمد للعام الماضي؟' },
];

const CompliancePage: React.FC = () => {
  // Removed ActiveTab state - Single Page View
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { showToast, currentWaqfId, role } = useUi();

  // Compliance State
  const [record, setRecord] = useState<Partial<ComplianceRecord>>({});
  const [newReqText, setNewReqText] = useState('');

  // Locking State
  const [isLocked, setIsLocked] = useState(false);

  // Admin Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Risk Register State
  const [instRisks, setInstRisks] = useState<RiskRegisterItem[]>([]);
  const [newRisk, setNewRisk] = useState<Partial<RiskRegisterItem>>({});
  const [showRiskForm, setShowRiskForm] = useState(false);

  // Real-time calculated risk based on compliance form
  const complianceRisk = calculateRiskScore(record);

  useEffect(() => {
    setInstitutions(getInstitutions());
  }, []);

  useEffect(() => {
    if (currentWaqfId) {
        // Check Lock Status
        const progress = getInstitutionProgress(currentWaqfId);
        setIsLocked(progress.isLocked);

        // Load Compliance
        const existing = getComplianceByInstAndYear(currentWaqfId, CURRENT_YEAR);
        if (existing) {
            setRecord(existing);
        } else {
            setRecord({
                institution_id: currentWaqfId,
                cycle_year: CURRENT_YEAR,
                institution_status: 'فاعلة',
                board_status: 'قائم',
                has_executive_management: false,
                has_auditor_company: false,
                has_minutes_prev_year: false,
                has_financial_report_prev_year: false,
                custom_requirements: [],
                hidden_core_requirements: [],
                renamed_core_requirements: {},
                notes: ''
            });
        }

        // Load Risks
        setInstRisks(getRisks(currentWaqfId));
    } else {
        setRecord({});
        setInstRisks([]);
    }
    // Reset edit mode when changing institution
    setIsEditMode(false);
  }, [currentWaqfId]);

  const handleSaveAll = () => {
      if (!currentWaqfId || isLocked) return;

      // 1. VALIDATION: Check Risks
      if (instRisks.length === 0) {
          showToast('عذراً، لا يمكن الحفظ. يجب تسجيل خطر واحد على الأقل في سجل المخاطر بالأسفل.', 'error');
          // Scroll to risk section
          const riskSection = document.getElementById('risk-register-section');
          if (riskSection) {
              riskSection.scrollIntoView({ behavior: 'smooth' });
              riskSection.classList.add('ring-4', 'ring-red-300'); // Highlight effect
              setTimeout(() => riskSection.classList.remove('ring-4', 'ring-red-300'), 2000);
          }
          return;
      }

      // Ensure ID exists or generate new one
      const recordId = record.id || generateId();

      const toSave: ComplianceRecord = {
          ...record as ComplianceRecord,
          id: recordId,
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          last_updated_at: new Date().toISOString()
      };

      saveComplianceRecord(toSave);
      setRecord(toSave); 
      setIsEditMode(false); // Exit edit mode on save
      showToast('تم حفظ سجل الامتثال والمخاطر بنجاح', 'success');
  };

  // --- CUSTOM REQUIREMENTS HANDLERS ---
  const handleAddRequirement = () => {
      if (!newReqText || isLocked) return;
      const newReq: CustomRequirement = {
          id: generateId(),
          text: newReqText,
          met: false
      };
      setRecord(prev => ({
          ...prev,
          custom_requirements: [...(prev.custom_requirements || []), newReq]
      }));
      setNewReqText('');
      showToast('تم إضافة المعيار الجديد', 'success');
  };

  const handleRemoveRequirement = (id: string) => {
      if(isLocked) return;
      if(confirm('هل أنت متأكد من حذف هذا المعيار؟')) {
        setRecord(prev => ({
            ...prev,
            custom_requirements: prev.custom_requirements?.filter(r => r.id !== id)
        }));
      }
  };

  const toggleCustomRequirement = (id: string) => {
      if (isEditMode || isLocked) return; // Disable toggling in edit mode
      setRecord(prev => ({
          ...prev,
          custom_requirements: prev.custom_requirements?.map(r => r.id === id ? { ...r, met: !r.met } : r)
      }));
  };

  // --- CORE REQUIREMENTS EDIT HANDLERS ---
  const handleRemoveCoreReq = (key: string) => {
      if(isLocked) return;
      if(confirm('حذف هذا المعيار الأساسي؟ سيتم إخفاؤه من القائمة ولن يدخل في حساب المخاطر.')) {
          const currentHidden = record.hidden_core_requirements || [];
          setRecord(prev => ({
              ...prev,
              hidden_core_requirements: [...currentHidden, key]
          }));
      }
  };

  const handleRenameCoreReq = (key: string, newText: string) => {
      if(isLocked) return;
      const currentRenamed = record.renamed_core_requirements || {};
      setRecord(prev => ({
          ...prev,
          renamed_core_requirements: { ...currentRenamed, [key]: newText }
      }));
  };


  // --- RISK HANDLERS ---
  const handleSaveRisk = () => {
      if (!currentWaqfId || !newRisk.risk_title || isLocked) {
          if(!newRisk.risk_title) showToast('يرجى إدخال عنوان الخطر', 'error');
          return;
      }

      // Check if we are updating (id exists) or creating new
      const riskId = newRisk.id || generateId();
      const isUpdate = !!newRisk.id;

      const riskToSave: RiskRegisterItem = {
          id: riskId,
          institution_id: currentWaqfId,
          risk_title: newRisk.risk_title!,
          category: newRisk.category || 'Operational',
          probability: Number(newRisk.probability) || 1,
          impact: Number(newRisk.impact) || 1,
          mitigation_plan: newRisk.mitigation_plan || '',
          status: newRisk.status || 'Open'
      };

      saveRisk(riskToSave);
      setInstRisks(getRisks(currentWaqfId));
      setShowRiskForm(false);
      setNewRisk({});

      showToast(isUpdate ? 'تم حفظ التعديلات على الخطر' : 'تم إضافة الخطر بنجاح', 'success');
  };

  const handleEditRisk = (risk: RiskRegisterItem) => {
      if(isLocked) return;
      setNewRisk(risk);
      setShowRiskForm(true);
      // Scroll to form inside risk section
      setTimeout(() => {
          document.getElementById('risk-form-container')?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
  };

  const handleDeleteRisk = (id: string) => {
      if(isLocked) return;
      if(confirm('هل أنت متأكد من حذف هذا الخطر؟')) {
          deleteRisk(id);
          setInstRisks(getRisks(currentWaqfId));
          showToast('تم حذف الخطر', 'info');
      }
  };

  const updateComplianceField = (field: keyof ComplianceRecord, value: any) => {
      if (isEditMode || isLocked) return; // Prevent changing values while editing structure
      setRecord(prev => ({ ...prev, [field]: value }));
  };

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  return (
    <div className="space-y-6 pb-24">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-navy-900 dark:text-white">الامتثال والمخاطر ({CURRENT_YEAR})</h2>
            {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
        </div>
      </div>

      {/* Currently Viewing Banner */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري إدارة امتثال:</div>
                      <div className="text-lg font-bold">{currentInstitutionName}</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود العمل عليها.</p>
          </div>
      )}

      {currentWaqfId && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fadeIn">

              {/* --- LEFT COLUMN: MAIN FORMS --- */}
              <div className="lg:col-span-2 space-y-8">

                  {/* SECTION 1: COMPLIANCE */}
                  <div className="space-y-6">
                      <div className="flex items-center gap-2 border-b border-gray-200 pb-3">
                          <Scale className="text-navy-800" size={24} />
                          <h3 className="text-xl font-bold text-navy-900">أولاً: الامتثال النظامي</h3>
                      </div>

                      {/* Status Card */}
                      <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                          <h3 className="font-bold text-navy-900 dark:text-white mb-4 flex items-center gap-2">
                              <Info size={20} className="text-teal-600" /> الحالة الأساسية
                          </h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div>
                                  <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة المؤسسة</label>
                                  <select 
                                      disabled={isEditMode || isLocked}
                                      className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                      value={record.institution_status || 'فاعلة'} 
                                      onChange={(e) => updateComplianceField('institution_status', e.target.value)}
                                  >
                                      <option value="فاعلة">فاعلة</option>
                                      <option value="غير فاعلة">غير فاعلة</option>
                                      <option value="قيد التصفية">قيد التصفية</option>
                                      <option value="متوقفة">متوقفة</option>
                                      <option value="أخرى">أخرى</option>
                                  </select>
                              </div>
                              <div>
                                  <label className="block text-sm text-gray-500 dark:text-gray-400 mb-1">حالة مجلس الإدارة</label>
                                  <select 
                                      disabled={isEditMode || isLocked}
                                      className="w-full p-2 border rounded-lg bg-gray-50 dark:bg-gray-700 dark:border-gray-600 dark:text-white disabled:opacity-50" 
                                      value={record.board_status || 'قائم'} 
                                      onChange={(e) => updateComplianceField('board_status', e.target.value)}
                                  >
                                      <option value="قائم">قائم</option>
                                      <option value="منتهي">منتهي الصلاحية</option>
                                      <option value="غير موجود">غير موجود</option>
                                  </select>
                              </div>
                          </div>
                      </div>

                      {/* Requirements Checklist */}
                      <div className={`bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border transition-all ${isEditMode ? 'border-amber-400 ring-2 ring-amber-100' : 'border-gray-100 dark:border-gray-700'}`}>
                          <div className="flex justify-between items-center mb-6">
                              <h3 className="font-bold text-navy-900 dark:text-white flex items-center gap-2">
                                  <CheckCircle size={20} className="text-teal-600" /> المتطلبات النظامية
                              </h3>

                              {role === 'admin' && !isLocked && (
                                  <button 
                                      onClick={() => setIsEditMode(!isEditMode)}
                                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${isEditMode ? 'bg-amber-100 text-amber-800 hover:bg-amber-200' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                  >
                                      {isEditMode ? (
                                          <> <CheckSquare size={16}/> إنهاء التعديل </>
                                      ) : (
                                          <> <Settings size={16}/> تعديل المعايير </>
                                      )}
                                  </button>
                              )}
                          </div>

                          {/* Core Requirements */}
                          <div className="space-y-4 mb-6">
                              <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">المعايير الأساسية</h4>
                              {CORE_REQUIREMENTS.map((req) => {
                                  if (record.hidden_core_requirements?.includes(req.key)) return null;
                                  const displayLabel = record.renamed_core_requirements?.[req.key] || req.label;

                                  return (
                                      <div key={req.key} className="flex items-center gap-3 relative animate-fadeIn">
                                          {isEditMode ? (
                                              <div className="flex-1 flex gap-2 items-center bg-gray-50 border border-gray-200 p-2 rounded-lg">
                                                  <input 
                                                      type="text" 
                                                      className="flex-1 bg-white border border-gray-300 rounded px-2 py-1 text-sm focus:ring-2 focus:ring-amber-500 outline-none"
                                                      value={displayLabel}
                                                      onChange={(e) => handleRenameCoreReq(req.key, e.target.value)}
                                                  />
                                                  <button onClick={() => handleRemoveCoreReq(req.key)} className="text-red-500 hover:bg-red-50 p-2 rounded-lg"><Trash2 size={18} /></button>
                                              </div>
                                          ) : (
                                              <ToggleItem 
                                                  label={displayLabel} 
                                                  checked={!!(record as any)[req.key]} 
                                                  onChange={() => updateComplianceField(req.key as keyof ComplianceRecord, !(record as any)[req.key])} 
                                                  className={`flex-1`}
                                                  disabled={isLocked}
                                              />
                                          )}
                                      </div>
                                  );
                              })}
                          </div>

                          {/* Custom Requirements */}
                          <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                              <div className="flex justify-between items-center mb-4">
                                  <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider">المعايير الإضافية</h4>
                              </div>
                              <div className="space-y-2">
                                  {record.custom_requirements?.map(req => (
                                      <div key={req.id} className="flex items-center gap-2 animate-fadeIn">
                                          {isEditMode ? (
                                              <div className="flex-1 flex gap-2 items-center bg-amber-50 border border-amber-200 p-2 rounded-lg">
                                                  <span className="flex-1 text-sm text-gray-700 px-2">{req.text}</span>
                                                  <button onClick={() => handleRemoveRequirement(req.id)} className="text-red-500 hover:bg-red-50 p-2 rounded-lg"><Trash2 size={18} /></button>
                                              </div>
                                          ) : (
                                              <ToggleItem 
                                                  label={req.text} 
                                                  checked={req.met} 
                                                  onChange={() => toggleCustomRequirement(req.id)} 
                                                  className="flex-1"
                                                  disabled={isLocked}
                                              />
                                          )}
                                      </div>
                                  ))}
                                  {(!record.custom_requirements || record.custom_requirements.length === 0) && (
                                      <p className="text-xs text-gray-400 text-center py-4 border border-dashed border-gray-200 rounded-lg">لا توجد معايير إضافية</p>
                                  )}
                              </div>
                          </div>

                          {/* Add New Section */}
                          {isEditMode && (
                              <div className="mt-6 pt-6 border-t border-amber-200 animate-slideIn">
                                  <h4 className="text-sm font-bold text-amber-800 mb-3 flex items-center gap-2"><Plus size={16}/> إضافة معيار جديد</h4>
                                  <div className="flex gap-2">
                                      <input type="text" className="flex-1 border border-amber-300 p-2.5 rounded-lg text-sm outline-none" placeholder="أدخل نص المعيار الجديد هنا..." value={newReqText} onChange={e => setNewReqText(e.target.value)} />
                                      <button onClick={handleAddRequirement} className="bg-amber-600 text-white px-4 py-2 rounded-lg text-sm font-bold">إضافة</button>
                                  </div>
                              </div>
                          )}
                      </div>
                  </div>

                  {/* SECTION 2: RISKS (Now visible directly) */}
                  <div id="risk-register-section" className="space-y-6 pt-6 border-t-4 border-gray-200">
                      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                          <div>
                              <div className="flex items-center gap-2 mb-1">
                                  <ShieldAlert className="text-red-600" size={24} />
                                  <h3 className="text-xl font-bold text-navy-900">ثانياً: سجل المخاطر</h3>
                              </div>
                              <p className="text-gray-500 text-sm">يجب رصد المخاطر المتوقعة لضمان سلامة الوقف.</p>
                          </div>
                          {!isLocked && (
