        <div className="flex items-center justify-between p-4 border-b border-navy-800 min-h-[5rem]">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 min-w-[2.5rem] bg-white rounded-full p-1 overflow-hidden flex items-center justify-center shadow-md transition-transform hover:scale-110 duration-300">
                 <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/5/52/Ministry_of_Endowments_and_Religious_Affairs_%28Oman%29_Logo.png" 
                    className="w-full h-full object-contain" 
                    onError={(e) => {
                        e.currentTarget.style.display = 'none';
                    }}
                 />
             </div>
             <div className="flex flex-col">
                 <h1 className="text-sm font-bold text-white leading-tight">نظام تقييم المؤسسات الوقفية</h1>
                 <span className="text-[10px] text-gray-400 mt-1 font-medium">وزارة الأوقاف والشؤون الدينية</span>
             </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-gray-400 hover:text-white transition-transform hover:rotate-90">
            <X size={24} />
          </button>
        </div>

        {/* User Role Badge */}
        <div className="px-4 mt-4">
            <div className={`p-2 rounded-lg text-center text-xs font-bold border transform hover:scale-105 transition-transform duration-300 ${role === 'admin' ? 'bg-navy-800 border-navy-700 text-gold-400' : 'bg-teal-900/50 border-teal-800 text-teal-400'}`}>
                {role === 'admin' ? 'صلاحية: مدير النظام' : 'صلاحية: مؤسسة وقفية'}
            </div>
        </div>

        <nav className="p-4 space-y-2 flex-1 overflow-y-auto mt-2 scrollbar-thin scrollbar-thumb-navy-700">
          {navItems.map((item) => {
              const locked = isRouteLocked(item.to, role, progress);
              return (
                  <SidebarItem 
                    key={item.to} 
                    {...item} 
                    active={location.pathname === item.to} 
                    locked={locked}
                  />
              );
          })}
          <button 
            onClick={logout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-300 text-red-300 hover:bg-red-900/20 hover:text-red-200 hover:scale-105 mt-4 group"
          >
             <LogOut size={20} className="group-hover:-translate-x-1 transition-transform"/>
             <span className="font-medium">تسجيل الخروج</span>
          </button>
        </nav>
        <div className="absolute bottom-0 w-full p-4 border-t border-navy-800 text-xs text-gray-400 text-center">
          <p>{settings.orgName}</p>
          <p className="mt-1 text-gold-500">تحت إشراف {settings.managerName}</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="bg-white dark:bg-gray-800 shadow-sm z-10 border-b border-gray-200 dark:border-gray-700 h-20 flex items-center px-6 justify-between print:hidden">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-gray-600 dark:text-gray-200 transition-transform hover:scale-110">
                <Menu size={24} />
            </button>

            <div className="flex flex-col items-center flex-1 lg:flex-none lg:items-start">
                <h2 className="text-xl font-bold text-navy-900 dark:text-white">نظام تقييم المؤسسات الوقفية</h2>
                <span className="text-xs text-teal-600 dark:text-teal-400 font-semibold hidden md:block">سلطنة عُمان - {settings.orgName}</span>
            </div>

            <div className="hidden md:flex items-center gap-4">
                {/* Refresh Button */}
                <button 
                  onClick={() => window.location.reload()}
                  className="p-2 text-gray-400 hover:text-teal-600 hover:bg-teal-50 rounded-full transition-all"
                  title="تحديث سريع"
                >
                    <RefreshCw size={20} />
                </button>

                <div className="text-left">
                   <p className="text-sm font-bold text-navy-900 dark:text-white">أهلاً، {user}</p>
                   <p className="text-xs text-gold-600 dark:text-gold-400">{role === 'admin' ? 'مدير النظام' : 'مستخدم مؤسسة'}</p>
                </div>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-md transform hover:scale-110 transition-transform duration-300 ${role === 'admin' ? 'bg-navy-800' : 'bg-teal-600'}`}>
                    {user?.charAt(0).toUpperCase()}
                </div>
            </div>
        </header>

        {/* ADMIN ACTION BAR (CONDITIONAL) */}
        {role === 'admin' && currentWaqfId && <AdminActionBar waqfId={currentWaqfId} showToast={showToast} />}

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-4 lg:p-8 relative dark:text-gray-100">
          {children}

          {/* Footer - Print Only */}
          <div className="hidden print:block fixed bottom-0 left-0 right-0 text-center p-4 border-t text-sm">
             <p>تم استخراج هذا التقرير آلياً من نظام تقييم المؤسسات الوقفية</p>
             <p className="font-bold">تحت إشراف {settings.managerName}</p>
          </div>
        </main>
      </div>

      {/* Overlay for mobile sidebar */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId, getInstitutionProgress } from '../services/db';
import { Institution, Indicator, Evaluation, Response, InstitutionDocument } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp, Paperclip, FileText, X, PlusCircle, PieChart as PieIcon, Trash2, MinusCircle, Building, SaveAll, Lock } from 'lucide-react';
import { useUi } from '../contexts/UiContext';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

declare const XLSX: any; // SheetJS global

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  // Use Global Context instead of local state for selection
  const { showToast, currentWaqfId, role } = useUi();

  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});

  // Locking State
  const [isLocked, setIsLocked] = useState(false);

  // New Indicator Modal State
  const [showAddInd, setShowAddInd] = useState(false);
  const [newIndAxis, setNewIndAxis] = useState('');
  const [customAxis, setCustomAxis] = useState('');
  const [newIndText, setNewIndText] = useState('');

  // Delete Indicator Modal State
  const [showDeleteInd, setShowDeleteInd] = useState(false);
  const [deleteAxis, setDeleteAxis] = useState('');
  const [deleteIndId, setDeleteIndId] = useState('');

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);

  useEffect(() => {
    setInstitutions(getInstitutions());
    // Auto load default indicators
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    // Check if global context is set
    if (currentWaqfId && indicators.length > 0) {
      // Check locking status
      const progress = getInstitutionProgress(currentWaqfId);
      setIsLocked(progress.isLocked);

      // Find or Create Evaluation for the current global institution
      let ev = getEvaluationByInstAndYear(currentWaqfId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          workflow_status: 'draft',
          attachments: [],
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      // Load Responses
      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [currentWaqfId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation || isLocked) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  const handleAddIndicator = () => {
      const finalAxis = newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' ? customAxis : newIndAxis;

      if(!newIndText || !finalAxis) {
          showToast('يرجى تعبئة جميع الحقول', 'error');
          return;
      }

      const indicator: Indicator = {
          id: `IND-MANUAL-${generateId().substring(0,6)}`,
          axis: finalAxis,
          text: newIndText,
          weight: 1,
          active: true
      };

      const updatedList = [...indicators, indicator];
      setIndicators(updatedList);
      saveIndicators(updatedList);

      setShowAddInd(false);
      setNewIndAxis('');
      setCustomAxis('');
      setNewIndText('');
      showToast('تم إضافة المؤشر الجديد بنجاح', 'success');
  };

  const handleDeleteIndicator = () => {
      if (!deleteIndId) {
          showToast('يرجى اختيار المؤشر للحذف', 'error');
          return;
      }

      if(confirm('هل أنت متأكد من حذف هذا المؤشر؟ سيتم حذفه من القائمة.')) {
          const updatedList = indicators.filter(i => i.id !== deleteIndId);
          setIndicators(updatedList);
          saveIndicators(updatedList);

          setShowDeleteInd(false);
          setDeleteIndId('');
          setDeleteAxis('');
          showToast('تم حذف المؤشر', 'info');
      }
  };

  const openDeleteModal = () => {
      setDeleteAxis('');
      setDeleteIndId('');
      setShowDeleteInd(true);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (isLocked) return;
      if (e.target.files && e.target.files[0] && evaluation) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = {
              id: generateId(),
              name: file.name,
              type: file.type,
              size: (file.size / 1024).toFixed(1) + ' KB',
              upload_date: new Date().toLocaleDateString('ar-OM')
          };

          const updatedEval = { 
              ...evaluation, 
              attachments: [...(evaluation.attachments || []), newDoc] 
          };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم إرفاق الدليل بنجاح', 'success');
      }
  };

  const removeAttachment = (docId: string) => {
      if (!evaluation || isLocked) return;
      const updatedEval = {
          ...evaluation,
          attachments: evaluation.attachments?.filter(d => d.id !== docId) || []
      };
      setEvaluation(updatedEval);
      saveEvaluation(updatedEval);
      showToast('تم حذف المرفق', 'info');
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isLocked) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);

      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة من الملف. هل أنت متأكد؟')) {
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');

          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              showToast(`تم استيراد ${newIndicators.length} مؤشر بنجاح`, 'success');
          } else {
              showToast('لم يتم العثور على بيانات صالحة في الملف.', 'error');
          }
      }
    };
    reader.readAsBinaryString(file);
  };

  // Group by Axis
  const grouped = indicators.reduce((acc, curr) => {
    if (!acc[curr.axis]) acc[curr.axis] = [];
    acc[curr.axis].push(curr);
    return acc;
  }, {} as Record<string, Indicator[]>);

  // Available Axes for Dropdowns
  const availableAxes = Object.keys(grouped);

  // Performance Pie Data
  const responseValues = Object.values(responses) as Response[];
  const performanceData = [
      { name: 'منخفض (1-2)', value: responseValues.filter(r => r.score <= 2).length, fill: '#ef4444' },
      { name: 'متوسط (3)', value: responseValues.filter(r => r.score === 3).length, fill: '#f59e0b' },
      { name: 'مرتفع (4-5)', value: responseValues.filter(r => r.score >= 4).length, fill: '#10b981' },
  ].filter(d => d.value > 0);

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  // Save Handlers
  const handleDraftSave = () => {
      if (isLocked) return;
      showToast('تم حفظ التغييرات كمسودة', 'info');
  };

  const handleFinalSave = () => {
      if (isLocked) return;
      // Check which indicators do NOT have a response
      const missingIndicators = indicators.filter(ind => !responses[ind.id]);

      if (missingIndicators.length > 0) {
          const missingNumbers = missingIndicators.map(ind => indicators.indexOf(ind) + 1);
          let missingStr = missingNumbers.join('، ');
          if (missingNumbers.length > 15) {
              missingStr = missingNumbers.slice(0, 15).join('، ') + ' ...وغيرها';
          }
          showToast(`عذراً، لا يمكن الاعتماد النهائي. يرجى استكمال تقييم المؤشرات أرقام: (${missingStr})`, 'error');
          return;
      }

      if (evaluation) {
          const updatedEval = { ...evaluation, status: 'final' as const };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم اعتماد التقييم النهائي بنجاح', 'success');
      }
  };

  return (
    <div className="space-y-6 relative pb-24">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>
            {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
        </div>

        {role === 'admin' && !isLocked && (
          <div className="flex gap-2">
              <button onClick={() => { setNewIndAxis(availableAxes[0] || 'عام'); setShowAddInd(true); }} className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50 shadow-sm transition-transform hover:scale-105 active:scale-95">
                  <PlusCircle size={18} /> إضافة مؤشر
              </button>
              <button onClick={openDeleteModal} className="bg-white border border-red-200 text-red-600 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-50 shadow-sm transition-transform hover:scale-105 active:scale-95">
                  <MinusCircle size={18} /> حذف مؤشر
              </button>
              <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md transition-transform hover:scale-105 active:scale-95">
                  <Upload size={18} /> تحديث (Excel)
                  <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
              </label>
          </div>
        )}
      </div>

      {/* Currently Viewing Banner - Replaces Selector */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn transition-all hover:shadow-md">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري عرض بيانات تقييم:</div>
                      <div className="text-lg font-bold">{currentInstitutionName} ({CURRENT_YEAR})</div>
                  </div>
              </div>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى الذهاب إلى لوحة القيادة (Dashboard) أو صفحة المؤسسات لاختيار المؤسسة التي تود العمل عليها.</p>
          </div>
      )}

      {/* Add Indicator Modal */}
      {showAddInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4">
                      <h3 className="text-lg font-bold">إضافة مؤشر جديد</h3>
                      <button onClick={() => setShowAddInd(false)} className="hover:rotate-90 transition-transform"><X size={20}/></button>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium mb-1">المحور</label>
                          <select 
                            className="w-full border p-2 rounded" 
                            value={newIndAxis} 
                            onChange={e => setNewIndAxis(e.target.value)}
                          >
                              {availableAxes.map(a => <option key={a} value={a}>{a}</option>)}
                              <option value="NEW_AXIS_CUSTOM_VALUE">محور جديد (اكتب أدناه)</option>
                          </select>
                          {newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' && (
                              <input 
                                type="text" 
                                placeholder="اكتب اسم المحور الجديد" 
                                className="w-full border p-2 rounded mt-2" 
                                value={customAxis}
                                onChange={e => setCustomAxis(e.target.value)} 
                              />
                          )}
                      </div>
                      <div>
                          <label className="block text-sm font-medium mb-1">نص المؤشر</label>
                          <textarea 
                            className="w-full border p-2 rounded h-24" 
                            value={newIndText} 
                            onChange={e => setNewIndText(e.target.value)}
                          ></textarea>
                      </div>
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowAddInd(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded transition-colors">إلغاء</button>
                      <button onClick={handleAddIndicator} className="px-4 py-2 bg-navy-800 text-white rounded hover:bg-navy-900 transition-colors">إضافة</button>
                  </div>
              </div>
          </div>
      )}

      {/* Delete Indicator Modal */}
      {showDeleteInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4">
                      <h3 className="text-lg font-bold text-red-600">حذف مؤشر</h3>
                      <button onClick={() => setShowDeleteInd(false)} className="hover:rotate-90 transition-transform"><X size={20}/></button>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium mb-1">اختر المحور</label>
                          <select 
                            className="w-full border p-2 rounded" 
                            value={deleteAxis} 
                            onChange={e => { setDeleteAxis(e.target.value); setDeleteIndId(''); }}
                          >
                              <option value="">-- اختر --</option>
                              {availableAxes.map(a => <option key={a} value={a}>{a}</option>)}
                          </select>
                      </div>
                      {deleteAxis && (
                          <div>
                              <label className="block text-sm font-medium mb-1">اختر المؤشر للحذف</label>
                              <select 
                                className="w-full border p-2 rounded" 
                                value={deleteIndId} 
                                onChange={e => setDeleteIndId(e.target.value)}
                              >
                                  <option value="">-- اختر --</option>
                                  {grouped[deleteAxis]?.map(ind => (
                                      <option key={ind.id} value={ind.id}>{ind.text.substring(0, 60)}...</option>
                                  ))}
                              </select>
                          </div>
                      )}
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowDeleteInd(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded transition-colors">إلغاء</button>
                      <button 
                        onClick={handleDeleteIndicator} 
                        disabled={!deleteIndId}
                        className={`px-4 py-2 text-white rounded transition-colors ${!deleteIndId ? 'bg-gray-300 cursor-not-allowed' : 'bg-red-600 hover:bg-red-700'}`}
                      >
                          حذف
                      </button>
                  </div>
              </div>
          </div>
      )}

      {currentWaqfId && indicators.length > 0 && (
        <div className="space-y-4 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => (
            <div key={axis} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300 hover:shadow-md">
              <button 
                className={`w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors ${openAxis === axis ? 'bg-navy-50' : ''}`}
                onClick={() => setOpenAxis(openAxis === axis ? null : axis)}
              >
                <div className="flex items-center gap-3">
                   <span className="w-8 h-8 rounded-full bg-navy-800 text-white flex items-center justify-center font-bold text-sm transform transition-transform duration-300 group-hover:scale-110">{idx + 1}</span>
                   <h3 className="font-bold text-navy-900 text-lg group-hover:translate-x-1 transition-transform">{axis}</h3>
                   <span className="text-sm text-gray-500">({grouped[axis].length} مؤشر)</span>
                </div>
                <div className={`transition-transform duration-300 ${openAxis === axis ? 'rotate-180' : ''}`}>
                    {openAxis === axis ? <ChevronUp className="text-navy-800" /> : <ChevronDown className="text-gray-400" />}
                </div>
              </button>

              {openAxis === axis && (
                <div className="p-4 space-y-4 bg-white border-t border-gray-100">
                  {grouped[axis].map((ind) => {
                    const globalIndex = indicators.findIndex(x => x.id === ind.id) + 1;
                    return (
                        <div key={ind.id} className="border-b border-gray-100 last:border-0 pb-6 mb-2 last:pb-0 last:mb-0 transition-colors hover:bg-gray-50 p-4 rounded-xl">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div className="flex gap-4 flex-1">
                                <span className="font-black text-teal-600 text-xl min-w-[32px] select-none">{globalIndex}.</span>
                                <p className="text-gray-900 font-bold text-lg leading-snug">{ind.text}</p>
                            </div>

                            <div className="flex gap-3 shrink-0 justify-center md:justify-end w-full md:w-auto mt-2 md:mt-0">
                                {[1, 2, 3, 4, 5].map(score => (
                                <button
                                    key={score}
                                    onClick={() => handleScore(ind.id, score)}
                                    disabled={isLocked}
                                    className={`w-12 h-12 rounded-xl flex items-center justify-center text-lg font-bold border-2 transition-all duration-200 shadow-sm transform ${!isLocked && 'hover:scale-110 active:scale-95'} ${
                                    responses[ind.id]?.score === score
                                        ? `${RATING_COLORS[score]} scale-110 shadow-md ring-2 ring-offset-2 ring-gray-300`
                                        : 'bg-white text-gray-400 border-gray-200 ' + (isLocked ? 'cursor-not-allowed opacity-50' : 'hover:border-gray-400 hover:text-gray-600')
                                    }`}
                                >
                                    {score}
                                </button>
                                ))}
                            </div>
                        </div>
                        </div>
                    );
                  })}
                </div>
              )}
            </div>
          ))}

          {/* Action Bar & Stats Footer */}
          <div className="fixed bottom-0 left-0 right-0 lg:right-64 bg-white border-t shadow-[0_-4px_10px_rgba(0,0,0,0.1)] p-4 flex flex-col md:flex-row justify-between items-center z-40 gap-4">
             <div className="flex items-center gap-6">
                <div>
                    <span className="text-sm text-gray-500 block">تقدم التقييم</span>
                    <span className="font-bold text-navy-900">{Object.keys(responses).length} / {indicators.length}</span>
                </div>

                {/* Mini Pie Chart for Score Breakdown */}
                {performanceData.length > 0 && (
                    <div className="flex items-center gap-3 border-r pr-6 mr-2">
                         <div className="w-10 h-10 relative hover:scale-110 transition-transform">
                             <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={performanceData} dataKey="value" innerRadius={10} outerRadius={20} stroke="none">
                                        {performanceData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.fill} />
                                        ))}
                                    </Pie>
                                </PieChart>
                             </ResponsiveContainer>
                         </div>
                         <div className="text-xs space-y-0.5">
                             {performanceData.map(d => (
                                 <div key={d.name} className="flex items-center gap-1">
                                     <span className="w-2 h-2 rounded-full" style={{backgroundColor: d.fill}}></span>
                                     <span className="text-gray-600">{d.value}</span>
                                 </div>
                             ))}
                         </div>
                    </div>
                )}
             </div>

             <div className="flex items-center gap-4">
                 <div className="relative">
                     <label className={`cursor-pointer bg-gray-100 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 text-sm transition-all ${isLocked ? 'opacity-50 cursor-not-allowed' : 'hover:bg-gray-200 hover:scale-105 active:scale-95'}`}>
                         <Paperclip size={16} /> إرفاق أدلة
                         <input type="file" className="hidden" onChange={handleFileUpload} disabled={isLocked} />
                     </label>
                 </div>

                 {/* NEW: Draft Save Button */}
                 {!isLocked && (
                    <button onClick={handleDraftSave} className="bg-gray-200 text-gray-800 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-300 shadow-sm font-bold text-sm transition-all hover:scale-105 active:scale-95">
                        <SaveAll size={18} /> حفظ التغييرات
                    </button>
                 )}

                 {/* FINAL SAVE: Checks for completion */}
                 {!isLocked && (
                    <button onClick={handleFinalSave} className="bg-teal-600 text-white px-6 py-2 rounded-lg flex items-center gap-2 hover:bg-teal-700 shadow-lg font-bold transition-all hover:scale-105 active:scale-95">
                        <Save size={18} /> حفظ واعتماد
                    </button>
                 )}
             </div>
          </div>

          {/* Attachments List */}
          {evaluation?.attachments && evaluation.attachments.length > 0 && (
             <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200 mb-20 transition-all hover:shadow-md">
                 <h4 className="font-bold text-gray-700 mb-3 text-sm flex items-center gap-2"><Paperclip size={16}/> المرفقات والأدلة ({evaluation.attachments.length})</h4>
                 <div className="flex flex-wrap gap-2">
                     {evaluation.attachments.map(doc => (
                         <div key={doc.id} className="bg-gray-50 border border-gray-200 px-3 py-2 rounded-lg flex items-center gap-2 text-sm hover:bg-gray-100 transition-colors">
                             <FileText size={14} className="text-blue-500" />
                             <span className="truncate max-w-[150px]">{doc.name}</span>
                             <button onClick={() => removeAttachment(doc.id)} disabled={isLocked} className={`text-gray-400 hover:text-red-500 transition-colors hover:scale-110 ${isLocked ? 'hidden' : ''}`}><X size={14}/></button>
                         </div>
                     ))}
                 </div>
             </div>
          )}
        </div>
      )}
    </div>
  );
};

export default EvaluationPage;

import React, { useState, useEffect, useMemo } from 'react';
import { getInstitutions, getIndicators, saveIndicators, getEvaluationByInstAndYear, saveEvaluation, getResponses, saveResponse, generateId, getInstitutionProgress } from '../services/db';
import { Institution, Indicator, Evaluation, Response, InstitutionDocument } from '../types';
import { CURRENT_YEAR, RATING_COLORS } from '../constants';
import { Upload, Save, ChevronDown, ChevronUp, Paperclip, FileText, X, PlusCircle, PieChart as PieIcon, Trash2, MinusCircle, Building, SaveAll, Lock, CheckCircle2, Circle, Scale, Briefcase, ShieldCheck, Lightbulb, Globe, Layout, ChevronRight } from 'lucide-react';
import { useUi } from '../contexts/UiContext';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

declare const XLSX: any; // SheetJS global

// Map Axis names to Icons
const AXIS_ICONS: Record<string, any> = {
    'الشرعي': Scale,
    'الإجراءات الإدارية والمالية': Briefcase,
    'الحوكمة': ShieldCheck,
    'الابتكار والتطوير': Lightbulb,
    'الاستدامة': Globe,
    'default': Layout
};

const EvaluationPage: React.FC = () => {
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const { showToast, currentWaqfId, role } = useUi();

  const [indicators, setIndicators] = useState<Indicator[]>([]);
  const [evaluation, setEvaluation] = useState<Evaluation | null>(null);
  const [responses, setResponses] = useState<Record<string, Response>>({});

  // Locking State
  const [isLocked, setIsLocked] = useState(false);

  // UI State
  const [openAxis, setOpenAxis] = useState<string | null>(null);
  const [expandAll, setExpandAll] = useState(false);

  // Modals State
  const [showAddInd, setShowAddInd] = useState(false);
  const [newIndAxis, setNewIndAxis] = useState('');
  const [customAxis, setCustomAxis] = useState('');
  const [newIndText, setNewIndText] = useState('');

  const [showDeleteInd, setShowDeleteInd] = useState(false);
  const [deleteAxis, setDeleteAxis] = useState('');
  const [deleteIndId, setDeleteIndId] = useState('');


  useEffect(() => {
    setInstitutions(getInstitutions());
    const inds = getIndicators();
    setIndicators(inds);
    // Open first axis by default if exists
    if (inds.length > 0) {
        setOpenAxis(inds[0].axis);
    }
  }, []);

  useEffect(() => {
    if (currentWaqfId && indicators.length > 0) {
      const progress = getInstitutionProgress(currentWaqfId);
      setIsLocked(progress.isLocked);

      let ev = getEvaluationByInstAndYear(currentWaqfId, CURRENT_YEAR);
      if (!ev) {
        ev = {
          id: generateId(),
          institution_id: currentWaqfId,
          cycle_year: CURRENT_YEAR,
          cycle_date: new Date().toISOString(),
          status: 'draft',
          workflow_status: 'draft',
          attachments: [],
          created_at: new Date().toISOString()
        };
        saveEvaluation(ev);
      }
      setEvaluation(ev);

      const resps = getResponses(ev.id);
      const respMap: Record<string, Response> = {};
      resps.forEach(r => respMap[r.indicator_id] = r);
      setResponses(respMap);
    } else {
      setEvaluation(null);
    }
  }, [currentWaqfId, indicators.length]);

  const handleScore = (indicatorId: string, score: number) => {
    if (!evaluation || isLocked) return;
    const newResp: Response = {
      id: responses[indicatorId]?.id || generateId(),
      evaluation_id: evaluation.id,
      indicator_id: indicatorId,
      score,
      updated_at: new Date().toISOString()
    };

    setResponses(prev => ({ ...prev, [indicatorId]: newResp }));
    saveResponse(newResp);
  };

  // --- CRUD Handlers (Add/Delete/Import) same as before ---
  const handleAddIndicator = () => {
      const finalAxis = newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' ? customAxis : newIndAxis;
      if(!newIndText || !finalAxis) { showToast('يرجى تعبئة جميع الحقول', 'error'); return; }
      const indicator: Indicator = { id: `IND-MANUAL-${generateId().substring(0,6)}`, axis: finalAxis, text: newIndText, weight: 1, active: true };
      const updatedList = [...indicators, indicator];
      setIndicators(updatedList);
      saveIndicators(updatedList);
      setShowAddInd(false); setNewIndAxis(''); setCustomAxis(''); setNewIndText('');
      showToast('تم إضافة المؤشر الجديد بنجاح', 'success');
  };

  const handleDeleteIndicator = () => {
      if (!deleteIndId) { showToast('يرجى اختيار المؤشر للحذف', 'error'); return; }
      if(confirm('هل أنت متأكد من حذف هذا المؤشر؟')) {
          const updatedList = indicators.filter(i => i.id !== deleteIndId);
          setIndicators(updatedList);
          saveIndicators(updatedList);
          setShowDeleteInd(false); setDeleteIndId(''); setDeleteAxis('');
          showToast('تم حذف المؤشر', 'info');
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (isLocked) return;
      if (e.target.files && e.target.files[0] && evaluation) {
          const file = e.target.files[0];
          const newDoc: InstitutionDocument = { id: generateId(), name: file.name, type: file.type, size: (file.size / 1024).toFixed(1) + ' KB', upload_date: new Date().toLocaleDateString('ar-OM') };
          const updatedEval = { ...evaluation, attachments: [...(evaluation.attachments || []), newDoc] };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم إرفاق الدليل بنجاح', 'success');
      }
  };

  const removeAttachment = (docId: string) => {
      if (!evaluation || isLocked) return;
      const updatedEval = { ...evaluation, attachments: evaluation.attachments?.filter(d => d.id !== docId) || [] };
      setEvaluation(updatedEval);
      saveEvaluation(updatedEval);
      showToast('تم حذف المرفق', 'info');
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isLocked) return;
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[] = XLSX.utils.sheet_to_json(ws);
      if (confirm('سيتم استبدال المؤشرات الحالية بالمؤشرات الجديدة. هل أنت متأكد؟')) {
          const newIndicators: Indicator[] = data.map((row, idx) => ({
            id: `IND-${idx + 1}`,
            axis: row['المحور'] || 'عام',
            text: row['وصف التقييم'] || row['Indicator'] || 'بدون نص',
            weight: 1,
            active: true
          })).filter(i => i.text !== 'بدون نص');
          if(newIndicators.length > 0) {
              saveIndicators(newIndicators);
              setIndicators(newIndicators);
              showToast(`تم استيراد ${newIndicators.length} مؤشر بنجاح`, 'success');
          } else { showToast('لم يتم العثور على بيانات صالحة.', 'error'); }
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleFinalSave = () => {
      if (isLocked) return;
      const missingIndicators = indicators.filter(ind => !responses[ind.id]);
      if (missingIndicators.length > 0) {
          showToast(`عذراً، يجب إكمال تقييم ${missingIndicators.length} مؤشر متبقي.`, 'error');
          return;
      }
      if (evaluation) {
          const updatedEval = { ...evaluation, status: 'final' as const };
          setEvaluation(updatedEval);
          saveEvaluation(updatedEval);
          showToast('تم اعتماد التقييم النهائي بنجاح', 'success');
      }
  };

  // --- Grouping & Calculations ---
  const grouped = useMemo(() => {
    return indicators.reduce((acc, curr) => {
        if (!acc[curr.axis]) acc[curr.axis] = [];
        acc[curr.axis].push(curr);
        return acc;
    }, {} as Record<string, Indicator[]>);
  }, [indicators]);

  const availableAxes = Object.keys(grouped);

  const responseValues = Object.values(responses) as Response[];
  const performanceData = [
      { name: 'منخفض (1-2)', value: responseValues.filter(r => r.score <= 2).length, fill: '#ef4444' },
      { name: 'متوسط (3)', value: responseValues.filter(r => r.score === 3).length, fill: '#f59e0b' },
      { name: 'مرتفع (4-5)', value: responseValues.filter(r => r.score >= 4).length, fill: '#10b981' },
  ].filter(d => d.value > 0);

  const currentInstitutionName = institutions.find(i => i.id === currentWaqfId)?.name;

  // Toggle All Logic
  const handleToggleAll = () => {
      setExpandAll(!expandAll);
      setOpenAxis(expandAll ? null : 'ALL');
  };

  return (
    <div className="space-y-8 relative pb-24">

      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-navy-900">نموذج التقييم</h2>
            {isLocked && <span className="bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1"><Lock size={12}/> للقراءة فقط</span>}
        </div>

        {/* Admin Tools */}
        {role === 'admin' && !isLocked && (
          <div className="flex gap-2">
              <button onClick={() => { setNewIndAxis(availableAxes[0] || 'عام'); setShowAddInd(true); }} className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50 shadow-sm transition-transform hover:scale-105 active:scale-95 text-sm font-bold">
                  <PlusCircle size={16} /> إضافة مؤشر
              </button>
              <button onClick={() => { setDeleteAxis(''); setDeleteIndId(''); setShowDeleteInd(true); }} className="bg-white border border-red-200 text-red-600 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-red-50 shadow-sm transition-transform hover:scale-105 active:scale-95 text-sm font-bold">
                  <MinusCircle size={16} /> حذف مؤشر
              </button>
              <label className="bg-navy-800 text-white px-4 py-2 rounded-lg cursor-pointer flex items-center gap-2 hover:bg-navy-900 shadow-md transition-transform hover:scale-105 active:scale-95 text-sm font-bold">
                  <Upload size={16} /> استيراد (Excel)
                  <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport} />
              </label>
          </div>
        )}
      </div>

      {/* INSTITUTION BANNER */}
      {currentWaqfId ? (
          <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl flex items-center justify-between text-blue-900 animate-fadeIn transition-all hover:shadow-md">
              <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-lg"><Building size={20} className="text-blue-700"/></div>
                  <div>
                      <div className="text-xs text-blue-600 uppercase font-bold tracking-wider">جاري تقييم:</div>
                      <div className="text-lg font-bold">{currentInstitutionName} ({CURRENT_YEAR})</div>
                  </div>
              </div>
              <button 
                onClick={handleToggleAll} 
                className="text-sm font-bold text-blue-600 hover:bg-blue-100 px-3 py-1.5 rounded-lg transition-colors"
              >
                  {expandAll ? 'طي الكل' : 'توسيع الكل'}
              </button>
          </div>
      ) : (
          <div className="bg-orange-50 border border-orange-200 p-6 rounded-xl text-center">
              <p className="text-orange-800 font-bold mb-2">لم يتم اختيار مؤسسة</p>
              <p className="text-sm text-orange-600">يرجى اختيار المؤسسة لبدء التقييم.</p>
          </div>
      )}

      {/* MODALS (Add/Delete) - Preserved */}
      {showAddInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold">إضافة مؤشر جديد</h3><button onClick={() => setShowAddInd(false)}><X size={20}/></button></div>
                  <div className="space-y-4">
                      <div><label className="block text-sm font-medium mb-1">المحور</label><select className="w-full border p-2 rounded" value={newIndAxis} onChange={e => setNewIndAxis(e.target.value)}>{availableAxes.map(a => <option key={a} value={a}>{a}</option>)}<option value="NEW_AXIS_CUSTOM_VALUE">محور جديد</option></select>{newIndAxis === 'NEW_AXIS_CUSTOM_VALUE' && <input type="text" placeholder="اسم المحور" className="w-full border p-2 rounded mt-2" value={customAxis} onChange={e => setCustomAxis(e.target.value)} />}</div>
                      <div><label className="block text-sm font-medium mb-1">نص المؤشر</label><textarea className="w-full border p-2 rounded h-24" value={newIndText} onChange={e => setNewIndText(e.target.value)}></textarea></div>
                  </div>
                  <div className="flex justify-end gap-2 mt-6"><button onClick={() => setShowAddInd(false)} className="px-4 py-2 bg-gray-100 rounded">إلغاء</button><button onClick={handleAddIndicator} className="px-4 py-2 bg-navy-800 text-white rounded">إضافة</button></div>
              </div>
          </div>
      )}
      {showDeleteInd && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-2xl animate-scaleIn">
                  <div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold text-red-600">حذف مؤشر</h3><button onClick={() => setShowDeleteInd(false)}><X size={20}/></button></div>
                  <div className="space-y-4">
                      <div><label className="block text-sm font-medium mb-1">المحور</label><select className="w-full border p-2 rounded" value={deleteAxis} onChange={e => { setDeleteAxis(e.target.value); setDeleteIndId(''); }}><option value="">-- اختر --</option>{availableAxes.map(a => <option key={a} value={a}>{a}</option>)}</select></div>
                      {deleteAxis && <div><label className="block text-sm font-medium mb-1">اختر المؤشر</label><select className="w-full border p-2 rounded" value={deleteIndId} onChange={e => setDeleteIndId(e.target.value)}><option value="">-- اختر --</option>{grouped[deleteAxis]?.map(ind => <option key={ind.id} value={ind.id}>{ind.text.substring(0, 60)}...</option>)}</select></div>}
                  </div>
                  <div className="flex justify-end gap-2 mt-6"><button onClick={() => setShowDeleteInd(false)} className="px-4 py-2 bg-gray-100 rounded">إلغاء</button><button onClick={handleDeleteIndicator} disabled={!deleteIndId} className={`px-4 py-2 text-white rounded ${!deleteIndId ? 'bg-gray-300' : 'bg-red-600'}`}>حذف</button></div>
              </div>
          </div>
      )}

      {/* MAIN CONTENT: AXES LIST */}
      {currentWaqfId && indicators.length > 0 && (
        <div className="space-y-6 animate-fadeIn">
          {Object.keys(grouped).map((axis, idx) => {
            const axisIndicators = grouped[axis];
            const completedCount = axisIndicators.filter(i => responses[i.id]).length;
            const totalCount = axisIndicators.length;
            const progressPercent = Math.round((completedCount / totalCount) * 100);
            const isAxisComplete = completedCount === totalCount && totalCount > 0;
            const isOpen = openAxis === axis || openAxis === 'ALL';

            const AxisIcon = AXIS_ICONS[axis] || AXIS_ICONS['default'];

            return (
                <div key={axis} className={`bg-white rounded-2xl border transition-all duration-300 shadow-sm overflow-hidden ${isAxisComplete ? 'border-teal-200' : 'border-gray-200 hover:shadow-md'}`}>

                    {/* AXIS HEADER */}
                    <button 
                        onClick={() => setOpenAxis(isOpen && openAxis !== 'ALL' ? null : axis)}
                        className={`w-full flex flex-col md:flex-row md:items-center justify-between p-5 transition-colors ${isOpen ? 'bg-gray-50' : 'bg-white hover:bg-gray-50'}`}
                    >
                        {/* Title Section */}
                        <div className="flex items-center gap-4 mb-3 md:mb-0">
                            {/* Number Badge */}
                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-xl shadow-sm ${isAxisComplete ? 'bg-teal-100 text-teal-700' : 'bg-navy-900 text-white'}`}>
                                {idx + 1}
                            </div>

                            <div className="text-right">
                                <h3 className={`text-lg font-bold flex items-center gap-2 ${isAxisComplete ? 'text-teal-800' : 'text-navy-900'}`}>
                                    <AxisIcon size={20} className="opacity-80"/>
                                    {axis}
                                </h3>
                                <p className="text-xs text-gray-500 font-medium mt-0.5 flex items-center gap-2">
                                    {totalCount} مؤشرات قياس
                                    {isAxisComplete && <span className="text-teal-600 flex items-center gap-1 font-bold"><CheckCircle2 size={12}/> مكتمل بالكامل</span>}
                                </p>
                            </div>
                        </div>

                        {/* Progress Section */}
                        <div className="flex items-center gap-6 w-full md:w-auto">
                            <div className="flex-1 md:w-48">
                                <div className="flex justify-between text-xs mb-1 font-bold">
                                    <span className={isAxisComplete ? 'text-teal-600' : 'text-gray-500'}>{progressPercent}% إنجاز</span>
                                    <span className="text-gray-400">{completedCount} من {totalCount}</span>
                                </div>
                                <div className="h-2.5 w-full bg-gray-200 rounded-full overflow-hidden">
                                    <div 
                                        className={`h-full rounded-full transition-all duration-1000 ${isAxisComplete ? 'bg-teal-500' : 'bg-blue-500'}`} 
                                        style={{ width: `${progressPercent}%` }}
                                    ></div>
                                </div>
                            </div>
                            <div className={`transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                                <ChevronDown className="text-gray-400" />
                            </div>
                        </div>
                    </button>

                    {/* INDICATORS LIST */}
                    {isOpen && (
                        <div className="border-t border-gray-100 bg-white">
                            {axisIndicators.map((ind, i) => {
                                const globalIndex = indicators.findIndex(x => x.id === ind.id) + 1;
                                const currentScore = responses[ind.id]?.score;

                                return (
                                    <div key={ind.id} className={`p-6 border-b border-gray-100 last:border-0 transition-colors ${currentScore ? 'bg-blue-50/20' : 'hover:bg-gray-50'}`}>
                                        <div className="flex flex-col md:flex-row gap-6">
                                            {/* Question Text */}
                                            <div className="flex-1">
                                                <div className="flex gap-3">
                                                    <span className="text-teal-600 font-black text-lg min-w-[30px]">{globalIndex}.</span>
                                                    <div>
